#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""設定客製動態 spin 按鈕的 SpinButtonLoader 參數（步驟 7）。

GameDownBar/Prefab/SlotUI.prefab 是 SlotCommon 那顆 SlotUI.prefab 的**巢狀實例**，
直接改展開值會被 Cocos 存檔時還原，所以要在 cc.PrefabInstance.propertyOverrides
補 CCPropertyOverrideInfo（localID = SpinButtonLoader 的 CompPrefabInfo.fileId）。
本腳本兩邊都寫：override（權威）＋展開值（讓還沒進編輯器前 runtime 也對）。

bonePath 由 spine 骨架推出來：找名為 Num（--bone 可改）的骨頭，
往上串成 'root/.../Num'。支援 .skel（二進位，3.8/4.x）與 .json 骨架。
"""

import argparse
import json
import struct
import sys
from pathlib import Path

SRC_PREFAB_REL = 'assets/SlotCommon/Components/SlotDownBar/Prefab/SlotUI.prefab'
LOADER_PROPS = ('bonePath', 'bundleName', 'skeletonPath')


# --------------------------------------------------------------------------- #
# spine 骨架解析
# --------------------------------------------------------------------------- #
class _Reader:
    def __init__(self, data: bytes):
        self.d = data
        self.i = 0

    def varint(self):
        """spine readInt(true)：7 bits/byte，0x80 為續接位。"""
        result = 0
        shift = 0
        while True:
            b = self.byte()
            result |= (b & 0x7F) << shift
            if not b & 0x80:
                return result
            shift += 7
            if shift > 35:
                raise ValueError('varint 過長')

    def byte(self):
        if self.i >= len(self.d):
            raise ValueError('讀超出檔案結尾')
        b = self.d[self.i]
        self.i += 1
        return b

    def string(self):
        n = self.varint()
        if n == 0:
            return None
        if n == 1:
            return ''
        raw = self.d[self.i:self.i + n - 1]
        if len(raw) != n - 1:
            raise ValueError('字串長度超出檔案結尾')
        self.i += n - 1
        return raw.decode('utf-8')

    def f32(self):
        if self.i + 4 > len(self.d):
            raise ValueError('float 超出檔案結尾')
        v = struct.unpack_from('>f', self.d, self.i)[0]
        self.i += 4
        return v

    def skip(self, n):
        self.i += n


def _read_bones(r: _Reader, nonessential: bool, extra_bool: bool):
    """讀 bone 區段，順便做合理性檢查（不合理就丟 ValueError）。"""
    n = r.varint()
    if not 1 <= n <= 4000:
        raise ValueError(f'bone 數不合理：{n}')
    bones = []
    for i in range(n):
        name = r.string()
        if not name or not name.isprintable():
            raise ValueError(f'bone[{i}] 名字不合理：{name!r}')
        parent = None
        if i:
            parent = r.varint()
            if parent >= i:
                raise ValueError(f'bone[{i}] parent 索引不合理：{parent}')
        for _ in range(8):  # rotation,x,y,scaleX,scaleY,shearX,shearY,length
            v = r.f32()
            if v != v or abs(v) > 1e9:
                raise ValueError(f'bone[{i}] 數值不合理：{v}')
        mode = r.varint()
        if mode > 5:
            raise ValueError(f'bone[{i}] transformMode/inherit 不合理：{mode}')
        skin_required = r.byte()
        if skin_required > 1:
            raise ValueError(f'bone[{i}] skinRequired 不是 bool：{skin_required}')
        if extra_bool:
            visible = r.byte()
            if visible > 1:
                raise ValueError(f'bone[{i}] visible 不是 bool：{visible}')
        if nonessential:
            r.skip(4)  # color
        bones.append({'name': name, 'parent': parent})
    return bones


def _try_parse(data: bytes, strings_table: bool, extra_bool: bool):
    r = _Reader(data)
    r.string()                      # hash
    version = r.string() or ''
    for _ in range(4):              # x, y, width, height
        r.f32()
    nonessential = r.byte()
    if nonessential > 1:
        raise ValueError('nonessential 不是 bool')
    if nonessential:
        r.f32()                     # fps
        r.string()                  # imagesPath
        r.string()                  # audioPath
    if strings_table:
        n = r.varint()
        if n > 20000:
            raise ValueError(f'strings 數不合理：{n}')
        for _ in range(n):
            r.string()
    bones = _read_bones(r, bool(nonessential), extra_bool)
    # 再往下讀 slot 區段當交叉驗證：slot 名要是可讀字串、bone 索引要在範圍內
    ns = r.varint()
    if ns > 4000:
        raise ValueError(f'slot 數不合理：{ns}')
    for _ in range(min(ns, 3)):
        name = r.string()
        bi = r.varint()
        if not name or not name.isprintable() or bi >= len(bones):
            raise ValueError('slot 區段驗證失敗')
        r.skip(4)                   # color
        r.varint()                  # dark color / attachment 之後不再讀
        break
    return version, bones


def parse_skel_bones(path: Path):
    """回傳 (version, bones)。二進位格式在 3.8/4.x 之間有差異，
    所以把「有沒有 strings table」「bone 尾端有沒有多一個 bool」四種組合都試，
    用合理性檢查挑出唯一過關的那組。"""
    data = path.read_bytes()
    last = None
    ok = []
    for strings_table in (True, False):
        for extra_bool in (False, True):
            try:
                ok.append(((strings_table, extra_bool), _try_parse(data, strings_table, extra_bool)))
            except Exception as e:  # noqa: BLE001
                last = f'strings_table={strings_table} extra_bool={extra_bool}: {e}'
    if not ok:
        raise ValueError(f'看不懂這個 .skel 的格式（最後一次失敗：{last}）')
    if len(ok) > 1:
        # 多組都過關時，取骨頭數最多的那組（最不可能是誤讀）
        ok.sort(key=lambda kv: -len(kv[1][1]))
    return ok[0][1]


def parse_json_bones(path: Path):
    data = json.loads(path.read_text(encoding='utf-8'))
    raw = data.get('bones')
    if not raw:
        raise ValueError('json 骨架裡沒有 bones')
    names = [b.get('name') for b in raw]
    bones = []
    for b in raw:
        parent = b.get('parent')
        bones.append({'name': b.get('name'),
                      'parent': names.index(parent) if parent in names else None})
    return data.get('skeleton', {}).get('spine', ''), bones


def skeleton_path_in_bundle(skel: Path, bundle_name='GameDownBar'):
    """SkeletonData 在 bundle 內的載入路徑（不含副檔名）。
    骨架檔在 <bundle>/Spine/Spin.skel → 'Spine/Spin'。
    找不到 bundle 資料夾時退回 '<父資料夾名>/<檔名>'。"""
    parts = skel.parts
    for i in range(len(parts) - 1, -1, -1):
        if parts[i] == bundle_name:
            return '/'.join(parts[i + 1:-1] + (skel.stem,)), True
    return f'{skel.parent.name}/{skel.stem}', False


def bone_path(bones, leaf: str):
    idx = [i for i, b in enumerate(bones) if b['name'] == leaf]
    if not idx:
        raise ValueError(f'骨架裡找不到名為 "{leaf}" 的骨頭。'
                         f'現有骨頭：{[b["name"] for b in bones]}')
    if len(idx) > 1:
        raise ValueError(f'骨架裡有多個 "{leaf}"，請用 --bone-path 直接指定')
    parts = []
    i = idx[0]
    while i is not None:
        parts.append(bones[i]['name'])
        i = bones[i]['parent']
        if len(parts) > 64:
            raise ValueError('骨頭 parent 形成迴圈')
    return '/'.join(reversed(parts))


# --------------------------------------------------------------------------- #
# prefab override
# --------------------------------------------------------------------------- #
def find_loader_file_id(src_prefab: Path):
    """從 SlotCommon 來源 prefab 找 SpinButtonLoader 的 CompPrefabInfo.fileId。
    fileId 會被實例沿用，所以它就是 override 要用的 localID。"""
    d = json.loads(src_prefab.read_text(encoding='utf-8'))
    hits = []
    for o in d:
        if isinstance(o, dict) and all(k in o for k in LOADER_PROPS):
            pi = o.get('__prefab', {}).get('__id__')
            if pi is not None and d[pi].get('__type__') == 'cc.CompPrefabInfo':
                hits.append((o.get('__type__'), d[pi].get('fileId')))
    if len(hits) != 1:
        raise ValueError(f'在 {src_prefab} 找到 {len(hits)} 個 SpinButtonLoader（預期 1 個）：{hits}')
    return hits[0]


def detect_newline(text: str):
    return '\r\n' if '\r\n' in text else '\n'


def main():
    ap = argparse.ArgumentParser(description='設定 SpinButtonLoader 參數（步驟 7）')
    ap.add_argument('--prefab', required=True,
                    help='GameDownBar/Prefab/SlotUI.prefab（巢狀 prefab）')
    ap.add_argument('--skel', help='spine 骨架檔（.skel 或 .json），用來推 bonePath')
    ap.add_argument('--bone', default='Num', help='auto 次數掛的骨頭名（預設 Num）')
    ap.add_argument('--bone-path', help='直接指定 bonePath，跳過骨架解析')
    ap.add_argument('--bundle-name', default='GameDownBar')
    ap.add_argument('--skeleton-path',
                    help='bundle 內 SkeletonData 路徑（不給就從 --skel 的位置/檔名推，'
                         '例如 Spine/Spin_Button → Spine/Spin_Button）')
    ap.add_argument('--source-prefab', help=f'SlotCommon 來源 prefab（預設 {SRC_PREFAB_REL}）')
    ap.add_argument('--project-root', help='Cocos 專案根（預設從 --prefab 往上找）')
    ap.add_argument('--apply', action='store_true', help='實際寫入。不加就是乾跑')
    args = ap.parse_args()

    prefab = Path(args.prefab).resolve()
    if not prefab.is_file():
        raise SystemExit(f'prefab 不存在：{prefab}')

    root = Path(args.project_root).resolve() if args.project_root else None
    if root is None:
        # 先從 prefab 位置往上找，找不到（例如 prefab 放在專案外）再退回 cwd
        for start in (prefab, Path.cwd().resolve()):
            for p in [start] + list(start.parents):
                if (p / 'assets').is_dir() and (p / 'package.json').is_file():
                    root = p
                    break
            if root is not None:
                break
    if root is None:
        raise SystemExit('找不到專案根，請用 --project-root 指定')
    src = Path(args.source_prefab).resolve() if args.source_prefab else root / SRC_PREFAB_REL
    if not src.is_file():
        raise SystemExit(f'來源 prefab 不存在：{src}')

    skel = Path(args.skel).resolve() if args.skel else None
    if skel is not None and not skel.is_file():
        raise SystemExit(f'骨架檔不存在：{skel}')

    # 1. bonePath
    if args.bone_path:
        bp = args.bone_path
        print(f'bonePath（使用者指定）：{bp}')
    else:
        if skel is None:
            raise SystemExit('請給 --skel（骨架檔）或 --bone-path')
        version, bones = (parse_json_bones(skel) if skel.suffix.lower() == '.json'
                          else parse_skel_bones(skel))
        print(f'骨架：{skel.name}（spine {version}，{len(bones)} 根骨頭）')
        print(f'骨頭列表：{[b["name"] for b in bones]}')
        bp = bone_path(bones, args.bone)
        print(f'bonePath（解析得到）：{bp}')

    # 2. skeletonPath：spine 不改名，所以路徑由 bundle 內的實際檔名決定
    if args.skeleton_path:
        sp = args.skeleton_path
        print(f'skeletonPath（使用者指定）：{sp}')
    else:
        if skel is None:
            raise SystemExit('沒給 --skel 時請用 --skeleton-path 指定 bundle 內的骨架路徑')
        sp, in_bundle = skeleton_path_in_bundle(skel, args.bundle_name)
        print(f'skeletonPath（由檔名推得）：{sp}')
        if not in_bundle:
            print(f'! --skel 不在 {args.bundle_name} 資料夾底下，推出來的路徑很可能是錯的。'
                  f'請指到 bundle 內那份骨架檔，或直接用 --skeleton-path 指定。')

    values = {'bonePath': bp, 'bundleName': args.bundle_name, 'skeletonPath': sp}

    # 2. 找 override 用的 localID
    class_id, file_id = find_loader_file_id(src)
    print(f'SpinButtonLoader class={class_id}  CompPrefabInfo.fileId={file_id}')

    text = prefab.read_text(encoding='utf-8')
    newline = detect_newline(text)
    d = json.loads(text)

    insts = [i for i, o in enumerate(d)
             if isinstance(o, dict) and o.get('__type__') == 'cc.PrefabInstance']
    if len(insts) != 1:
        raise SystemExit(f'{prefab.name} 裡有 {len(insts)} 個 cc.PrefabInstance（預期 1 個）。'
                         '這顆 prefab 可能不是單純的巢狀實例，請人工處理。')
    inst = d[insts[0]]
    overrides = inst.setdefault('propertyOverrides', [])

    # 既有的 override：同一個 localID + propertyPath 就更新，不重複新增
    def find_existing(prop):
        for ref in overrides:
            o = d[ref['__id__']]
            if o.get('__type__') != 'CCPropertyOverrideInfo':
                continue
            if o.get('propertyPath') != [prop]:
                continue
            ti = d[o['targetInfo']['__id__']]
            if ti.get('localID') == [file_id]:
                return o
        return None

    actions = []
    target_ref = None
    for ref in overrides:  # 沿用既有的 cc.TargetInfo（跟 Cocos 存檔的樣子一致）
        o = d[ref['__id__']]
        if o.get('__type__') == 'CCPropertyOverrideInfo':
            ti_id = o['targetInfo']['__id__']
            if d[ti_id].get('localID') == [file_id]:
                target_ref = ti_id
                break

    for prop, val in values.items():
        cur = find_existing(prop)
        if cur is not None:
            if cur.get('value') == val:
                actions.append(f'[已是正確值] override {prop} = {val!r}')
            else:
                actions.append(f'[更新] override {prop}: {cur.get("value")!r} -> {val!r}')
                cur['value'] = val
            continue
        if target_ref is None:
            d.append({'__type__': 'cc.TargetInfo', 'localID': [file_id]})
            target_ref = len(d) - 1
            actions.append(f'[新增] cc.TargetInfo localID={file_id}（__id__={target_ref}）')
        d.append({
            '__type__': 'CCPropertyOverrideInfo',
            'targetInfo': {'__id__': target_ref},
            'propertyPath': [prop],
            'value': val,
        })
        overrides.append({'__id__': len(d) - 1})
        actions.append(f'[新增] override {prop} = {val!r}（__id__={len(d) - 1}）')

    # 3. 一併更新展開值（找 fileId 對得上的那顆 component）
    comp = None
    for o in d:
        if isinstance(o, dict) and all(k in o for k in LOADER_PROPS):
            pi = o.get('__prefab', {}).get('__id__')
            if pi is not None and d[pi].get('fileId') == file_id:
                comp = o
                break
    if comp is None:
        actions.append('! 找不到展開的 SpinButtonLoader component（只寫 override，'
                       '回編輯器存一次檔就會同步）')
    else:
        for prop, val in values.items():
            if comp.get(prop) != val:
                actions.append(f'[展開值] {prop}: {comp.get(prop)!r} -> {val!r}')
                comp[prop] = val

    print()
    print('== 動作 ==' if args.apply else '== 動作（乾跑，未寫入）==')
    for a in actions:
        print('  ' + a)

    if args.apply:
        out = json.dumps(d, indent=2, ensure_ascii=False)
        json.loads(out)  # 驗證合法
        if newline != '\n':
            out = out.replace('\n', newline)
        prefab.write_text(out, encoding='utf-8', newline='')
        print(f'\n已寫入 {prefab}')
        print('下一步：回 Cocos Editor 重新載入 prefab，點 Spin 節點確認 '
              'SpinButtonLoader 三個欄位（會顯示成有 override 的樣式）。')
    else:
        print('\n（乾跑）確認以上沒問題後，指令尾端加 --apply 實際執行。')
    return 0


if __name__ == '__main__':
    sys.exit(main())

