# --------------------------------------------------------------------------- #
# 音檔長度 / 格式探測（純標準庫）
# --------------------------------------------------------------------------- #
_MP3_BR = [
    [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384],
    [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256],
    [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160],
]
_MP3_SR = {3: [44100, 48000, 32000], 2: [22050, 24000, 16000], 0: [11025, 12000, 8000]}
_MODE = {0: 'stereo', 1: 'joint', 2: 'dual', 3: 'mono'}


def _probe_mp3(data: bytes) -> dict:
    i = 0
    if data[:3] == b'ID3':
        i = 10 + ((data[6] & 0x7F) << 21 | (data[7] & 0x7F) << 14
                  | (data[8] & 0x7F) << 7 | (data[9] & 0x7F))
    total = 0.0
    frames = 0
    brs, srs, modes = set(), set(), set()
    n = len(data)
    while i < n - 4:
        if data[i] == 0xFF and (data[i + 1] & 0xE0) == 0xE0:
            h = struct.unpack('>I', data[i:i + 4])[0]
            ver, layer = (h >> 19) & 3, (h >> 17) & 3
            bri, sri = (h >> 12) & 0xF, (h >> 10) & 3
            pad, mode = (h >> 9) & 1, (h >> 6) & 3
            if layer == 0 or ver == 1 or sri == 3 or bri in (0, 15):
                i += 1
                continue
            srate = _MP3_SR[ver][sri]
            row = (3 - layer) if ver == 3 else (3 if layer == 3 else 4)
            bitrate = _MP3_BR[row][bri]
            spf = 384 if layer == 3 else (1152 if layer == 2 else (1152 if ver == 3 else 576))
            flen = int(spf / 8 * bitrate * 1000 / srate) + pad
            if flen <= 0:
                i += 1
                continue
            total += spf / srate
            frames += 1
            brs.add(bitrate)
            srs.add(srate)
            modes.add(mode)
            i += flen
        else:
            i += 1
    bitrate = None
    if brs:
        bitrate = min(brs) if len(brs) == 1 else 'VBR%d-%d' % (min(brs), max(brs))
    return {
        'dur': round(total, 2),
        'frames': frames,
        'bitrate': bitrate,
        'samplerate': sorted(srs)[0] if srs else None,
        'channels': _MODE.get(min(modes), '?') if modes else '?',
    }


def _probe_mp4(data: bytes) -> dict:
    """在 moov/mvhd 裡找 timescale / duration。"""
    idx = data.find(b'mvhd')
    if idx < 0:
        return {'dur': 0.0, 'note': 'mvhd 找不到'}
    p = idx + 4
    ver = data[p]
    if ver == 1:
        ts = struct.unpack('>I', data[p + 20:p + 24])[0]
        du = struct.unpack('>Q', data[p + 24:p + 32])[0]
    else:
        ts = struct.unpack('>I', data[p + 12:p + 16])[0]
        du = struct.unpack('>I', data[p + 16:p + 20])[0]
    return {'dur': round(du / ts, 2) if ts else 0.0, 'bitrate': None,
            'samplerate': None, 'channels': '?'}


def _probe_wav(data: bytes) -> dict:
    if data[:4] != b'RIFF':
        return {'dur': 0.0}
    sr = struct.unpack('<I', data[24:28])[0]
    byte_rate = struct.unpack('<I', data[28:32])[0]
    ch = struct.unpack('<H', data[22:24])[0]
    idx = data.find(b'data', 12)
    size = struct.unpack('<I', data[idx + 4:idx + 8])[0] if idx > 0 else 0
    return {'dur': round(size / byte_rate, 2) if byte_rate else 0.0,
            'bitrate': byte_rate * 8 // 1000, 'samplerate': sr,
            'channels': 'mono' if ch == 1 else '%dch' % ch}


def probe_audio(path) -> dict:
    path = Path(path)
    data = path.read_bytes()
    ext = path.suffix.lower()
    try:
        if ext == '.mp3':
            info = _probe_mp3(data)
        elif ext in ('.m4a', '.mp4', '.aac'):
            info = _probe_mp4(data)
        elif ext == '.wav':
            info = _probe_wav(data)
        else:
            info = {'dur': 0.0, 'note': '%s 不支援長度解析' % ext}
    except Exception as exc:  # 壞檔不要讓整批停下來
        info = {'dur': 0.0, 'note': '解析失敗: %s' % exc}
    info.update(file=path.name, stem=path.stem, size=path.stat().st_size,
                ext=ext, path=str(path))
    return info


def scan_audio_dir(folder) -> list:
    folder = Path(folder)
    if not folder.is_dir():
        raise SystemExit('[audio_lib] 音檔資料夾不存在：%s' % folder)
    files = [p for p in sorted(folder.rglob('*')) if p.suffix.lower() in AUDIO_EXT]
    return [probe_audio(p) for p in files]


# --------------------------------------------------------------------------- #
# clip key
# --------------------------------------------------------------------------- #
_SECTION_RE = re.compile(r'^(MG|FG|SG|JP|CM)_(BGM|SFX|MIX|VO)_(.+)$', re.I)
_PREFIX_RE = re.compile(r'^([A-Za-z0-9]+)_((?:MG|FG|SG|JP|CM)_(?:BGM|SFX|MIX|VO)_.+)$', re.I)


def strip_game_prefix(stem: str, prefix=None) -> str:
    """去掉遊戲代號前綴：'1024_MG_SFX_SpinStart' -> 'MG_SFX_SpinStart'。"""
    if prefix and stem.lower().startswith(prefix.lower() + '_'):
        return stem[len(prefix) + 1:]
    m = _PREFIX_RE.match(stem)
    return m.group(2) if m else stem


def detect_game_prefix(stems):
    """交付檔名的共同前綴（'1024_MG_SFX_x' -> '1024'）；抓不到回 None。"""
    heads = {}
    for s in stems:
        m = _PREFIX_RE.match(s)
        if m:
            heads[m.group(1)] = heads.get(m.group(1), 0) + 1
    if not heads:
        return None
    top, cnt = max(heads.items(), key=lambda kv: kv[1])
    return top if cnt >= 2 else None


def short_key(key: str) -> str:
    """'MG_SFX_SpinStart' -> 'SpinStart'。

    只縮 SFX；BGM / MIX 原樣保留（那些名字本身就靠 MG_/FG_ 區分，縮了會看不懂）。
    """
    m = _SECTION_RE.match(key)
    if not m or m.group(2).upper() != 'SFX':
        return key
    return m.group(3)


def make_keys(stems, prefix=None, short=False) -> dict:
    """回傳 {stem: clip_key}；短名撞名時該筆自動退回長名。"""
    base = {s: strip_game_prefix(s, prefix) for s in stems}
    if not short:
        return base
    buckets = {}
    for stem, long_key in base.items():
        buckets.setdefault(short_key(long_key), []).append(stem)
    out = {}
    for stem, long_key in base.items():
        sk = short_key(long_key)
        out[stem] = long_key if len(buckets[sk]) > 1 else sk
    return out


# --------------------------------------------------------------------------- #
# 規格表（xlsx / csv）
# --------------------------------------------------------------------------- #
#: 規格表欄位 -> 內部欄名。比對時去掉空白、取「包含」關係。
COLUMN_ALIASES = {
    'no': ['編號', '序號', 'no', 'id'],
    'scene': ['運用場景', '使用場景', '場景', '用途'],
    'kind': ['類型', '種類'],
    'filename': ['檔名', '檔案名稱', 'filename', 'file'],
    'melody': ['旋律'],
    'loop': ['loop', '循環'],
    'power': ['強度'],
    'length': ['聲音長度', '長度', '秒數'],
    'desc': ['需求說明', '說明', '腳本'],
    'ref_video': ['示意影片檔名', '示意影片'],
    'ref_time': ['示意影片時間點', '時間點'],
    'ref_sound': ['參考影片或聲音檔', '參考聲音', '參考'],
    'note': ['備註'],
    'modify': ['修改說明'],
    'accept': ['驗收'],
}


def _norm(s) -> str:
    return re.sub(r'\s+', '', str(s or '')).lower()


def _map_columns(header_rows) -> dict:
    """規格表的表頭常跨 2~3 列，把前幾列疊起來一起比對。"""
    width = max(len(r) for r in header_rows)
    merged = []
    for c in range(width):
        merged.append(''.join(_norm(r[c]) if c < len(r) else '' for r in header_rows))
    mapping = {}
    for field, names in COLUMN_ALIASES.items():
        for c, text in enumerate(merged):
            if text and any(_norm(n) in text for n in names):
                mapping.setdefault(field, c)
                break
    return mapping


def _read_rows(path: Path, sheet=None):
    if path.suffix.lower() in ('.xlsx', '.xlsm'):
        try:
            import openpyxl
        except ImportError:
            raise SystemExit('[audio_lib] 讀 .xlsx 需要 openpyxl：pip install openpyxl')
        wb = openpyxl.load_workbook(path, data_only=True)
        ws = wb[sheet] if sheet else wb.worksheets[0]
        return [['' if v is None else str(v).strip() for v in r]
                for r in ws.iter_rows(values_only=True)]
    if path.suffix.lower() in ('.csv', '.tsv'):
        import csv
        delim = '\t' if path.suffix.lower() == '.tsv' else ','
        with path.open(encoding='utf-8-sig', newline='') as fh:
            return [[c.strip() for c in r] for r in csv.reader(fh, delimiter=delim)]
    raise SystemExit('[audio_lib] 規格表只支援 .xlsx/.csv/.tsv：%s' % path.name)


def read_spec(path, sheet=None) -> list:
    """讀規格表，回傳 list of dict。

    容許：表頭跨列、章節標題列（MAIN GAME / FREE GAME）、空白列、
    「檔名」欄寫成 `X_1~3` 這種一列代表多支的寫法（保留原字串，由對帳處理）。
    """
    path = Path(path)
    rows = _read_rows(path, sheet)
    head = next((i for i, r in enumerate(rows)
                 if any('檔名' in _norm(c) or _norm(c) in ('filename', 'file')
                        for c in r)), None)
    if head is None:
        raise SystemExit('[audio_lib] 規格表找不到「檔名」欄，無法解析')
    mapping = _map_columns(rows[head:head + 3])
    if 'filename' not in mapping:
        raise SystemExit('[audio_lib] 規格表找不到「檔名」欄，無法解析')

    def cell(row, field):
        c = mapping.get(field)
        return row[c].strip() if c is not None and c < len(row) else ''

    out, section = [], ''
    for row in rows[head + 1:]:
        if not any(row):
            continue
        first = row[0].strip() if row else ''
        if not cell(row, 'filename'):
            # 只有一兩欄有字 -> 視為章節標題列（MAIN GAME / FREE GAME）
            if first and len([c for c in row if c.strip()]) <= 2:
                section = first
            continue
        out.append({
            'section': section,
            'no': cell(row, 'no'),
            'scene': cell(row, 'scene'),
            'kind': cell(row, 'kind'),
            'filename': cell(row, 'filename'),
            'melody': cell(row, 'melody'),
            'loop': cell(row, 'loop'),
            'power': cell(row, 'power'),
            'length': cell(row, 'length'),
            'desc': cell(row, 'desc'),
            'ref_video': cell(row, 'ref_video'),
            'ref_time': cell(row, 'ref_time'),
            'ref_sound': cell(row, 'ref_sound'),
            'note': cell(row, 'note'),
        })
    return out


def spec_seconds(text):
    """'30~40' -> 40.0；'5+8+10' -> 23.0；'1.5s' -> 1.5；讀不出來 None。"""
    t = str(text or '').replace('s', '').replace('秒', '').strip()
    if not t:
        return None
    nums = re.findall(r'[\d.]+', t)
    if not nums:
        return None
    if '+' in t:
        return round(sum(float(n) for n in nums), 2)
    return float(nums[-1])


def expand_spec_filename(name: str):
    """'X_1~3' -> ['X_1','X_2','X_3']；其餘回 [name]。"""
    m = re.match(r'^(.*?)(\d+)\s*~\s*(\d+)$', name.strip())
    if not m:
        return [name.strip()]
    head, a, b = m.group(1), int(m.group(2)), int(m.group(3))
    if b < a or b - a > 20:
        return [name.strip()]
    return ['%s%d' % (head, i) for i in range(a, b + 1)]


def is_loop(spec_row) -> bool:
    return str(spec_row.get('loop', '')).strip().upper() in ('O', 'YES', 'TRUE', '1', 'V')


def is_music(spec_row) -> bool:
    """類型含「音樂」且不含「音效」，或檔名有 _BGM_ -> 走 BGM group / playMusic。"""
    kind = str(spec_row.get('kind', ''))
    if '_BGM_' in str(spec_row.get('filename', '')).upper():
        return True
    return ('音樂' in kind or 'music' in kind.lower()) and '音效' not in kind


def suggest_volume(spec_row) -> float:
    """volume 一律 1。

    規格的「強度」欄是音色設計的相對強弱（音效師混音時就做進音檔了），
    不是播放音量，拿它推 volume 只會讓每支音都偏掉一點、又沒有依據。
    真正的音量平衡請在遊戲內 AudioMixer 面板調，調完用
    `SoundManager.exportAudioMixerJsonFile()` 匯出回寫。
    """
    return 1.0


# --------------------------------------------------------------------------- #
# 專案內位置
# --------------------------------------------------------------------------- #
def bundle_dir(root: Path, name=DEFAULT_BUNDLE) -> Path:
    """已存在就用既有位置，否則有 assets/Bundle 放它底下，沒有就放 assets 底下。"""
    root = Path(root)
    for cand in (root / 'assets' / name, root / 'assets' / 'Bundle' / name):
        if cand.is_dir():
            return cand
    base = root / 'assets' / 'Bundle'
    if not base.is_dir():
        base = root / 'assets'
    return base / name


def game_code(root: Path):
    """從 assets/Game/Script/G####_*.ts 或場景名推遊戲代號（G1028）。"""
    root = Path(root)
    for p in sorted((root / 'assets' / 'Game').rglob('G[0-9][0-9][0-9][0-9]_*.ts')):
        m = re.match(r'^(G\d{4})_', p.name)
        if m:
            return m.group(1)
    for p in sorted((root / 'assets' / 'Game').rglob('*.scene')):
        m = re.search(r'(G\d{4})', p.name)
        if m:
            return m.group(1)
    return None


def game_name(root: Path):
    """Scene_G1028_WildFrontier.scene -> WildFrontier。"""
    for p in sorted((Path(root) / 'assets' / 'Game').rglob('*.scene')):
        m = re.match(r'^Scene_G\d{4}_(.+)\.scene$', p.name)
        if m:
            return m.group(1)
    return None


def main_scene(root: Path):
    scenes = sorted((Path(root) / 'assets' / 'Game').rglob('Scene_*.scene'))
    return scenes[0] if scenes else None


def sound_dir(root: Path) -> Path:
    """AudioMixer json 與隨場景載入的 BGM 放這裡（與 BrawlRooster 一致）。"""
    return Path(root) / 'assets' / 'Game' / 'game' / 'Sound'


def manifest_path(root: Path) -> Path:
    return Path(root) / 'audio_data' / 'audio_manifest.json'


def load_manifest(root: Path) -> dict:
    p = manifest_path(root)
    if not p.is_file():
        raise SystemExit('[audio_lib] 找不到 %s，請先跑 audio_manifest.py' % p)
    return load_json(p)


def overrides_path(root: Path) -> Path:
    return Path(root) / 'audio_data' / 'audio_overrides.json'


def load_overrides(root: Path) -> dict:
    """人工覆寫規格推導出來的 mixer 值。

    規格表偶爾會填錯（例如 Intro 的 LOOP 欄標 O，但它必須播一次就接 Loop）。
    這種偏差寫在 audio_data/audio_overrides.json，讓產生器與驗收都認同一份，
    而不是去手改產生出來的 json —— 手改的下次重跑就沒了、也查不到理由。

        {
          "clips": {
            "MG_BGM_Intro": {"loop": 0, "_why": "Intro 播一次就接 Loop，規格 LOOP 欄填錯"}
          }
        }
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    data = load_json(p)
    return data.get('clips', data if 'aliases' not in data else {}) or {}


def load_groups(root: Path) -> dict:
    """mixer 的 Group 定義，順便指定哪些 clip 屬於該 group。

        "groups": {
          "WIN": {"volume": 1, "limit": 0, "limitType": "first",
                  "clips": ["MG_MIX_BigWinLoop"]}
        }

    `clips` 只是給產生器用的歸屬清單，不會寫進 json 的 Group 區。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    return load_json(p).get('groups', {}) or {}


def load_ducks(root: Path) -> dict:
    """Duck 設定：某個 group 在播的時候，把另一個 group 壓低。

        "duck": {"WIN": {"BGM": {"volCut": -90, "begUnduck": 100, "unduckTime": 1}}}

    volCut 單位是 dB（-90 約等於靜音）；begUnduck 是「觸發音播放進度的百分比」，
    到了才開始用 unduckTime 秒淡回。語意見 AudioMixerStructure.DuckedGroup。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    return load_json(p).get('duck', {}) or {}


def load_aliases(root: Path) -> dict:
    """把底層寫死的 clip key 指到這台遊戲的某支音檔。

    底層會主動呼叫 wheel_stop / CM_Spin / trigger_alarm1 這些 key（見 RESERVED_KEYS）。
    清單裡沒有同名 clip 就完全沒聲音。用 alias 把它們指到自己的音檔，
    比繞過底層自己播安全，而且不用改 submodule。

        {
          "aliases": {
            "wheel_stop": {"target": "MG_SFX_ReelStop_1", "_why": "底層停輪音 fallback"},
            "CM_Spin":    {"target": "MG_SFX_SpinStart"}
          }
        }

    也可以簡寫成 {"wheel_stop": "MG_SFX_ReelStop_1"}。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    raw = load_json(p).get('aliases', {}) or {}
    out = {}
    for key, val in raw.items():
        out[key] = {'target': val} if isinstance(val, str) else dict(val)
    return out

# -*- coding: utf-8 -*-
"""驗收：把「音檔 / AudioMixer json / AudioClipList.prefab / 程式引用 / 場景接線」
五邊對齊起來檢查。任何一邊漏掉，症狀都是「沒聲音但也沒錯誤」。

檢查項目：
  1. bundle 目錄的 isBundle（沒設 -> 整包載不到）
  2. prefab 清單裡的 audioClip uuid 是否真的指到存在的音檔
  3. prefab 清單 vs AudioMixer json：json 沒有的 clip 會用預設值（volume 1、不 loop）
  4. loop clip 是否真的設了 loop: -1（漏掉 -> BGM 只播一次就沒了）
  5. 場景的 AudioMixerFileLoader.audioMixerFile 有沒有接（null -> 整份混音設定沒生效）
  6. 程式裡 play()/playMusic() 的字串字面值是否都在清單內（打錯字只會印 warn）
  7. clip key 是否撞到底層保留 key

退出碼：0 全過、1 有錯。
用法： python check_audio.py
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import audio_lib as L  # noqa: E402

MIXER_LOADER_TS = 'assets/CommonModule/Script/Manager/AudioTool/AudioMixerFileLoader.ts'
CONTAINER_TS = 'assets/CommonModule/Script/Audio/AudioClipContainer.ts'
PLAY_RE = re.compile(r"audioManager\s*\.\s*(play|playMusic|playOn|stop)\s*\(\s*'([^']+)'")
PLAY_RE2 = re.compile(r"SoundManager\.instance\s*\.\s*(play|playMusic|playOn)\s*\(\s*'([^']+)'")


def prefab_clips(prefab: Path):
    """回傳 [(clipName, uuid)]，把所有 AudioClipContainer 的清單合起來。"""
    if not prefab.is_file():
        return None
    data = L.load_json(prefab)
    out = []
    for o in data:
        if isinstance(o, dict) and o.get('__type__') == 'CommonAudioSetting':
            out.append((o.get('clipName', ''), (o.get('audioClip') or {}).get('__uuid__')))
    return out


def split_severity(items, own_keys):
    """屬於這台遊戲的 clip 沒接好是錯；共用清單那些名字在參考專案本來就多半是空的。"""
    mine = [n for n in items if n in own_keys]
    others = [n for n in items if n not in own_keys]
    return mine, others


def asset_uuid_index(root: Path):
    """{uuid: 相對路徑}，只掃音檔的 .meta。"""
    idx = {}
    for meta in (root / 'assets').rglob('*.meta'):
        if meta.suffix != '.meta':
            continue
        asset = Path(str(meta)[:-5])
        if asset.suffix.lower() not in L.AUDIO_EXT:
            continue
        u = L.read_meta_uuid(asset)
        if u:
            idx[u] = str(asset.relative_to(root)).replace('\\', '/')
    return idx


def scene_mixer_wired(root: Path):
    """回傳 (是否接上, 說明)。"""
    scene = L.main_scene(root)
    if not scene:
        return None, '找不到 assets/Game/**/Scene_*.scene'
    try:
        type_id = L.script_type_id(root, MIXER_LOADER_TS)
    except SystemExit:
        return None, '找不到 AudioMixerFileLoader.ts.meta'
    data = json.loads(scene.read_text(encoding='utf-8'))
    comps = [o for o in data if isinstance(o, dict) and o.get('__type__') == type_id]
    if not comps:
        return False, '%s 裡沒有 AudioMixerFileLoader 元件' % scene.name
    wired = [c for c in comps if (c.get('audioMixerFile') or {}).get('__uuid__')]
    if not wired:
        return False, '%s 的 AudioMixerFileLoader.audioMixerFile = null' % scene.name
    return True, '%s 已接 uuid=%s' % (scene.name, wired[0]['audioMixerFile']['__uuid__'][:8])


def code_refs(root: Path):
    """遊戲層程式裡出現的 clip 字串字面值 -> [檔案:行]。"""
    refs = {}
    game = root / 'assets' / 'Game'
    if not game.is_dir():
        return refs
    for ts in game.rglob('*.ts'):
        try:
            text = ts.read_text(encoding='utf-8')
        except Exception:
            continue
        for i, line in enumerate(text.splitlines(), 1):
            if line.lstrip().startswith('//'):
                continue
            for rx in (PLAY_RE, PLAY_RE2):
                for m in rx.finditer(line):
                    refs.setdefault(m.group(2), []).append(
                        '%s:%d' % (ts.relative_to(root).as_posix(), i))
    return refs


def main():
    L.utf8_stdout()
    ap = argparse.ArgumentParser()
    ap.add_argument('--root', default=None)
    ap.add_argument('--bundle', default=L.DEFAULT_BUNDLE)
    args = ap.parse_args()

    root = Path(args.root) if args.root else L.find_project_root(Path.cwd())
    errs, warns, oks = [], [], []
    aliases = L.load_aliases(root)
    try:
        own_keys = {c['key'] for c in L.load_manifest(root)['clips']} | set(aliases)
    except SystemExit:
        own_keys = set(aliases)

    # 1 bundle
    bdir = L.bundle_dir(root, args.bundle)
    bmeta = Path(str(bdir) + '.meta')
    if not bdir.is_dir():
        errs.append('找不到 bundle 目錄 %s' % bdir.relative_to(root))
    elif not bmeta.is_file() or not L.load_json(bmeta).get('userData', {}).get('isBundle'):
        errs.append('%s.meta 的 userData.isBundle 沒設 -> 整包載不到' % bdir.name)
    else:
        oks.append('bundle %s isBundle = true' % bdir.relative_to(root))

    # 2/3 prefab vs 音檔 vs mixer json
    prefab = bdir / 'Prefab' / 'AudioClipList.prefab'
    pc = prefab_clips(prefab)
    if pc is None:
        errs.append('找不到 %s' % prefab.relative_to(root))
        pc = []
    else:
        uidx = asset_uuid_index(root)
        # 同一個 clipName 只要有任一筆接好就算接好（SoundManager 會跳過沒接的那筆），
        # 共用清單常留著同名的空欄位佔位
        wired = {n for n, u in pc if u and u in uidx}
        empty = [n for n, u in pc if not u and n not in wired]
        dangling = [n for n, u in pc if u and u not in uidx and n not in wired]
        for label, items in (('沒有接音檔', empty), ('的 audioClip 指到不存在的資產', dangling)):
            mine, others = split_severity(items, own_keys)
            if mine:
                errs.append('prefab 有 %d 筆「這台遊戲的」clip %s：%s'
                            % (len(mine), label, '、'.join(mine[:8])))
            if others:
                warns.append('prefab 有 %d 筆共用/舊 clip %s：%s…'
                             '（共用清單在參考專案也多半是空的，只是佔名字；'
                             '只有這台真的要播才需要接）'
                             % (len(others), label, '、'.join(others[:6])))
        # 只有「真的接了音檔」的才算重複；沒接的空欄位在 SoundManager 會被跳過
        dup = {}
        for n, u in pc:
            if u:
                dup[n] = dup.get(n, 0) + 1
        dups = [k for k, v in dup.items() if v > 1]
        if dups:
            errs.append('prefab 有重複 clipName（後面的會蓋掉前面）：%s' % '、'.join(dups))
        mine_ok = [n for n, u in pc if n in own_keys and u and u in uidx]
        if own_keys and len(mine_ok) == len(own_keys & {n for n, _ in pc}):
            oks.append('prefab 裡這台遊戲的 %d 筆 clip 全部指到存在的音檔' % len(mine_ok))

    mixer = sorted(L.sound_dir(root).glob('AudioMixer*.json'))
    mix_clips = {}
    if not mixer:
        errs.append('找不到 assets/Game/game/Sound/AudioMixer*.json'
                    ' -> 全部 clip 走預設值（volume 1、不 loop、無群組）')
    else:
        if len(mixer) > 1:
            warns.append('有 %d 份 AudioMixer json，場景只會載一份：%s'
                         % (len(mixer), '、'.join(p.name for p in mixer)))
        mix_clips = L.load_json(mixer[0]).get('Clips', {})
        oks.append('%s：%d 筆 clip 設定' % (mixer[0].name, len(mix_clips)))
        # ⚠️ mixer json 的 key 是「音檔資產名」，不是 clipName
        # （SoundManager.play 走 playMixerClip(audioClip.name)）
        asset_name = {}   # clipName -> 資產名
        for n, u in pc:
            if u and u in uidx:
                asset_name[n] = Path(uidx[u]).stem
        bad_key = [k for k in mix_clips
                   if k in asset_name and asset_name[k] != k]
        if bad_key:
            errs.append('mixer json 有 %d 個 key 是 clipName 而不是音檔資產名，'
                        '這些設定不會生效：%s'
                        % (len(bad_key), '、'.join(bad_key[:8])))
        no_setting = sorted({a for a in asset_name.values()} - set(mix_clips))
        if no_setting:
            warns.append('有音檔、mixer json 沒設定（會用預設值 volume 1 / 不 loop）%d 筆：%s'
                         % (len(no_setting), '、'.join(no_setting[:10])))

    # 4 loop
    try:
        man = L.load_manifest(root)
    except SystemExit:
        man = None
        warns.append('沒有 audio_manifest.json，跳過 loop / 保留 key 檢查')
    if man:
        ov = L.load_overrides(root)
        for c in man['clips']:
            if not c['has_file']:
                continue
            stem = c.get('asset_stem') or c['stem']
            spec_ov = ov.get(stem) or ov.get(c['key']) or {}
            want_loop = spec_ov.get('loop', -1 if c['loop'] else 0)
            got_loop = mix_clips.get(stem, {}).get('loop')
            if 'loop' in spec_ov:
                if got_loop != want_loop:
                    errs.append('`%s` overrides 要 loop=%r，但 mixer json 是 %r'
                                % (stem, want_loop, got_loop))
            elif c['loop'] and got_loop != -1:
                errs.append('`%s` 規格是 LOOP，但 mixer json（key=資產名）的 loop 不是 -1'
                            '（只會播一次）' % stem)
            if c['key'] in L.RESERVED_KEYS:
                warns.append('`%s` 撞到底層保留 key（%s）'
                             % (c['key'], L.RESERVED_KEYS[c['key']]))
        names_in_prefab = {n for n, _ in pc}
        for alias, spec in sorted(aliases.items()):
            why = L.RESERVED_KEYS.get(alias, spec.get('_why', ''))
            if alias in names_in_prefab:
                oks.append('alias `%s` -> `%s`%s'
                           % (alias, spec.get('target'), '（%s）' % why if why else ''))
            else:
                errs.append('alias `%s` 不在 clip 清單裡，請重跑 update_clip_list.py --apply'
                            % alias)

    # 5 場景接線
    wired, why = scene_mixer_wired(root)
    if wired is None:
        warns.append(why)
    elif not wired:
        errs.append('%s -> 混音設定完全沒生效' % why)
    else:
        oks.append(why)
        if mixer:
            want = L.read_meta_uuid(mixer[0])
            scene = L.main_scene(root)
            if want and want not in scene.read_text(encoding='utf-8'):
                errs.append('場景接的 json 不是 %s（uuid 對不上）' % mixer[0].name)

    # 5b 場景上的 AudioClipContainer：--bgm scene 的音檔要掛在這裡，
    #    否則它們既不在 bundle prefab、也沒人餵給 SoundManager -> 完全播不到
    scene = L.main_scene(root)
    if man and scene:
        outside = [c for c in man['clips']
                   if c['has_file'] and c.get('asset')
                   and '/%s/' % args.bundle not in c['asset']
                   and not c['asset'].startswith('assets/%s/' % args.bundle)]
        if outside:
            try:
                cont_id = L.script_type_id(root, CONTAINER_TS)
            except SystemExit:
                cont_id = None
            text = scene.read_text(encoding='utf-8')
            uncovered = [c for c in outside if c['uuid'] not in text]
            if cont_id and cont_id not in text:
                errs.append('有 %d 支音檔放在 bundle 外（%s…），但場景上沒有 AudioClipContainer '
                            '可以餵給 SoundManager -> 這些音完全播不到'
                            % (len(outside), outside[0]['key']))
            elif uncovered:
                errs.append('有 %d 支音檔放在 bundle 外但場景的 AudioClipContainer 沒引用到，'
                            '播不出來：%s'
                            % (len(uncovered), '、'.join(c['key'] for c in uncovered[:6])))
            else:
                oks.append('bundle 外的 %d 支音檔都掛在場景的 AudioClipContainer 上' % len(outside))

    # 5c 場景 / prefab 的 audioKey 欄位（SymbolShowSetting、DropSymbolPrefabItems…）
    #    那些欄位吃的是 clipName；填成音檔資產名或打錯字都只會印 warn，不會報錯
    names_all = {n for n, _ in pc}
    if scene:
        targets = [scene] + sorted((root / 'assets' / 'Game').rglob('*.prefab'))
        bad, total = [], 0
        for f in targets:
            try:
                data = json.loads(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            for o in data:
                if not isinstance(o, dict):
                    continue
                for field in ('audioKey', 'audioName', 'clipName'):
                    v = o.get(field)
                    if isinstance(v, str) and v and field != 'clipName':
                        total += 1
                        if v not in names_all:
                            bad.append('%s 的 %s="%s"' % (f.name, field, v))
        if bad:
            errs.append('場景/prefab 有 %d 個 audioKey 不在 clip 清單裡（播不出來）：%s'
                        % (len(bad), '、'.join(bad[:6])))
        elif total:
            oks.append('場景/prefab 的 %d 個 audioKey 都對得到 clip' % total)

    # 6 程式引用
    names = {n for n, _ in pc}
    refs = code_refs(root)
    unknown = {k: v for k, v in refs.items() if k not in names and k not in mix_clips}
    if unknown:
        warns.append('程式裡用到不在清單裡的 clip 名（play 只會印 warn，不會報錯）：\n    '
                     + '\n    '.join('`%s`  %s' % (k, v[0]) for k, v in sorted(unknown.items())))
    elif refs:
        oks.append('程式裡 %d 個字面值 clip 名都在清單內' % len(refs))
    if refs:
        warns.append('有 %d 處直接寫字串播音效，建議改用 <G####>_AudioClipNames.ts 的常數：%s'
                     % (sum(len(v) for v in refs.values()),
                        '、'.join(sorted(refs)[:6])))

    print('# 音效接線驗收')
    print('')
    for o in oks:
        print('- ✅ %s' % o)
    for w in warns:
        print('- ⚠️ %s' % w)
    for e in errs:
        print('- ❌ %s' % e)
    print('')
    print('結果：%d 過、%d 警告、%d 錯誤' % (len(oks), len(warns), len(errs)))
    return 1 if errs else 0


if __name__ == '__main__':
    sys.exit(main())

