def find_project_root(start: Path) -> Path:
    """往上找到含 assets/ 的專案根。"""
    cur = Path(start).resolve()
    for p in [cur, *cur.parents]:
        if (p / 'assets').is_dir() and (
            (p / 'project.json').is_file() or (p / 'assets' / 'Game').is_dir()
        ):
