def find_project_root(start: Path) -> Path:
    """往上找到含 assets/ 的專案根。"""
    cur = Path(start).resolve()
    for p in [cur, *cur.parents]:
        if (p / 'assets').is_dir() and (
            (p / 'project.json').is_file() or (p / 'assets' / 'Game').is_dir()
        ):
            return p
    raise SystemExit('[audio_lib] 找不到專案根（從 %s 往上找）' % start)


def load_json(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def dump_json(data) -> str:
    return json.dumps(data, ensure_ascii=False, indent=2) + '\n'


def dump_mixer_json(data) -> str:
    """AudioMixer json 沿用底層匯出時的 4 空白縮排，方便與人工匯出的檔比對。"""
    return json.dumps(data, ensure_ascii=False, indent=4) + '\n'


def new_uuid() -> str:
    return str(_uuid.uuid4())


# --------------------------------------------------------------------------- #
# Cocos 壓縮 uuid（prefab / scene 裡 script 元件的 __type__）
# --------------------------------------------------------------------------- #
_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'


def compress_uuid(raw: str) -> str:
    """'987b65d4-a5ab-4d73-9111-7a38c8a625cc' -> '987b6XUpatNc5ERejjIpiXM'

    前 5 個 hex 原樣保留，剩下 27 個 hex 每 3 個（12 bits）編成 2 個 base64 字元。
    """
    hex_str = raw.replace('-', '')
    if len(hex_str) != 32:
        raise ValueError('不是 32 碼 uuid: %s' % raw)
    out = [hex_str[:5]]
    for i in range(5, 32, 3):
        n = int(hex_str[i:i + 3], 16)
        out.append(_B64[n >> 6] + _B64[n & 63])
    return ''.join(out)


def script_type_id(root: Path, ts_rel: str) -> str:
    """讀 <ts>.meta 的 uuid 並壓縮成 prefab / scene 裡的 __type__。"""
    meta = Path(root) / (ts_rel + '.meta')
    if not meta.is_file():
        raise SystemExit('[audio_lib] 找不到 %s' % meta)
    return compress_uuid(load_json(meta)['uuid'])


