  );
  // 消除的 Bingo 播到 CLEAR_DIM_RESTORE_RATIO（檔頭常數，WildFrontier = 2/3）時還原
  // （getBingoAnimDuration 內含 runtime data 未載入時的 fallback）
  const dimRestoreDelay =
    (this.dropSymbolPrefabCtrl?.getBingoAnimDuration(bingoSymbol) ?? 0) * CLEAR_DIM_RESTORE_RATIO;
  waitForSeconds(dimRestoreDelay).then(() => {
    // 被新的一手接手就不動：新的一手可能已經在聽牌壓暗，還原會把它清掉
    if (!this.isStaleEpoch(epoch)) wheelCtrl?.restoreDimmedSymbols?.();
  });
  const clearDone = this.startClear(bingoSymbol);
  // …金框 Bingo → Wild 鏈…
  await Promise.all([clearDone, postWinChainDone]);
  if (this.isStaleEpoch(epoch)) return;
  wheelCtrl?.restoreDimmedSymbols?.(); // 保險：正常已在 Bingo 播到該比例時還原
  // …掉落…
```

其他專案的 cascade 流程名稱不同時，找「呼叫 `DropModule.setClearEffect`（消除演出）」與「呼叫 `dropSingleWheel`／`drop`（掉落）」的位置：前者之前壓暗、後者之前還原。「中獎但不消除」的格子依該遊戲協定決定（沒有就傳空陣列）。

## 4. SymbolShowPrefabController 端：三個掛勾

`GXXXX_SymbolShowPrefabController extends SymbolShowPrefabController`。沒有這個子類的話要新建，並確認場景上 SymbolShowPrefab 節點掛的是它（用 MCP 換腳本，或請使用者在 Inspector 換）。

```ts
import {GXXXX_WheelBlockController} from './GXXXX_WheelBlockController';

  /** 這一格目前掛著的一般停輪動畫節點（沒有或已關閉回 null）。給聽牌壓暗用 */
  public getStopAnimNode(wheelIndex: number, visibleRowIdx: number): Node | null {
    const wheel = this.wheelBlockControllerEx?.wheelAry?.[wheelIndex];
    const node =
      this.symbolShowInfoAry?.[wheelIndex]?.[
        visibleRowIdx + (wheel?.outOfTopSymbolAmount ?? 0)
      ]?.wheelStopAnimaPrefabTform;
    return node?.isValid && node.active ? node : null;
  }

  // ① 生完停輪動畫：通知 Controller 補壓（已有 override 的話，加在 super 之後最後面）
  protected spawnWheelStopAnimaPrefab(wheelCtrlIndex: number, wheelIndex: number, sortedSymbolAry: Symbol[]): void {
    super.spawnWheelStopAnimaPrefab(wheelCtrlIndex, wheelIndex, sortedSymbolAry);
    (this.wheelBlockControllerEx as GXXXX_WheelBlockController)?.onStopAnimSpawned?.(wheelIndex);
  }

  // ② 停輪動畫還給物件池之前：先還原顏色（加在 override 最前面）
  protected hideStopAnimaPrefab(wheelIndex: number, sortedIndex: number, showSymbol = false): void {
    const info = this.symbolShowInfoAry?.[wheelIndex]?.[sortedIndex];
    if (!info) return;
    this._undim(info.wheelStopAnimaPrefabTform);
    super.hideStopAnimaPrefab(wheelIndex, sortedIndex, showSymbol);
  }

  // ③ 若有自己直接 despawn 的路徑（例如 _forceDespawn），一樣先 _undim(node)

  private _undim(node: Node | null): void {
    (this.wheelBlockControllerEx as GXXXX_WheelBlockController)?.undimNode?.(node);
  }
```

`wheelBlockControllerEx` 在場景檔裡可能是 null、但透過 `cc.TargetOverrideInfo` 接上（WildFrontier 就是），要用 MCP `component_get_component_info` 看 live 值，不要只看 `.scene`。

## 5. 黑張 prefab 設定

| 項目 | 建議值 | 為什麼 |
|------|--------|--------|
| 圖 | `default_sprite_splash`（`7d8f9b89-4fd1-4c9f-a3ab-38ec7cded7ca@f9941`） | 2×2 純白、直角。`default_sprite`（新建 Sprite 預設圖）是 40×36 圓角佔位圖，四角透明，拉伸後圓角跟著放大 |
| Sprite sizeMode | Custom（0） | 換圖不會把尺寸改成圖的大小 |
| 顏色 | 黑 (0,0,0,255) | 白圖 × 黑 = 黑 |
| UIOpacity | 依美術（WildFrontier 180） | 半透明時兩張重疊處會更深，接縫會出現深色細線 |
| 尺寸 | ≈ 一格的格距（左右 = 相鄰輪中心距、上下 = 同輪符號距） | 用 `inspect_dim_mask_setup.js` 第 4 段試算接縫。WildFrontier 使用者最後選 125×91 |
| 節點位置 | WheelMaskController 節點要排在 WheelBlock **之前** | 之前 = 畫在圖騰底下；之後 = 蓋在圖騰上面 |

改 prefab 的 MCP 步驟見 `pitfalls.md` 第 6 點。

#!/usr/bin/env node
/**
 * 聽牌壓暗＋黑張底：動手前的現況檢查（只讀，不改任何檔案）。
 *
 * 列出六件「看程式看不出來、但決定做法對不對」的事：
 *   1. 場景上的 WheelMaskController：有沒有、mask prefab / maskPool 有沒有接、節點排在 WheelBlock 前還是後
 *      （排在前面 = 黑張畫在圖騰底下；排在後面 = 蓋在圖騰上面，那就不是「底」了）
 *   2. bingo.useWheelMask 的值（各 HostSetting json）——它是報獎用的全域開關，聽牌功能不要靠打開它
 *   3. 黑張 prefab 的尺寸、顏色、透明度、用的圖（default_sprite 是圓角佔位圖，拉伸後四角透明）
 *   4. 每輪的實際格距（左右：相鄰輪中心距；上下：同輪相鄰符號距）與各尺寸下的接縫（重疊／縫隙）
 *   5. 哪些符號有 offClipping 上層複本、哪些有停輪動畫（決定壓暗要不要處理複本與動畫）
 *   6. 遊戲層 Controller / SymbolShowPrefabController 是否已經有壓暗相關程式
 *
 * 用法（在專案根目錄）：
 *   node .claude/skills/slot-prewin-dim-mask/scripts/inspect_dim_mask_setup.js \
 *     [--scene assets/Game/Scene/Scene_GXXXX_Name.scene] \
 *     [--prefab assets/Game/Prefab/WheelBlock.prefab] \
 *     [--sizes "120x90,124x91"]      # 額外想試算接縫的黑張尺寸
 */
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const arg = (k, d = null) => {
  const i = args.indexOf(k);
  return i >= 0 ? args[i + 1] : d;
};
const ROOT = process.cwd();

// ── uuid 壓縮／解壓縮（Cocos 3.x：前 5 碼 hex 保留，其餘每 3 個 hex = 2 個 base64 字元） ──
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function compressUuid(uuid) {
  const hex = uuid.replace(/-/g, '');
  let out = hex.slice(0, 5);
  for (let i = 5; i < 32; i += 3) {
    const v = parseInt(hex.substr(i, 3), 16);
    out += B64[v >> 6] + B64[v & 63];
  }
  return out;
}

function walk(dir, test, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, {withFileTypes: true})) {
    if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, test, out);
    else if (test(e.name, p)) out.push(p);
  }
  return out;
}
const rel = p => path.relative(ROOT, p).replace(/\\/g, '/');
const load = p => (p && fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null);

// 腳本 uuid（壓縮後）→ 類別檔名；資源 uuid → 路徑
const scriptByType = {};
const assetByUuid = {};
for (const m of walk(path.join(ROOT, 'assets'), n => n.endsWith('.meta'))) {
  try {
    const u = JSON.parse(fs.readFileSync(m, 'utf8')).uuid;
    if (!u) continue;
    const file = rel(m).replace(/\.meta$/, '');
    assetByUuid[u] = file;
    if (file.endsWith('.ts')) scriptByType[compressUuid(u)] = path.basename(file, '.ts');
  } catch (_) { /* ignore */ }
}
const typeOf = t => scriptByType[t] || t;

const scenePath =
  arg('--scene') ||
  walk(path.join(ROOT, 'assets/Game'), n => n.endsWith('.scene'))[0];
const prefabPath =
  arg('--prefab') ||
  walk(path.join(ROOT, 'assets/Game'), n => /^WheelBlock.*\.prefab$/.test(n))[0];
const scene = load(scenePath);
const wheelPrefab = load(prefabPath);
console.log(`scene : ${scenePath ? rel(scenePath) : '(找不到)'}`);
console.log(`prefab: ${prefabPath ? rel(prefabPath) : '(找不到)'}\n`);
if (!scene) process.exit(1);

const nodePath = id => {
  const parts = [];
  while (id !== undefined && id !== null && scene[id]) {
    parts.unshift(scene[id]._name || '(prefab)');
    id = scene[id]._parent ? scene[id]._parent.__id__ : null;
  }
  return parts.join('/');
};
const prefabInstanceName = n => {
  if (n._name || !n._prefab) return n._name;
  const pi = scene[n._prefab.__id__];
  const asset = pi && pi.asset && pi.asset.__uuid__;
  return `(prefab ${asset && assetByUuid[asset] ? path.basename(assetByUuid[asset]) : asset})`;
};

// ── 1. WheelMaskController ──
console.log('== 1. 場景上的 WheelMaskController ==');
const maskCtrls = scene
  .map((o, i) => ({o, i}))
  .filter(({o}) => o && typeof o.__type__ === 'string' && typeOf(o.__type__) === 'WheelMaskController');
let maskPrefabPath = null;
if (maskCtrls.length === 0) {
  console.log('  （沒有）→ 要先在 GameRoot 下、WheelBlock 之前建一個節點，掛 WheelMaskController + SpawnPool，');
  console.log('    並接到 AwardController.showFrameObj[0].wheelMaskControllerEx（用 Cocos MCP）');
}
for (const {o, i} of maskCtrls) {
  const nodeId = o.node.__id__;
  const maskUuid = o.mask && o.mask.__uuid__;
  maskPrefabPath = maskUuid ? assetByUuid[maskUuid] || maskUuid : null;
  const pool = o.maskPool && o.maskPool.__id__ !== undefined ? scene[o.maskPool.__id__] : null;
  console.log(`  #${i} 節點 ${nodePath(nodeId)}`);
  console.log(`     mask     = ${maskPrefabPath || '（沒接）'}`);
  console.log(`     maskPool = ${pool ? typeOf(pool.__type__) + '（已接）' : '（沒接）'}`);
  const refBy = scene
    .map((x, j) => ({x, j}))
    .filter(({x}) => x && x.wheelMaskControllerEx && x.wheelMaskControllerEx.__id__ === i);
  console.log(`     被 ${refBy.length ? refBy.map(({x, j}) => `#${j} ${typeOf(x.__type__)}.wheelMaskControllerEx`).join('、') : '（沒有任何 ShowFrameObj 參照 → 程式從 awardController.showFrameObj[0] 拿不到它）'}`);
  const parent = scene[scene[nodeId]._parent.__id__];
  const sibs = parent._children.map(c => ({id: c.__id__, name: prefabInstanceName(scene[c.__id__])}));
  const me = sibs.findIndex(s => s.id === nodeId);
  const wb = sibs.findIndex(s => /WheelBlock(?!BG)/i.test(s.name));
  console.log(`     同層順序：${sibs.map((s, k) => (k === me ? `[${s.name}]` : s.name)).join(', ')}`);
  if (wb >= 0) {
    console.log(me < wb
      ? '     → 排在 WheelBlock 之前：黑張畫在圖騰「底下」✔'
      : '     → 排在 WheelBlock 之後：黑張會「蓋住」圖騰，若要當底版要調整節點順序');
  } else {
    console.log('     → 同層找不到名稱含 WheelBlock 的節點（可能是沒改名的 prefab 實例），請在 Editor 確認它在轉輪之前');
  }
}
console.log();

// ── 2. useWheelMask ──
console.log('== 2. bingo.useWheelMask（報獎用的全域開關，聽牌功能不要靠它）==');
for (const f of walk(path.join(ROOT, 'assets/Game'), n => /HostSetting.*\.json$/i.test(n))) {
  const m = fs.readFileSync(f, 'utf8').match(/"useWheelMask"\s*:\s*(true|false)/);
  console.log(`  ${rel(f)}: ${m ? m[1] : '（沒有這個欄位）'}`);
}
console.log('  ※ true 時 AwardSet.init 會為每格 spawnMask、報獎時 showWheelMask 會用同一批黑張；聽牌自己生的黑張與它分開管理\n');

// ── 3. 黑張 prefab ──
const DEFAULT_SPRITE = '57520716-48c8-4a19-8acf-41c9f8777fb0';
const SPLASH = '7d8f9b89-4fd1-4c9f-a3ab-38ec7cded7ca';
let maskSize = null;
console.log('== 3. 黑張 prefab ==');
const mp = maskPrefabPath && fs.existsSync(path.join(ROOT, maskPrefabPath)) ? load(path.join(ROOT, maskPrefabPath)) : null;
