    if (o.__type__ === 'cc.Sprite') {
      const f = o._spriteFrame && o._spriteFrame.__uuid__ ? o._spriteFrame.__uuid__.split('@')[0] : null;
      const name = f === DEFAULT_SPRITE ? 'default_sprite（Cocos 內建圓角佔位圖：四角透明，拉伸後圓角跟著放大）✘ 建議換 default_sprite_splash'
        : f === SPLASH ? 'default_sprite_splash（2×2 純白，直角）✔'
        : f ? assetByUuid[f] || f : '（沒有圖）';
      console.log(`  圖 ${name}`);
      console.log(`  顏色 rgba(${o._color.r},${o._color.g},${o._color.b},${o._color.a})，sizeMode ${o._sizeMode}${o._sizeMode === 0 ? '（Custom，換圖不會改尺寸）' : '（不是 Custom：換圖會把尺寸改成圖的大小）'}，type ${o._type}`);
    }
    if (o.__type__ === 'cc.UIOpacity') console.log(`  UIOpacity ${o._opacity}（半透明時重疊處會比較深）`);
