}
console.log();

// ── 4. 格距與接縫 ──
console.log('== 4. 每輪實際格距與接縫 ==');
if (!wheelPrefab) console.log('  （找不到 WheelBlock prefab）');
else {
  const comp = (n, t) => (n._components || []).map(c => wheelPrefab[c.__id__]).find(c => c && c.__type__ === t);
  // 有 symbolAry 的元件 = 轉輪
  const wheels = wheelPrefab
    .filter(o => o && Array.isArray(o.symbolAry) && o.symbolAry.length > 1 && o.node)
    .map(o => {
      const n = wheelPrefab[o.node.__id__];
      const parent = n._parent ? wheelPrefab[n._parent.__id__] : null;
      const symNodes = o.symbolAry.map(r => wheelPrefab[wheelPrefab[r.__id__].node.__id__]);
      const ys = symNodes.map(s => s._lpos.y);
      const pitchY = Math.abs(ys[0] - ys[1]);
      const ut = comp(symNodes[0], 'cc.UITransform');
      return {
        name: n._name,
        x: n._lpos.x + (parent && parent._lpos ? parent._lpos.x : 0),
        pitchY,
        count: symNodes.length,
        symbolSize: ut ? `${ut._contentSize.width}×${ut._contentSize.height}` : '?',
      };
    })
    .sort((a, b) => a.x - b.x);
  wheels.forEach((w, k) => {
    const dx = k > 0 ? (w.x - wheels[k - 1].x).toFixed(0) : '-';
    console.log(`  ${w.name.padEnd(8)} x=${String(w.x).padStart(5)}  與左輪距 ${String(dx).padStart(4)}  上下格距 ${w.pitchY}  符號節點 ${w.symbolSize}（${w.count} 張）`);
  });
  const pitchesX = wheels.slice(1).map((w, k) => Math.round(w.x - wheels[k].x));
  const pitchesY = [...new Set(wheels.map(w => w.pitchY))];
  const sizes = [];
  if (maskSize) sizes.push([maskSize.width, maskSize.height, '目前']);
  sizes.push([Math.min(...pitchesX), Math.min(...pitchesY), '最小格距（不重疊，但寬間距處留縫）']);
  sizes.push([Math.max(...pitchesX), Math.max(...pitchesY), '最大格距（不留縫，但窄間距處重疊）']);
  for (const s of (arg('--sizes') || '').split(',').filter(Boolean)) {
