```

---

## 2. 場景縮放

### `GXXXX_GameManager`

```ts
  @property({type: Node, displayName: 'GameRoot'})
  public gameRoot: Node = null;

  @property({type: CCFloat, displayName: '聽牌縮小比例', tooltip: '0.9 = 縮小 10%；>1 則為拉近', min: 0.1})
  public prewinShrinkRatio = 0.9;
  @property({type: CCFloat, displayName: '聽牌縮小時間(秒)', min: 0})
  public prewinShrinkDuration = 2.5;
  @property({type: CCFloat, displayName: '聽牌復原時間(秒)', min: 0})
  public prewinRestoreDuration = 0.3;

  private _baseScale: Vec3 = null;
  private _prewinShrinking = false;

  protected onLoad(): void {
    // ……
    if (this.gameRoot?.isValid) this._baseScale = this.gameRoot.scale.clone(); // 場景上的原始 scale
  }

  /** 縮到 base × ratio 後停住，等 restore */
  public playPrewinShrink(): void {
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale) {
      console.error('[GameManager] GameRoot 沒接，跳過聽牌縮放');
      return;
    }
    const b = this._baseScale, r = this.prewinShrinkRatio;
    this._prewinShrinking = true;
    Tween.stopAllByTarget(root);
    tween(root)
      .to(this.prewinShrinkDuration, {scale: new Vec3(b.x * r, b.y * r, b.z)}, {easing: 'sineIn'})
      .start();
  }

  /** 從目前大小（縮到一半也一樣）彈回 base。quartIn = 前段幾乎不動、尾段猛彈，有力道 */
  public restorePrewinShrink(): void {
    if (!this._prewinShrinking) return;
    this._prewinShrinking = false;
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale) return;
    Tween.stopAllByTarget(root);
    tween(root)
      .to(this.prewinRestoreDuration, {scale: this._baseScale.clone()}, {easing: 'quartIn'})
      .start();
  }

  /** 保險：起轉時如果還在縮放中，代表 hidePrewin 沒來，直接回原大小並報錯 */
  public forceResetPrewinShrink(): void {
    if (!this._prewinShrinking) return;
    console.error('[GameManager] 起轉時聽牌縮放仍未復原（hidePrewin 沒收到），強制回原大小');
    this._prewinShrinking = false;
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale) return;
    Tween.stopAllByTarget(root);
    root.setScale(this._baseScale);
  }
```

### Controller 的觸發點

```ts
  private _prewinPlaying = false; // 「當下正在聽牌」：第一次 showPrewin ~ 最後一個聽牌輪的 hidePrewin

  public spinAll(PlayMode: GamePlayMode): Promise<void> {
    GXXXX_GameManager.instance.forceResetPrewinShrink();
    return super.spinAll(PlayMode);
  }

  public showPrewin(wheelIndex: number): void {
    // ……變速（第 1 節）
    if (!this._prewinPlaying) {
      GXXXX_GameManager.instance.playPrewinShrink();   // 這一手第一次進聽牌
    }
    this._prewinPlaying = true;
    // ……
  }

  public hidePrewin(wheelIndex: number): void {
    super.hidePrewin(wheelIndex);
    if (this.hasPrewinAfter(wheelIndex)) return;       // 後面還有聽牌輪，維持縮小
    this._prewinPlaying = false;
    GXXXX_GameManager.instance.restorePrewinShrink();  // 最後一個聽牌輪停穩
    // ……
  }

  private hasPrewinAfter(wheelIndex: number): boolean {
    const a = this._prewinAry;
    if (!a) return false;
    for (let w = wheelIndex + 1; w < a.length; w++) if (a[w] === 1) return true;
    return false;
  }
```

「只有第 N 輪聽牌才縮」的變體：把開始條件改成 `wheelIndex === this.wheelAry.length - 1`，用一次播完的 tween（縮小 → 復原串在同一條），總長設成等於 Prewin 的 `wheelStopGapTime`。

---

## 3. 每輪聽牌特效（`GXXXX_PrewinController extends PrewinController`）

```ts
  @property({type: CCString, displayName: '聽牌動畫名', tooltip: '留空自動取 spine 的第一支動畫'})
  protected prewinAnimationKey = '';

  public onLoad(): void {
    if (!this.wheelBlockController) {   // 共用層 onLoad 對 null 取值會拋錯，整個元件靜默失效
      this.wheelBlockController = director.getScene()?.getComponentInChildren(WheelBlockController) ?? null;
    }
    if (!this.wheelBlockController) {
      console.warn('[PrewinController] 找不到 WheelBlockController，聽牌演出停用');
      return;
    }
    super.onLoad();
  }

  protected onDestroy(): void {         // 共用層沒有解除訂閱
    this.wheelBlockController?.eventPrewinStart.remove(this.onPrewinStart, this);
    this.wheelBlockController?.eventPrewinFinished.remove(this.onPrewinFinish, this);
  }

  public onPrewinStart(ctrlIndex: number, wheelIndex: number): void {
    super.onPrewinStart(ctrlIndex, wheelIndex);   // 音效 + 開節點
    const sk = this.getSkeleton(wheelIndex);
    const name = this.prewinAnimationKey || sk?.skeletonData?.getRuntimeData()?.animations?.[0]?.name;
    if (!sk || !name) return;
    sk.setCompleteListener(null);                 // 先清 listener，clearTracks 會送出 end 事件
    sk.setEndListener(null);
    sk.clearTracks();
    sk.setAnimation(0, name, true);
  }

  public onPrewinFinish(ctrlIndex: number, wheelIndex: number): void {
    const sk = this.getSkeleton(wheelIndex);
    if (sk) { sk.setCompleteListener(null); sk.setEndListener(null); sk.clearTracks(); }
    super.onPrewinFinish(ctrlIndex, wheelIndex);
  }

  private getSkeleton(i: number): sp.Skeleton | null {
    const n = this.prewinObjectAry?.[i];
    return n?.isValid ? (n.getComponent(sp.Skeleton) ?? n.getComponentInChildren(sp.Skeleton)) : null;
  }
```

`prewinAudioKey` 留空時，共用層會改用 `'prewin'`。要填 AudioMixer 裡實際存在的 key（WildFrontier 用的是 `MG_SFX_Nearwin`）。

