#!/usr/bin/env node
/**
 * 檢查轉輪設定的「實際狀態」，避免改了沒生效：
 *   1. prefab / scene 上每個元件實際掛的是哪支腳本（解壓縮 __type__ uuid → .ts 路徑）
 *   2. wheelRotateInfoList / wheelDropSettingList 實際生效值（prefab 預設 + scene 覆寫）
 *   3. 已被序列化進 scene / prefab 的自訂欄位（預設 /prewin/i，可用 --fields 改）
 *      —— 已序列化的欄位改程式預設值不會生效，要改場景值
 *
 * 用法（在專案根目錄）：
 *   node .claude/skills/slot-prewin-effect/scripts/inspect_wheel_setup.js \
 *     --prefab assets/Game/Prefab/WheelBlock.prefab \
 *     --scene  assets/Game/Scene/Scene_GXXXX_Name.scene \
 *     [--fields "prewin|shrink"]
 *
 * --prefab / --scene 都可省略，省略時自動在 assets/Game 下找（WheelBlock*.prefab、*.scene）。
 */
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const arg = (k, d = null) => {
  const i = args.indexOf(k);
  return i >= 0 ? args[i + 1] : d;
};

const ROOT = process.cwd();
const fieldRe = new RegExp(arg('--fields', 'prewin'), 'i');

// ── uuid 解壓縮（Cocos 3.x：前 5 碼 hex 保留，其餘每 2 個 base64 字元 = 3 個 hex） ──
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decompressUuid(c) {
  if (typeof c !== 'string' || c.length !== 23) return null;
  let hex = c.slice(0, 5);
  for (let i = 5; i < 23; i += 2) {
    const a = B64.indexOf(c[i]);
    const b = B64.indexOf(c[i + 1]);
    if (a < 0 || b < 0) return null;
    hex += ((a << 6) | b).toString(16).padStart(3, '0');
  }
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// ── 掃 assets 下所有 .ts.meta，建 uuid → 腳本路徑 ──
function walk(dir, out) {
  for (const e of fs.readdirSync(dir, {withFileTypes: true})) {
    if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (e.name.endsWith('.ts.meta')) out.push(p);
  }
  return out;
}
const scriptByUuid = {};
for (const m of walk(path.join(ROOT, 'assets'), [])) {
  try {
    const u = JSON.parse(fs.readFileSync(m, 'utf8')).uuid;
    if (u) scriptByUuid[u] = path.relative(ROOT, m).replace(/\.meta$/, '').replace(/\\/g, '/');
  } catch (_) { /* ignore */ }
}
const typeName = t => {
  const u = decompressUuid(t);
  return u && scriptByUuid[u] ? `${t} → ${scriptByUuid[u]}` : t;
};

function findFirst(dir, re) {
  if (!fs.existsSync(dir)) return null;
  const hits = [];
  (function rec(d) {
    for (const e of fs.readdirSync(d, {withFileTypes: true})) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) rec(p);
      else if (re.test(e.name)) hits.push(p);
    }
  })(dir);
  return hits[0] || null;
}

const prefabPath = arg('--prefab') || findFirst(path.join(ROOT, 'assets/Game'), /^WheelBlock.*\.prefab$/);
const scenePath = arg('--scene') || findFirst(path.join(ROOT, 'assets/Game'), /\.scene$/);
const load = p => (p && fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null);
const prefab = load(prefabPath);
const scene = load(scenePath);

console.log(`prefab: ${prefabPath || '(找不到)'}\nscene : ${scenePath || '(找不到)'}\n`);

// ── 1. 元件實際掛的腳本 ──
if (prefab) {
  console.log('== prefab 上的自訂元件（同類型只列一次，括號為數量）==');
  const count = {};
  for (const o of prefab) {
    if (o && typeof o.__type__ === 'string' && o.__type__.length === 23 && o.node) {
      count[o.__type__] = (count[o.__type__] || 0) + 1;
    }
  }
  for (const [t, n] of Object.entries(count)) console.log(`  (${n}) ${typeName(t)}`);
  console.log('  ※ 遊戲層子類別（例如 GXXXX_Wheel）若沒出現在這裡，代表它沒掛上，覆寫它的方法不會執行\n');
}

// ── 2. 轉速設定實際生效值 ──
const MODE = {0: 'None', 1: 'Normal', 2: 'SpecialGame', 3: 'Prewin'};
function listSettings(data, listKey) {
  const ctrl = data && data.find(o => o && Array.isArray(o[listKey]));
  if (!ctrl) return null;
  return ctrl[listKey].map(r => Object.assign({}, data[r.__id__]));
}
for (const listKey of ['wheelRotateInfoList', 'wheelDropSettingList']) {
  const base = listSettings(prefab, listKey) || listSettings(scene, listKey);
  if (!base) continue;
  const eff = base.map(x => Object.assign({}, x));
  if (scene) {
    for (const o of scene) {
      if (!o || o.__type__ !== 'CCPropertyOverrideInfo' || !o.propertyPath) continue;
      const [k, idx, field] = o.propertyPath;
      if (k !== listKey) continue;
      if (idx === 'length') { eff.length = o.value; continue; }
      const i = Number(idx);
      let v = o.value;
      if (v && v.__id__ !== undefined) v = Object.assign({}, scene[v.__id__]);
      if (field === undefined) eff[i] = v;
      else { eff[i] = eff[i] || {}; eff[i][field] = v; }
    }
  }
  console.log(`== ${listKey}（prefab + scene 覆寫後的實際值）==`);
  eff.forEach((s, i) => {
    if (!s) return;
    const keys = ['wheelRotateSpeed', 'wheelStopGapTime', 'readyToStopDelayTime', 'breakSneakingTime', 'breakSneakingSpeed', 'breakAndBoundTime'];
    console.log(`  [${i}] ${MODE[s.playModeName] || s.playModeName}: ` + keys.filter(k => s[k] !== undefined).map(k => `${k}=${s[k]}`).join(', '));
  });
  console.log('  ※ wheelRotateSpeed 單位是 px/幀（1/60 秒）；breakSneakingTime 實際被當成「幀數」用\n');
}

// ── 3. 已序列化的自訂欄位 ──
function serialized(data, label) {
  if (!data) return;
  const hits = [];
  data.forEach((o, i) => {
    if (!o || typeof o !== 'object') return;
    for (const k of Object.keys(o)) if (fieldRe.test(k) && (typeof o[k] !== 'object' || Array.isArray(o[k]))) hits.push(`  #${i} ${typeName(o.__type__)}  ${k} = ${Array.isArray(o[k]) ? JSON.stringify(o[k]) : o[k]}`);
    if (o.__type__ === 'CCPropertyOverrideInfo' && o.propertyPath && fieldRe.test(o.propertyPath.join('.'))) hits.push(`  override ${o.propertyPath.join('.')} = ${JSON.stringify(o.value)}`);
  });
  console.log(`== ${label} 已序列化、符合 /${fieldRe.source}/ 的欄位 ==`);
  console.log(hits.length ? hits.join('\n') : '  （沒有：目前用的是程式預設值）');
  console.log();
}
serialized(scene, 'scene');
serialized(prefab, 'prefab');

// ── 4. 每格圖距（轉速上限參考） ──
if (prefab) {
  const wheel = prefab.find(o => o && Array.isArray(o.symbolAry) && o.symbolAry.length > 1);
  if (wheel) {
    const ys = wheel.symbolAry.slice(0, 2).map(r => {
      const c = prefab[r.__id__];
      const n = c && c.node ? prefab[c.node.__id__] : null;
      return n && n._lpos ? n._lpos : null;
    });
    if (ys[0] && ys[1]) {
      const d = Math.max(Math.abs(ys[0].x - ys[1].x), Math.abs(ys[0].y - ys[1].y));
      console.log(`== 圖距 == ${d}px（速度須 < 圖距，每幀最多換一張；建議上限 ${Math.floor(d * 0.9)}）`);
      if (wheel.fastSpinSpeedMultiple !== undefined) console.log(`  fastSpinSpeedMultiple = ${wheel.fastSpinSpeedMultiple}（Normal 模式開 turbo 時轉速再乘這個倍數）`);
    }
  }
}

# 聽牌運鏡（左移定位 → 放大＋位置補償 → 等速復原）參考實作

規格、需求演變與陷阱的完整版在指導書 `llm-wiki/llmwiki/07_rules/rule__prewin_camera_and_rhythm.md`。本檔只放程式，取自 WildFrontier（G1028）2026-10-15 定案版，移植時把 `G1028_` 換成目標遊戲的前綴。

運鏡要配合 `timeline-landing.md` 的停輪節奏一起用：放大的結束時間要對齊「停轉」，而停轉時間來自時間表 `prewinTerminal[]`。

---

## 1. Controller 端（`GXXXX_WheelBlockController`）

### 提供停轉時間與構圖焦點

```ts
  /**
   * 聽牌輪可視區中心的世界座標（給鏡頭放大時固定構圖用）。
   * 用轉輪原位 + 可視格的平均位置，不用轉輪節點目前位置（轉動中會上下位移）。
   */
  public getPrewinFocusWorld(wheelIndex: number): Vec3 | null {
    const wheel = this.wheelAry[wheelIndex];
    const parent = wheel?.node?.parent;
    if (!wheel || !parent) return null;
    const top = wheel.outOfTopSymbolAmount ?? 0;
    const count = wheel.visibleSymbolAmount ?? 0;
    let sx = 0, sy = 0, n = 0;
    for (let s = 0; s < count; s++) {
      const p = wheel.symbolAry?.[top + s]?.node?.position;
      if (!p) continue;
      sx += p.x; sy += p.y; n++;
    }
    const local = new Vec3(
      wheel.originWheelPos.x + (n > 0 ? sx / n : 0),
      wheel.originWheelPos.y + (n > 0 ? sy / n : 0),
      0
    );
    return Vec3.transformMat4(new Vec3(), local, parent.worldMatrix);
  }

  /** 這一輪從聽牌開始（光框亮）到停轉（轉輪抵達、開始收停）的秒數 */
  public getPrewinLandTime(wheelIndex: number): number {
    const C = GXXXX_WheelBlockController;
    return C.pickParam(this.prewinTerminal, this.prewinOrdinal(wheelIndex), 0);
  }
```

「停轉」刻意用 `prewinTerminal`（轉輪抵達、開始收停），不是主要落回（再晚 0.234 秒）。使用者對「停轉／停輪」的感受是轉輪抵達那一刻（指導書 §2 第 8 點）。

