    tooltip: '停轉前幾秒完成；0 = 同時；負值 = 停轉後才完成'})
  public prewinZoomEndEarly: number = -0.3;

  @property({type: CCFloat, displayName: '聽牌復原時間(秒)', min: 0})
  public prewinRestoreDuration: number = 0.3;

  private _baseScale: Vec3 = null;     // onLoad 記下場景原值，不在縮放當下讀
  private _basePosition: Vec3 = null;
  private _prewinShrinking = false;
  private _prewinPanTween: Tween<Node> = null;
  private _prewinZoomTween: Tween<Node> = null; // 只停自己，不用 stopAllByTarget，以免砍掉同時在跑的左移
  private _prewinShowAt = 0;
  private _prewinLandTime = 0;
  private _prewinFocus: Vec3 | null = null;
  private static readonly MIN_ZOOM_TIME = 0.3;

  protected onLoad(): void {
    // ……
    if (this.gameRoot?.isValid) {
      this._baseScale = this.gameRoot.scale.clone();
      this._basePosition = this.gameRoot.position.clone();
    }
  }

  /** 第 wheelIndex 輪（0 起算，第 3 輪 = 2）聽牌時的放大倍率 */
  private getPrewinZoom(wheelIndex: number): number {
    const ary = this.prewinZoomByWheel;
    if (!ary || ary.length === 0) return 1;
    return ary[Math.min(Math.max(wheelIndex - 2, 0), ary.length - 1)];
  }
```

### 開始：記下停轉時間與焦點 → 左移

```ts
  public playPrewinShrink(wheelIndex: number, landTime = 0, focusWorld: Vec3 | null = null): void {
    if (wheelIndex < 2 || wheelIndex > 5) return;          // 盤面不同時調整範圍
    this._prewinShowAt = performance.now();
    this._prewinLandTime = landTime;
    this._prewinFocus = null;
    if (focusWorld && this.gameRoot?.isValid) {
      // 轉成 GameRoot 本地座標：之後 GameRoot 怎麼移動、縮放，這個值都不變
      this._prewinFocus = this.gameRoot.inverseTransformPoint(new Vec3(), focusWorld);
    }
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale || !this._basePosition) {
      console.error('[GameManager] GameRoot 沒接，跳過聽牌運鏡');
      return;
    }
    if (!this._prewinShrinking) {
      this._prewinShrinking = true;
      Tween.stopAllByTarget(root);                           // 清掉進場放大等殘留
    }
    this._prewinZoomTween?.stop();
    this._prewinZoomTween = null;
    this._prewinPanTween?.stop();
    this._prewinPanTween = null;
    this.startPrewinPan(wheelIndex);
  }

  private startPrewinPan(wheelIndex: number): void {
    const root = this.gameRoot;
    if (!root?.isValid || !this._basePosition) return;
    const position = this._basePosition.clone();
    // 步距是原尺寸下的距離；放大後畫面上的距離也等比放大
    const scale = this.getPrewinZoom(wheelIndex) * (this._baseScale?.x ?? 1);
    position.x -= (wheelIndex - 2) * this.prewinPanStep * scale;
    if (wheelIndex >= 3 && Math.abs(root.position.x - position.x) > 0.001) {
      const panTween: Tween<Node> = tween(root)
        .to(this.prewinPanDuration, {position}, {easing: 'sineOut'})
        .call(() => {
          if (this._prewinPanTween !== panTween) return;   // 已被下一輪取代
          this._prewinPanTween = null;
          this.startPrewinZoom(wheelIndex);                // 到定位後才放大
        })
        .start();
      this._prewinPanTween = panTween;
      return;
    }
    this.startPrewinZoom(wheelIndex);
  }
```

### 放大＋位置補償（對齊停轉）

```ts
  private startPrewinZoom(wheelIndex: number): void {
    const root = this.gameRoot;
    const base = this._baseScale;
    if (!this._prewinShrinking || !root?.isValid || !base) return;
    const r = this.getPrewinZoom(wheelIndex);

    // 對齊停轉：結束時間 = 停轉 − prewinZoomEndEarly；左移被延後時放大自動變短
    let duration = this.prewinShrinkDuration;
    if (this._prewinLandTime > 0) {
      const elapsed = (performance.now() - this._prewinShowAt) / 1000;
      duration = Math.max(GXXXX_GameManager.MIN_ZOOM_TIME,
        this._prewinLandTime - this.prewinZoomEndEarly - elapsed);
    }

    // 焦點的畫面位置 = GameRoot 位置 + 焦點 × 縮放。固定它：每幀位置 = anchor − 焦點 × 當下縮放
    const focus = this._prewinFocus;
    const start = root.position.clone();
    const startScale = root.scale.clone();
    const anchorX = focus ? start.x + focus.x * startScale.x : 0;
    const anchorY = focus ? start.y + focus.y * startScale.y : 0;

    this._prewinZoomTween?.stop();
    this._prewinZoomTween = tween(root)
      .to(duration, {scale: new Vec3(base.x * r, base.y * r, base.z)}, {
        easing: 'sineOut',
        onUpdate: () => {
          if (!focus) return;
          const s = root.scale; // 引擎先套好本幀含 easing 的縮放，再呼叫 onUpdate
          root.setPosition(anchorX - focus.x * s.x, anchorY - focus.y * s.y, start.z);
        },
      })
      .start();
  }
```

### 復原與保險

```ts
  public restorePrewinShrink(): void {
    if (!this._prewinShrinking) return;
    this._prewinPanTween = null;
    this._prewinZoomTween = null;
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale || !this._basePosition) return;
    Tween.stopAllByTarget(root);
    tween(root)
      .to(this.prewinRestoreDuration,
        {scale: this._baseScale.clone(), position: this._basePosition.clone()},
        {easing: 'linear'})
      .call(() => { this._prewinShrinking = false; })
      .start();
  }

  public forceResetPrewinShrink(): void {
    if (!this._prewinShrinking) return;
    console.error('[GameManager] 起轉時聽牌運鏡仍未復原（hidePrewin 沒收到），強制回原值');
    this._prewinShrinking = false;
    this._prewinPanTween = null;
    this._prewinZoomTween = null;
    const root = this.gameRoot;
    if (!root?.isValid || !this._baseScale) return;
    Tween.stopAllByTarget(root);
    root.setScale(this._baseScale);
    if (this._basePosition) root.setPosition(this._basePosition);
  }
```

