```ts
  @property({type: CCString, displayName: '聽牌動畫名', tooltip: '留空自動取 spine 的第一支動畫'})
  protected prewinAnimationKey = '';

  public onLoad(): void {
    if (!this.wheelBlockController) {   // 共用層 onLoad 對 null 取值會拋錯，整個元件靜默失效
      this.wheelBlockController = director.getScene()?.getComponentInChildren(WheelBlockController) ?? null;
    }
    if (!this.wheelBlockController) {
      console.warn('[PrewinController] 找不到 WheelBlockController，聽牌演出停用');
      return;
    }
    super.onLoad();
  }

  protected onDestroy(): void {         // 共用層沒有解除訂閱
    this.wheelBlockController?.eventPrewinStart.remove(this.onPrewinStart, this);
    this.wheelBlockController?.eventPrewinFinished.remove(this.onPrewinFinish, this);
  }

  public onPrewinStart(ctrlIndex: number, wheelIndex: number): void {
    super.onPrewinStart(ctrlIndex, wheelIndex);   // 音效 + 開節點
    const sk = this.getSkeleton(wheelIndex);
    const name = this.prewinAnimationKey || sk?.skeletonData?.getRuntimeData()?.animations?.[0]?.name;
    if (!sk || !name) return;
    sk.setCompleteListener(null);                 // 先清 listener，clearTracks 會送出 end 事件
    sk.setEndListener(null);
    sk.clearTracks();
    sk.setAnimation(0, name, true);
  }

  public onPrewinFinish(ctrlIndex: number, wheelIndex: number): void {
    const sk = this.getSkeleton(wheelIndex);
    if (sk) { sk.setCompleteListener(null); sk.setEndListener(null); sk.clearTracks(); }
    super.onPrewinFinish(ctrlIndex, wheelIndex);
  }

  private getSkeleton(i: number): sp.Skeleton | null {
    const n = this.prewinObjectAry?.[i];
    return n?.isValid ? (n.getComponent(sp.Skeleton) ?? n.getComponentInChildren(sp.Skeleton)) : null;
  }
