# -*- coding: utf-8 -*-
"""檢查 spec data.json 結構是否正確、可被 spec_gen.py 安全產出。
用法： python validate.py <data.json>
檢查：sheets/blocks 結構、table 每列長度=headers、steps 欄位、未知區塊型別；
並提醒可能未標記的數值（裸數字賠率/獎金，建議改成『由企劃/數值團隊提供』）。"""
import sys, json, re

VALID = {"title","sub","bullets","table","steps","image","note","spacer"}
NUMHINT = re.compile(r"(賠率|odds|RTP|機率|獎金|彩金|倍|級距|門檻)", re.I)
# 特色關鍵字：出現在分頁名/標題時，提醒先做「存在性查證」(避免把框架支援誤當本遊戲有)
FEATURE_KEYS = re.compile(r"(特殊遊戲|免費遊戲|特色遊戲|FEATURE\s*GAME|FREE\s*GAME|FREE\s*SPIN|BONUS|JP|JACKPOT|彩金|收集|COLLECT|RE-?SPIN|PICK)", re.I)
# 已據實標註「未實作/待確認」的字眼 → 視為已查證，不再提醒
SETTLED = re.compile(r"(未實作|現況|查證|待企劃|待確認|框架支援)")
# 演出/表演相關分頁（用來提醒「停輪後表演」是否盤點完整）
PERF_SHEET = re.compile(r"(演出|表演|中獎|動畫|MAIN\s*GAME|主遊戲)", re.I)
def has_bare_number(s):
    return bool(re.search(r"\d", str(s)))

def main():
    if len(sys.argv) < 2:
        print("用法: python validate.py <data.json>"); sys.exit(1)
    try:
        spec = json.load(open(sys.argv[1], "r", encoding="utf-8"))
    except Exception as e:
        print("FAIL: JSON 無法解析 -", e); sys.exit(1)
    errs=[]; warns=[]; feats=[]; nsheet=0; nblk=0; has_perf=False
    sheets = spec.get("sheets")
    if not isinstance(sheets, list) or not sheets:
        print("FAIL: 缺少 sheets 陣列"); sys.exit(1)
    for si, sh in enumerate(sheets):
        nsheet+=1
        name = sh.get("name","?")
        if not sh.get("name"): errs.append("[sheet %d] 缺 name"%si)
        blocks = sh.get("blocks")
        if not isinstance(blocks, list) or not blocks:
            errs.append("[%s] 缺 blocks"%name); continue
        has_title = any(b.get("t")=="title" for b in blocks)
        if not has_title: warns.append("[%s] 沒有 title 區塊（建議每頁第一塊為 title）"%name)
        # 特色存在性查證提醒：分頁談到某特色，但未標『未實作/待確認』→ 提醒先確認本遊戲真有此特色
        sheet_txt = name + " " + " ".join(str(b.get("text","")) for b in blocks if b.get("t") in ("title","sub"))
        body_txt = " ".join(str(b.get("text","")) for b in blocks)
        if FEATURE_KEYS.search(sheet_txt) and not SETTLED.search(body_txt):
            feats.append(name)
        if PERF_SHEET.search(name) or PERF_SHEET.search(sheet_txt):
            has_perf = True
        for bi, b in enumerate(blocks):
            nblk+=1
            t=b.get("t")
            if t not in VALID:
                errs.append("[%s#%d] 未知區塊型別: %r"%(name,bi,t)); continue
            if t=="table":
                heads=b.get("headers",[])
                if not heads: errs.append("[%s#%d] table 缺 headers"%(name,bi))
                for ri,row in enumerate(b.get("rows",[])):
                    if len(row)!=len(heads):
                        errs.append("[%s#%d] table 第%d列長度 %d ≠ headers %d"%(name,bi,ri,len(row),len(heads)))
            if t=="bullets":
                for ri,it in enumerate(b.get("items",[])):
                    if not isinstance(it,str) or not it.strip():
                        errs.append("[%s#%d] bullets 第%d項應為非空字串"%(name,bi,ri))
            if t=="steps":
                for ri,it in enumerate(b.get("items",[])):
                    if "step" not in it: errs.append("[%s#%d] steps 第%d項缺 step"%(name,bi,ri))
                    if "desc" not in it: errs.append("[%s#%d] steps 第%d項缺 desc"%(name,bi,ri))
            # 數值提醒：bullets / table 內含『賠率/獎金…』關鍵字又有裸數字、且未標『由企劃』
            texts=[]
            if t=="bullets": texts=b.get("items",[])
            if t=="table": texts=[c for row in b.get("rows",[]) for c in row]
            for tx in texts:
                if NUMHINT.search(str(tx)) and has_bare_number(tx) and ("企劃" not in str(tx)) and ("數值團隊" not in str(tx)):
                    warns.append("[%s] 疑似未標記的數值：%s"%(name, str(tx)[:40]))
    print("結構：%d 分頁 / %d 區塊"%(nsheet,nblk))
    for w in warns[:40]: print("  ⚠", w)
    if len(warns)>40: print("  …(另有 %d 則提醒)"%(len(warns)-40))
    if feats:
        print("特色存在性查證（請逐頁確認對『本遊戲』有正面證據，而非僅框架/引擎支援）：")
        for f in feats:
            print("  ⚑ [%s] 需≥1 正面證據：①遊戲端有對應客製碼(extends FGBase/專屬資料夾·State)  ②場景特殊遊戲清單非空 或 有專屬場景·prefab·BGM  ③實際遊戲資料出現非零特殊遊戲狀態(sg_state≠0/sg_id 指向真實特色/開局宣告)。三者皆無 → 改標『框架支援，本遊戲未實作，待企劃確認』。"%f)
            print("     ✗ 不算證據：submodule 內有 FGBase/SpecialGameAgent/FreeGameTimeCtrl 等框架檔(每款都有)；設定檔殘留路徑(指向不存在的檔)。")
    # 停輪後表演盤點提醒
    if has_perf:
        print("停輪後表演盤點（對照程式，勿漏）：")
        print("  ⚐ 逐項確認『主遊戲停輪後表演』都已寫入：中獎連線/燈號、分級演出+滾分、中獎音效、特殊符號演出、")
        print("     飛行物/收集(銅錢→聚寶盆/鞭炮)、計量器/彩金累積與升級(分階段)、進特色/JP 前置轉場、押注門檻表演。")
        print("     找法：grep eventSingleWheelStopped|eventWheelStopped|WheelsAllStopped + fly|coin|collect|pot|GoldenPot|SymbolShow（別只搜主檔/別只搜 \"wild\"）。")
    else:
        print("  ⚠ 沒有〔演出/表演/中獎〕類分頁 → 建議補『演出說明』並盤點停輪後表演（見 RULES.md）。")
    for e in errs: print("  ✗", e)
    print("---")
    print("PASS：結構正確" if not errs else "FAIL：有 %d 個結構錯誤"%len(errs))
    sys.exit(0 if not errs else 1)

if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""通用 slot 規格書產生引擎：讀『區塊式 JSON』→ 產出 house 風格多分頁 Excel。
與遊戲無關，任何 slot 皆可用。用法：
    python spec_gen.py <data.json> [out.xlsx]
data.json 結構：
{
  "meta": {"game": "...", "ncol": 9},                 # 可省略
  "sheets": [
    {"name": "JP GAME", "blocks": [
        {"t":"title",   "text": "JP GAME - 聚寶盆"},
        {"t":"note",    "text": "..."},                # ※ 灰字小註（含『參考圖』會上藍底）
        {"t":"sub",     "text": "玩法規則"},            # ■ 小標
        {"t":"bullets", "items": ["...","..."]},        # ◎ 條列（含數值關鍵字→黃底）
        {"t":"table",   "headers":[...], "rows":[[...]]},
        {"t":"steps",   "items":[{"step":"步驟1","desc":"..."}]},  # 分鏡：步驟|內容|參考圖
        {"t":"image",   "text": "主遊戲畫面"},          # 🖼【需編導提供參考圖】
        {"t":"spacer"}
    ]}
  ]
}
規則：數值（賠率/機率/獎金/次數/押注）一律寫『由企劃/數值團隊提供』(黃底)；
      畫面一律用 image 或在備註寫『需編導提供參考圖』(藍底)。
"""
import os, sys, json
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter

CJK = "Microsoft JhengHei"
NAVY="0F172A"; SUBBG="E2E8F0"; HEAD="2563EB"; ALT="F8FAFC"; YEL="FEF3C7"; BLUE="DBEAFE"; WHITE="FFFFFF"
thin = Side(style="thin", color="C7D0DD")
BORD = Border(left=thin,right=thin,top=thin,bottom=thin)
def F(sz=10,b=False,c="1E293B"): return Font(name=CJK,size=sz,bold=b,color=c)
def FILL(h): return PatternFill("solid",fgColor=h)
def AL(h="left",v="center",wrap=True): return Alignment(horizontal=h,vertical=v,wrap_text=wrap)
def needimg(s): return isinstance(s,str) and (("編導" in s) or ("參考圖" in s))
def needval(s): return isinstance(s,str) and (("企劃" in s) or ("數值團隊" in s) or ("TBD" in s) or ("待確認" in s) or ("待補" in s))
def _wlen(s): return sum(2 if ord(ch)>127 else 1 for ch in str(s))

def render(ws, blocks, NCOL=9):
    ws.sheet_view.showGridLines = False
    r = 1
    for blk in blocks:
        t = blk.get("t")
        if t == "title":
            ws.cell(r,1,blk.get("text","")).font=F(15,True,WHITE)
            ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=NCOL)
            for c in range(1,NCOL+1): ws.cell(r,c).fill=FILL(NAVY); ws.cell(r,c).alignment=AL()
            ws.row_dimensions[r].height=28; r+=1
        elif t == "sub":
            ws.cell(r,1,"■ "+blk.get("text","")).font=F(12,True,NAVY)
            ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=NCOL)
            for c in range(1,NCOL+1): ws.cell(r,c).fill=FILL(SUBBG); ws.cell(r,c).alignment=AL()
            ws.row_dimensions[r].height=22; r+=1
        elif t == "bullets":
            for it in blk.get("items",[]):
                it = "" if it is None else str(it)
                if not it.strip(): continue
                txt = it if it[:1] in "◎◆-˙•※" else "◎ "+it
                cell=ws.cell(r,1,txt); cell.font=F(10.5); cell.alignment=AL(v="top")
                ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=NCOL)
                if needval(it): cell.fill=FILL(YEL)
                ws.row_dimensions[r].height=max(18, 16*(1+_wlen(txt)//(NCOL*7)))
                r+=1
        elif t == "note":
            txt=blk.get("text",""); cell=ws.cell(r,1,"※ "+txt); cell.font=F(9,False,"64748B"); cell.alignment=AL(v="top")
            ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=NCOL)
            if needimg(txt): cell.fill=FILL(BLUE)
            ws.row_dimensions[r].height=max(16,16*(1+_wlen(txt)//(NCOL*8))); r+=1
        elif t == "image":
            cell=ws.cell(r,1,"🖼 【需編導提供參考圖】 "+blk.get("text","")); cell.font=F(10,False,"1D4ED8")
            ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=NCOL)
            cell.fill=FILL(BLUE); cell.alignment=AL(v="center"); ws.row_dimensions[r].height=24; r+=1
        elif t == "table":
            heads=blk.get("headers",[]); nc=max(len(heads),1)
            for c,h in enumerate(heads,1):
                cell=ws.cell(r,c,h); cell.font=F(10.5,True,WHITE); cell.fill=FILL(HEAD); cell.alignment=AL("center"); cell.border=BORD
            ws.row_dimensions[r].height=20; r+=1
            for i,row in enumerate(blk.get("rows",[])):
                for c in range(nc):
                    v = row[c] if c<len(row) else ""
                    cell=ws.cell(r,c+1,v); cell.font=F(10); cell.alignment=AL(v="top"); cell.border=BORD
                    if i%2==1: cell.fill=FILL(ALT)
                    if needval(v): cell.fill=FILL(YEL)
                    if needimg(v): cell.fill=FILL(BLUE)
                maxw=max((_wlen(row[c] if c<len(row) else "") for c in range(nc)), default=10)
                ws.row_dimensions[r].height=max(18,16*(1+maxw//40)); r+=1
        elif t == "steps":
            for c,h in enumerate(["步驟","內容","參考圖"],1):
                cell=ws.cell(r,c,h); cell.font=F(10.5,True,WHITE); cell.fill=FILL(HEAD); cell.alignment=AL("center"); cell.border=BORD
            r+=1
            for i,it in enumerate(blk.get("items",[])):
                ws.cell(r,1,it.get("step","")).font=F(10,True); ws.cell(r,1).alignment=AL("center","top"); ws.cell(r,1).border=BORD
                cdesc=ws.cell(r,2,it.get("desc","")); cdesc.font=F(10); cdesc.alignment=AL(v="top")
                ws.merge_cells(start_row=r,start_column=2,end_row=r,end_column=NCOL-1)
                for c in range(2,NCOL): ws.cell(r,c).border=BORD
                cimg=ws.cell(r,NCOL, it.get("img","需編導提供參考圖")); cimg.font=F(9,False,"1D4ED8"); cimg.fill=FILL(BLUE); cimg.alignment=AL("center","center"); cimg.border=BORD
                if i%2==1 and not needval(it.get("desc","")): cdesc.fill=FILL(ALT)
                if needval(it.get("desc","")): cdesc.fill=FILL(YEL)
                ws.row_dimensions[r].height=max(20,16*(1+_wlen(it.get("desc",""))//((NCOL-2)*7))); r+=1
        elif t == "spacer":
            ws.row_dimensions[r].height=6; r+=1
    ws.column_dimensions["A"].width=14
    for c in range(2,NCOL+1):
        ws.column_dimensions[get_column_letter(c)].width=16

def main():
    if len(sys.argv) < 2:
        print("用法: python spec_gen.py <data.json> [out.xlsx]"); sys.exit(1)
    data_path = sys.argv[1]
    out_path = sys.argv[2] if len(sys.argv) > 2 else os.path.splitext(data_path)[0] + ".xlsx"
    with open(data_path, "r", encoding="utf-8") as f:
        spec = json.load(f)
    ncol = int(spec.get("meta", {}).get("ncol", 9))
    sheets = spec.get("sheets", [])
    if not sheets:
        print("錯誤: data 內無 sheets"); sys.exit(1)
    wb = Workbook(); first=True
    for sh in sheets:
        ws = wb.active if first else wb.create_sheet()
        ws.title = str(sh.get("name","Sheet"))[:31]; first=False
        render(ws, sh.get("blocks", []), ncol)
    wb.save(out_path)
    print("WROTE", out_path, "| sheets:", len(wb.sheetnames))

if __name__ == "__main__":
    main()

