                        errs.append("[%s#%d] table 第%d列長度 %d ≠ headers %d"%(name,bi,ri,len(row),len(heads)))
            if t=="bullets":
                for ri,it in enumerate(b.get("items",[])):
                    if not isinstance(it,str) or not it.strip():
                        errs.append("[%s#%d] bullets 第%d項應為非空字串"%(name,bi,ri))
            if t=="steps":
                for ri,it in enumerate(b.get("items",[])):
                    if "step" not in it: errs.append("[%s#%d] steps 第%d項缺 step"%(name,bi,ri))
                    if "desc" not in it: errs.append("[%s#%d] steps 第%d項缺 desc"%(name,bi,ri))
            # 數值提醒：bullets / table 內含『賠率/獎金…』關鍵字又有裸數字、且未標『由企劃』
            texts=[]
            if t=="bullets": texts=b.get("items",[])
            if t=="table": texts=[c for row in b.get("rows",[]) for c in row]
            for tx in texts:
                if NUMHINT.search(str(tx)) and has_bare_number(tx) and ("企劃" not in str(tx)) and ("數值團隊" not in str(tx)):
                    warns.append("[%s] 疑似未標記的數值：%s"%(name, str(tx)[:40]))
    print("結構：%d 分頁 / %d 區塊"%(nsheet,nblk))
    for w in warns[:40]: print("  ⚠", w)
    if len(warns)>40: print("  …(另有 %d 則提醒)"%(len(warns)-40))
    if feats:
        print("特色存在性查證（請逐頁確認對『本遊戲』有正面證據，而非僅框架/引擎支援）：")
        for f in feats:
            print("  ⚑ [%s] 需≥1 正面證據：①遊戲端有對應客製碼(extends FGBase/專屬資料夾·State)  ②場景特殊遊戲清單非空 或 有專屬場景·prefab·BGM  ③實際遊戲資料出現非零特殊遊戲狀態(sg_state≠0/sg_id 指向真實特色/開局宣告)。三者皆無 → 改標『框架支援，本遊戲未實作，待企劃確認』。"%f)
            print("     ✗ 不算證據：submodule 內有 FGBase/SpecialGameAgent/FreeGameTimeCtrl 等框架檔(每款都有)；設定檔殘留路徑(指向不存在的檔)。")
    # 停輪後表演盤點提醒
    if has_perf:
        print("停輪後表演盤點（對照程式，勿漏）：")
        print("  ⚐ 逐項確認『主遊戲停輪後表演』都已寫入：中獎連線/燈號、分級演出+滾分、中獎音效、特殊符號演出、")
        print("     飛行物/收集(銅錢→聚寶盆/鞭炮)、計量器/彩金累積與升級(分階段)、進特色/JP 前置轉場、押注門檻表演。")
        print("     找法：grep eventSingleWheelStopped|eventWheelStopped|WheelsAllStopped + fly|coin|collect|pot|GoldenPot|SymbolShow（別只搜主檔/別只搜 \"wild\"）。")
    else:
        print("  ⚠ 沒有〔演出/表演/中獎〕類分頁 → 建議補『演出說明』並盤點停輪後表演（見 RULES.md）。")
    for e in errs: print("  ✗", e)
    print("---")
    print("PASS：結構正確" if not errs else "FAIL：有 %d 個結構錯誤"%len(errs))
    sys.exit(0 if not errs else 1)

if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""spec_gen.py — 規格書 INFO 分頁 → GameInfo 產生器的 spec.json

用法:
    python spec_gen.py <info.csv> <config.json> <out.json>

info.csv  : 規格書 INFO 或 多國語系表 分頁的 CSV 匯出（兩者內容相同）
config.json: 規格書沒有的東西（符號表、賠付檔位、meta、logo、toggles…），見 example.config.json
out.json  : 輸出

格式規範見 RULES.md；工具位置與陷阱見 E:\\Igaming\\GAMEINFO_PLAYBOOK.md
"""
import csv, io, json, re, sys, collections

LANGS = ['cht', 'chs', 'en', 'th', 'vi', 'ms', 'es']
# 規格書 INFO 分頁的語系欄順序（zh-TW, zh-CN, en-US, th-TH, vi-VN, ms-MY, es-ES）
IDX = {'cht': 0, 'chs': 1, 'en': 2, 'th': 3, 'vi': 4, 'ms': 5, 'es': 6}

# 規格書 key -> commonTexts 欄位。RTP2 是「RTP（Extra Bet）」-> extraBetRtpLabel，不是 rtp2Label
COMMON_MAP = {
    'Payout':      'payoutInfoTitle',
    'max-payout':  'maxPayoutLabel',
    'max-winodds': 'maxWinOddsLabel',
    'min-bet':     'minBetLabel',
    'max-bet':     'maxBetLabel',
    'RTP':         'rtpLabel',
    'RTP1':        'rtp1Label',
    'RTP2':        'extraBetRtpLabel',
    'buttons':     'buttonsTitle',
    'spin-info':   'spinInfo',
    'auto-info':   'autoInfo',
    'bet-info':    'betInfo',
    'turbo-info':  'turboInfo',
    'option-info': 'optionInfo',
    'rule-info':   'ruleInfo',
    'sound-info':  'soundInfo',
}
COMMON_ALL = list(COMMON_MAP.values()) + ['rtp2Label', 'superTurboInfo']
# 這些只是「標籤前綴」，數值由平台執行期灌入 -> 規格書的 {TBD} 與尾隨 % 要清掉
LABEL_KEYS = {'max-payout', 'max-winodds', 'min-bet', 'max-bet', 'RTP', 'RTP1', 'RTP2'}

NUMBERED_RE = re.compile(r'^\d+\.\s*')

DEV_DEFAULTS = {
    'oddsInfo': {}, 'infoMaxPayout': 10000, 'infoMaxWinOdds': 1000,
    'infoMinBet': 50, 'infoMaxBet': 5000, 'currencySymbol': '$', 'infoMaxLines': 50,
    'rtp': '96.00', 'buyBonusDataList': [], 'logo': 'logo', 'lang': 'en',
    'extraInfo': {'bet_level': [], 'Rtp1': None}, 'Rtp1': '',
    'currencyRatio': 0.01, 'decimalPlaces': 2, 'isDaraEnv': False,
}


class Gen(object):
    def __init__(self, csv_path, cfg):
        self.cfg = cfg
        self.notes = []
        self.dropped = []
        self._n = 0
        self._load(csv_path)

    # ---------- 讀規格書 ----------
    def _load(self, path):
        rows = list(csv.reader(io.open(path, encoding='utf-8')))
        # 第 3 列是機器表頭(section/key/zh-TW…)、第 4 列是人看的表頭 -> 資料從第 5 列起
        head = -1
        for i, r in enumerate(rows[:8]):
            if len(r) > 1 and r[0].strip() == 'section' and r[1].strip() == 'key':
                head = i
                break
        if head < 0:
            sys.exit('讀不到表頭：INFO 分頁應該有一列是 section | key | zh-TW | …')

        self.name = None
        self.subtitles = {}
        self.rules = {}
        self.commons = collections.OrderedDict()
        for cells in rows[head + 2:]:
            cells = cells + [''] * 9
            section, key = cells[0].strip(), cells[1].strip()
            vals = [c.strip() for c in cells[2:9]]
            if section == '機台名' and not key:
                self.name = vals
            elif re.fullmatch(r'subtitle(\d+)', key or ''):
                self.subtitles[int(key[8:])] = vals
            elif re.fullmatch(r'rule\d+-\d+', key or ''):
                m = re.fullmatch(r'rule(\d+)-(\d+)', key)
                self.rules.setdefault(int(m.group(1)), []).append((int(m.group(2)), vals))
            elif key in COMMON_MAP:
                self.commons[key] = vals
        if not self.name:
            sys.exit('規格書裡找不到「機台名」那一列')
        if not self.subtitles:
            sys.exit('規格書裡找不到任何 subtitleN')

    def _id(self):
        self._n += 1
        return 'id-%s%04d' % (self.cfg.get('idPrefix', 'gi'), self._n)

    @staticmethod
    def _langs(vals, xform=None):
        return {L: (xform(vals[IDX[L]]) if xform else vals[IDX[L]]) for L in LANGS}

    @staticmethod
    def _strip_label(t):
        return re.sub(r'\s*%\s*$', '', t.replace('{TBD}', '')).rstrip()

    # ---------- 段落 ----------
    def sections(self):
        cfg = self.cfg
        bb_en = cfg.get('buyBonusSectionEn', 'buy bonus').lower()
        pt_cht = cfg.get('paytableSectionCht', '賠付表')
        pin = cfg.get('pinKeys', False)
        drop_tbd = cfg.get('dropTbdRules', True)
        out = []

        for n in sorted(self.subtitles):
            rs = []
            for m, v in sorted(self.rules.get(n, [])):
                if drop_tbd and '{TBD}' in v[IDX['cht']]:
                    # 「沒有資料」的規則不留：上線會把 {TBD} 直接印給玩家看
                    self.dropped.append('rule%d-%d  %s' % (n, m, v[IDX['cht']]))
                    continue
                rs.append((m, v))

            # 編號策略逐段判斷，同段不混用（RULES.md §5）
            numbered = bool(rs) and all(NUMBERED_RE.match(v[IDX['cht']]) for _, v in rs)
            xf = (lambda t: NUMBERED_RE.sub('', t)) if numbered else None
            if not numbered and rs:
                self.notes.append('subtitle%d「%s」規格書原文沒編號 -> numbering: none'
                                  % (n, self.subtitles[n][IDX['cht']]))

            title = self._langs(self.subtitles[n])
            rules = []
            for m, v in rs:
                t = self._langs(v, xf)
                if pin:
                    t['key'] = 'rule%d-%d' % (len(out) + 1, len(rules) + 1)
                rules.append({'text': t})
            if pin:
                title['key'] = 'subtitle%d' % (len(out) + 1)

            sec = {
                'id': self._id(),
                'kind': 'ruleList',
                'titleMode': 'header',
                'title': title,
                'boxStyle': cfg.get('boxStyle', 'no-border'),
                'numbering': 'sequential' if numbered else 'none',
                'rules': rules,
            }
            if self.subtitles[n][IDX['en']].strip().lower() == bb_en:
                sec['visibleWhen'] = 'hasBuyBonus'
            if self.subtitles[n][IDX['cht']].strip() == pt_cht:
                sec['appendPaytable'] = True   # ★ 不是 attachPaytable
            out.append(sec)

        if not any(s.get('appendPaytable') for s in out):
            self.notes.append('⚠ 沒有段落設 appendPaytable -> 賠付表不會出現。'
                              '請確認 config.paytableSectionCht 是否對到規格書的段落標題')
        out.append({'id': self._id(), 'kind': 'betInfo'})
        out.append({'id': self._id(), 'kind': 'buttons'})
        return out

    # ---------- 符號 / 賠付表 ----------
    def symbols(self):
        return [{
            'key': s['key'],
            'image': {'fileName': s.get('fileName') or (s['key'] + '.png'),
                      'hasRealFile': bool(s.get('hasRealFile', False)),
                      'subDir': s.get('subDir', 'Symbols')},
            'displayType': s.get('displayType', 'PLAIN'),
        } for s in self.cfg['symbols']]

    def paytable(self):
        entries = []
        for s in self.cfg['symbols']:
            if not s.get('paying', True):
                continue
            entries.append({'symbolKey': s['key'], 'oddsIndex': str(s.get('oddsIndex', ''))})
            if s.get('idPlaceholder'):
                self.notes.append('⚠ 符號 %s 的 oddsIndex=%s 是佔位值（規格書「圖騰設計」ID 欄空白）'
                                  ' -> 這決定對到後端哪一組賠率，猜錯會賠錯，務必問企劃'
                                  % (s['key'], s.get('oddsIndex')))
        return {'tiers': self.cfg['tiers'], 'entries': entries}

    def dev_preview(self):
        dev = json.loads(json.dumps(DEV_DEFAULTS))
        dev.update(self.cfg.get('devPreview', {}))
        # 賠付表的預覽數字：規格書的賠付值一律是 {TBD}，所以這裡必定是假數字。
        # 但 key 一定要涵蓋所有 entries[].oddsIndex，否則預覽的賠付表是空的。
        if not dev['oddsInfo']:
            slots = [t['oddsSlot'] for t in self.cfg['tiers']]
            size = max(slots) + 1 if slots else 6
            paying = [s for s in self.cfg['symbols'] if s.get('paying', True)]
            for rank, s in enumerate(paying):
                top = 200 // (rank + 1) + 20
                arr = [0] * size
                for i, sl in enumerate(sorted(slots)):
                    arr[sl] = max(1, top // (2 ** (len(slots) - 1 - i)))
                dev['oddsInfo'][str(s.get('oddsIndex', ''))] = arr
            self.notes.append('devPreview.oddsInfo 是自動產生的預覽假數字'
                              '（工具說明頁：預覽數值不會變成正式設定）')
        return dev

    # ---------- 組裝 ----------
    def build(self):
        cfg = self.cfg
        common = {}
        for k, vals in self.commons.items():
            common[COMMON_MAP[k]] = self._langs(
                vals, self._strip_label if k in LABEL_KEYS else None)
        # 規格書沒有的一律 null（不是空字串）——工具的 i18nKeys() 用 if(text) 判斷
        for f in COMMON_ALL:
            if f not in common:
                common[f] = None
        for f in cfg.get('commonTextsNull', []):
            common[f] = None
            self.notes.append('清掉 commonTexts.%s（規格書沒有這一項）' % f)
        missing = [f for f in COMMON_ALL if common.get(f) is None
                   and f not in cfg.get('commonTextsNull', [])
                   and f not in ('rtp2Label', 'superTurboInfo')]
        if missing:
            self.notes.append('⚠ commonTexts 缺：%s（規格書沒有對應的 key）' % ', '.join(missing))

        logo = cfg.get('logo') or {}
        def asset(a):
            if not a:
                return None
            return {'fileName': a.get('fileName', ''),
                    'hasRealFile': bool(a.get('hasRealFile', False)),
                    'subDir': a.get('subDir', '')}

        return {
            'schemaVersion': '1.0',
            'dictionary': {},
            'meta': {'id': str(cfg.get('meta', {}).get('id', '')),
                     'code': str(cfg.get('meta', {}).get('code', '')),
                     'name': self._langs(self.name)},
            'logo': {'default': asset(logo.get('default')) or
                                {'fileName': '', 'hasRealFile': False, 'subDir': ''},
                     'zh': asset(logo.get('zh')),
                     'vi': asset(logo.get('vi'))},
            'symbols': self.symbols(),
            'sections': self.sections(),
            'paytable': self.paytable(),
            'toggles': dict({'showBtnInfo': True, 'showBetInfo': True, 'showAutoBtn': True,
                             'showTurboBtn': True, 'useTurboPhase': False,
                             'hasBuyBonus': False}, **cfg.get('toggles', {})),
            'commonTexts': common,
            'devPreview': self.dev_preview(),
        }

    # ---------- 交付報告 ----------
    def report(self, spec):
        print('規格書 subtitle -> 段落對照')
        print('%-4s %-16s %-7s %-11s %s' % ('#', '標題(繁中)', '條數', '編號', '備註'))
        for i, sec in enumerate(spec['sections'], 1):
            if sec['kind'] != 'ruleList':
                print('%-4d %-16s %-7s %-11s %s' % (i, sec['kind'], '-', '-', '平台固定區'))
                continue
            extra = []
            if sec.get('appendPaytable'):
                extra.append('接賠付表')
            if sec.get('visibleWhen'):
                extra.append('條件顯示')
            print('%-4d %-16s %-7s %-11s %s' % (
                i, sec['title']['cht'], '%d 條' % len(sec['rules']),
                sec['numbering'], ' '.join(extra)))
        if self.dropped:
            print()
            print('刪掉「沒有資料」的規則（%d 條，內容還是 {TBD}）' % len(self.dropped))
            for x in self.dropped:
                print(' -', x)
        if self.notes:
            print()
            print('說明 / 待辦')
            for x in self.notes:
                print(' -', x)
        print()
        print('人工補：遊戲代號%s、LOGO 檔名%s、符號圖檔 %d 個' % (
            '(已填)' if spec['meta']['code'] else '(未填)',
            '(已填)' if spec['logo']['default']['fileName'] else '(未填)',
            len(spec['symbols'])))


def main():
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    csv_path, cfg_path, out_path = sys.argv[1:4]
    cfg = json.load(io.open(cfg_path, encoding='utf-8'))
    for req in ('symbols', 'tiers'):
        if req not in cfg:
            sys.exit('config.json 缺 "%s"' % req)
    g = Gen(csv_path, cfg)
    spec = g.build()
    with io.open(out_path, 'w', encoding='utf-8') as f:
        json.dump(spec, f, ensure_ascii=False, indent=2)
    print('wrote', out_path)
    print()
    g.report(spec)


if __name__ == '__main__':
    main()

# -*- coding: utf-8 -*-
"""validate.py — 驗 spec.json

用法:
    python validate.py <spec.json>

做兩件事:
  A. 欄位名 / 合法值白名單 —— 抓 attachPaytable 這類拼錯。
     工具對不認識的欄位「不報錯也不忽略警告，就是靜默不生效」，所以這關最重要。
  B. 模擬工具的匯出前檢查（validate()）—— 缺語系、缺圖、符號沒登記、oddsInfo 對不到…

離開碼: 0 = 只有提示；1 = 有 ERROR
"""
import io, json, re, sys, collections

LANGS = ['cht', 'chs', 'en', 'th', 'vi', 'ms', 'es']
LANG_NAME = {'cht': '繁中', 'chs': '簡中', 'en': '英文', 'th': '泰文',
             'vi': '越南', 'ms': '馬來', 'es': '西班牙'}

TOP = {'schemaVersion', 'dictionary', 'meta', 'logo', 'symbols', 'sections',
       'paytable', 'toggles', 'commonTexts', 'devPreview'}
SEC_COMMON = {'id', 'kind'}
SEC_RULELIST = SEC_COMMON | {'titleMode', 'title', 'boxStyle', 'numbering', 'rules',
                             'subLabel', 'topImages', 'topImagePlacement',
                             'appendPaytable', 'visibleWhen'}
SEC_CALLOUT = SEC_COMMON | {'titleMode', 'title', 'callouts',
                            'topImages', 'topImagePlacement', 'visibleWhen'}
I18N_EXTRA = {'key', 'socialApiOverride'}
COMMON_FIELDS = {
    'payoutInfoTitle', 'maxPayoutLabel', 'maxWinOddsLabel', 'minBetLabel', 'maxBetLabel',
    'rtpLabel', 'extraBetRtpLabel', 'rtp1Label', 'rtp2Label', 'buttonsTitle',
    'spinInfo', 'autoInfo', 'turboInfo', 'superTurboInfo', 'betInfo',
    'optionInfo', 'ruleInfo', 'soundInfo',
}
ENUMS = {
    'kind':              {'ruleList', 'symbolCallout', 'betInfo', 'buttons'},
    'titleMode':         {'header', 'inline', 'none'},
    'boxStyle':          {'bordered', 'no-border', 'plain'},
    'numbering':         {'sequential', 'none'},
    'displayType':      {'LG', 'NOR', 'PLAIN'},
    'topImagePlacement': {'inside', 'outside'},
    'visibleWhen':       {'hasBuyBonus'},
}
TOP_IMG_SIZE = {'LG', 'NOR', 'base', 'natural'}
# 曾經真的猜錯過的名字 -> 正確名字
TYPOS = {'attachPaytable': 'appendPaytable', 'attachedPaytable': 'appendPaytable',
         'showPaytable': 'appendPaytable', 'visibleIf': 'visibleWhen',
         'displayTypes': 'displayType', 'commonText': 'commonTexts'}

E, W = [], []
err = lambda m: E.append(m)
warn = lambda m: W.append(m)


def check_i18n(t, where, required=True):
    if t is None:
        return
    if not isinstance(t, dict):
        err('%s：應該是 I18nText 物件' % where)
        return
    for k in t:
        if k not in LANGS and k not in I18N_EXTRA:
            err('%s：不認識的語系/欄位 "%s"' % (where, k))
    if required:
        miss = [LANG_NAME[l] for l in LANGS if not str(t.get(l, '')).strip()]
        if miss:
            err('%s：缺 %s' % (where, '、'.join(miss)))
    for l in LANGS:
        if '{TBD}' in str(t.get(l, '')):
            warn('%s(%s)：還有 {TBD}，上線會直接印給玩家看' % (where, LANG_NAME[l]))


def check_asset(a, where):
    if a is None:
        return
    for k in a:
        if k not in ('fileName', 'hasRealFile', 'subDir'):
            err('%s：不認識的欄位 "%s"' % (where, k))
    if not a.get('fileName'):
        warn('%s：沒填檔名' % where)
    elif not a.get('hasRealFile'):
        warn('%s：尚無圖檔（工具會產代圖並在匯出時列清單）' % where)


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    spec = json.load(io.open(sys.argv[1], encoding='utf-8'))

    # ---------- A. 欄位名 / 合法值 ----------
    if spec.get('schemaVersion') != '1.0':
        err('schemaVersion 不是 "1.0"（工具會直接擋掉沒有 schemaVersion 的檔案）')
    for k in spec:
        if k in TYPOS:
            err('頂層欄位 "%s" 拼錯 -> 應該是 "%s"' % (k, TYPOS[k]))
        elif k not in TOP:
            err('頂層不認識的欄位 "%s"' % k)
    for k in TOP - set(spec):
        err('頂層缺欄位 "%s"' % k)

    declared = set()
    for i, s in enumerate(spec.get('symbols', []), 1):
        w = '符號第%d個' % i
        for k in s:
            if k not in ('key', 'image', 'displayType'):
                err('%s：不認識的欄位 "%s"' % (w, k))
        if not s.get('key'):
            err('%s：沒填 key' % w)
        elif not re.fullmatch(r'[A-Za-z0-9]+', s['key']):
            err('%s：key "%s" 只能英數' % (w, s['key']))
        else:
            declared.add(s['key'])
        if s.get('displayType') not in ENUMS['displayType']:
            err('%s(%s)：displayType "%s" 不合法（%s）'
                % (w, s.get('key'), s.get('displayType'), '/'.join(sorted(ENUMS['displayType']))))
        check_asset(s.get('image'), '%s(%s) 的圖' % (w, s.get('key')))

    used, pt_used = set(), False
    for i, sec in enumerate(spec.get('sections', []), 1):
        kind = sec.get('kind')
        w = '第%d段' % i
        if kind not in ENUMS['kind']:
            err('%s：kind "%s" 不合法' % (w, kind))
            continue
        allow = (SEC_RULELIST if kind == 'ruleList'
                 else SEC_CALLOUT if kind == 'symbolCallout' else SEC_COMMON)
        for k in sec:
            if k in TYPOS:
                err('%s：欄位 "%s" 拼錯 -> 應該是 "%s"（工具不認識就靜默不生效）'
                    % (w, k, TYPOS[k]))
            elif k not in allow:
                err('%s(%s)：不認識的欄位 "%s"' % (w, kind, k))
        for f in ('titleMode', 'boxStyle', 'numbering', 'topImagePlacement', 'visibleWhen'):
            if f in sec and sec[f] not in ENUMS[f]:
                err('%s：%s "%s" 不合法（%s）'
                    % (w, f, sec[f], '/'.join(sorted(ENUMS[f]))))
        if kind in ('betInfo', 'buttons'):
            continue

        title = sec.get('title')
        if sec.get('titleMode', 'none') != 'none':
            if title is None:
                err('%s：titleMode=%s 卻沒有 title' % (w, sec['titleMode']))
            else:
                check_i18n(title, '%s 標題' % w)
        label = (title or {}).get('cht') or kind
        w = '第%d段「%s」' % (i, label)
        if 'subLabel' in sec:
            check_i18n(sec['subLabel'], '%s 小標' % w)

        for ri, r in enumerate(sec.get('rules', []), 1):
            for k in r:
                if k not in ('text', 'afterImage'):
                    err('%s 第%d條：不認識的欄位 "%s"' % (w, ri, k))
            check_i18n(r.get('text'), '%s 第%d條' % (w, ri))
            # 自帶編號的檢查一條只報一次（否則 7 語系會噴 7 行講同一件事）
            self_numbered = []
            for l in LANGS:
                t = str((r.get('text') or {}).get(l, ''))
                used |= set(re.findall(r'@([A-Za-z0-9]+)', t))
                if re.match(r'^\s*\d+\s*[.、)]', t):
                    self_numbered.append(LANG_NAME[l])
            if self_numbered and sec.get('numbering') == 'sequential':
                err('%s 第%d條：文字自帶編號又設 numbering=sequential -> 畫面會變 1.1.'
                    '（%s；RULES.md §5）'
                    % (w, ri, '全語系' if len(self_numbered) == len(LANGS)
                       else '、'.join(self_numbered)))
            if r.get('afterImage'):
                check_asset((r['afterImage'] or {}).get('image'), '%s 第%d條的下接圖' % (w, ri))

        for ci, c in enumerate(sec.get('callouts', []), 1):
            if not c.get('symbolKeys'):
                err('%s 卡片%d：沒指定符號' % (w, ci))
            used |= set(c.get('symbolKeys') or [])
            check_i18n(c.get('text'), '%s 卡片%d' % (w, ci))

        for ti, im in enumerate(sec.get('topImages', []) or [], 1):
            if im.get('kind') == 'symbol':
                used.add(im.get('symbolKey'))
                if im.get('size') not in TOP_IMG_SIZE:
                    err('%s 頂圖%d：size "%s" 不合法（%s）'
                        % (w, ti, im.get('size'), '/'.join(sorted(TOP_IMG_SIZE))))
            elif im.get('kind') == 'custom':
                check_asset(((im.get('ref') or {}).get('image')), '%s 頂圖%d' % (w, ti))
            else:
                err('%s 頂圖%d：kind 只能 symbol / custom' % (w, ti))

        if sec.get('numbering') == 'none' and sec.get('rules'):
            if all(re.match(r'^\s*\d+\.\s', str(r['text']['cht'])) for r in sec['rules']):
                warn('%s：每條都自帶編號但 numbering=none，確認是刻意的' % w)
        if sec.get('appendPaytable'):
            pt_used = True

    for k in sorted(used - declared):
        if k:
            err('文案用到 @%s 但 symbols 沒登記' % k)
    if not pt_used:
        err('沒有任何段落設 appendPaytable -> 賠付表不會出現在頁面上')
    for kind in ('betInfo', 'buttons'):
        if not any(s.get('kind') == kind for s in spec.get('sections', [])):
            err('sections 裡沒有 %s 段' % kind)

    # ---------- commonTexts ----------
    ct = spec.get('commonTexts', {})
    for k in ct:
        if k in TYPOS:
            err('commonTexts.%s 拼錯 -> 應該是 "%s"' % (k, TYPOS[k]))
        elif k not in COMMON_FIELDS:
            err('commonTexts 不認識的欄位 "%s"' % k)
    for f in COMMON_FIELDS - set(ct):
        err('commonTexts 缺欄位 "%s"（沒有就明確設 null）' % f)
    for f, v in ct.items():
        if v is None:
            continue
        if isinstance(v, dict) and not any(str(v.get(l, '')).strip() for l in LANGS):
            err('commonTexts.%s 是空的 -> 該遊戲沒有就設 null，不要留空物件'
                '（工具的 i18nKeys() 用 if(text) 判斷，空物件會被寫進語系檔）' % f)
        else:
            check_i18n(v, 'commonTexts.%s' % f)

    # ---------- paytable ----------
    pt = spec.get('paytable', {})
    dev = spec.get('devPreview', {})
    odds = dev.get('oddsInfo', {}) or {}
    if not pt.get('tiers'):
        err('paytable：沒有檔位')
    if not pt.get('entries'):
        err('paytable：沒有符號列')
    slots = []
    for i, t in enumerate(pt.get('tiers', []), 1):
        for k in t:
            if k not in ('label', 'oddsSlot'):
                err('檔位%d：不認識的欄位 "%s"' % (i, k))
        if not str(t.get('label', '')).strip():
            err('檔位%d：沒填 label' % i)
        if not isinstance(t.get('oddsSlot'), int):
            err('檔位%d：oddsSlot 要是整數' % i)
        else:
            slots.append(t['oddsSlot'])
    for i, e in enumerate(pt.get('entries', []), 1):
        for k in e:
            if k not in ('symbolKey', 'oddsIndex'):
                err('賠付表第%d列：不認識的欄位 "%s"' % (i, k))
        if e.get('symbolKey') not in declared:
            err('賠付表第%d列：符號 "%s" 沒在 symbols 登記' % (i, e.get('symbolKey')))
        oi = str(e.get('oddsIndex', ''))
        if not oi:
            err('賠付表第%d列(%s)：oddsIndex 空白'
                ' -> 這是正式資料，會寫進 OddsInfoManager.tsx' % (i, e.get('symbolKey')))
        elif oi not in odds:
            err('賠付表第%d列(%s)：devPreview.oddsInfo 沒有 key "%s" -> 預覽的賠付表會是空的'
                % (i, e.get('symbolKey'), oi))
        elif slots:
            arr = odds[oi]
            if not isinstance(arr, list) or len(arr) <= max(slots):
                err('devPreview.oddsInfo["%s"] 長度 %s，但最大 oddsSlot=%d'
                    % (oi, len(arr) if isinstance(arr, list) else '?', max(slots)))

    # ---------- toggles / devPreview ----------
    tg = spec.get('toggles', {})
    for k in tg:
        if k not in ('showBtnInfo', 'showBetInfo', 'showAutoBtn', 'showTurboBtn',
                     'useTurboPhase', 'hasBuyBonus'):
            err('toggles 不認識的欄位 "%s"' % k)
    if any(s.get('visibleWhen') == 'hasBuyBonus' for s in spec.get('sections', [])) \
            and not tg.get('hasBuyBonus'):
        warn('有段落設 visibleWhen=hasBuyBonus，但 toggles.hasBuyBonus 是 false'
             ' -> 預覽看不到那一段')
    if tg.get('useTurboPhase') and ct.get('superTurboInfo') is None:
        err('useTurboPhase=true 但 commonTexts.superTurboInfo 是 null -> 超加速按鈕說明會空白')
    if not tg.get('useTurboPhase') and ct.get('superTurboInfo') is not None:
        warn('useTurboPhase=false 卻留著 superTurboInfo -> 規格書沒有就設 null')
    if not isinstance(dev.get('rtp'), str):
        warn('devPreview.rtp 應該是字串（新版 GameInfo type 是 string）')

    # ---------- i18n key 重複 ----------
    keys = []
    for i, sec in enumerate(spec.get('sections', []), 1):
        if sec.get('kind') in ('betInfo', 'buttons'):
            continue
        if sec.get('title'):
            keys.append(sec['title'].get('key') or 'subtitle%d' % i)
        if sec.get('subLabel'):
            keys.append(sec['subLabel'].get('key') or 'sublabel%d' % i)
        for ri, r in enumerate(sec.get('rules', []), 1):
            keys.append((r.get('text') or {}).get('key') or 'rule%d-%d' % (i, ri))
        for ci, c in enumerate(sec.get('callouts', []), 1):
            keys.append((c.get('text') or {}).get('key') or 'symtext%d-%d' % (i, ci))
    for k, n in collections.Counter(keys).items():
        if n > 1:
            err('i18n key "%s" 重複 %d 次 -> 語系檔會互相覆蓋' % (k, n))

    # ---------- meta / logo ----------
    check_i18n((spec.get('meta') or {}).get('name'), 'meta.name')
    if not str((spec.get('meta') or {}).get('id', '')).strip():
        warn('meta.id 沒填')
    if not str((spec.get('meta') or {}).get('code', '')).strip():
        warn('meta.code（遊戲代號）沒填 -> 要跟平台配號的人要，例 AR2')
    lg = spec.get('logo') or {}
    check_asset(lg.get('default'), 'logo.default')
    for k in ('zh', 'vi'):
        if lg.get(k):
            check_asset(lg[k], 'logo.%s' % k)

    # ---------- 報告 ----------
    print('=== ERROR（%d）===' % len(E))
    for x in E:
        print(' ✗', x)
    if not E:
        print(' （無）')
    print()
    print('=== 提示 / 待補（%d）===' % len(W))
    for x in W:
        print(' !', x)
    if not W:
        print(' （無）')
    print()
    print('段落 %d、規則 %d、符號 %d、i18n key %d'
          % (len(spec.get('sections', [])),
             sum(len(s.get('rules', [])) for s in spec.get('sections', [])),
             len(spec.get('symbols', [])), len(keys)))
    sys.exit(1 if E else 0)


if __name__ == '__main__':
    main()

# -*- coding: utf-8 -*-
"""spec_gen.py — 規格書 INFO 分頁 → GameInfo 產生器的 spec.json

用法:
    python spec_gen.py <info.csv> <config.json> <out.json>

info.csv  : 規格書 INFO 或 多國語系表 分頁的 CSV 匯出（兩者內容相同）
config.json: 規格書沒有的東西（符號表、賠付檔位、meta、logo、toggles…），見 example.config.json
out.json  : 輸出

格式規範見 RULES.md；工具位置與陷阱見 E:\\Igaming\\GAMEINFO_PLAYBOOK.md
"""
import csv, io, json, re, sys, collections

LANGS = ['cht', 'chs', 'en', 'th', 'vi', 'ms', 'es']
# 規格書 INFO 分頁的語系欄順序（zh-TW, zh-CN, en-US, th-TH, vi-VN, ms-MY, es-ES）
IDX = {'cht': 0, 'chs': 1, 'en': 2, 'th': 3, 'vi': 4, 'ms': 5, 'es': 6}

# 規格書 key -> commonTexts 欄位。RTP2 是「RTP（Extra Bet）」-> extraBetRtpLabel，不是 rtp2Label
COMMON_MAP = {
    'Payout':      'payoutInfoTitle',
    'max-payout':  'maxPayoutLabel',
    'max-winodds': 'maxWinOddsLabel',
    'min-bet':     'minBetLabel',
    'max-bet':     'maxBetLabel',
    'RTP':         'rtpLabel',
    'RTP1':        'rtp1Label',
    'RTP2':        'extraBetRtpLabel',
    'buttons':     'buttonsTitle',
    'spin-info':   'spinInfo',
    'auto-info':   'autoInfo',
    'bet-info':    'betInfo',
    'turbo-info':  'turboInfo',
    'option-info': 'optionInfo',
    'rule-info':   'ruleInfo',
    'sound-info':  'soundInfo',
}
COMMON_ALL = list(COMMON_MAP.values()) + ['rtp2Label', 'superTurboInfo']
# 這些只是「標籤前綴」，數值由平台執行期灌入 -> 規格書的 {TBD} 與尾隨 % 要清掉
LABEL_KEYS = {'max-payout', 'max-winodds', 'min-bet', 'max-bet', 'RTP', 'RTP1', 'RTP2'}

NUMBERED_RE = re.compile(r'^\d+\.\s*')

DEV_DEFAULTS = {
    'oddsInfo': {}, 'infoMaxPayout': 10000, 'infoMaxWinOdds': 1000,
    'infoMinBet': 50, 'infoMaxBet': 5000, 'currencySymbol': '$', 'infoMaxLines': 50,
    'rtp': '96.00', 'buyBonusDataList': [], 'logo': 'logo', 'lang': 'en',
    'extraInfo': {'bet_level': [], 'Rtp1': None}, 'Rtp1': '',
    'currencyRatio': 0.01, 'decimalPlaces': 2, 'isDaraEnv': False,
}


class Gen(object):
    def __init__(self, csv_path, cfg):
        self.cfg = cfg
        self.notes = []
        self.dropped = []
        self._n = 0
        self._load(csv_path)

    # ---------- 讀規格書 ----------
    def _load(self, path):
        rows = list(csv.reader(io.open(path, encoding='utf-8')))
        # 第 3 列是機器表頭(section/key/zh-TW…)、第 4 列是人看的表頭 -> 資料從第 5 列起
        head = -1
        for i, r in enumerate(rows[:8]):
            if len(r) > 1 and r[0].strip() == 'section' and r[1].strip() == 'key':
                head = i
                break
        if head < 0:
            sys.exit('讀不到表頭：INFO 分頁應該有一列是 section | key | zh-TW | …')

        self.name = None
        self.subtitles = {}
        self.rules = {}
        self.commons = collections.OrderedDict()
        for cells in rows[head + 2:]:
            cells = cells + [''] * 9
            section, key = cells[0].strip(), cells[1].strip()
            vals = [c.strip() for c in cells[2:9]]
            if section == '機台名' and not key:
                self.name = vals
            elif re.fullmatch(r'subtitle(\d+)', key or ''):
                self.subtitles[int(key[8:])] = vals
            elif re.fullmatch(r'rule\d+-\d+', key or ''):
                m = re.fullmatch(r'rule(\d+)-(\d+)', key)
                self.rules.setdefault(int(m.group(1)), []).append((int(m.group(2)), vals))
            elif key in COMMON_MAP:
                self.commons[key] = vals
        if not self.name:
            sys.exit('規格書裡找不到「機台名」那一列')
        if not self.subtitles:
            sys.exit('規格書裡找不到任何 subtitleN')

    def _id(self):
        self._n += 1
        return 'id-%s%04d' % (self.cfg.get('idPrefix', 'gi'), self._n)

    @staticmethod
    def _langs(vals, xform=None):
        return {L: (xform(vals[IDX[L]]) if xform else vals[IDX[L]]) for L in LANGS}

    @staticmethod
    def _strip_label(t):
        return re.sub(r'\s*%\s*$', '', t.replace('{TBD}', '')).rstrip()

    # ---------- 段落 ----------
    def sections(self):
        cfg = self.cfg
        bb_en = cfg.get('buyBonusSectionEn', 'buy bonus').lower()
        pt_cht = cfg.get('paytableSectionCht', '賠付表')
        pin = cfg.get('pinKeys', False)
        drop_tbd = cfg.get('dropTbdRules', True)
        out = []

        for n in sorted(self.subtitles):
            rs = []
            for m, v in sorted(self.rules.get(n, [])):
                if drop_tbd and '{TBD}' in v[IDX['cht']]:
                    # 「沒有資料」的規則不留：上線會把 {TBD} 直接印給玩家看
                    self.dropped.append('rule%d-%d  %s' % (n, m, v[IDX['cht']]))
                    continue
                rs.append((m, v))

            # 編號策略逐段判斷，同段不混用（RULES.md §5）
            numbered = bool(rs) and all(NUMBERED_RE.match(v[IDX['cht']]) for _, v in rs)
            xf = (lambda t: NUMBERED_RE.sub('', t)) if numbered else None
            if not numbered and rs:
                self.notes.append('subtitle%d「%s」規格書原文沒編號 -> numbering: none'
                                  % (n, self.subtitles[n][IDX['cht']]))

            title = self._langs(self.subtitles[n])
            rules = []
            for m, v in rs:
                t = self._langs(v, xf)
                if pin:
                    t['key'] = 'rule%d-%d' % (len(out) + 1, len(rules) + 1)
                rules.append({'text': t})
            if pin:
                title['key'] = 'subtitle%d' % (len(out) + 1)

            sec = {
                'id': self._id(),
                'kind': 'ruleList',
                'titleMode': 'header',
                'title': title,
                'boxStyle': cfg.get('boxStyle', 'no-border'),
                'numbering': 'sequential' if numbered else 'none',
                'rules': rules,
            }
            if self.subtitles[n][IDX['en']].strip().lower() == bb_en:
                sec['visibleWhen'] = 'hasBuyBonus'
            if self.subtitles[n][IDX['cht']].strip() == pt_cht:
                sec['appendPaytable'] = True   # ★ 不是 attachPaytable
            out.append(sec)

        if not any(s.get('appendPaytable') for s in out):
            self.notes.append('⚠ 沒有段落設 appendPaytable -> 賠付表不會出現。'
                              '請確認 config.paytableSectionCht 是否對到規格書的段落標題')
        out.append({'id': self._id(), 'kind': 'betInfo'})
        out.append({'id': self._id(), 'kind': 'buttons'})
        return out

    # ---------- 符號 / 賠付表 ----------
    def symbols(self):
        return [{
            'key': s['key'],
            'image': {'fileName': s.get('fileName') or (s['key'] + '.png'),
                      'hasRealFile': bool(s.get('hasRealFile', False)),
                      'subDir': s.get('subDir', 'Symbols')},
            'displayType': s.get('displayType', 'PLAIN'),
        } for s in self.cfg['symbols']]

    def paytable(self):
        entries = []
        for s in self.cfg['symbols']:
            if not s.get('paying', True):
                continue
            entries.append({'symbolKey': s['key'], 'oddsIndex': str(s.get('oddsIndex', ''))})
            if s.get('idPlaceholder'):
                self.notes.append('⚠ 符號 %s 的 oddsIndex=%s 是佔位值（規格書「圖騰設計」ID 欄空白）'
                                  ' -> 這決定對到後端哪一組賠率，猜錯會賠錯，務必問企劃'
                                  % (s['key'], s.get('oddsIndex')))
        return {'tiers': self.cfg['tiers'], 'entries': entries}

    def dev_preview(self):
        dev = json.loads(json.dumps(DEV_DEFAULTS))
        dev.update(self.cfg.get('devPreview', {}))
        # 賠付表的預覽數字：規格書的賠付值一律是 {TBD}，所以這裡必定是假數字。
        # 但 key 一定要涵蓋所有 entries[].oddsIndex，否則預覽的賠付表是空的。
        if not dev['oddsInfo']:
            slots = [t['oddsSlot'] for t in self.cfg['tiers']]
            size = max(slots) + 1 if slots else 6
            paying = [s for s in self.cfg['symbols'] if s.get('paying', True)]
            for rank, s in enumerate(paying):
                top = 200 // (rank + 1) + 20
                arr = [0] * size
                for i, sl in enumerate(sorted(slots)):
                    arr[sl] = max(1, top // (2 ** (len(slots) - 1 - i)))
                dev['oddsInfo'][str(s.get('oddsIndex', ''))] = arr
            self.notes.append('devPreview.oddsInfo 是自動產生的預覽假數字'
                              '（工具說明頁：預覽數值不會變成正式設定）')
        return dev

    # ---------- 組裝 ----------
    def build(self):
        cfg = self.cfg
        common = {}
        for k, vals in self.commons.items():
            common[COMMON_MAP[k]] = self._langs(
                vals, self._strip_label if k in LABEL_KEYS else None)
        # 規格書沒有的一律 null（不是空字串）——工具的 i18nKeys() 用 if(text) 判斷
        for f in COMMON_ALL:
            if f not in common:
                common[f] = None
        for f in cfg.get('commonTextsNull', []):
            common[f] = None
            self.notes.append('清掉 commonTexts.%s（規格書沒有這一項）' % f)
        missing = [f for f in COMMON_ALL if common.get(f) is None
                   and f not in cfg.get('commonTextsNull', [])
                   and f not in ('rtp2Label', 'superTurboInfo')]
        if missing:
            self.notes.append('⚠ commonTexts 缺：%s（規格書沒有對應的 key）' % ', '.join(missing))

        logo = cfg.get('logo') or {}
        def asset(a):
            if not a:
                return None
            return {'fileName': a.get('fileName', ''),
                    'hasRealFile': bool(a.get('hasRealFile', False)),
                    'subDir': a.get('subDir', '')}

        return {
            'schemaVersion': '1.0',
            'dictionary': {},
            'meta': {'id': str(cfg.get('meta', {}).get('id', '')),
                     'code': str(cfg.get('meta', {}).get('code', '')),
                     'name': self._langs(self.name)},
            'logo': {'default': asset(logo.get('default')) or
                                {'fileName': '', 'hasRealFile': False, 'subDir': ''},
                     'zh': asset(logo.get('zh')),
                     'vi': asset(logo.get('vi'))},
            'symbols': self.symbols(),
            'sections': self.sections(),
            'paytable': self.paytable(),
            'toggles': dict({'showBtnInfo': True, 'showBetInfo': True, 'showAutoBtn': True,
                             'showTurboBtn': True, 'useTurboPhase': False,
                             'hasBuyBonus': False}, **cfg.get('toggles', {})),
            'commonTexts': common,
            'devPreview': self.dev_preview(),
        }

    # ---------- 交付報告 ----------
    def report(self, spec):
        print('規格書 subtitle -> 段落對照')
        print('%-4s %-16s %-7s %-11s %s' % ('#', '標題(繁中)', '條數', '編號', '備註'))
        for i, sec in enumerate(spec['sections'], 1):
            if sec['kind'] != 'ruleList':
                print('%-4d %-16s %-7s %-11s %s' % (i, sec['kind'], '-', '-', '平台固定區'))
                continue
            extra = []
            if sec.get('appendPaytable'):
                extra.append('接賠付表')
            if sec.get('visibleWhen'):
                extra.append('條件顯示')
            print('%-4d %-16s %-7s %-11s %s' % (
                i, sec['title']['cht'], '%d 條' % len(sec['rules']),
                sec['numbering'], ' '.join(extra)))
        if self.dropped:
            print()
            print('刪掉「沒有資料」的規則（%d 條，內容還是 {TBD}）' % len(self.dropped))
            for x in self.dropped:
                print(' -', x)
        if self.notes:
            print()
            print('說明 / 待辦')
            for x in self.notes:
                print(' -', x)
        print()
        print('人工補：遊戲代號%s、LOGO 檔名%s、符號圖檔 %d 個' % (
            '(已填)' if spec['meta']['code'] else '(未填)',
            '(已填)' if spec['logo']['default']['fileName'] else '(未填)',
            len(spec['symbols'])))


def main():
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    csv_path, cfg_path, out_path = sys.argv[1:4]
    cfg = json.load(io.open(cfg_path, encoding='utf-8'))
    for req in ('symbols', 'tiers'):
        if req not in cfg:
            sys.exit('config.json 缺 "%s"' % req)
    g = Gen(csv_path, cfg)
    spec = g.build()
    with io.open(out_path, 'w', encoding='utf-8') as f:
        json.dump(spec, f, ensure_ascii=False, indent=2)
    print('wrote', out_path)
    print()
    g.report(spec)


if __name__ == '__main__':
    main()

# -*- coding: utf-8 -*-
"""validate.py — 驗 spec.json

用法:
    python validate.py <spec.json>

做兩件事:
  A. 欄位名 / 合法值白名單 —— 抓 attachPaytable 這類拼錯。
     工具對不認識的欄位「不報錯也不忽略警告，就是靜默不生效」，所以這關最重要。
  B. 模擬工具的匯出前檢查（validate()）—— 缺語系、缺圖、符號沒登記、oddsInfo 對不到…

離開碼: 0 = 只有提示；1 = 有 ERROR
"""
import io, json, re, sys, collections

LANGS = ['cht', 'chs', 'en', 'th', 'vi', 'ms', 'es']
LANG_NAME = {'cht': '繁中', 'chs': '簡中', 'en': '英文', 'th': '泰文',
             'vi': '越南', 'ms': '馬來', 'es': '西班牙'}

TOP = {'schemaVersion', 'dictionary', 'meta', 'logo', 'symbols', 'sections',
       'paytable', 'toggles', 'commonTexts', 'devPreview'}
SEC_COMMON = {'id', 'kind'}
SEC_RULELIST = SEC_COMMON | {'titleMode', 'title', 'boxStyle', 'numbering', 'rules',
                             'subLabel', 'topImages', 'topImagePlacement',
                             'appendPaytable', 'visibleWhen'}
SEC_CALLOUT = SEC_COMMON | {'titleMode', 'title', 'callouts',
                            'topImages', 'topImagePlacement', 'visibleWhen'}
I18N_EXTRA = {'key', 'socialApiOverride'}
COMMON_FIELDS = {
    'payoutInfoTitle', 'maxPayoutLabel', 'maxWinOddsLabel', 'minBetLabel', 'maxBetLabel',
    'rtpLabel', 'extraBetRtpLabel', 'rtp1Label', 'rtp2Label', 'buttonsTitle',
    'spinInfo', 'autoInfo', 'turboInfo', 'superTurboInfo', 'betInfo',
    'optionInfo', 'ruleInfo', 'soundInfo',
}
ENUMS = {
    'kind':              {'ruleList', 'symbolCallout', 'betInfo', 'buttons'},
    'titleMode':         {'header', 'inline', 'none'},
    'boxStyle':          {'bordered', 'no-border', 'plain'},
    'numbering':         {'sequential', 'none'},
    'displayType':      {'LG', 'NOR', 'PLAIN'},
    'topImagePlacement': {'inside', 'outside'},
    'visibleWhen':       {'hasBuyBonus'},
}
TOP_IMG_SIZE = {'LG', 'NOR', 'base', 'natural'}
# 曾經真的猜錯過的名字 -> 正確名字
TYPOS = {'attachPaytable': 'appendPaytable', 'attachedPaytable': 'appendPaytable',
         'showPaytable': 'appendPaytable', 'visibleIf': 'visibleWhen',
         'displayTypes': 'displayType', 'commonText': 'commonTexts'}

E, W = [], []
err = lambda m: E.append(m)
warn = lambda m: W.append(m)


def check_i18n(t, where, required=True):
    if t is None:
        return
    if not isinstance(t, dict):
        err('%s：應該是 I18nText 物件' % where)
        return
    for k in t:
        if k not in LANGS and k not in I18N_EXTRA:
            err('%s：不認識的語系/欄位 "%s"' % (where, k))
    if required:
        miss = [LANG_NAME[l] for l in LANGS if not str(t.get(l, '')).strip()]
        if miss:
            err('%s：缺 %s' % (where, '、'.join(miss)))
    for l in LANGS:
        if '{TBD}' in str(t.get(l, '')):
            warn('%s(%s)：還有 {TBD}，上線會直接印給玩家看' % (where, LANG_NAME[l]))


def check_asset(a, where):
    if a is None:
        return
    for k in a:
        if k not in ('fileName', 'hasRealFile', 'subDir'):
            err('%s：不認識的欄位 "%s"' % (where, k))
    if not a.get('fileName'):
        warn('%s：沒填檔名' % where)
    elif not a.get('hasRealFile'):
        warn('%s：尚無圖檔（工具會產代圖並在匯出時列清單）' % where)


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    spec = json.load(io.open(sys.argv[1], encoding='utf-8'))

    # ---------- A. 欄位名 / 合法值 ----------
    if spec.get('schemaVersion') != '1.0':
        err('schemaVersion 不是 "1.0"（工具會直接擋掉沒有 schemaVersion 的檔案）')
    for k in spec:
        if k in TYPOS:
            err('頂層欄位 "%s" 拼錯 -> 應該是 "%s"' % (k, TYPOS[k]))
        elif k not in TOP:
            err('頂層不認識的欄位 "%s"' % k)
    for k in TOP - set(spec):
        err('頂層缺欄位 "%s"' % k)

    declared = set()
    for i, s in enumerate(spec.get('symbols', []), 1):
        w = '符號第%d個' % i
        for k in s:
            if k not in ('key', 'image', 'displayType'):
                err('%s：不認識的欄位 "%s"' % (w, k))
        if not s.get('key'):
            err('%s：沒填 key' % w)
        elif not re.fullmatch(r'[A-Za-z0-9]+', s['key']):
            err('%s：key "%s" 只能英數' % (w, s['key']))
        else:
            declared.add(s['key'])
        if s.get('displayType') not in ENUMS['displayType']:
            err('%s(%s)：displayType "%s" 不合法（%s）'
                % (w, s.get('key'), s.get('displayType'), '/'.join(sorted(ENUMS['displayType']))))
        check_asset(s.get('image'), '%s(%s) 的圖' % (w, s.get('key')))

    used, pt_used = set(), False
    for i, sec in enumerate(spec.get('sections', []), 1):
        kind = sec.get('kind')
        w = '第%d段' % i
        if kind not in ENUMS['kind']:
            err('%s：kind "%s" 不合法' % (w, kind))
            continue
        allow = (SEC_RULELIST if kind == 'ruleList'
                 else SEC_CALLOUT if kind == 'symbolCallout' else SEC_COMMON)
        for k in sec:
            if k in TYPOS:
                err('%s：欄位 "%s" 拼錯 -> 應該是 "%s"（工具不認識就靜默不生效）'
                    % (w, k, TYPOS[k]))
            elif k not in allow:
                err('%s(%s)：不認識的欄位 "%s"' % (w, kind, k))
        for f in ('titleMode', 'boxStyle', 'numbering', 'topImagePlacement', 'visibleWhen'):
            if f in sec and sec[f] not in ENUMS[f]:
                err('%s：%s "%s" 不合法（%s）'
                    % (w, f, sec[f], '/'.join(sorted(ENUMS[f]))))
        if kind in ('betInfo', 'buttons'):
            continue

        title = sec.get('title')
        if sec.get('titleMode', 'none') != 'none':
            if title is None:
                err('%s：titleMode=%s 卻沒有 title' % (w, sec['titleMode']))
            else:
                check_i18n(title, '%s 標題' % w)
        label = (title or {}).get('cht') or kind
        w = '第%d段「%s」' % (i, label)
        if 'subLabel' in sec:
            check_i18n(sec['subLabel'], '%s 小標' % w)

        for ri, r in enumerate(sec.get('rules', []), 1):
            for k in r:
                if k not in ('text', 'afterImage'):
                    err('%s 第%d條：不認識的欄位 "%s"' % (w, ri, k))
            check_i18n(r.get('text'), '%s 第%d條' % (w, ri))
            # 自帶編號的檢查一條只報一次（否則 7 語系會噴 7 行講同一件事）
            self_numbered = []
            for l in LANGS:
                t = str((r.get('text') or {}).get(l, ''))
                used |= set(re.findall(r'@([A-Za-z0-9]+)', t))
                if re.match(r'^\s*\d+\s*[.、)]', t):
                    self_numbered.append(LANG_NAME[l])
            if self_numbered and sec.get('numbering') == 'sequential':
                err('%s 第%d條：文字自帶編號又設 numbering=sequential -> 畫面會變 1.1.'
                    '（%s；RULES.md §5）'
                    % (w, ri, '全語系' if len(self_numbered) == len(LANGS)
                       else '、'.join(self_numbered)))
            if r.get('afterImage'):
                check_asset((r['afterImage'] or {}).get('image'), '%s 第%d條的下接圖' % (w, ri))

        for ci, c in enumerate(sec.get('callouts', []), 1):
            if not c.get('symbolKeys'):
                err('%s 卡片%d：沒指定符號' % (w, ci))
            used |= set(c.get('symbolKeys') or [])
            check_i18n(c.get('text'), '%s 卡片%d' % (w, ci))

        for ti, im in enumerate(sec.get('topImages', []) or [], 1):
            if im.get('kind') == 'symbol':
                used.add(im.get('symbolKey'))
                if im.get('size') not in TOP_IMG_SIZE:
                    err('%s 頂圖%d：size "%s" 不合法（%s）'
                        % (w, ti, im.get('size'), '/'.join(sorted(TOP_IMG_SIZE))))
            elif im.get('kind') == 'custom':
                check_asset(((im.get('ref') or {}).get('image')), '%s 頂圖%d' % (w, ti))
            else:
                err('%s 頂圖%d：kind 只能 symbol / custom' % (w, ti))

        if sec.get('numbering') == 'none' and sec.get('rules'):
            if all(re.match(r'^\s*\d+\.\s', str(r['text']['cht'])) for r in sec['rules']):
                warn('%s：每條都自帶編號但 numbering=none，確認是刻意的' % w)
        if sec.get('appendPaytable'):
            pt_used = True

    for k in sorted(used - declared):
        if k:
            err('文案用到 @%s 但 symbols 沒登記' % k)
    if not pt_used:
        err('沒有任何段落設 appendPaytable -> 賠付表不會出現在頁面上')
    for kind in ('betInfo', 'buttons'):
        if not any(s.get('kind') == kind for s in spec.get('sections', [])):
            err('sections 裡沒有 %s 段' % kind)

    # ---------- commonTexts ----------
    ct = spec.get('commonTexts', {})
    for k in ct:
        if k in TYPOS:
            err('commonTexts.%s 拼錯 -> 應該是 "%s"' % (k, TYPOS[k]))
        elif k not in COMMON_FIELDS:
            err('commonTexts 不認識的欄位 "%s"' % k)
    for f in COMMON_FIELDS - set(ct):
        err('commonTexts 缺欄位 "%s"（沒有就明確設 null）' % f)
    for f, v in ct.items():
        if v is None:
            continue
        if isinstance(v, dict) and not any(str(v.get(l, '')).strip() for l in LANGS):
            err('commonTexts.%s 是空的 -> 該遊戲沒有就設 null，不要留空物件'
                '（工具的 i18nKeys() 用 if(text) 判斷，空物件會被寫進語系檔）' % f)
        else:
            check_i18n(v, 'commonTexts.%s' % f)

    # ---------- paytable ----------
    pt = spec.get('paytable', {})
    dev = spec.get('devPreview', {})
    odds = dev.get('oddsInfo', {}) or {}
    if not pt.get('tiers'):
        err('paytable：沒有檔位')
    if not pt.get('entries'):
        err('paytable：沒有符號列')
    slots = []
    for i, t in enumerate(pt.get('tiers', []), 1):
        for k in t:
            if k not in ('label', 'oddsSlot'):
                err('檔位%d：不認識的欄位 "%s"' % (i, k))
        if not str(t.get('label', '')).strip():
            err('檔位%d：沒填 label' % i)
        if not isinstance(t.get('oddsSlot'), int):
            err('檔位%d：oddsSlot 要是整數' % i)
        else:
            slots.append(t['oddsSlot'])
    for i, e in enumerate(pt.get('entries', []), 1):
        for k in e:
            if k not in ('symbolKey', 'oddsIndex'):
                err('賠付表第%d列：不認識的欄位 "%s"' % (i, k))
        if e.get('symbolKey') not in declared:
            err('賠付表第%d列：符號 "%s" 沒在 symbols 登記' % (i, e.get('symbolKey')))
        oi = str(e.get('oddsIndex', ''))
        if not oi:
            err('賠付表第%d列(%s)：oddsIndex 空白'
                ' -> 這是正式資料，會寫進 OddsInfoManager.tsx' % (i, e.get('symbolKey')))
        elif oi not in odds:
            err('賠付表第%d列(%s)：devPreview.oddsInfo 沒有 key "%s" -> 預覽的賠付表會是空的'
                % (i, e.get('symbolKey'), oi))
        elif slots:
            arr = odds[oi]
            if not isinstance(arr, list) or len(arr) <= max(slots):
                err('devPreview.oddsInfo["%s"] 長度 %s，但最大 oddsSlot=%d'
                    % (oi, len(arr) if isinstance(arr, list) else '?', max(slots)))

    # ---------- toggles / devPreview ----------
    tg = spec.get('toggles', {})
    for k in tg:
        if k not in ('showBtnInfo', 'showBetInfo', 'showAutoBtn', 'showTurboBtn',
                     'useTurboPhase', 'hasBuyBonus'):
            err('toggles 不認識的欄位 "%s"' % k)
    if any(s.get('visibleWhen') == 'hasBuyBonus' for s in spec.get('sections', [])) \
            and not tg.get('hasBuyBonus'):
        warn('有段落設 visibleWhen=hasBuyBonus，但 toggles.hasBuyBonus 是 false'
             ' -> 預覽看不到那一段')
    if tg.get('useTurboPhase') and ct.get('superTurboInfo') is None:
        err('useTurboPhase=true 但 commonTexts.superTurboInfo 是 null -> 超加速按鈕說明會空白')
    if not tg.get('useTurboPhase') and ct.get('superTurboInfo') is not None:
        warn('useTurboPhase=false 卻留著 superTurboInfo -> 規格書沒有就設 null')
    if not isinstance(dev.get('rtp'), str):
        warn('devPreview.rtp 應該是字串（新版 GameInfo type 是 string）')

    # ---------- i18n key 重複 ----------
    keys = []
    for i, sec in enumerate(spec.get('sections', []), 1):
        if sec.get('kind') in ('betInfo', 'buttons'):
            continue
        if sec.get('title'):
            keys.append(sec['title'].get('key') or 'subtitle%d' % i)
        if sec.get('subLabel'):
            keys.append(sec['subLabel'].get('key') or 'sublabel%d' % i)
        for ri, r in enumerate(sec.get('rules', []), 1):
            keys.append((r.get('text') or {}).get('key') or 'rule%d-%d' % (i, ri))
        for ci, c in enumerate(sec.get('callouts', []), 1):
            keys.append((c.get('text') or {}).get('key') or 'symtext%d-%d' % (i, ci))
    for k, n in collections.Counter(keys).items():
        if n > 1:
            err('i18n key "%s" 重複 %d 次 -> 語系檔會互相覆蓋' % (k, n))

    # ---------- meta / logo ----------
    check_i18n((spec.get('meta') or {}).get('name'), 'meta.name')
    if not str((spec.get('meta') or {}).get('id', '')).strip():
        warn('meta.id 沒填')
    if not str((spec.get('meta') or {}).get('code', '')).strip():
        warn('meta.code（遊戲代號）沒填 -> 要跟平台配號的人要，例 AR2')
    lg = spec.get('logo') or {}
    check_asset(lg.get('default'), 'logo.default')
    for k in ('zh', 'vi'):
        if lg.get(k):
            check_asset(lg[k], 'logo.%s' % k)

    # ---------- 報告 ----------
    print('=== ERROR（%d）===' % len(E))
    for x in E:
        print(' ✗', x)
    if not E:
        print(' （無）')
    print()
    print('=== 提示 / 待補（%d）===' % len(W))
    for x in W:
        print(' !', x)
    if not W:
        print(' （無）')
    print()
    print('段落 %d、規則 %d、符號 %d、i18n key %d'
          % (len(spec.get('sections', [])),
             sum(len(s.get('rules', [])) for s in spec.get('sections', [])),
             len(spec.get('symbols', [])), len(keys)))
    sys.exit(1 if E else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
用 Atlas 資料夾裡的新圖，替換 Cocos prefab / scene 中「同名」舊圖的 SpriteFrame 引用。
會涵蓋 cc.Sprite 的 _spriteFrame，以及 script 元件上任何 SpriteFrame property
（例如 clickedSpriteFrame、originalSprietFrame）。

★ 重點：兩種資產結構要用不同做法 ★
  A. 「自己擁有節點」的 prefab / scene（沒有 cc.PrefabInstance）：
     直接把展開資料裡的 base UUID 換掉即可。
  B. 「巢狀 prefab 實例」（檔案裡有 cc.PrefabInstance，節點來自另一個來源 prefab）：
     直接改展開值【無效】，Cocos 存檔時會依「來源 prefab + override」還原。
     必須在該 PrefabInstance 的 propertyOverrides 裡新增
     CCPropertyOverrideInfo + cc.TargetInfo，才會真正生效。
  本腳本會自動偵測並對兩種結構分別處理；同一份檔案可同時存在兩種情況。

對照方式：以「檔名」對應。對 Atlas 內每張圖，找專案裡同名舊圖 .meta 取得舊 base UUID，
再對應到新圖 base UUID。只要新舊圖 subMeta id 一致（Cocos 依內容產生，通常一致），
換掉 36 碼 base UUID、保留 @<subId> 後綴即可。

★ 換圖後還要同步 cc.UITransform 的 contentSize ★
  cc.Sprite 的 _spriteFrame 是 @serializable 欄位，反序列化【不走 setter】，
  所以 _applySpriteFrame -> _applySpriteSize 在執行期從未被呼叫
  （engine/cocos/2d/components/sprite.ts：setter 在 215、_applySpriteSize 在 629/715）。
  而 _resized() 開頭就 `if (!EDITOR) return`（同檔 646）。因此：
    - build 後：sizeMode=RAW/TRIMMED 都【不會】自動套用新圖尺寸，
      contentSize 停在舊圖尺寸 -> 新圖被縮著畫。
    - 編輯器裡：__preload() 會呼叫 _resized()，一發現 contentSize 與期望不符，
      就把 _sizeMode 偷偷改成 CUSTOM（不慎存檔就固化）。
  原本沒問題是因為來源 prefab 的 contentSize 本來就等於舊圖尺寸；換圖破壞了這個不變式。
  所以換完圖必須依來源的 sizeMode 補上 contentSize：
    RAW     -> 新圖 .meta subMeta f9941 的 rawWidth/rawHeight（= spriteFrame.originalSize）
    TRIMMED -> 同處的 width/height（= spriteFrame.rect，trim 後）
    CUSTOM  -> 不動（那是刻意設計的尺寸）
  要關掉這段用 --no-content-size。

用法：
  # 先乾跑看看會改什麼
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> [<b.scene> ...]
  # 確認無誤後實際寫入
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> --apply

  [--search-root assets]  搜尋同名舊圖的根目錄，預設 assets

★ 執行前務必先關閉 Cocos Editor（或至少關掉該 prefab 分頁），
  否則編輯器存檔會覆蓋腳本的修改。改完再開編輯器並重新載入。
"""
import argparse, glob, json, os, sys

def load(p):  return json.load(open(p, encoding="utf-8"))
def base_uuid(meta): return load(meta)["uuid"]
def sub_ids(meta):   return set(load(meta).get("subMetas", {}).keys())

def sprite_frame_meta(meta):
    """新圖 .meta 的 spriteFrame 尺寸資訊（供 contentSize 用）。
    rawWidth/rawHeight 就是 spriteFrame.originalSize；width/height 是 trim 後的 rect。"""
    d = load(meta)
    f = (d.get("subMetas") or {}).get("f9941") or {}
    u = f.get("userData") or f
    raw = (u.get("rawWidth"), u.get("rawHeight"))
    trim = (u.get("width"), u.get("height"))
    return {"raw": raw if None not in raw else None,
            "trim": trim if None not in trim else None,
            "imported": bool(d.get("imported"))}

def build_name_map(atlas_dir, search_root):
    """回傳 {舊base: 新base}, {舊base: 檔名}, {新base: 尺寸資訊}, {舊base: 尺寸資訊}, warnings
    舊圖尺寸是用來判斷「CUSTOM 其實是不是該跟著圖」的依據，見 wanted_size()。"""
    old2new, names, new_size, old_size, warns = {}, {}, {}, {}, []
    for f in sorted(glob.glob(os.path.join(atlas_dir, "*.png.meta"))):
        name = os.path.basename(f)[:-len(".png.meta")]
        nb, nsub = base_uuid(f), sub_ids(f)
        info = sprite_frame_meta(f)
        info["name"] = name
        new_size[nb] = info
        olds = [m for m in glob.glob(os.path.join(search_root, "**", name + ".png.meta"), recursive=True)
                if os.path.abspath(os.path.dirname(m)) != os.path.abspath(atlas_dir)]
        if not olds:
            warns.append(f"[跳過] {name}：專案內找不到同名舊圖")
            continue
        for om in olds:
            ob, osub = base_uuid(om), sub_ids(om)
            if ob == nb:
                continue
            if osub != nsub:
                warns.append(f"[警告] {name}：新舊 subMeta id 不一致，仍以 base UUID 對應，請人工確認")
            old2new[ob] = nb
            names[ob] = name
            oi = sprite_frame_meta(om)
            oi["name"] = name
            old_size[ob] = oi
    return old2new, names, new_size, old_size, warns

# ---------------------------------------------------------------- contentSize

RAW, TRIMMED, CUSTOM = 2, 1, 0
SIZEMODE_NAME = {0: "CUSTOM", 1: "TRIMMED", 2: "RAW"}

def _prefab_uuid_index():
    """{prefab uuid: prefab 檔路徑}，用來從 cc.PrefabInfo.asset 找回來源檔。"""
    idx = {}
    for m in glob.glob(os.path.join("assets", "**", "*.prefab.meta"), recursive=True):
        try:
            idx[base_uuid(m)] = m[:-len(".meta")]
        except Exception:
            pass
    return idx

def build_sprite_index(arr, seen=None, idx=None):
    """遞迴走 cc.PrefabInfo.asset 指到的來源 prefab，
    建 {cc.Sprite 的 fileId: {sizeMode, ut(同節點 UITransform 的 fileId), name}}。
    支援多層巢狀（override 的 localID 可能有多段）。"""
    if idx is None:
        idx = _prefab_uuid_index()
    if seen is None:
        seen = set()
    out = {}
    srcs = set()
    for o in arr:
        if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInfo":
            asset = o.get("asset")
            if isinstance(asset, dict) and asset.get("__uuid__"):
                srcs.add(asset["__uuid__"])
    for u in srcs:
        if u in seen:
            continue
        seen.add(u)
        p = idx.get(u)
        if not p or not os.path.exists(p):
            continue
        try:
            sub = load(p)
        except Exception:
            continue
        out.update(_sprite_index_of(sub))
        out.update(build_sprite_index(sub, seen, idx))
    return out

def _sprite_index_of(arr):
    """單一份 prefab/scene 裡的 cc.Sprite 索引。"""
    node_of = {}
    for i, o in enumerate(arr):
        if isinstance(o, dict) and o.get("__type__") == "cc.Node":
            for c in (o.get("_components") or []):
                if isinstance(c, dict) and "__id__" in c:
                    node_of[c["__id__"]] = i
    out = {}
    for i, o in enumerate(arr):
        if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
            continue
        fid = comp_fileid(arr, o)
        if not fid:
            continue
        ni = node_of.get(i)
        ut, cs = None, None
        if ni is not None:
            for c in (arr[ni].get("_components") or []):
                comp = arr[c["__id__"]]
                if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                    ut = comp_fileid(arr, comp)
                    s = comp.get("_contentSize") or {}
                    cs = (s.get("width"), s.get("height"))
        out[fid] = {"sizeMode": o.get("_sizeMode"), "ut": ut, "cs": cs,
                    "sf": (o.get("_spriteFrame") or {}).get("__uuid__")
                          if isinstance(o.get("_spriteFrame"), dict) else None,
                    "name": str(arr[ni].get("_name")) if ni is not None else "?"}
    return out

def _by_raw(info):
    return (info.get("raw"), None, "") if info.get("raw") else (None, "新圖 .meta 沒有 rawWidth/rawHeight", "")

def _by_trim(info):
    if not info.get("imported"):
        return None, "新圖 .meta 尚未匯入（imported:false），trim 值不可信，請先讓 Cocos 匯入再跑", ""
    return (info.get("trim"), None, "") if info.get("trim") else (None, "新圖 .meta 沒有 trim 後的 width/height", "")

def wanted_size(sizemode, info, old_info=None, base_cs=None, strict_custom=False):
    """依 sizeMode 決定 contentSize。回傳 ((w,h), None, 備註) 或 (None, 不能做的原因, "")。

    CUSTOM 的處理：SlotCommon 有些節點被設成 CUSTOM，但 contentSize 剛好等於舊圖的
    rawSize / trim rect —— 那表示它的意圖本來就是「跟著圖」，只是 sizeMode 沒設對
    （共用模組不方便改，所以在這裡補救）。反之，contentSize 與圖尺寸無關的才是
    真正刻意的 CUSTOM，一定不能動。判定條件很嚴格，誤判機率低；
    要完全不碰 CUSTOM 就加 --strict-custom。
    """
    if sizemode == RAW:
        return _by_raw(info)
    if sizemode == TRIMMED:
        wh, why, _ = _by_trim(info)
        return wh, (f"TRIMMED 但{why}" if why else None), ""
    if sizemode == CUSTOM:
        if strict_custom:
            return None, "CUSTOM", ""
        if not old_info or not base_cs or None in base_cs:
            return None, "CUSTOM", ""
        cs = tuple(base_cs)
        # raw 優先：舊圖 raw==trim 時無從區分意圖，而 raw（不裁切）才是按鈕類的慣例
        if old_info.get("raw") and cs == tuple(old_info["raw"]):
            wh, why, _ = _by_raw(info)
            return wh, why, "CUSTOM→raw"
        if old_info.get("trim") and cs == tuple(old_info["trim"]):
            wh, why, _ = _by_trim(info)
            return wh, (f"CUSTOM 疑似 TRIMMED 但{why}" if why else None), "CUSTOM→trim"
        return None, "CUSTOM", ""
    return None, f"sizeMode={sizemode} 非預期值", ""

def _size_val(wh):
    return {"__type__": "cc.Size", "width": wh[0], "height": wh[1]}

def comp_fileid(a, comp):
    pf = comp.get("__prefab")
    return a[pf["__id__"]].get("fileId") if isinstance(pf, dict) else None

def is_spriteframe_val(v):
    return isinstance(v, dict) and v.get("__expectedType__") == "cc.SpriteFrame" and v.get("__uuid__")

def process_file(path, old2new, names, apply, new_size=None, do_cs=True,
                 old_size=None, strict_custom=False):
    a = load(path)
    if not isinstance(a, list):
        return 0, [f"[跳過] {path} 不是資產陣列格式"]
    new_size = new_size or {}
    old_size = old_size or {}
    new2old = {nb: ob for ob, nb in old2new.items()}
    logs = []
    prefab_instances = [o for o in a if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInstance"]

    # 每個 component 找出它所屬的 PrefabInstance（若有）。單層情況：整份檔通常只有一個實例。
    # 這裡以「檔案是否含 PrefabInstance」+「component 有 __prefab.fileId」判斷該 comp 是否來自巢狀來源。
    changed = 0

    # ---- 情況 B：巢狀 prefab 實例 → 產生 override ----
    for pi in prefab_instances:
        overrides = pi.setdefault("propertyOverrides", [])
        existing = set()
        for ref in overrides:
            ov = a[ref["__id__"]]
            ti = ov.get("targetInfo", {})
            tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
            lid = tuple(tinfo.get("localID", [])) if isinstance(tinfo, dict) else ()
            existing.add((lid, tuple(ov.get("propertyPath", []))))

        for comp in list(a):
            if not isinstance(comp, dict):
                continue
            fid = comp_fileid(a, comp)
            if not fid:
                continue
            for prop, val in list(comp.items()):
                if not is_spriteframe_val(val):
                    continue
                b, _, suf = val["__uuid__"].partition("@")
                if b not in old2new:
                    continue
                key = ((fid,), (prop,))
                if key in existing:
                    continue
                newu = old2new[b] + ("@" + suf if suf else "")
                ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": [fid]})
                ov_idx = len(a); a.append({
                    "__type__": "CCPropertyOverrideInfo",
                    "targetInfo": {"__id__": ti_idx},
                    "propertyPath": [prop],
                    "value": {"__uuid__": newu, "__expectedType__": "cc.SpriteFrame"},
                })
                overrides.append({"__id__": ov_idx})
                existing.add(key)
                changed += 1
                logs.append(f"  [override] {names[b]:28s} {prop:20s} -> {newu}")

    # ---- 情況 A：非實例（或實例外的一般節點）→ 直接替換展開 base UUID ----
    # 只有在【沒有 PrefabInstance】時才做全域 base UUID 取代，避免動到會被 override 機制還原的值。
    if not prefab_instances:
        txt = json.dumps(a, ensure_ascii=False, indent=2)
        for ob, nb in old2new.items():
            c = txt.count(ob)
            if c:
                txt = txt.replace(ob, nb)
                changed += c
                logs.append(f"  [直接替換] {names[ob]:28s} {ob} -> {nb}  ({c} 處)")
        a = json.loads(txt)

    # ---- 換圖後同步 contentSize（理由見檔頭）----
    if do_cs and new_size:
        # sizeMode 真值 = 來源 prefab + _sizeMode override。
        # 【不要】拿本檔展開值覆蓋：展開值只是快取（Cocos 依「來源 + override」還原），
        # 而且很容易被編輯器的 _resized() 汙染成 CUSTOM —— 那正是本段要修的 bug 留下的痕跡。
        # 展開值只用來補來源查不到的項，以及來源缺 ut 時當 fallback。
        smidx = build_sprite_index(a)
        for k, v in _sprite_index_of(a).items():
            if k not in smidx:
                smidx[k] = v
                continue
            if not smidx[k].get("ut"):
                smidx[k]["ut"] = v.get("ut")
            if not smidx[k].get("cs"):
                smidx[k]["cs"] = v.get("cs")
            if smidx[k].get("sizeMode") != v.get("sizeMode"):
                logs.append(
                    f"  [注意] {v['name']:24s} 展開值 sizeMode="
                    f"{SIZEMODE_NAME.get(v.get('sizeMode'), v.get('sizeMode'))}"
                    f" 與來源 {SIZEMODE_NAME.get(smidx[k].get('sizeMode'), smidx[k].get('sizeMode'))}"
                    f" 不符（展開值多半是被 _resized() 汙染的殘留），依來源處理")
        for pi in prefab_instances:
            for ref in pi.get("propertyOverrides", []):
                ov = a[ref["__id__"]]
                if ov.get("propertyPath") != ["_sizeMode"]:
                    continue
                ti = ov.get("targetInfo", {})
                tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                lid = (tinfo or {}).get("localID") or []
                if lid and lid[-1] in smidx:
                    smidx[lid[-1]]["sizeMode"] = ov.get("value")

        def target_for(newu):
            nb = (newu or "").split("@")[0]
            return new_size.get(nb)

        if prefab_instances:
            # 情況 B：contentSize 也要走 override
            for pi in prefab_instances:
                overrides = pi.setdefault("propertyOverrides", [])
                def cs_entries():
                    for ref in overrides:
                        ov = a[ref["__id__"]]
                        ti = ov.get("targetInfo", {})
                        tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                        yield ov, list((tinfo or {}).get("localID") or [])
                sf_targets = [(ov, lid) for ov, lid in cs_entries()
                              if lid and ov.get("propertyPath") == ["_spriteFrame"]]
                for ov, lid in sf_targets:
                    fid = lid[-1]
                    d = smidx.get(fid)
                    if not d:
                        continue                      # 不是 cc.Sprite（script 屬性等）
                    val = ov.get("value") or {}
                    info = target_for(val.get("__uuid__") if isinstance(val, dict) else None)
                    if not info:
                        continue
                    newu = val.get("__uuid__") if isinstance(val, dict) else None
                    old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                    wh, why, note = wanted_size(d.get("sizeMode"), info, old_info,
                                                d.get("cs"), strict_custom)
                    if wh is None:
                        if why != "CUSTOM":
                            logs.append(f"  [contentSize 略過] {d['name']:24s} {why}")
                        continue
                    if not d.get("ut"):
                        logs.append(f"  [contentSize 略過] {d['name']:24s} 同節點找不到 cc.UITransform")
                        continue
                    ut_lid = lid[:-1] + [d["ut"]]
                    hit = None
                    for ov2, lid2 in cs_entries():
                        if lid2 == ut_lid and ov2.get("propertyPath") == ["_contentSize"]:
                            hit = ov2
                    if hit is not None:
                        cur = hit.get("value") or {}
                        if (cur.get("width"), cur.get("height")) == tuple(wh):
                            continue
                        hit["value"] = _size_val(wh)
                    else:
                        ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": ut_lid})
                        ov_idx = len(a); a.append({
                            "__type__": "CCPropertyOverrideInfo",
                            "targetInfo": {"__id__": ti_idx},
                            "propertyPath": ["_contentSize"],
                            "value": _size_val(wh),
                        })
                        overrides.append({"__id__": ov_idx})
                    changed += 1
                    mode = note or SIZEMODE_NAME.get(d.get("sizeMode"), "?")
                    logs.append(f"  [contentSize] {d['name']:24s} "
                                f"{mode:11s} -> {wh[0]}x{wh[1]}")
        else:
            # 情況 A：直接改同節點 cc.UITransform
            node_of = {}
            for i, o in enumerate(a):
                if isinstance(o, dict) and o.get("__type__") == "cc.Node":
                    for c in (o.get("_components") or []):
                        if isinstance(c, dict) and "__id__" in c:
                            node_of[c["__id__"]] = i
            for i, o in enumerate(a):
                if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
                    continue
                sf = o.get("_spriteFrame")
                info = target_for(sf.get("__uuid__") if isinstance(sf, dict) else None)
                if not info:
                    continue
                name = str(a[node_of[i]].get("_name")) if i in node_of else "?"
                ut = None
                for c in (a[node_of[i]].get("_components") or []):
                    comp = a[c["__id__"]]
                    if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                        ut = comp
                # 此時圖已換成新的，但 contentSize 還是舊值 —— 正好是判斷 CUSTOM 意圖的依據
                base_cs = None
                if ut is not None:
                    s = ut.get("_contentSize") or {}
                    base_cs = (s.get("width"), s.get("height"))
                newu = sf.get("__uuid__") if isinstance(sf, dict) else None
                old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                wh, why, note = wanted_size(o.get("_sizeMode"), info, old_info,
                                            base_cs, strict_custom)
                if wh is None:
                    if why != "CUSTOM":
                        logs.append(f"  [contentSize 略過] {name:24s} {why}")
                    continue
                if ut is None:
                    logs.append(f"  [contentSize 略過] {name:24s} 同節點找不到 cc.UITransform")
                    continue
                cur = ut.get("_contentSize") or {}
                if (cur.get("width"), cur.get("height")) == tuple(wh):
                    continue
                ut["_contentSize"] = _size_val(wh)
                changed += 1
                mode = note or SIZEMODE_NAME.get(o.get("_sizeMode"), "?")
                logs.append(f"  [contentSize] {name:24s} {mode:11s} -> {wh[0]}x{wh[1]}")

    if changed and apply:
        with open(path, "w", encoding="utf-8") as fp:
            json.dump(a, fp, ensure_ascii=False, indent=2)
    # 驗證 JSON（用 dumps 後可解析即可）
    if changed:
        json.loads(json.dumps(a, ensure_ascii=False))
    return changed, logs

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--atlas", required=True)
    ap.add_argument("--targets", required=True, nargs="+")
    ap.add_argument("--search-root", default="assets")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--no-content-size", action="store_true",
                    help="不要在換圖後同步 cc.UITransform 的 contentSize（預設會同步，理由見檔頭）")
    ap.add_argument("--strict-custom", action="store_true",
                    help="完全不碰 sizeMode=CUSTOM 的節點。預設會處理「contentSize 剛好等於舊圖尺寸」"
                         "的 CUSTOM（那種其實是該跟著圖、只是 sizeMode 沒設對），報告標為 CUSTOM→raw/trim")
    args = ap.parse_args()

    old2new, names, new_size, old_size, warns = build_name_map(args.atlas, args.search_root)
    print(f"名稱對照（舊→新）：{len(old2new)} 組")
    if args.no_content_size:
        print("※ --no-content-size：只換圖，不同步 contentSize")
    elif args.strict_custom:
        print("※ --strict-custom：sizeMode=CUSTOM 的節點一律不動")

    total = 0
    for t in args.targets:
        if not os.path.exists(t):
            warns.append(f"[跳過] 目標檔不存在：{t}")
            continue
        print(f"\n目標：{t}")
        c, logs = process_file(t, old2new, names, args.apply,
                               new_size=new_size, do_cs=not args.no_content_size,
                               old_size=old_size, strict_custom=args.strict_custom)
        for l in logs:
            print(l)
        print(f"  小計：{c} 處")
        total += c

    print(f"\n合計：{total} 處")
    if warns:
        print("\n訊息：")
        for w in warns:
            print("  " + w)
    if not args.apply:
        print("\n(乾跑模式，未寫入。確認無誤後加 --apply)")
    print("\n★ 記得先關閉 Cocos Editor 再執行；改完重開編輯器並重新載入 prefab。")

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
用 Atlas 資料夾裡的新圖，替換 Cocos prefab / scene 中「同名」舊圖的 SpriteFrame 引用。
會涵蓋 cc.Sprite 的 _spriteFrame，以及 script 元件上任何 SpriteFrame property
（例如 clickedSpriteFrame、originalSprietFrame）。

★ 重點：兩種資產結構要用不同做法 ★
  A. 「自己擁有節點」的 prefab / scene（沒有 cc.PrefabInstance）：
     直接把展開資料裡的 base UUID 換掉即可。
  B. 「巢狀 prefab 實例」（檔案裡有 cc.PrefabInstance，節點來自另一個來源 prefab）：
     直接改展開值【無效】，Cocos 存檔時會依「來源 prefab + override」還原。
     必須在該 PrefabInstance 的 propertyOverrides 裡新增
     CCPropertyOverrideInfo + cc.TargetInfo，才會真正生效。
  本腳本會自動偵測並對兩種結構分別處理；同一份檔案可同時存在兩種情況。

對照方式：以「檔名」對應。對 Atlas 內每張圖，找專案裡同名舊圖 .meta 取得舊 base UUID，
再對應到新圖 base UUID。只要新舊圖 subMeta id 一致（Cocos 依內容產生，通常一致），
換掉 36 碼 base UUID、保留 @<subId> 後綴即可。

★ 換圖後還要同步 cc.UITransform 的 contentSize ★
  cc.Sprite 的 _spriteFrame 是 @serializable 欄位，反序列化【不走 setter】，
  所以 _applySpriteFrame -> _applySpriteSize 在執行期從未被呼叫
  （engine/cocos/2d/components/sprite.ts：setter 在 215、_applySpriteSize 在 629/715）。
  而 _resized() 開頭就 `if (!EDITOR) return`（同檔 646）。因此：
    - build 後：sizeMode=RAW/TRIMMED 都【不會】自動套用新圖尺寸，
      contentSize 停在舊圖尺寸 -> 新圖被縮著畫。
    - 編輯器裡：__preload() 會呼叫 _resized()，一發現 contentSize 與期望不符，
      就把 _sizeMode 偷偷改成 CUSTOM（不慎存檔就固化）。
  原本沒問題是因為來源 prefab 的 contentSize 本來就等於舊圖尺寸；換圖破壞了這個不變式。
  所以換完圖必須依來源的 sizeMode 補上 contentSize：
    RAW     -> 新圖 .meta subMeta f9941 的 rawWidth/rawHeight（= spriteFrame.originalSize）
    TRIMMED -> 同處的 width/height（= spriteFrame.rect，trim 後）
    CUSTOM  -> 不動（那是刻意設計的尺寸）
  要關掉這段用 --no-content-size。

用法：
  # 先乾跑看看會改什麼
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> [<b.scene> ...]
  # 確認無誤後實際寫入
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> --apply

  [--search-root assets]  搜尋同名舊圖的根目錄，預設 assets

★ 執行前務必先關閉 Cocos Editor（或至少關掉該 prefab 分頁），
  否則編輯器存檔會覆蓋腳本的修改。改完再開編輯器並重新載入。
"""
import argparse, glob, json, os, sys

def load(p):  return json.load(open(p, encoding="utf-8"))
def base_uuid(meta): return load(meta)["uuid"]
def sub_ids(meta):   return set(load(meta).get("subMetas", {}).keys())

def sprite_frame_meta(meta):
    """新圖 .meta 的 spriteFrame 尺寸資訊（供 contentSize 用）。
    rawWidth/rawHeight 就是 spriteFrame.originalSize；width/height 是 trim 後的 rect。"""
    d = load(meta)
    f = (d.get("subMetas") or {}).get("f9941") or {}
    u = f.get("userData") or f
    raw = (u.get("rawWidth"), u.get("rawHeight"))
    trim = (u.get("width"), u.get("height"))
    return {"raw": raw if None not in raw else None,
            "trim": trim if None not in trim else None,
            "imported": bool(d.get("imported"))}

def build_name_map(atlas_dir, search_root):
    """回傳 {舊base: 新base}, {舊base: 檔名}, {新base: 尺寸資訊}, {舊base: 尺寸資訊}, warnings
    舊圖尺寸是用來判斷「CUSTOM 其實是不是該跟著圖」的依據，見 wanted_size()。"""
    old2new, names, new_size, old_size, warns = {}, {}, {}, {}, []
    for f in sorted(glob.glob(os.path.join(atlas_dir, "*.png.meta"))):
        name = os.path.basename(f)[:-len(".png.meta")]
        nb, nsub = base_uuid(f), sub_ids(f)
        info = sprite_frame_meta(f)
        info["name"] = name
        new_size[nb] = info
        olds = [m for m in glob.glob(os.path.join(search_root, "**", name + ".png.meta"), recursive=True)
                if os.path.abspath(os.path.dirname(m)) != os.path.abspath(atlas_dir)]
        if not olds:
            warns.append(f"[跳過] {name}：專案內找不到同名舊圖")
            continue
        for om in olds:
            ob, osub = base_uuid(om), sub_ids(om)
            if ob == nb:
                continue
            if osub != nsub:
                warns.append(f"[警告] {name}：新舊 subMeta id 不一致，仍以 base UUID 對應，請人工確認")
            old2new[ob] = nb
            names[ob] = name
            oi = sprite_frame_meta(om)
            oi["name"] = name
            old_size[ob] = oi
    return old2new, names, new_size, old_size, warns

# ---------------------------------------------------------------- contentSize

RAW, TRIMMED, CUSTOM = 2, 1, 0
SIZEMODE_NAME = {0: "CUSTOM", 1: "TRIMMED", 2: "RAW"}

def _prefab_uuid_index():
    """{prefab uuid: prefab 檔路徑}，用來從 cc.PrefabInfo.asset 找回來源檔。"""
    idx = {}
    for m in glob.glob(os.path.join("assets", "**", "*.prefab.meta"), recursive=True):
        try:
            idx[base_uuid(m)] = m[:-len(".meta")]
        except Exception:
            pass
    return idx

def build_sprite_index(arr, seen=None, idx=None):
    """遞迴走 cc.PrefabInfo.asset 指到的來源 prefab，
    建 {cc.Sprite 的 fileId: {sizeMode, ut(同節點 UITransform 的 fileId), name}}。
    支援多層巢狀（override 的 localID 可能有多段）。"""
    if idx is None:
        idx = _prefab_uuid_index()
    if seen is None:
        seen = set()
    out = {}
    srcs = set()
    for o in arr:
        if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInfo":
            asset = o.get("asset")
            if isinstance(asset, dict) and asset.get("__uuid__"):
                srcs.add(asset["__uuid__"])
    for u in srcs:
        if u in seen:
            continue
        seen.add(u)
        p = idx.get(u)
        if not p or not os.path.exists(p):
            continue
        try:
            sub = load(p)
        except Exception:
            continue
        out.update(_sprite_index_of(sub))
        out.update(build_sprite_index(sub, seen, idx))
    return out

def _sprite_index_of(arr):
    """單一份 prefab/scene 裡的 cc.Sprite 索引。"""
    node_of = {}
    for i, o in enumerate(arr):
        if isinstance(o, dict) and o.get("__type__") == "cc.Node":
            for c in (o.get("_components") or []):
                if isinstance(c, dict) and "__id__" in c:
                    node_of[c["__id__"]] = i
    out = {}
    for i, o in enumerate(arr):
        if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
            continue
        fid = comp_fileid(arr, o)
        if not fid:
            continue
        ni = node_of.get(i)
        ut, cs = None, None
        if ni is not None:
            for c in (arr[ni].get("_components") or []):
                comp = arr[c["__id__"]]
                if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                    ut = comp_fileid(arr, comp)
                    s = comp.get("_contentSize") or {}
                    cs = (s.get("width"), s.get("height"))
        out[fid] = {"sizeMode": o.get("_sizeMode"), "ut": ut, "cs": cs,
                    "sf": (o.get("_spriteFrame") or {}).get("__uuid__")
                          if isinstance(o.get("_spriteFrame"), dict) else None,
                    "name": str(arr[ni].get("_name")) if ni is not None else "?"}
    return out

def _by_raw(info):
    return (info.get("raw"), None, "") if info.get("raw") else (None, "新圖 .meta 沒有 rawWidth/rawHeight", "")

def _by_trim(info):
    if not info.get("imported"):
        return None, "新圖 .meta 尚未匯入（imported:false），trim 值不可信，請先讓 Cocos 匯入再跑", ""
    return (info.get("trim"), None, "") if info.get("trim") else (None, "新圖 .meta 沒有 trim 後的 width/height", "")

def wanted_size(sizemode, info, old_info=None, base_cs=None, strict_custom=False):
    """依 sizeMode 決定 contentSize。回傳 ((w,h), None, 備註) 或 (None, 不能做的原因, "")。

    CUSTOM 的處理：SlotCommon 有些節點被設成 CUSTOM，但 contentSize 剛好等於舊圖的
    rawSize / trim rect —— 那表示它的意圖本來就是「跟著圖」，只是 sizeMode 沒設對
    （共用模組不方便改，所以在這裡補救）。反之，contentSize 與圖尺寸無關的才是
    真正刻意的 CUSTOM，一定不能動。判定條件很嚴格，誤判機率低；
    要完全不碰 CUSTOM 就加 --strict-custom。
    """
    if sizemode == RAW:
        return _by_raw(info)
    if sizemode == TRIMMED:
        wh, why, _ = _by_trim(info)
        return wh, (f"TRIMMED 但{why}" if why else None), ""
    if sizemode == CUSTOM:
        if strict_custom:
            return None, "CUSTOM", ""
        if not old_info or not base_cs or None in base_cs:
            return None, "CUSTOM", ""
        cs = tuple(base_cs)
        # raw 優先：舊圖 raw==trim 時無從區分意圖，而 raw（不裁切）才是按鈕類的慣例
        if old_info.get("raw") and cs == tuple(old_info["raw"]):
            wh, why, _ = _by_raw(info)
            return wh, why, "CUSTOM→raw"
        if old_info.get("trim") and cs == tuple(old_info["trim"]):
            wh, why, _ = _by_trim(info)
            return wh, (f"CUSTOM 疑似 TRIMMED 但{why}" if why else None), "CUSTOM→trim"
        return None, "CUSTOM", ""
    return None, f"sizeMode={sizemode} 非預期值", ""

def _size_val(wh):
    return {"__type__": "cc.Size", "width": wh[0], "height": wh[1]}

def comp_fileid(a, comp):
    pf = comp.get("__prefab")
    return a[pf["__id__"]].get("fileId") if isinstance(pf, dict) else None

def is_spriteframe_val(v):
    return isinstance(v, dict) and v.get("__expectedType__") == "cc.SpriteFrame" and v.get("__uuid__")

def process_file(path, old2new, names, apply, new_size=None, do_cs=True,
                 old_size=None, strict_custom=False):
    a = load(path)
    if not isinstance(a, list):
        return 0, [f"[跳過] {path} 不是資產陣列格式"]
    new_size = new_size or {}
    old_size = old_size or {}
    new2old = {nb: ob for ob, nb in old2new.items()}
    logs = []
    prefab_instances = [o for o in a if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInstance"]

    # 每個 component 找出它所屬的 PrefabInstance（若有）。單層情況：整份檔通常只有一個實例。
    # 這裡以「檔案是否含 PrefabInstance」+「component 有 __prefab.fileId」判斷該 comp 是否來自巢狀來源。
    changed = 0

    # ---- 情況 B：巢狀 prefab 實例 → 產生 override ----
    for pi in prefab_instances:
        overrides = pi.setdefault("propertyOverrides", [])
        existing = set()
        for ref in overrides:
            ov = a[ref["__id__"]]
            ti = ov.get("targetInfo", {})
            tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
            lid = tuple(tinfo.get("localID", [])) if isinstance(tinfo, dict) else ()
            existing.add((lid, tuple(ov.get("propertyPath", []))))

        for comp in list(a):
            if not isinstance(comp, dict):
                continue
            fid = comp_fileid(a, comp)
            if not fid:
                continue
            for prop, val in list(comp.items()):
                if not is_spriteframe_val(val):
                    continue
                b, _, suf = val["__uuid__"].partition("@")
                if b not in old2new:
                    continue
                key = ((fid,), (prop,))
                if key in existing:
                    continue
                newu = old2new[b] + ("@" + suf if suf else "")
                ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": [fid]})
                ov_idx = len(a); a.append({
                    "__type__": "CCPropertyOverrideInfo",
                    "targetInfo": {"__id__": ti_idx},
                    "propertyPath": [prop],
                    "value": {"__uuid__": newu, "__expectedType__": "cc.SpriteFrame"},
                })
                overrides.append({"__id__": ov_idx})
                existing.add(key)
                changed += 1
                logs.append(f"  [override] {names[b]:28s} {prop:20s} -> {newu}")

    # ---- 情況 A：非實例（或實例外的一般節點）→ 直接替換展開 base UUID ----
    # 只有在【沒有 PrefabInstance】時才做全域 base UUID 取代，避免動到會被 override 機制還原的值。
    if not prefab_instances:
        txt = json.dumps(a, ensure_ascii=False, indent=2)
        for ob, nb in old2new.items():
            c = txt.count(ob)
            if c:
                txt = txt.replace(ob, nb)
                changed += c
                logs.append(f"  [直接替換] {names[ob]:28s} {ob} -> {nb}  ({c} 處)")
        a = json.loads(txt)

    # ---- 換圖後同步 contentSize（理由見檔頭）----
    if do_cs and new_size:
        # sizeMode 真值 = 來源 prefab + _sizeMode override。
        # 【不要】拿本檔展開值覆蓋：展開值只是快取（Cocos 依「來源 + override」還原），
        # 而且很容易被編輯器的 _resized() 汙染成 CUSTOM —— 那正是本段要修的 bug 留下的痕跡。
        # 展開值只用來補來源查不到的項，以及來源缺 ut 時當 fallback。
        smidx = build_sprite_index(a)
        for k, v in _sprite_index_of(a).items():
            if k not in smidx:
                smidx[k] = v
                continue
            if not smidx[k].get("ut"):
                smidx[k]["ut"] = v.get("ut")
            if not smidx[k].get("cs"):
                smidx[k]["cs"] = v.get("cs")
            if smidx[k].get("sizeMode") != v.get("sizeMode"):
                logs.append(
                    f"  [注意] {v['name']:24s} 展開值 sizeMode="
                    f"{SIZEMODE_NAME.get(v.get('sizeMode'), v.get('sizeMode'))}"
                    f" 與來源 {SIZEMODE_NAME.get(smidx[k].get('sizeMode'), smidx[k].get('sizeMode'))}"
                    f" 不符（展開值多半是被 _resized() 汙染的殘留），依來源處理")
        for pi in prefab_instances:
            for ref in pi.get("propertyOverrides", []):
                ov = a[ref["__id__"]]
                if ov.get("propertyPath") != ["_sizeMode"]:
                    continue
                ti = ov.get("targetInfo", {})
                tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                lid = (tinfo or {}).get("localID") or []
                if lid and lid[-1] in smidx:
                    smidx[lid[-1]]["sizeMode"] = ov.get("value")

        def target_for(newu):
            nb = (newu or "").split("@")[0]
            return new_size.get(nb)

        if prefab_instances:
            # 情況 B：contentSize 也要走 override
            for pi in prefab_instances:
                overrides = pi.setdefault("propertyOverrides", [])
                def cs_entries():
                    for ref in overrides:
                        ov = a[ref["__id__"]]
                        ti = ov.get("targetInfo", {})
                        tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                        yield ov, list((tinfo or {}).get("localID") or [])
                sf_targets = [(ov, lid) for ov, lid in cs_entries()
                              if lid and ov.get("propertyPath") == ["_spriteFrame"]]
                for ov, lid in sf_targets:
                    fid = lid[-1]
                    d = smidx.get(fid)
                    if not d:
                        continue                      # 不是 cc.Sprite（script 屬性等）
                    val = ov.get("value") or {}
                    info = target_for(val.get("__uuid__") if isinstance(val, dict) else None)
                    if not info:
                        continue
                    newu = val.get("__uuid__") if isinstance(val, dict) else None
                    old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                    wh, why, note = wanted_size(d.get("sizeMode"), info, old_info,
                                                d.get("cs"), strict_custom)
                    if wh is None:
                        if why != "CUSTOM":
                            logs.append(f"  [contentSize 略過] {d['name']:24s} {why}")
                        continue
                    if not d.get("ut"):
                        logs.append(f"  [contentSize 略過] {d['name']:24s} 同節點找不到 cc.UITransform")
                        continue
                    ut_lid = lid[:-1] + [d["ut"]]
                    hit = None
                    for ov2, lid2 in cs_entries():
                        if lid2 == ut_lid and ov2.get("propertyPath") == ["_contentSize"]:
                            hit = ov2
                    if hit is not None:
                        cur = hit.get("value") or {}
                        if (cur.get("width"), cur.get("height")) == tuple(wh):
                            continue
                        hit["value"] = _size_val(wh)
                    else:
                        ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": ut_lid})
                        ov_idx = len(a); a.append({
                            "__type__": "CCPropertyOverrideInfo",
                            "targetInfo": {"__id__": ti_idx},
                            "propertyPath": ["_contentSize"],
                            "value": _size_val(wh),
                        })
                        overrides.append({"__id__": ov_idx})
                    changed += 1
                    mode = note or SIZEMODE_NAME.get(d.get("sizeMode"), "?")
                    logs.append(f"  [contentSize] {d['name']:24s} "
                                f"{mode:11s} -> {wh[0]}x{wh[1]}")
        else:
            # 情況 A：直接改同節點 cc.UITransform
            node_of = {}
            for i, o in enumerate(a):
                if isinstance(o, dict) and o.get("__type__") == "cc.Node":
                    for c in (o.get("_components") or []):
                        if isinstance(c, dict) and "__id__" in c:
                            node_of[c["__id__"]] = i
            for i, o in enumerate(a):
                if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
                    continue
                sf = o.get("_spriteFrame")
                info = target_for(sf.get("__uuid__") if isinstance(sf, dict) else None)
                if not info:
                    continue
                name = str(a[node_of[i]].get("_name")) if i in node_of else "?"
                ut = None
                for c in (a[node_of[i]].get("_components") or []):
                    comp = a[c["__id__"]]
                    if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                        ut = comp
                # 此時圖已換成新的，但 contentSize 還是舊值 —— 正好是判斷 CUSTOM 意圖的依據
                base_cs = None
                if ut is not None:
                    s = ut.get("_contentSize") or {}
                    base_cs = (s.get("width"), s.get("height"))
                newu = sf.get("__uuid__") if isinstance(sf, dict) else None
                old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                wh, why, note = wanted_size(o.get("_sizeMode"), info, old_info,
                                            base_cs, strict_custom)
                if wh is None:
                    if why != "CUSTOM":
                        logs.append(f"  [contentSize 略過] {name:24s} {why}")
                    continue
                if ut is None:
                    logs.append(f"  [contentSize 略過] {name:24s} 同節點找不到 cc.UITransform")
                    continue
                cur = ut.get("_contentSize") or {}
                if (cur.get("width"), cur.get("height")) == tuple(wh):
                    continue
                ut["_contentSize"] = _size_val(wh)
                changed += 1
                mode = note or SIZEMODE_NAME.get(o.get("_sizeMode"), "?")
                logs.append(f"  [contentSize] {name:24s} {mode:11s} -> {wh[0]}x{wh[1]}")

    if changed and apply:
        with open(path, "w", encoding="utf-8") as fp:
            json.dump(a, fp, ensure_ascii=False, indent=2)
    # 驗證 JSON（用 dumps 後可解析即可）
    if changed:
        json.loads(json.dumps(a, ensure_ascii=False))
    return changed, logs

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--atlas", required=True)
    ap.add_argument("--targets", required=True, nargs="+")
    ap.add_argument("--search-root", default="assets")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--no-content-size", action="store_true",
                    help="不要在換圖後同步 cc.UITransform 的 contentSize（預設會同步，理由見檔頭）")
    ap.add_argument("--strict-custom", action="store_true",
                    help="完全不碰 sizeMode=CUSTOM 的節點。預設會處理「contentSize 剛好等於舊圖尺寸」"
                         "的 CUSTOM（那種其實是該跟著圖、只是 sizeMode 沒設對），報告標為 CUSTOM→raw/trim")
    args = ap.parse_args()

    old2new, names, new_size, old_size, warns = build_name_map(args.atlas, args.search_root)
    print(f"名稱對照（舊→新）：{len(old2new)} 組")
    if args.no_content_size:
        print("※ --no-content-size：只換圖，不同步 contentSize")
    elif args.strict_custom:
        print("※ --strict-custom：sizeMode=CUSTOM 的節點一律不動")

    total = 0
    for t in args.targets:
        if not os.path.exists(t):
            warns.append(f"[跳過] 目標檔不存在：{t}")
            continue
        print(f"\n目標：{t}")
        c, logs = process_file(t, old2new, names, args.apply,
                               new_size=new_size, do_cs=not args.no_content_size,
                               old_size=old_size, strict_custom=args.strict_custom)
        for l in logs:
            print(l)
        print(f"  小計：{c} 處")
        total += c

    print(f"\n合計：{total} 處")
    if warns:
        print("\n訊息：")
        for w in warns:
            print("  " + w)
    if not args.apply:
        print("\n(乾跑模式，未寫入。確認無誤後加 --apply)")
    print("\n★ 記得先關閉 Cocos Editor 再執行；改完重開編輯器並重新載入 prefab。")

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
用 Atlas 資料夾裡的新圖，替換 Cocos prefab / scene 中「同名」舊圖的 SpriteFrame 引用。
會涵蓋 cc.Sprite 的 _spriteFrame，以及 script 元件上任何 SpriteFrame property
（例如 clickedSpriteFrame、originalSprietFrame）。

★ 重點：兩種資產結構要用不同做法 ★
  A. 「自己擁有節點」的 prefab / scene（沒有 cc.PrefabInstance）：
     直接把展開資料裡的 base UUID 換掉即可。
  B. 「巢狀 prefab 實例」（檔案裡有 cc.PrefabInstance，節點來自另一個來源 prefab）：
     直接改展開值【無效】，Cocos 存檔時會依「來源 prefab + override」還原。
     必須在該 PrefabInstance 的 propertyOverrides 裡新增
     CCPropertyOverrideInfo + cc.TargetInfo，才會真正生效。
  本腳本會自動偵測並對兩種結構分別處理；同一份檔案可同時存在兩種情況。

對照方式：以「檔名」對應。對 Atlas 內每張圖，找專案裡同名舊圖 .meta 取得舊 base UUID，
再對應到新圖 base UUID。只要新舊圖 subMeta id 一致（Cocos 依內容產生，通常一致），
換掉 36 碼 base UUID、保留 @<subId> 後綴即可。

★ 換圖後還要同步 cc.UITransform 的 contentSize ★
  cc.Sprite 的 _spriteFrame 是 @serializable 欄位，反序列化【不走 setter】，
  所以 _applySpriteFrame -> _applySpriteSize 在執行期從未被呼叫
  （engine/cocos/2d/components/sprite.ts：setter 在 215、_applySpriteSize 在 629/715）。
  而 _resized() 開頭就 `if (!EDITOR) return`（同檔 646）。因此：
    - build 後：sizeMode=RAW/TRIMMED 都【不會】自動套用新圖尺寸，
      contentSize 停在舊圖尺寸 -> 新圖被縮著畫。
    - 編輯器裡：__preload() 會呼叫 _resized()，一發現 contentSize 與期望不符，
      就把 _sizeMode 偷偷改成 CUSTOM（不慎存檔就固化）。
  原本沒問題是因為來源 prefab 的 contentSize 本來就等於舊圖尺寸；換圖破壞了這個不變式。
  所以換完圖必須依來源的 sizeMode 補上 contentSize：
    RAW     -> 新圖 .meta subMeta f9941 的 rawWidth/rawHeight（= spriteFrame.originalSize）
    TRIMMED -> 同處的 width/height（= spriteFrame.rect，trim 後）
    CUSTOM  -> 不動（那是刻意設計的尺寸）
  要關掉這段用 --no-content-size。

用法：
  # 先乾跑看看會改什麼
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> [<b.scene> ...]
  # 確認無誤後實際寫入
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> --apply

  [--search-root assets]  搜尋同名舊圖的根目錄，預設 assets

★ 執行前務必先關閉 Cocos Editor（或至少關掉該 prefab 分頁），
  否則編輯器存檔會覆蓋腳本的修改。改完再開編輯器並重新載入。
"""
import argparse, glob, json, os, sys

def load(p):  return json.load(open(p, encoding="utf-8"))
def base_uuid(meta): return load(meta)["uuid"]
def sub_ids(meta):   return set(load(meta).get("subMetas", {}).keys())

def sprite_frame_meta(meta):
    """新圖 .meta 的 spriteFrame 尺寸資訊（供 contentSize 用）。
    rawWidth/rawHeight 就是 spriteFrame.originalSize；width/height 是 trim 後的 rect。"""
    d = load(meta)
    f = (d.get("subMetas") or {}).get("f9941") or {}
    u = f.get("userData") or f
    raw = (u.get("rawWidth"), u.get("rawHeight"))
    trim = (u.get("width"), u.get("height"))
    return {"raw": raw if None not in raw else None,
            "trim": trim if None not in trim else None,
            "imported": bool(d.get("imported"))}

def build_name_map(atlas_dir, search_root):
    """回傳 {舊base: 新base}, {舊base: 檔名}, {新base: 尺寸資訊}, {舊base: 尺寸資訊}, warnings
    舊圖尺寸是用來判斷「CUSTOM 其實是不是該跟著圖」的依據，見 wanted_size()。"""
    old2new, names, new_size, old_size, warns = {}, {}, {}, {}, []
    for f in sorted(glob.glob(os.path.join(atlas_dir, "*.png.meta"))):
        name = os.path.basename(f)[:-len(".png.meta")]
        nb, nsub = base_uuid(f), sub_ids(f)
        info = sprite_frame_meta(f)
        info["name"] = name
        new_size[nb] = info
        olds = [m for m in glob.glob(os.path.join(search_root, "**", name + ".png.meta"), recursive=True)
                if os.path.abspath(os.path.dirname(m)) != os.path.abspath(atlas_dir)]
        if not olds:
            warns.append(f"[跳過] {name}：專案內找不到同名舊圖")
            continue
        for om in olds:
            ob, osub = base_uuid(om), sub_ids(om)
            if ob == nb:
                continue
            if osub != nsub:
                warns.append(f"[警告] {name}：新舊 subMeta id 不一致，仍以 base UUID 對應，請人工確認")
            old2new[ob] = nb
            names[ob] = name
            oi = sprite_frame_meta(om)
            oi["name"] = name
            old_size[ob] = oi
    return old2new, names, new_size, old_size, warns

# ---------------------------------------------------------------- contentSize

RAW, TRIMMED, CUSTOM = 2, 1, 0
SIZEMODE_NAME = {0: "CUSTOM", 1: "TRIMMED", 2: "RAW"}

def _prefab_uuid_index():
    """{prefab uuid: prefab 檔路徑}，用來從 cc.PrefabInfo.asset 找回來源檔。"""
    idx = {}
    for m in glob.glob(os.path.join("assets", "**", "*.prefab.meta"), recursive=True):
        try:
            idx[base_uuid(m)] = m[:-len(".meta")]
        except Exception:
            pass
    return idx

def build_sprite_index(arr, seen=None, idx=None):
    """遞迴走 cc.PrefabInfo.asset 指到的來源 prefab，
    建 {cc.Sprite 的 fileId: {sizeMode, ut(同節點 UITransform 的 fileId), name}}。
    支援多層巢狀（override 的 localID 可能有多段）。"""
    if idx is None:
        idx = _prefab_uuid_index()
    if seen is None:
        seen = set()
    out = {}
    srcs = set()
    for o in arr:
        if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInfo":
            asset = o.get("asset")
            if isinstance(asset, dict) and asset.get("__uuid__"):
                srcs.add(asset["__uuid__"])
    for u in srcs:
        if u in seen:
            continue
        seen.add(u)
        p = idx.get(u)
        if not p or not os.path.exists(p):
            continue
        try:
            sub = load(p)
        except Exception:
            continue
        out.update(_sprite_index_of(sub))
        out.update(build_sprite_index(sub, seen, idx))
    return out

def _sprite_index_of(arr):
    """單一份 prefab/scene 裡的 cc.Sprite 索引。"""
    node_of = {}
    for i, o in enumerate(arr):
        if isinstance(o, dict) and o.get("__type__") == "cc.Node":
            for c in (o.get("_components") or []):
                if isinstance(c, dict) and "__id__" in c:
                    node_of[c["__id__"]] = i
    out = {}
    for i, o in enumerate(arr):
        if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
            continue
        fid = comp_fileid(arr, o)
        if not fid:
            continue
        ni = node_of.get(i)
        ut, cs = None, None
        if ni is not None:
            for c in (arr[ni].get("_components") or []):
                comp = arr[c["__id__"]]
                if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                    ut = comp_fileid(arr, comp)
                    s = comp.get("_contentSize") or {}
                    cs = (s.get("width"), s.get("height"))
        out[fid] = {"sizeMode": o.get("_sizeMode"), "ut": ut, "cs": cs,
                    "sf": (o.get("_spriteFrame") or {}).get("__uuid__")
                          if isinstance(o.get("_spriteFrame"), dict) else None,
                    "name": str(arr[ni].get("_name")) if ni is not None else "?"}
    return out

def _by_raw(info):
    return (info.get("raw"), None, "") if info.get("raw") else (None, "新圖 .meta 沒有 rawWidth/rawHeight", "")

def _by_trim(info):
    if not info.get("imported"):
        return None, "新圖 .meta 尚未匯入（imported:false），trim 值不可信，請先讓 Cocos 匯入再跑", ""
    return (info.get("trim"), None, "") if info.get("trim") else (None, "新圖 .meta 沒有 trim 後的 width/height", "")

def wanted_size(sizemode, info, old_info=None, base_cs=None, strict_custom=False):
    """依 sizeMode 決定 contentSize。回傳 ((w,h), None, 備註) 或 (None, 不能做的原因, "")。

    CUSTOM 的處理：SlotCommon 有些節點被設成 CUSTOM，但 contentSize 剛好等於舊圖的
    rawSize / trim rect —— 那表示它的意圖本來就是「跟著圖」，只是 sizeMode 沒設對
    （共用模組不方便改，所以在這裡補救）。反之，contentSize 與圖尺寸無關的才是
    真正刻意的 CUSTOM，一定不能動。判定條件很嚴格，誤判機率低；
    要完全不碰 CUSTOM 就加 --strict-custom。
    """
    if sizemode == RAW:
        return _by_raw(info)
    if sizemode == TRIMMED:
        wh, why, _ = _by_trim(info)
        return wh, (f"TRIMMED 但{why}" if why else None), ""
    if sizemode == CUSTOM:
        if strict_custom:
            return None, "CUSTOM", ""
        if not old_info or not base_cs or None in base_cs:
            return None, "CUSTOM", ""
        cs = tuple(base_cs)
        # raw 優先：舊圖 raw==trim 時無從區分意圖，而 raw（不裁切）才是按鈕類的慣例
        if old_info.get("raw") and cs == tuple(old_info["raw"]):
            wh, why, _ = _by_raw(info)
            return wh, why, "CUSTOM→raw"
        if old_info.get("trim") and cs == tuple(old_info["trim"]):
            wh, why, _ = _by_trim(info)
            return wh, (f"CUSTOM 疑似 TRIMMED 但{why}" if why else None), "CUSTOM→trim"
        return None, "CUSTOM", ""
    return None, f"sizeMode={sizemode} 非預期值", ""

def _size_val(wh):
    return {"__type__": "cc.Size", "width": wh[0], "height": wh[1]}

def comp_fileid(a, comp):
    pf = comp.get("__prefab")
    return a[pf["__id__"]].get("fileId") if isinstance(pf, dict) else None

def is_spriteframe_val(v):
    return isinstance(v, dict) and v.get("__expectedType__") == "cc.SpriteFrame" and v.get("__uuid__")

def process_file(path, old2new, names, apply, new_size=None, do_cs=True,
                 old_size=None, strict_custom=False):
    a = load(path)
    if not isinstance(a, list):
        return 0, [f"[跳過] {path} 不是資產陣列格式"]
    new_size = new_size or {}
    old_size = old_size or {}
    new2old = {nb: ob for ob, nb in old2new.items()}
    logs = []
    prefab_instances = [o for o in a if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInstance"]

    # 每個 component 找出它所屬的 PrefabInstance（若有）。單層情況：整份檔通常只有一個實例。
    # 這裡以「檔案是否含 PrefabInstance」+「component 有 __prefab.fileId」判斷該 comp 是否來自巢狀來源。
    changed = 0

    # ---- 情況 B：巢狀 prefab 實例 → 產生 override ----
    for pi in prefab_instances:
        overrides = pi.setdefault("propertyOverrides", [])
        existing = set()
        for ref in overrides:
            ov = a[ref["__id__"]]
            ti = ov.get("targetInfo", {})
            tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
            lid = tuple(tinfo.get("localID", [])) if isinstance(tinfo, dict) else ()
            existing.add((lid, tuple(ov.get("propertyPath", []))))

        for comp in list(a):
            if not isinstance(comp, dict):
                continue
            fid = comp_fileid(a, comp)
            if not fid:
                continue
            for prop, val in list(comp.items()):
                if not is_spriteframe_val(val):
                    continue
                b, _, suf = val["__uuid__"].partition("@")
                if b not in old2new:
                    continue
                key = ((fid,), (prop,))
                if key in existing:
                    continue
                newu = old2new[b] + ("@" + suf if suf else "")
                ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": [fid]})
                ov_idx = len(a); a.append({
                    "__type__": "CCPropertyOverrideInfo",
                    "targetInfo": {"__id__": ti_idx},
                    "propertyPath": [prop],
                    "value": {"__uuid__": newu, "__expectedType__": "cc.SpriteFrame"},
                })
                overrides.append({"__id__": ov_idx})
                existing.add(key)
                changed += 1
                logs.append(f"  [override] {names[b]:28s} {prop:20s} -> {newu}")

    # ---- 情況 A：非實例（或實例外的一般節點）→ 直接替換展開 base UUID ----
    # 只有在【沒有 PrefabInstance】時才做全域 base UUID 取代，避免動到會被 override 機制還原的值。
    if not prefab_instances:
        txt = json.dumps(a, ensure_ascii=False, indent=2)
        for ob, nb in old2new.items():
            c = txt.count(ob)
            if c:
                txt = txt.replace(ob, nb)
                changed += c
                logs.append(f"  [直接替換] {names[ob]:28s} {ob} -> {nb}  ({c} 處)")
        a = json.loads(txt)

    # ---- 換圖後同步 contentSize（理由見檔頭）----
    if do_cs and new_size:
        # sizeMode 真值 = 來源 prefab + _sizeMode override。
        # 【不要】拿本檔展開值覆蓋：展開值只是快取（Cocos 依「來源 + override」還原），
        # 而且很容易被編輯器的 _resized() 汙染成 CUSTOM —— 那正是本段要修的 bug 留下的痕跡。
        # 展開值只用來補來源查不到的項，以及來源缺 ut 時當 fallback。
        smidx = build_sprite_index(a)
        for k, v in _sprite_index_of(a).items():
            if k not in smidx:
                smidx[k] = v
                continue
            if not smidx[k].get("ut"):
                smidx[k]["ut"] = v.get("ut")
            if not smidx[k].get("cs"):
                smidx[k]["cs"] = v.get("cs")
            if smidx[k].get("sizeMode") != v.get("sizeMode"):
                logs.append(
                    f"  [注意] {v['name']:24s} 展開值 sizeMode="
                    f"{SIZEMODE_NAME.get(v.get('sizeMode'), v.get('sizeMode'))}"
                    f" 與來源 {SIZEMODE_NAME.get(smidx[k].get('sizeMode'), smidx[k].get('sizeMode'))}"
                    f" 不符（展開值多半是被 _resized() 汙染的殘留），依來源處理")
        for pi in prefab_instances:
            for ref in pi.get("propertyOverrides", []):
                ov = a[ref["__id__"]]
                if ov.get("propertyPath") != ["_sizeMode"]:
                    continue
                ti = ov.get("targetInfo", {})
                tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                lid = (tinfo or {}).get("localID") or []
                if lid and lid[-1] in smidx:
                    smidx[lid[-1]]["sizeMode"] = ov.get("value")

        def target_for(newu):
            nb = (newu or "").split("@")[0]
            return new_size.get(nb)

        if prefab_instances:
            # 情況 B：contentSize 也要走 override
            for pi in prefab_instances:
                overrides = pi.setdefault("propertyOverrides", [])
                def cs_entries():
                    for ref in overrides:
                        ov = a[ref["__id__"]]
                        ti = ov.get("targetInfo", {})
                        tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                        yield ov, list((tinfo or {}).get("localID") or [])
                sf_targets = [(ov, lid) for ov, lid in cs_entries()
                              if lid and ov.get("propertyPath") == ["_spriteFrame"]]
                for ov, lid in sf_targets:
                    fid = lid[-1]
                    d = smidx.get(fid)
                    if not d:
                        continue                      # 不是 cc.Sprite（script 屬性等）
                    val = ov.get("value") or {}
                    info = target_for(val.get("__uuid__") if isinstance(val, dict) else None)
                    if not info:
                        continue
                    newu = val.get("__uuid__") if isinstance(val, dict) else None
                    old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                    wh, why, note = wanted_size(d.get("sizeMode"), info, old_info,
                                                d.get("cs"), strict_custom)
                    if wh is None:
                        if why != "CUSTOM":
                            logs.append(f"  [contentSize 略過] {d['name']:24s} {why}")
                        continue
                    if not d.get("ut"):
                        logs.append(f"  [contentSize 略過] {d['name']:24s} 同節點找不到 cc.UITransform")
                        continue
                    ut_lid = lid[:-1] + [d["ut"]]
                    hit = None
                    for ov2, lid2 in cs_entries():
                        if lid2 == ut_lid and ov2.get("propertyPath") == ["_contentSize"]:
                            hit = ov2
                    if hit is not None:
                        cur = hit.get("value") or {}
                        if (cur.get("width"), cur.get("height")) == tuple(wh):
                            continue
                        hit["value"] = _size_val(wh)
                    else:
                        ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": ut_lid})
                        ov_idx = len(a); a.append({
                            "__type__": "CCPropertyOverrideInfo",
                            "targetInfo": {"__id__": ti_idx},
                            "propertyPath": ["_contentSize"],
                            "value": _size_val(wh),
                        })
                        overrides.append({"__id__": ov_idx})
                    changed += 1
                    mode = note or SIZEMODE_NAME.get(d.get("sizeMode"), "?")
                    logs.append(f"  [contentSize] {d['name']:24s} "
                                f"{mode:11s} -> {wh[0]}x{wh[1]}")
        else:
            # 情況 A：直接改同節點 cc.UITransform
            node_of = {}
            for i, o in enumerate(a):
                if isinstance(o, dict) and o.get("__type__") == "cc.Node":
                    for c in (o.get("_components") or []):
                        if isinstance(c, dict) and "__id__" in c:
                            node_of[c["__id__"]] = i
            for i, o in enumerate(a):
                if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
                    continue
                sf = o.get("_spriteFrame")
                info = target_for(sf.get("__uuid__") if isinstance(sf, dict) else None)
                if not info:
                    continue
                name = str(a[node_of[i]].get("_name")) if i in node_of else "?"
                ut = None
                for c in (a[node_of[i]].get("_components") or []):
                    comp = a[c["__id__"]]
                    if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                        ut = comp
                # 此時圖已換成新的，但 contentSize 還是舊值 —— 正好是判斷 CUSTOM 意圖的依據
                base_cs = None
                if ut is not None:
                    s = ut.get("_contentSize") or {}
                    base_cs = (s.get("width"), s.get("height"))
                newu = sf.get("__uuid__") if isinstance(sf, dict) else None
                old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                wh, why, note = wanted_size(o.get("_sizeMode"), info, old_info,
                                            base_cs, strict_custom)
                if wh is None:
                    if why != "CUSTOM":
                        logs.append(f"  [contentSize 略過] {name:24s} {why}")
                    continue
                if ut is None:
                    logs.append(f"  [contentSize 略過] {name:24s} 同節點找不到 cc.UITransform")
                    continue
                cur = ut.get("_contentSize") or {}
                if (cur.get("width"), cur.get("height")) == tuple(wh):
                    continue
                ut["_contentSize"] = _size_val(wh)
                changed += 1
                mode = note or SIZEMODE_NAME.get(o.get("_sizeMode"), "?")
                logs.append(f"  [contentSize] {name:24s} {mode:11s} -> {wh[0]}x{wh[1]}")

    if changed and apply:
        with open(path, "w", encoding="utf-8") as fp:
            json.dump(a, fp, ensure_ascii=False, indent=2)
    # 驗證 JSON（用 dumps 後可解析即可）
    if changed:
        json.loads(json.dumps(a, ensure_ascii=False))
    return changed, logs

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--atlas", required=True)
    ap.add_argument("--targets", required=True, nargs="+")
    ap.add_argument("--search-root", default="assets")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--no-content-size", action="store_true",
                    help="不要在換圖後同步 cc.UITransform 的 contentSize（預設會同步，理由見檔頭）")
    ap.add_argument("--strict-custom", action="store_true",
                    help="完全不碰 sizeMode=CUSTOM 的節點。預設會處理「contentSize 剛好等於舊圖尺寸」"
                         "的 CUSTOM（那種其實是該跟著圖、只是 sizeMode 沒設對），報告標為 CUSTOM→raw/trim")
    args = ap.parse_args()

    old2new, names, new_size, old_size, warns = build_name_map(args.atlas, args.search_root)
    print(f"名稱對照（舊→新）：{len(old2new)} 組")
    if args.no_content_size:
        print("※ --no-content-size：只換圖，不同步 contentSize")
    elif args.strict_custom:
        print("※ --strict-custom：sizeMode=CUSTOM 的節點一律不動")

    total = 0
    for t in args.targets:
        if not os.path.exists(t):
            warns.append(f"[跳過] 目標檔不存在：{t}")
            continue
        print(f"\n目標：{t}")
        c, logs = process_file(t, old2new, names, args.apply,
                               new_size=new_size, do_cs=not args.no_content_size,
                               old_size=old_size, strict_custom=args.strict_custom)
        for l in logs:
            print(l)
        print(f"  小計：{c} 處")
        total += c

    print(f"\n合計：{total} 處")
    if warns:
        print("\n訊息：")
        for w in warns:
            print("  " + w)
    if not args.apply:
        print("\n(乾跑模式，未寫入。確認無誤後加 --apply)")
    print("\n★ 記得先關閉 Cocos Editor 再執行；改完重開編輯器並重新載入 prefab。")

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
用 Atlas 資料夾裡的新圖，替換 Cocos prefab / scene 中「同名」舊圖的 SpriteFrame 引用。
會涵蓋 cc.Sprite 的 _spriteFrame，以及 script 元件上任何 SpriteFrame property
（例如 clickedSpriteFrame、originalSprietFrame）。

★ 重點：兩種資產結構要用不同做法 ★
  A. 「自己擁有節點」的 prefab / scene（沒有 cc.PrefabInstance）：
     直接把展開資料裡的 base UUID 換掉即可。
  B. 「巢狀 prefab 實例」（檔案裡有 cc.PrefabInstance，節點來自另一個來源 prefab）：
     直接改展開值【無效】，Cocos 存檔時會依「來源 prefab + override」還原。
     必須在該 PrefabInstance 的 propertyOverrides 裡新增
     CCPropertyOverrideInfo + cc.TargetInfo，才會真正生效。
  本腳本會自動偵測並對兩種結構分別處理；同一份檔案可同時存在兩種情況。

對照方式：以「檔名」對應。對 Atlas 內每張圖，找專案裡同名舊圖 .meta 取得舊 base UUID，
再對應到新圖 base UUID。只要新舊圖 subMeta id 一致（Cocos 依內容產生，通常一致），
換掉 36 碼 base UUID、保留 @<subId> 後綴即可。

★ 換圖後還要同步 cc.UITransform 的 contentSize ★
  cc.Sprite 的 _spriteFrame 是 @serializable 欄位，反序列化【不走 setter】，
  所以 _applySpriteFrame -> _applySpriteSize 在執行期從未被呼叫
  （engine/cocos/2d/components/sprite.ts：setter 在 215、_applySpriteSize 在 629/715）。
  而 _resized() 開頭就 `if (!EDITOR) return`（同檔 646）。因此：
    - build 後：sizeMode=RAW/TRIMMED 都【不會】自動套用新圖尺寸，
      contentSize 停在舊圖尺寸 -> 新圖被縮著畫。
    - 編輯器裡：__preload() 會呼叫 _resized()，一發現 contentSize 與期望不符，
      就把 _sizeMode 偷偷改成 CUSTOM（不慎存檔就固化）。
  原本沒問題是因為來源 prefab 的 contentSize 本來就等於舊圖尺寸；換圖破壞了這個不變式。
  所以換完圖必須依來源的 sizeMode 補上 contentSize：
    RAW     -> 新圖 .meta subMeta f9941 的 rawWidth/rawHeight（= spriteFrame.originalSize）
    TRIMMED -> 同處的 width/height（= spriteFrame.rect，trim 後）
    CUSTOM  -> 不動（那是刻意設計的尺寸）
  要關掉這段用 --no-content-size。

用法：
  # 先乾跑看看會改什麼
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> [<b.scene> ...]
  # 確認無誤後實際寫入
  python replace_atlas_sprites.py --atlas <新圖資料夾> --targets <a.prefab> --apply

  [--search-root assets]  搜尋同名舊圖的根目錄，預設 assets

★ 執行前務必先關閉 Cocos Editor（或至少關掉該 prefab 分頁），
  否則編輯器存檔會覆蓋腳本的修改。改完再開編輯器並重新載入。
"""
import argparse, glob, json, os, sys

def load(p):  return json.load(open(p, encoding="utf-8"))
def base_uuid(meta): return load(meta)["uuid"]
def sub_ids(meta):   return set(load(meta).get("subMetas", {}).keys())

def sprite_frame_meta(meta):
    """新圖 .meta 的 spriteFrame 尺寸資訊（供 contentSize 用）。
    rawWidth/rawHeight 就是 spriteFrame.originalSize；width/height 是 trim 後的 rect。"""
    d = load(meta)
    f = (d.get("subMetas") or {}).get("f9941") or {}
    u = f.get("userData") or f
    raw = (u.get("rawWidth"), u.get("rawHeight"))
    trim = (u.get("width"), u.get("height"))
    return {"raw": raw if None not in raw else None,
            "trim": trim if None not in trim else None,
            "imported": bool(d.get("imported"))}

def build_name_map(atlas_dir, search_root):
    """回傳 {舊base: 新base}, {舊base: 檔名}, {新base: 尺寸資訊}, {舊base: 尺寸資訊}, warnings
    舊圖尺寸是用來判斷「CUSTOM 其實是不是該跟著圖」的依據，見 wanted_size()。"""
    old2new, names, new_size, old_size, warns = {}, {}, {}, {}, []
    for f in sorted(glob.glob(os.path.join(atlas_dir, "*.png.meta"))):
        name = os.path.basename(f)[:-len(".png.meta")]
        nb, nsub = base_uuid(f), sub_ids(f)
        info = sprite_frame_meta(f)
        info["name"] = name
        new_size[nb] = info
        olds = [m for m in glob.glob(os.path.join(search_root, "**", name + ".png.meta"), recursive=True)
                if os.path.abspath(os.path.dirname(m)) != os.path.abspath(atlas_dir)]
        if not olds:
            warns.append(f"[跳過] {name}：專案內找不到同名舊圖")
            continue
        for om in olds:
            ob, osub = base_uuid(om), sub_ids(om)
            if ob == nb:
                continue
            if osub != nsub:
                warns.append(f"[警告] {name}：新舊 subMeta id 不一致，仍以 base UUID 對應，請人工確認")
            old2new[ob] = nb
            names[ob] = name
            oi = sprite_frame_meta(om)
            oi["name"] = name
            old_size[ob] = oi
    return old2new, names, new_size, old_size, warns

# ---------------------------------------------------------------- contentSize

RAW, TRIMMED, CUSTOM = 2, 1, 0
SIZEMODE_NAME = {0: "CUSTOM", 1: "TRIMMED", 2: "RAW"}

def _prefab_uuid_index():
    """{prefab uuid: prefab 檔路徑}，用來從 cc.PrefabInfo.asset 找回來源檔。"""
    idx = {}
    for m in glob.glob(os.path.join("assets", "**", "*.prefab.meta"), recursive=True):
        try:
            idx[base_uuid(m)] = m[:-len(".meta")]
        except Exception:
            pass
    return idx

def build_sprite_index(arr, seen=None, idx=None):
    """遞迴走 cc.PrefabInfo.asset 指到的來源 prefab，
    建 {cc.Sprite 的 fileId: {sizeMode, ut(同節點 UITransform 的 fileId), name}}。
    支援多層巢狀（override 的 localID 可能有多段）。"""
    if idx is None:
        idx = _prefab_uuid_index()
    if seen is None:
        seen = set()
    out = {}
    srcs = set()
    for o in arr:
        if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInfo":
            asset = o.get("asset")
            if isinstance(asset, dict) and asset.get("__uuid__"):
                srcs.add(asset["__uuid__"])
    for u in srcs:
        if u in seen:
            continue
        seen.add(u)
        p = idx.get(u)
        if not p or not os.path.exists(p):
            continue
        try:
            sub = load(p)
        except Exception:
            continue
        out.update(_sprite_index_of(sub))
        out.update(build_sprite_index(sub, seen, idx))
    return out

def _sprite_index_of(arr):
    """單一份 prefab/scene 裡的 cc.Sprite 索引。"""
    node_of = {}
    for i, o in enumerate(arr):
        if isinstance(o, dict) and o.get("__type__") == "cc.Node":
            for c in (o.get("_components") or []):
                if isinstance(c, dict) and "__id__" in c:
                    node_of[c["__id__"]] = i
    out = {}
    for i, o in enumerate(arr):
        if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
            continue
        fid = comp_fileid(arr, o)
        if not fid:
            continue
        ni = node_of.get(i)
        ut, cs = None, None
        if ni is not None:
            for c in (arr[ni].get("_components") or []):
                comp = arr[c["__id__"]]
                if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                    ut = comp_fileid(arr, comp)
                    s = comp.get("_contentSize") or {}
                    cs = (s.get("width"), s.get("height"))
        out[fid] = {"sizeMode": o.get("_sizeMode"), "ut": ut, "cs": cs,
                    "sf": (o.get("_spriteFrame") or {}).get("__uuid__")
                          if isinstance(o.get("_spriteFrame"), dict) else None,
                    "name": str(arr[ni].get("_name")) if ni is not None else "?"}
    return out

def _by_raw(info):
    return (info.get("raw"), None, "") if info.get("raw") else (None, "新圖 .meta 沒有 rawWidth/rawHeight", "")

def _by_trim(info):
    if not info.get("imported"):
        return None, "新圖 .meta 尚未匯入（imported:false），trim 值不可信，請先讓 Cocos 匯入再跑", ""
    return (info.get("trim"), None, "") if info.get("trim") else (None, "新圖 .meta 沒有 trim 後的 width/height", "")

def wanted_size(sizemode, info, old_info=None, base_cs=None, strict_custom=False):
    """依 sizeMode 決定 contentSize。回傳 ((w,h), None, 備註) 或 (None, 不能做的原因, "")。

    CUSTOM 的處理：SlotCommon 有些節點被設成 CUSTOM，但 contentSize 剛好等於舊圖的
    rawSize / trim rect —— 那表示它的意圖本來就是「跟著圖」，只是 sizeMode 沒設對
    （共用模組不方便改，所以在這裡補救）。反之，contentSize 與圖尺寸無關的才是
    真正刻意的 CUSTOM，一定不能動。判定條件很嚴格，誤判機率低；
    要完全不碰 CUSTOM 就加 --strict-custom。
    """
    if sizemode == RAW:
        return _by_raw(info)
    if sizemode == TRIMMED:
        wh, why, _ = _by_trim(info)
        return wh, (f"TRIMMED 但{why}" if why else None), ""
    if sizemode == CUSTOM:
        if strict_custom:
            return None, "CUSTOM", ""
        if not old_info or not base_cs or None in base_cs:
            return None, "CUSTOM", ""
        cs = tuple(base_cs)
        # raw 優先：舊圖 raw==trim 時無從區分意圖，而 raw（不裁切）才是按鈕類的慣例
        if old_info.get("raw") and cs == tuple(old_info["raw"]):
            wh, why, _ = _by_raw(info)
            return wh, why, "CUSTOM→raw"
        if old_info.get("trim") and cs == tuple(old_info["trim"]):
            wh, why, _ = _by_trim(info)
            return wh, (f"CUSTOM 疑似 TRIMMED 但{why}" if why else None), "CUSTOM→trim"
        return None, "CUSTOM", ""
    return None, f"sizeMode={sizemode} 非預期值", ""

def _size_val(wh):
    return {"__type__": "cc.Size", "width": wh[0], "height": wh[1]}

def comp_fileid(a, comp):
    pf = comp.get("__prefab")
    return a[pf["__id__"]].get("fileId") if isinstance(pf, dict) else None

def is_spriteframe_val(v):
    return isinstance(v, dict) and v.get("__expectedType__") == "cc.SpriteFrame" and v.get("__uuid__")

def process_file(path, old2new, names, apply, new_size=None, do_cs=True,
                 old_size=None, strict_custom=False):
    a = load(path)
    if not isinstance(a, list):
        return 0, [f"[跳過] {path} 不是資產陣列格式"]
    new_size = new_size or {}
    old_size = old_size or {}
    new2old = {nb: ob for ob, nb in old2new.items()}
    logs = []
    prefab_instances = [o for o in a if isinstance(o, dict) and o.get("__type__") == "cc.PrefabInstance"]

    # 每個 component 找出它所屬的 PrefabInstance（若有）。單層情況：整份檔通常只有一個實例。
    # 這裡以「檔案是否含 PrefabInstance」+「component 有 __prefab.fileId」判斷該 comp 是否來自巢狀來源。
    changed = 0

    # ---- 情況 B：巢狀 prefab 實例 → 產生 override ----
    for pi in prefab_instances:
        overrides = pi.setdefault("propertyOverrides", [])
        existing = set()
        for ref in overrides:
            ov = a[ref["__id__"]]
            ti = ov.get("targetInfo", {})
            tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
            lid = tuple(tinfo.get("localID", [])) if isinstance(tinfo, dict) else ()
            existing.add((lid, tuple(ov.get("propertyPath", []))))

        for comp in list(a):
            if not isinstance(comp, dict):
                continue
            fid = comp_fileid(a, comp)
            if not fid:
                continue
            for prop, val in list(comp.items()):
                if not is_spriteframe_val(val):
                    continue
                b, _, suf = val["__uuid__"].partition("@")
                if b not in old2new:
                    continue
                key = ((fid,), (prop,))
                if key in existing:
                    continue
                newu = old2new[b] + ("@" + suf if suf else "")
                ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": [fid]})
                ov_idx = len(a); a.append({
                    "__type__": "CCPropertyOverrideInfo",
                    "targetInfo": {"__id__": ti_idx},
                    "propertyPath": [prop],
                    "value": {"__uuid__": newu, "__expectedType__": "cc.SpriteFrame"},
                })
                overrides.append({"__id__": ov_idx})
                existing.add(key)
                changed += 1
                logs.append(f"  [override] {names[b]:28s} {prop:20s} -> {newu}")

    # ---- 情況 A：非實例（或實例外的一般節點）→ 直接替換展開 base UUID ----
    # 只有在【沒有 PrefabInstance】時才做全域 base UUID 取代，避免動到會被 override 機制還原的值。
    if not prefab_instances:
        txt = json.dumps(a, ensure_ascii=False, indent=2)
        for ob, nb in old2new.items():
            c = txt.count(ob)
            if c:
                txt = txt.replace(ob, nb)
                changed += c
                logs.append(f"  [直接替換] {names[ob]:28s} {ob} -> {nb}  ({c} 處)")
        a = json.loads(txt)

    # ---- 換圖後同步 contentSize（理由見檔頭）----
    if do_cs and new_size:
        # sizeMode 真值 = 來源 prefab + _sizeMode override。
        # 【不要】拿本檔展開值覆蓋：展開值只是快取（Cocos 依「來源 + override」還原），
        # 而且很容易被編輯器的 _resized() 汙染成 CUSTOM —— 那正是本段要修的 bug 留下的痕跡。
        # 展開值只用來補來源查不到的項，以及來源缺 ut 時當 fallback。
        smidx = build_sprite_index(a)
        for k, v in _sprite_index_of(a).items():
            if k not in smidx:
                smidx[k] = v
                continue
            if not smidx[k].get("ut"):
                smidx[k]["ut"] = v.get("ut")
            if not smidx[k].get("cs"):
                smidx[k]["cs"] = v.get("cs")
            if smidx[k].get("sizeMode") != v.get("sizeMode"):
                logs.append(
                    f"  [注意] {v['name']:24s} 展開值 sizeMode="
                    f"{SIZEMODE_NAME.get(v.get('sizeMode'), v.get('sizeMode'))}"
                    f" 與來源 {SIZEMODE_NAME.get(smidx[k].get('sizeMode'), smidx[k].get('sizeMode'))}"
                    f" 不符（展開值多半是被 _resized() 汙染的殘留），依來源處理")
        for pi in prefab_instances:
            for ref in pi.get("propertyOverrides", []):
                ov = a[ref["__id__"]]
                if ov.get("propertyPath") != ["_sizeMode"]:
                    continue
                ti = ov.get("targetInfo", {})
                tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                lid = (tinfo or {}).get("localID") or []
                if lid and lid[-1] in smidx:
                    smidx[lid[-1]]["sizeMode"] = ov.get("value")

        def target_for(newu):
            nb = (newu or "").split("@")[0]
            return new_size.get(nb)

        if prefab_instances:
            # 情況 B：contentSize 也要走 override
            for pi in prefab_instances:
                overrides = pi.setdefault("propertyOverrides", [])
                def cs_entries():
                    for ref in overrides:
                        ov = a[ref["__id__"]]
                        ti = ov.get("targetInfo", {})
                        tinfo = a[ti["__id__"]] if isinstance(ti, dict) and "__id__" in ti else None
                        yield ov, list((tinfo or {}).get("localID") or [])
                sf_targets = [(ov, lid) for ov, lid in cs_entries()
                              if lid and ov.get("propertyPath") == ["_spriteFrame"]]
                for ov, lid in sf_targets:
                    fid = lid[-1]
                    d = smidx.get(fid)
                    if not d:
                        continue                      # 不是 cc.Sprite（script 屬性等）
                    val = ov.get("value") or {}
                    info = target_for(val.get("__uuid__") if isinstance(val, dict) else None)
                    if not info:
                        continue
                    newu = val.get("__uuid__") if isinstance(val, dict) else None
                    old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                    wh, why, note = wanted_size(d.get("sizeMode"), info, old_info,
                                                d.get("cs"), strict_custom)
                    if wh is None:
                        if why != "CUSTOM":
                            logs.append(f"  [contentSize 略過] {d['name']:24s} {why}")
                        continue
                    if not d.get("ut"):
                        logs.append(f"  [contentSize 略過] {d['name']:24s} 同節點找不到 cc.UITransform")
                        continue
                    ut_lid = lid[:-1] + [d["ut"]]
                    hit = None
                    for ov2, lid2 in cs_entries():
                        if lid2 == ut_lid and ov2.get("propertyPath") == ["_contentSize"]:
                            hit = ov2
                    if hit is not None:
                        cur = hit.get("value") or {}
                        if (cur.get("width"), cur.get("height")) == tuple(wh):
                            continue
                        hit["value"] = _size_val(wh)
                    else:
                        ti_idx = len(a); a.append({"__type__": "cc.TargetInfo", "localID": ut_lid})
                        ov_idx = len(a); a.append({
                            "__type__": "CCPropertyOverrideInfo",
                            "targetInfo": {"__id__": ti_idx},
                            "propertyPath": ["_contentSize"],
                            "value": _size_val(wh),
                        })
                        overrides.append({"__id__": ov_idx})
                    changed += 1
                    mode = note or SIZEMODE_NAME.get(d.get("sizeMode"), "?")
                    logs.append(f"  [contentSize] {d['name']:24s} "
                                f"{mode:11s} -> {wh[0]}x{wh[1]}")
        else:
            # 情況 A：直接改同節點 cc.UITransform
            node_of = {}
            for i, o in enumerate(a):
                if isinstance(o, dict) and o.get("__type__") == "cc.Node":
                    for c in (o.get("_components") or []):
                        if isinstance(c, dict) and "__id__" in c:
                            node_of[c["__id__"]] = i
            for i, o in enumerate(a):
                if not isinstance(o, dict) or o.get("__type__") != "cc.Sprite":
                    continue
                sf = o.get("_spriteFrame")
                info = target_for(sf.get("__uuid__") if isinstance(sf, dict) else None)
                if not info:
                    continue
                name = str(a[node_of[i]].get("_name")) if i in node_of else "?"
                ut = None
                for c in (a[node_of[i]].get("_components") or []):
                    comp = a[c["__id__"]]
                    if isinstance(comp, dict) and comp.get("__type__") == "cc.UITransform":
                        ut = comp
                # 此時圖已換成新的，但 contentSize 還是舊值 —— 正好是判斷 CUSTOM 意圖的依據
                base_cs = None
                if ut is not None:
                    s = ut.get("_contentSize") or {}
                    base_cs = (s.get("width"), s.get("height"))
                newu = sf.get("__uuid__") if isinstance(sf, dict) else None
                old_info = old_size.get(new2old.get((newu or "").split("@")[0]))
                wh, why, note = wanted_size(o.get("_sizeMode"), info, old_info,
                                            base_cs, strict_custom)
                if wh is None:
                    if why != "CUSTOM":
                        logs.append(f"  [contentSize 略過] {name:24s} {why}")
                    continue
                if ut is None:
                    logs.append(f"  [contentSize 略過] {name:24s} 同節點找不到 cc.UITransform")
                    continue
                cur = ut.get("_contentSize") or {}
                if (cur.get("width"), cur.get("height")) == tuple(wh):
                    continue
                ut["_contentSize"] = _size_val(wh)
                changed += 1
                mode = note or SIZEMODE_NAME.get(o.get("_sizeMode"), "?")
                logs.append(f"  [contentSize] {name:24s} {mode:11s} -> {wh[0]}x{wh[1]}")

    if changed and apply:
        with open(path, "w", encoding="utf-8") as fp:
            json.dump(a, fp, ensure_ascii=False, indent=2)
    # 驗證 JSON（用 dumps 後可解析即可）
    if changed:
        json.loads(json.dumps(a, ensure_ascii=False))
    return changed, logs

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--atlas", required=True)
    ap.add_argument("--targets", required=True, nargs="+")
    ap.add_argument("--search-root", default="assets")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--no-content-size", action="store_true",
                    help="不要在換圖後同步 cc.UITransform 的 contentSize（預設會同步，理由見檔頭）")
    ap.add_argument("--strict-custom", action="store_true",
                    help="完全不碰 sizeMode=CUSTOM 的節點。預設會處理「contentSize 剛好等於舊圖尺寸」"
                         "的 CUSTOM（那種其實是該跟著圖、只是 sizeMode 沒設對），報告標為 CUSTOM→raw/trim")
    args = ap.parse_args()

    old2new, names, new_size, old_size, warns = build_name_map(args.atlas, args.search_root)
    print(f"名稱對照（舊→新）：{len(old2new)} 組")
    if args.no_content_size:
        print("※ --no-content-size：只換圖，不同步 contentSize")
    elif args.strict_custom:
        print("※ --strict-custom：sizeMode=CUSTOM 的節點一律不動")

    total = 0
    for t in args.targets:
        if not os.path.exists(t):
            warns.append(f"[跳過] 目標檔不存在：{t}")
            continue
        print(f"\n目標：{t}")
        c, logs = process_file(t, old2new, names, args.apply,
                               new_size=new_size, do_cs=not args.no_content_size,
                               old_size=old_size, strict_custom=args.strict_custom)
        for l in logs:
            print(l)
        print(f"  小計：{c} 處")
        total += c

    print(f"\n合計：{total} 處")
    if warns:
        print("\n訊息：")
        for w in warns:
            print("  " + w)
    if not args.apply:
        print("\n(乾跑模式，未寫入。確認無誤後加 --apply)")
    print("\n★ 記得先關閉 Cocos Editor 再執行；改完重開編輯器並重新載入 prefab。")

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
設定 / 修正 Cocos 專案圖片的壓縮設定 (compressSettings)。

有效 preset 來源：settings/v2/packages/builder.json 的 textureCompressConfig.userPreset
寫入位置：圖片的 .meta -> userData.compressSettings.{useCompressTexture, presetId}

處理四種目標：AutoAtlas(.pac) / Spine 圖 / jpg / fnt 用圖。
被 AutoAtlas 合走的散圖不個別設壓縮，只檢查 type 是否為 sprite-frame。

預設 dry-run，加 --apply 才寫檔。
"""

import argparse
import json
import re
import sys
from pathlib import Path

# Windows 主控台預設 cp950，中文會亂碼
for _s in (sys.stdout, sys.stderr):
    try:
        if (_s.encoding or '').lower().replace('-', '') != 'utf8':
            _s.reconfigure(encoding='utf-8')
    except (AttributeError, ValueError):
        pass

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.webp'}
JPG_EXTS = {'.jpg', '.jpeg'}

# 分類代號
KIND_ATLAS = 'AutoAtlas'
KIND_SPINE = 'Spine'
KIND_JPG = 'JPG'
KIND_FNT = 'Fnt'
KIND_PACKED = '被Atlas合走'
KIND_OTHER = '未分類'

OTHER_LIST_LIMIT = 10   # 「未分類」清單最多列幾筆

# 處理結果
ACT_ADD = 'ADD'            # 沒有 compressSettings -> 新增
ACT_FIX = 'FIX'            # presetId 對應不到 -> 改成目標 preset
ACT_OK = 'OK'              # presetId 有效 -> 不動
ACT_TYPE = 'TYPE'          # type 不是 sprite-frame
ACT_NOMETA = 'NOMETA'      # 找不到 .meta


# ---------------------------------------------------------------- preset

def find_project_root(start: Path) -> Path:
    """從 start 往上找含 settings/v2/packages/builder.json 的專案根。"""
    for d in [start, *start.parents]:
        if (d / 'settings' / 'v2' / 'packages' / 'builder.json').is_file():
            return d
    raise SystemExit(f'[錯誤] 從 {start} 往上找不到 settings/v2/packages/builder.json，'
                     f'請用 --project-root 指定專案根。')


def load_presets(root: Path) -> dict:
    """回傳 {presetId: name}。"""
    f = root / 'settings' / 'v2' / 'packages' / 'builder.json'
    data = json.loads(f.read_text(encoding='utf-8'))
    user = data.get('textureCompressConfig', {}).get('userPreset', {}) or {}
    return {pid: (info or {}).get('name', '(無名稱)') for pid, info in user.items()}


def pick_default_preset(presets: dict, prefix: str):
    """找 name 以 prefix 開頭的 preset（不分大小寫），回傳 (id, name) 或 None。"""
    low = prefix.lower()
    for pid, name in presets.items():
        if name.lower().startswith(low):
            return pid, name
    return None


# ---------------------------------------------------------------- meta 讀寫

def read_meta(meta_path: Path):
    """回傳 (data, newline, trailing)。保留原換行風格與結尾換行，寫回才不會整檔 diff。"""
    raw = meta_path.read_text(encoding='utf-8', newline='')
    newline = '\r\n' if '\r\n' in raw else '\n'
    trailing = raw.endswith(('\n', '\r'))
    return json.loads(raw), newline, trailing


def write_meta(meta_path: Path, data, newline: str, trailing: bool):
    text = json.dumps(data, indent=2, ensure_ascii=False)
    if trailing:
        text += '\n'
    if newline != '\n':
        text = text.replace('\n', newline)
    meta_path.write_text(text, encoding='utf-8', newline='')


# ---------------------------------------------------------------- 掃描 / 分類

def _spine_atlas_files(base: Path):
    """spine 的 atlas 檔可能是 .atlas，也可能是 .atlas.txt（Cocos 常見）。"""
    found = set(base.rglob('*.atlas'))
    found.update(base.rglob('*.atlas.txt'))
    return sorted(found)


def _atlas_stem(atlas_file: Path) -> str:
    """ExtraBet.atlas.txt -> ExtraBet；Spin.atlas -> Spin"""
    name = atlas_file.name
    for suf in ('.atlas.txt', '.atlas'):
        if name.lower().endswith(suf):
            return name[:-len(suf)]
    return atlas_file.stem


def parse_spine_atlas(atlas_file: Path):
    """從 .atlas 取出它引用的圖檔（可能多張）。解析不到才退回同名比對。"""
    out = []
    try:
        lines = atlas_file.read_text(encoding='utf-8', errors='ignore').splitlines()
    except OSError:
        return out
    for line in lines:
        s = line.strip()
        # 圖名行：不含 ':'（那是屬性行）、不縮排、副檔名是圖片
        if not s or ':' in s or line[:1] in (' ', '\t'):
            continue
        if Path(s).suffix.lower() in IMAGE_EXTS:
            p = atlas_file.parent / s
            if p.is_file():
                out.append(p.resolve())
    if not out:
        # 退回同名：Spin.atlas.txt -> Spin.png / Spin.jpg ...
        stem = _atlas_stem(atlas_file)
        for ext in IMAGE_EXTS:
            p = atlas_file.parent / (stem + ext)
            if p.is_file():
                out.append(p.resolve())
                break
    return out


# 同時涵蓋文字格式 (page id=0 file="x.png") 與 XML 格式 (<page id="0" file="x.png"/>)
FNT_FILE_RE = re.compile(r'file\s*=\s*(?:"([^"]+)"|([^\s/>]+))')


def parse_fnt(fnt_file: Path):
    """從 .fnt 的 page 取出圖檔（檔名常帶 _0 後綴，不能靠同名比對）。"""
    out = []
    try:
        text = fnt_file.read_text(encoding='utf-8', errors='ignore')
    except OSError:
        return out
    for m in FNT_FILE_RE.finditer(text):
        name = (m.group(1) or m.group(2) or '').strip()
        if Path(name).suffix.lower() not in IMAGE_EXTS:
            continue
        p = fnt_file.parent / name
        if p.is_file():
            rp = p.resolve()
            if rp not in out:
                out.append(rp)
    return out


class AtlasScope:
    """判斷某張圖是否落在 AutoAtlas 的覆蓋範圍（atlas 所在目錄與其所有子目錄）。

    往上找到 assets 根為止，所以即使使用者只指定深層子資料夾，
    上層的 .pac 也一樣算數。
    """

    def __init__(self):
        self._dir_cache = {}
        self._scope_cache = {}

    def _has_pac(self, d: Path) -> bool:
        if d not in self._dir_cache:
            try:
                self._dir_cache[d] = any(d.glob('*.pac'))
            except OSError:
                self._dir_cache[d] = False
        return self._dir_cache[d]

    def covering_atlas_dir(self, img: Path):
        """回傳覆蓋這張圖的 atlas 目錄，沒有則 None。"""
        d = img.parent
        if d in self._scope_cache:
            return self._scope_cache[d]
        chain, found = [], None
        cur = d
        while True:
            chain.append(cur)
            if cur in self._scope_cache and self._scope_cache[cur] is not None:
                found = self._scope_cache[cur]
                break
            if self._has_pac(cur):
                found = cur
                break
            if cur.name == 'assets' or cur.parent == cur:
                break
            cur = cur.parent
        for c in chain:
            self._scope_cache[c] = found
        return found


def scan_dir(base: Path, scope: AtlasScope):
    """掃一個資料夾，回傳 {resolved_path: [kind, note]}。"""
    targets = {}
    claimed = set()

    def claim(p: Path, kind: str):
        p = p.resolve()
        claimed.add(p)
        if p in targets:
            # 一張圖被多個 .atlas/.fnt 共用（多 skel 共用一張 png）—— 只記一次
            return
        atlas_dir = scope.covering_atlas_dir(p)
        note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                if atlas_dir is not None else '')
        targets[p] = [kind, note]

    # 1) AutoAtlas 本身
    for pac in sorted(base.rglob('*.pac')):
        targets.setdefault(pac.resolve(), [KIND_ATLAS, ''])

    # 2) Spine：解析 .atlas / .atlas.txt 取真正引用的圖
    for at in _spine_atlas_files(base):
        for img in parse_spine_atlas(at):
            claim(img, KIND_SPINE)

    # 3) Fnt：解析 page 的 file=
    for fnt in sorted(base.rglob('*.fnt')):
        for img in parse_fnt(fnt):
            claim(img, KIND_FNT)

    # 4) 其餘圖片
    for img in sorted(base.rglob('*')):
        if not img.is_file() or img.suffix.lower() not in IMAGE_EXTS:
            continue
        rp = img.resolve()
        if rp in claimed or rp in targets:
            continue
        atlas_dir = scope.covering_atlas_dir(rp)
        if img.suffix.lower() in JPG_EXTS:
            note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                    if atlas_dir is not None else '')
            targets[rp] = [KIND_JPG, note]
        elif atlas_dir is not None:
            targets[rp] = [KIND_PACKED, f'由 {atlas_dir.name} 合圖']
        else:
            targets[rp] = [KIND_OTHER, '不屬於四種目標，且不在任何 AutoAtlas 範圍內']

    return targets


def scan(paths, scope: AtlasScope):
    """掃描指定路徑（資料夾或單檔），回傳 {resolved_path: [kind, note]}。

    指定單檔時：仍掃它所在資料夾以判斷分類（是否 spine/fnt 用圖、是否被 atlas 合走），
    但結果只保留該檔案本身。
    """
    merged = {}
    for root in paths:
        if root.is_file():
            found = scan_dir(root.parent, scope)
            rp = root.resolve()
            if rp in found:
                merged.setdefault(rp, found[rp])
            elif root.suffix.lower() in IMAGE_EXTS or root.suffix.lower() == '.pac':
                merged.setdefault(rp, [KIND_ATLAS if root.suffix.lower() == '.pac'
                                       else KIND_OTHER, ''])
            else:
                print(f'[略過] 不是圖片或 .pac: {root}', file=sys.stderr)
        else:
            for k, v in scan_dir(root, scope).items():
                merged.setdefault(k, v)
    return merged


# ---------------------------------------------------------------- 處理單一目標

def process(img: Path, kind: str, valid_ids: set, target_id: str,
            fix_type: bool, force_enable: bool, apply: bool):
    """回傳 result dict。"""
    meta_path = Path(str(img) + '.meta')
    res = {
        'path': img, 'kind': kind, 'meta': meta_path,
        'actions': [], 'warns': [], 'type': None, 'preset': None, 'dirty': False,
    }
    if not meta_path.is_file():
        res['actions'].append(ACT_NOMETA)
        return res

    try:
        data, newline, trailing = read_meta(meta_path)
    except (json.JSONDecodeError, OSError) as e:
        res['actions'].append(ACT_NOMETA)
        res['warns'].append(f'meta 讀取失敗: {e}')
        return res

    ud = data.setdefault('userData', {})
    dirty = False

    # --- type 檢查 ---
    # .pac 是 auto-atlas importer 沒有 type 欄位；
    # 未分類的圖不屬於四種目標（可能是 TextMeshPro/shader 用圖，刻意設 texture），一律不碰。
    if kind not in (KIND_ATLAS, KIND_OTHER):
        t = ud.get('type')
        res['type'] = t
        if t != 'sprite-frame':
            res['actions'].append(ACT_TYPE)
            if fix_type:
                ud['type'] = 'sprite-frame'
                dirty = True

    # --- 被 atlas 合走的散圖 / 未分類：不碰壓縮設定 ---
    if kind in (KIND_PACKED, KIND_OTHER):
        if dirty and apply:
            write_meta(meta_path, data, newline, trailing)
        res['dirty'] = dirty
        return res

    # --- 壓縮設定 ---
    cs = ud.get('compressSettings')
    if not isinstance(cs, dict):
        ud['compressSettings'] = {'useCompressTexture': True, 'presetId': target_id}
        res['actions'].append(ACT_ADD)
        res['preset'] = target_id
        dirty = True
    else:
        pid = cs.get('presetId')
        res['preset'] = pid
        if pid not in valid_ids:
            cs['presetId'] = target_id
            res['actions'].append(ACT_FIX)
            res['preset'] = target_id
            dirty = True
        else:
            res['actions'].append(ACT_OK)

        # 沒有 useCompressTexture 這個 key 等同「勾選框沒勾」（Cocos 匯入 AutoAtlas 時
        # 常只寫 presetId），一樣不會生效，所以跟明確的 false 同等處理。
        if cs.get('useCompressTexture') is not True:
            missing = 'useCompressTexture' not in cs
            how = '缺少 useCompressTexture 欄位' if missing else '壓縮勾選是關的'
            if force_enable:
                cs['useCompressTexture'] = True
                dirty = True
                res['warns'].append(f'{how}，已依 --force-enable 補上 true')
            else:
                res['warns'].append(f'{how}，presetId 設了也不會生效'
                                    '（要開就加 --force-enable）')

    if dirty and apply:
        write_meta(meta_path, data, newline, trailing)
    res['dirty'] = dirty
    return res


# ---------------------------------------------------------------- 報告

def rel(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root)).replace('\\', '/')
    except ValueError:
        return str(p)


def report(results, root: Path, presets: dict, target_id: str, apply: bool):
    order = [KIND_ATLAS, KIND_SPINE, KIND_JPG, KIND_FNT, KIND_PACKED, KIND_OTHER]
    by_kind = {k: [] for k in order}
    for r in results:
        by_kind[r['kind']].append(r)

    print('=' * 72)
    print(f'目標 Preset: {presets.get(target_id, "(不在 builder.json)")}  [{target_id}]')
    print(f'模式: {"實際寫入 (--apply)" if apply else "乾跑 dry-run，不寫檔"}')
    print('=' * 72)

    n_add = n_fix = n_ok = n_type = n_nometa = 0

    for kind in order:
        rs = by_kind[kind]
        if not rs:
            continue
        # 「未分類」不處理，只列清單讓使用者知道有這些圖沒被涵蓋
        if kind == KIND_OTHER:
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（不屬於四種目標，也不在任何 AutoAtlas 範圍內；未做任何檢查與修改）')
            for r in sorted(rs, key=lambda x: str(x['path']))[:OTHER_LIST_LIMIT]:
                print(f'  {rel(r["path"], root)}')
            if len(rs) > OTHER_LIST_LIMIT:
                print(f'  ...另外還有 {len(rs) - OTHER_LIST_LIMIT} 個')
            continue

        # 「被Atlas合走」的散圖只需要看有問題的，正常的摺成一行
        if kind == KIND_PACKED:
            bad = [r for r in rs if r['actions']]
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（{len(rs) - len(bad)} 個 type 正常，不個別設壓縮）')
            if not bad:
                continue
            rs = bad
        else:
            print(f'\n【{kind}】{len(rs)} 個')
        for r in sorted(rs, key=lambda x: str(x['path'])):
            acts = r['actions']
            path = rel(r['path'], root)
            tags = []
            if ACT_NOMETA in acts:
                tags.append('沒有 .meta（Cocos 未 import）')
                n_nometa += 1
            if ACT_ADD in acts:
                tags.append('新增壓縮設定')
                n_add += 1
            if ACT_FIX in acts:
                tags.append('presetId 對應不到 → 已改為目標 preset')
                n_fix += 1
            if ACT_OK in acts:
                name = presets.get(r['preset'], '?')
                tags.append(f'壓縮設定正常 ({name})')
                n_ok += 1
            if ACT_TYPE in acts:
                tags.append(f'type 是 "{r["type"]}" 不是 sprite-frame')
                n_type += 1
            note = r.get('note') or ''
            line = f'  {path}'
            if tags:
                line += '\n      - ' + '\n      - '.join(tags)
            for w in r['warns']:
                line += f'\n      ! {w}'
            if note:
                line += f'\n      {note}'
            print(line)

    print('\n' + '=' * 72)
    print(f'新增壓縮設定 : {n_add}')
    print(f'修正 presetId: {n_fix}')
    print(f'原本就正常   : {n_ok}')
    print(f'type 非 sprite-frame: {n_type}')
    print(f'缺少 .meta   : {n_nometa}')
    changed = n_add + n_fix
    if not apply and changed:
        print(f'\n※ 這是乾跑。確認無誤後加 --apply 才會實際寫入 {changed} 個 meta。')
    print('=' * 72)


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description='設定/修正 Cocos 圖片壓縮設定')
    ap.add_argument('--path', nargs='+', help='要處理的路徑（資料夾或單檔），可多個')
    ap.add_argument('--preset-id', help='目標 preset id；不給則自動找 --preset-prefix 開頭的')
    ap.add_argument('--preset-prefix', default='rd4', help='自動挑 preset 的名稱前綴（預設 rd4）')
    ap.add_argument('--project-root', help='專案根目錄；不給則從 --path 往上找')
    ap.add_argument('--list-presets', action='store_true', help='只列出所有 preset 後結束')
    ap.add_argument('--apply', action='store_true', help='實際寫入 meta（預設只乾跑）')
    ap.add_argument('--fix-type', action='store_true', help='把 type 非 sprite-frame 的改掉')
    ap.add_argument('--force-enable', action='store_true',
                    help='把 useCompressTexture=false 強制改成 true')
    args = ap.parse_args()

    if args.project_root:
        root = Path(args.project_root).resolve()
    elif args.path:
        root = find_project_root(Path(args.path[0]).resolve())
    else:
        root = find_project_root(Path.cwd())

    presets = load_presets(root)

    if args.list_presets:
        print(f'專案: {root}')
        print(f'共 {len(presets)} 個 Compress Preset:')
        for pid, name in presets.items():
            print(f'  - {name}\n      id: {pid}')
        return 0

    if not args.path:
        ap.error('需要 --path（或用 --list-presets）')

    # 決定目標 preset
    if args.preset_id:
        target_id = args.preset_id
        if target_id not in presets:
            print(f'[警告] 指定的 preset id 不在 builder.json: {target_id}', file=sys.stderr)
    else:
        picked = pick_default_preset(presets, args.preset_prefix)
        if not picked:
            print(f'[錯誤] 找不到名稱以 "{args.preset_prefix}" 開頭的 preset。'
                  f'請用 --list-presets 查看後以 --preset-id 指定。', file=sys.stderr)
            return 1
        target_id = picked[0]

    paths = []
    for p in args.path:
        pp = Path(p).resolve()
        if not pp.exists():
            print(f'[錯誤] 路徑不存在: {p}', file=sys.stderr)
            return 1
        paths.append(pp)

    scope = AtlasScope()
    targets = scan(paths, scope)
    if not targets:
        print('掃描結果：目標路徑下沒有任何圖片。')
        return 0

    valid_ids = set(presets.keys())
    results = []
    for img, (kind, note) in targets.items():
        r = process(img, kind, valid_ids, target_id,
                    args.fix_type, args.force_enable, args.apply)
        r['note'] = note
        results.append(r)

    report(results, root, presets, target_id, args.apply)
    return 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
設定 / 修正 Cocos 專案圖片的壓縮設定 (compressSettings)。

有效 preset 來源：settings/v2/packages/builder.json 的 textureCompressConfig.userPreset
寫入位置：圖片的 .meta -> userData.compressSettings.{useCompressTexture, presetId}

處理四種目標：AutoAtlas(.pac) / Spine 圖 / jpg / fnt 用圖。
被 AutoAtlas 合走的散圖不個別設壓縮，只檢查 type 是否為 sprite-frame。

預設 dry-run，加 --apply 才寫檔。
"""

import argparse
import json
import re
import sys
from pathlib import Path

# Windows 主控台預設 cp950，中文會亂碼
for _s in (sys.stdout, sys.stderr):
    try:
        if (_s.encoding or '').lower().replace('-', '') != 'utf8':
            _s.reconfigure(encoding='utf-8')
    except (AttributeError, ValueError):
        pass

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.webp'}
JPG_EXTS = {'.jpg', '.jpeg'}

# 分類代號
KIND_ATLAS = 'AutoAtlas'
KIND_SPINE = 'Spine'
KIND_JPG = 'JPG'
KIND_FNT = 'Fnt'
KIND_PACKED = '被Atlas合走'
KIND_OTHER = '未分類'

OTHER_LIST_LIMIT = 10   # 「未分類」清單最多列幾筆

# 處理結果
ACT_ADD = 'ADD'            # 沒有 compressSettings -> 新增
ACT_FIX = 'FIX'            # presetId 對應不到 -> 改成目標 preset
ACT_OK = 'OK'              # presetId 有效 -> 不動
ACT_TYPE = 'TYPE'          # type 不是 sprite-frame
ACT_NOMETA = 'NOMETA'      # 找不到 .meta


# ---------------------------------------------------------------- preset

def find_project_root(start: Path) -> Path:
    """從 start 往上找含 settings/v2/packages/builder.json 的專案根。"""
    for d in [start, *start.parents]:
        if (d / 'settings' / 'v2' / 'packages' / 'builder.json').is_file():
            return d
    raise SystemExit(f'[錯誤] 從 {start} 往上找不到 settings/v2/packages/builder.json，'
                     f'請用 --project-root 指定專案根。')


def load_presets(root: Path) -> dict:
    """回傳 {presetId: name}。"""
    f = root / 'settings' / 'v2' / 'packages' / 'builder.json'
    data = json.loads(f.read_text(encoding='utf-8'))
    user = data.get('textureCompressConfig', {}).get('userPreset', {}) or {}
    return {pid: (info or {}).get('name', '(無名稱)') for pid, info in user.items()}


def pick_default_preset(presets: dict, prefix: str):
    """找 name 以 prefix 開頭的 preset（不分大小寫），回傳 (id, name) 或 None。"""
    low = prefix.lower()
    for pid, name in presets.items():
        if name.lower().startswith(low):
            return pid, name
    return None


# ---------------------------------------------------------------- meta 讀寫

def read_meta(meta_path: Path):
    """回傳 (data, newline, trailing)。保留原換行風格與結尾換行，寫回才不會整檔 diff。"""
    raw = meta_path.read_text(encoding='utf-8', newline='')
    newline = '\r\n' if '\r\n' in raw else '\n'
    trailing = raw.endswith(('\n', '\r'))
    return json.loads(raw), newline, trailing


def write_meta(meta_path: Path, data, newline: str, trailing: bool):
    text = json.dumps(data, indent=2, ensure_ascii=False)
    if trailing:
        text += '\n'
    if newline != '\n':
        text = text.replace('\n', newline)
    meta_path.write_text(text, encoding='utf-8', newline='')


# ---------------------------------------------------------------- 掃描 / 分類

def _spine_atlas_files(base: Path):
    """spine 的 atlas 檔可能是 .atlas，也可能是 .atlas.txt（Cocos 常見）。"""
    found = set(base.rglob('*.atlas'))
    found.update(base.rglob('*.atlas.txt'))
    return sorted(found)


def _atlas_stem(atlas_file: Path) -> str:
    """ExtraBet.atlas.txt -> ExtraBet；Spin.atlas -> Spin"""
    name = atlas_file.name
    for suf in ('.atlas.txt', '.atlas'):
        if name.lower().endswith(suf):
            return name[:-len(suf)]
    return atlas_file.stem


def parse_spine_atlas(atlas_file: Path):
    """從 .atlas 取出它引用的圖檔（可能多張）。解析不到才退回同名比對。"""
    out = []
    try:
        lines = atlas_file.read_text(encoding='utf-8', errors='ignore').splitlines()
    except OSError:
        return out
    for line in lines:
        s = line.strip()
        # 圖名行：不含 ':'（那是屬性行）、不縮排、副檔名是圖片
        if not s or ':' in s or line[:1] in (' ', '\t'):
            continue
        if Path(s).suffix.lower() in IMAGE_EXTS:
            p = atlas_file.parent / s
            if p.is_file():
                out.append(p.resolve())
    if not out:
        # 退回同名：Spin.atlas.txt -> Spin.png / Spin.jpg ...
        stem = _atlas_stem(atlas_file)
        for ext in IMAGE_EXTS:
            p = atlas_file.parent / (stem + ext)
            if p.is_file():
                out.append(p.resolve())
                break
    return out


# 同時涵蓋文字格式 (page id=0 file="x.png") 與 XML 格式 (<page id="0" file="x.png"/>)
FNT_FILE_RE = re.compile(r'file\s*=\s*(?:"([^"]+)"|([^\s/>]+))')


def parse_fnt(fnt_file: Path):
    """從 .fnt 的 page 取出圖檔（檔名常帶 _0 後綴，不能靠同名比對）。"""
    out = []
    try:
        text = fnt_file.read_text(encoding='utf-8', errors='ignore')
    except OSError:
        return out
    for m in FNT_FILE_RE.finditer(text):
        name = (m.group(1) or m.group(2) or '').strip()
        if Path(name).suffix.lower() not in IMAGE_EXTS:
            continue
        p = fnt_file.parent / name
        if p.is_file():
            rp = p.resolve()
            if rp not in out:
                out.append(rp)
    return out


class AtlasScope:
    """判斷某張圖是否落在 AutoAtlas 的覆蓋範圍（atlas 所在目錄與其所有子目錄）。

    往上找到 assets 根為止，所以即使使用者只指定深層子資料夾，
    上層的 .pac 也一樣算數。
    """

    def __init__(self):
        self._dir_cache = {}
        self._scope_cache = {}

    def _has_pac(self, d: Path) -> bool:
        if d not in self._dir_cache:
            try:
                self._dir_cache[d] = any(d.glob('*.pac'))
            except OSError:
                self._dir_cache[d] = False
        return self._dir_cache[d]

    def covering_atlas_dir(self, img: Path):
        """回傳覆蓋這張圖的 atlas 目錄，沒有則 None。"""
        d = img.parent
        if d in self._scope_cache:
            return self._scope_cache[d]
        chain, found = [], None
        cur = d
        while True:
            chain.append(cur)
            if cur in self._scope_cache and self._scope_cache[cur] is not None:
                found = self._scope_cache[cur]
                break
            if self._has_pac(cur):
                found = cur
                break
            if cur.name == 'assets' or cur.parent == cur:
                break
            cur = cur.parent
        for c in chain:
            self._scope_cache[c] = found
        return found


def scan_dir(base: Path, scope: AtlasScope):
    """掃一個資料夾，回傳 {resolved_path: [kind, note]}。"""
    targets = {}
    claimed = set()

    def claim(p: Path, kind: str):
        p = p.resolve()
        claimed.add(p)
        if p in targets:
            # 一張圖被多個 .atlas/.fnt 共用（多 skel 共用一張 png）—— 只記一次
            return
        atlas_dir = scope.covering_atlas_dir(p)
        note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                if atlas_dir is not None else '')
        targets[p] = [kind, note]

    # 1) AutoAtlas 本身
    for pac in sorted(base.rglob('*.pac')):
        targets.setdefault(pac.resolve(), [KIND_ATLAS, ''])

    # 2) Spine：解析 .atlas / .atlas.txt 取真正引用的圖
    for at in _spine_atlas_files(base):
        for img in parse_spine_atlas(at):
            claim(img, KIND_SPINE)

    # 3) Fnt：解析 page 的 file=
    for fnt in sorted(base.rglob('*.fnt')):
        for img in parse_fnt(fnt):
            claim(img, KIND_FNT)

    # 4) 其餘圖片
    for img in sorted(base.rglob('*')):
        if not img.is_file() or img.suffix.lower() not in IMAGE_EXTS:
            continue
        rp = img.resolve()
        if rp in claimed or rp in targets:
            continue
        atlas_dir = scope.covering_atlas_dir(rp)
        if img.suffix.lower() in JPG_EXTS:
            note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                    if atlas_dir is not None else '')
            targets[rp] = [KIND_JPG, note]
        elif atlas_dir is not None:
            targets[rp] = [KIND_PACKED, f'由 {atlas_dir.name} 合圖']
        else:
            targets[rp] = [KIND_OTHER, '不屬於四種目標，且不在任何 AutoAtlas 範圍內']

    return targets


def scan(paths, scope: AtlasScope):
    """掃描指定路徑（資料夾或單檔），回傳 {resolved_path: [kind, note]}。

    指定單檔時：仍掃它所在資料夾以判斷分類（是否 spine/fnt 用圖、是否被 atlas 合走），
    但結果只保留該檔案本身。
    """
    merged = {}
    for root in paths:
        if root.is_file():
            found = scan_dir(root.parent, scope)
            rp = root.resolve()
            if rp in found:
                merged.setdefault(rp, found[rp])
            elif root.suffix.lower() in IMAGE_EXTS or root.suffix.lower() == '.pac':
                merged.setdefault(rp, [KIND_ATLAS if root.suffix.lower() == '.pac'
                                       else KIND_OTHER, ''])
            else:
                print(f'[略過] 不是圖片或 .pac: {root}', file=sys.stderr)
        else:
            for k, v in scan_dir(root, scope).items():
                merged.setdefault(k, v)
    return merged


# ---------------------------------------------------------------- 處理單一目標

def process(img: Path, kind: str, valid_ids: set, target_id: str,
            fix_type: bool, force_enable: bool, apply: bool):
    """回傳 result dict。"""
    meta_path = Path(str(img) + '.meta')
    res = {
        'path': img, 'kind': kind, 'meta': meta_path,
        'actions': [], 'warns': [], 'type': None, 'preset': None, 'dirty': False,
    }
    if not meta_path.is_file():
        res['actions'].append(ACT_NOMETA)
        return res

    try:
        data, newline, trailing = read_meta(meta_path)
    except (json.JSONDecodeError, OSError) as e:
        res['actions'].append(ACT_NOMETA)
        res['warns'].append(f'meta 讀取失敗: {e}')
        return res

    ud = data.setdefault('userData', {})
    dirty = False

    # --- type 檢查 ---
    # .pac 是 auto-atlas importer 沒有 type 欄位；
    # 未分類的圖不屬於四種目標（可能是 TextMeshPro/shader 用圖，刻意設 texture），一律不碰。
    if kind not in (KIND_ATLAS, KIND_OTHER):
        t = ud.get('type')
        res['type'] = t
        if t != 'sprite-frame':
            res['actions'].append(ACT_TYPE)
            if fix_type:
                ud['type'] = 'sprite-frame'
                dirty = True

    # --- 被 atlas 合走的散圖 / 未分類：不碰壓縮設定 ---
    if kind in (KIND_PACKED, KIND_OTHER):
        if dirty and apply:
            write_meta(meta_path, data, newline, trailing)
        res['dirty'] = dirty
        return res

    # --- 壓縮設定 ---
    cs = ud.get('compressSettings')
    if not isinstance(cs, dict):
        ud['compressSettings'] = {'useCompressTexture': True, 'presetId': target_id}
        res['actions'].append(ACT_ADD)
        res['preset'] = target_id
        dirty = True
    else:
        pid = cs.get('presetId')
        res['preset'] = pid
        if pid not in valid_ids:
            cs['presetId'] = target_id
            res['actions'].append(ACT_FIX)
            res['preset'] = target_id
            dirty = True
        else:
            res['actions'].append(ACT_OK)

        # 沒有 useCompressTexture 這個 key 等同「勾選框沒勾」（Cocos 匯入 AutoAtlas 時
        # 常只寫 presetId），一樣不會生效，所以跟明確的 false 同等處理。
        if cs.get('useCompressTexture') is not True:
            missing = 'useCompressTexture' not in cs
            how = '缺少 useCompressTexture 欄位' if missing else '壓縮勾選是關的'
            if force_enable:
                cs['useCompressTexture'] = True
                dirty = True
                res['warns'].append(f'{how}，已依 --force-enable 補上 true')
            else:
                res['warns'].append(f'{how}，presetId 設了也不會生效'
                                    '（要開就加 --force-enable）')

    if dirty and apply:
        write_meta(meta_path, data, newline, trailing)
    res['dirty'] = dirty
    return res


# ---------------------------------------------------------------- 報告

def rel(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root)).replace('\\', '/')
    except ValueError:
        return str(p)


def report(results, root: Path, presets: dict, target_id: str, apply: bool):
    order = [KIND_ATLAS, KIND_SPINE, KIND_JPG, KIND_FNT, KIND_PACKED, KIND_OTHER]
    by_kind = {k: [] for k in order}
    for r in results:
        by_kind[r['kind']].append(r)

    print('=' * 72)
    print(f'目標 Preset: {presets.get(target_id, "(不在 builder.json)")}  [{target_id}]')
    print(f'模式: {"實際寫入 (--apply)" if apply else "乾跑 dry-run，不寫檔"}')
    print('=' * 72)

    n_add = n_fix = n_ok = n_type = n_nometa = 0

    for kind in order:
        rs = by_kind[kind]
        if not rs:
            continue
        # 「未分類」不處理，只列清單讓使用者知道有這些圖沒被涵蓋
        if kind == KIND_OTHER:
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（不屬於四種目標，也不在任何 AutoAtlas 範圍內；未做任何檢查與修改）')
            for r in sorted(rs, key=lambda x: str(x['path']))[:OTHER_LIST_LIMIT]:
                print(f'  {rel(r["path"], root)}')
            if len(rs) > OTHER_LIST_LIMIT:
                print(f'  ...另外還有 {len(rs) - OTHER_LIST_LIMIT} 個')
            continue

        # 「被Atlas合走」的散圖只需要看有問題的，正常的摺成一行
        if kind == KIND_PACKED:
            bad = [r for r in rs if r['actions']]
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（{len(rs) - len(bad)} 個 type 正常，不個別設壓縮）')
            if not bad:
                continue
            rs = bad
        else:
            print(f'\n【{kind}】{len(rs)} 個')
        for r in sorted(rs, key=lambda x: str(x['path'])):
            acts = r['actions']
            path = rel(r['path'], root)
            tags = []
            if ACT_NOMETA in acts:
                tags.append('沒有 .meta（Cocos 未 import）')
                n_nometa += 1
            if ACT_ADD in acts:
                tags.append('新增壓縮設定')
                n_add += 1
            if ACT_FIX in acts:
                tags.append('presetId 對應不到 → 已改為目標 preset')
                n_fix += 1
            if ACT_OK in acts:
                name = presets.get(r['preset'], '?')
                tags.append(f'壓縮設定正常 ({name})')
                n_ok += 1
            if ACT_TYPE in acts:
                tags.append(f'type 是 "{r["type"]}" 不是 sprite-frame')
                n_type += 1
            note = r.get('note') or ''
            line = f'  {path}'
            if tags:
                line += '\n      - ' + '\n      - '.join(tags)
            for w in r['warns']:
                line += f'\n      ! {w}'
            if note:
                line += f'\n      {note}'
            print(line)

    print('\n' + '=' * 72)
    print(f'新增壓縮設定 : {n_add}')
    print(f'修正 presetId: {n_fix}')
    print(f'原本就正常   : {n_ok}')
    print(f'type 非 sprite-frame: {n_type}')
    print(f'缺少 .meta   : {n_nometa}')
    changed = n_add + n_fix
    if not apply and changed:
        print(f'\n※ 這是乾跑。確認無誤後加 --apply 才會實際寫入 {changed} 個 meta。')
    print('=' * 72)


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description='設定/修正 Cocos 圖片壓縮設定')
    ap.add_argument('--path', nargs='+', help='要處理的路徑（資料夾或單檔），可多個')
    ap.add_argument('--preset-id', help='目標 preset id；不給則自動找 --preset-prefix 開頭的')
    ap.add_argument('--preset-prefix', default='rd4', help='自動挑 preset 的名稱前綴（預設 rd4）')
    ap.add_argument('--project-root', help='專案根目錄；不給則從 --path 往上找')
    ap.add_argument('--list-presets', action='store_true', help='只列出所有 preset 後結束')
    ap.add_argument('--apply', action='store_true', help='實際寫入 meta（預設只乾跑）')
    ap.add_argument('--fix-type', action='store_true', help='把 type 非 sprite-frame 的改掉')
    ap.add_argument('--force-enable', action='store_true',
                    help='把 useCompressTexture=false 強制改成 true')
    args = ap.parse_args()

    if args.project_root:
        root = Path(args.project_root).resolve()
    elif args.path:
        root = find_project_root(Path(args.path[0]).resolve())
    else:
        root = find_project_root(Path.cwd())

    presets = load_presets(root)

    if args.list_presets:
        print(f'專案: {root}')
        print(f'共 {len(presets)} 個 Compress Preset:')
        for pid, name in presets.items():
            print(f'  - {name}\n      id: {pid}')
        return 0

    if not args.path:
        ap.error('需要 --path（或用 --list-presets）')

    # 決定目標 preset
    if args.preset_id:
        target_id = args.preset_id
        if target_id not in presets:
            print(f'[警告] 指定的 preset id 不在 builder.json: {target_id}', file=sys.stderr)
    else:
        picked = pick_default_preset(presets, args.preset_prefix)
        if not picked:
            print(f'[錯誤] 找不到名稱以 "{args.preset_prefix}" 開頭的 preset。'
                  f'請用 --list-presets 查看後以 --preset-id 指定。', file=sys.stderr)
            return 1
        target_id = picked[0]

    paths = []
    for p in args.path:
        pp = Path(p).resolve()
        if not pp.exists():
            print(f'[錯誤] 路徑不存在: {p}', file=sys.stderr)
            return 1
        paths.append(pp)

    scope = AtlasScope()
    targets = scan(paths, scope)
    if not targets:
        print('掃描結果：目標路徑下沒有任何圖片。')
        return 0

    valid_ids = set(presets.keys())
    results = []
    for img, (kind, note) in targets.items():
        r = process(img, kind, valid_ids, target_id,
                    args.fix_type, args.force_enable, args.apply)
        r['note'] = note
        results.append(r)

    report(results, root, presets, target_id, args.apply)
    return 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
設定 / 修正 Cocos 專案圖片的壓縮設定 (compressSettings)。

有效 preset 來源：settings/v2/packages/builder.json 的 textureCompressConfig.userPreset
寫入位置：圖片的 .meta -> userData.compressSettings.{useCompressTexture, presetId}

處理四種目標：AutoAtlas(.pac) / Spine 圖 / jpg / fnt 用圖。
被 AutoAtlas 合走的散圖不個別設壓縮，只檢查 type 是否為 sprite-frame。

預設 dry-run，加 --apply 才寫檔。
"""

import argparse
import json
import re
import sys
from pathlib import Path

# Windows 主控台預設 cp950，中文會亂碼
for _s in (sys.stdout, sys.stderr):
    try:
        if (_s.encoding or '').lower().replace('-', '') != 'utf8':
            _s.reconfigure(encoding='utf-8')
    except (AttributeError, ValueError):
        pass

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.webp'}
JPG_EXTS = {'.jpg', '.jpeg'}

# 分類代號
KIND_ATLAS = 'AutoAtlas'
KIND_SPINE = 'Spine'
KIND_JPG = 'JPG'
KIND_FNT = 'Fnt'
KIND_PACKED = '被Atlas合走'
KIND_OTHER = '未分類'

OTHER_LIST_LIMIT = 10   # 「未分類」清單最多列幾筆

# 處理結果
ACT_ADD = 'ADD'            # 沒有 compressSettings -> 新增
ACT_FIX = 'FIX'            # presetId 對應不到 -> 改成目標 preset
ACT_OK = 'OK'              # presetId 有效 -> 不動
ACT_TYPE = 'TYPE'          # type 不是 sprite-frame
ACT_NOMETA = 'NOMETA'      # 找不到 .meta


# ---------------------------------------------------------------- preset

def find_project_root(start: Path) -> Path:
    """從 start 往上找含 settings/v2/packages/builder.json 的專案根。"""
    for d in [start, *start.parents]:
        if (d / 'settings' / 'v2' / 'packages' / 'builder.json').is_file():
            return d
    raise SystemExit(f'[錯誤] 從 {start} 往上找不到 settings/v2/packages/builder.json，'
                     f'請用 --project-root 指定專案根。')


def load_presets(root: Path) -> dict:
    """回傳 {presetId: name}。"""
    f = root / 'settings' / 'v2' / 'packages' / 'builder.json'
    data = json.loads(f.read_text(encoding='utf-8'))
    user = data.get('textureCompressConfig', {}).get('userPreset', {}) or {}
    return {pid: (info or {}).get('name', '(無名稱)') for pid, info in user.items()}


def pick_default_preset(presets: dict, prefix: str):
    """找 name 以 prefix 開頭的 preset（不分大小寫），回傳 (id, name) 或 None。"""
    low = prefix.lower()
    for pid, name in presets.items():
        if name.lower().startswith(low):
            return pid, name
    return None


# ---------------------------------------------------------------- meta 讀寫

def read_meta(meta_path: Path):
    """回傳 (data, newline, trailing)。保留原換行風格與結尾換行，寫回才不會整檔 diff。"""
    raw = meta_path.read_text(encoding='utf-8', newline='')
    newline = '\r\n' if '\r\n' in raw else '\n'
    trailing = raw.endswith(('\n', '\r'))
    return json.loads(raw), newline, trailing


def write_meta(meta_path: Path, data, newline: str, trailing: bool):
    text = json.dumps(data, indent=2, ensure_ascii=False)
    if trailing:
        text += '\n'
    if newline != '\n':
        text = text.replace('\n', newline)
    meta_path.write_text(text, encoding='utf-8', newline='')


# ---------------------------------------------------------------- 掃描 / 分類

def _spine_atlas_files(base: Path):
    """spine 的 atlas 檔可能是 .atlas，也可能是 .atlas.txt（Cocos 常見）。"""
    found = set(base.rglob('*.atlas'))
    found.update(base.rglob('*.atlas.txt'))
    return sorted(found)


def _atlas_stem(atlas_file: Path) -> str:
    """ExtraBet.atlas.txt -> ExtraBet；Spin.atlas -> Spin"""
    name = atlas_file.name
    for suf in ('.atlas.txt', '.atlas'):
        if name.lower().endswith(suf):
            return name[:-len(suf)]
    return atlas_file.stem


def parse_spine_atlas(atlas_file: Path):
    """從 .atlas 取出它引用的圖檔（可能多張）。解析不到才退回同名比對。"""
    out = []
    try:
        lines = atlas_file.read_text(encoding='utf-8', errors='ignore').splitlines()
    except OSError:
        return out
    for line in lines:
        s = line.strip()
        # 圖名行：不含 ':'（那是屬性行）、不縮排、副檔名是圖片
        if not s or ':' in s or line[:1] in (' ', '\t'):
            continue
        if Path(s).suffix.lower() in IMAGE_EXTS:
            p = atlas_file.parent / s
            if p.is_file():
                out.append(p.resolve())
    if not out:
        # 退回同名：Spin.atlas.txt -> Spin.png / Spin.jpg ...
        stem = _atlas_stem(atlas_file)
        for ext in IMAGE_EXTS:
            p = atlas_file.parent / (stem + ext)
            if p.is_file():
                out.append(p.resolve())
                break
    return out


# 同時涵蓋文字格式 (page id=0 file="x.png") 與 XML 格式 (<page id="0" file="x.png"/>)
FNT_FILE_RE = re.compile(r'file\s*=\s*(?:"([^"]+)"|([^\s/>]+))')


def parse_fnt(fnt_file: Path):
    """從 .fnt 的 page 取出圖檔（檔名常帶 _0 後綴，不能靠同名比對）。"""
    out = []
    try:
        text = fnt_file.read_text(encoding='utf-8', errors='ignore')
    except OSError:
        return out
    for m in FNT_FILE_RE.finditer(text):
        name = (m.group(1) or m.group(2) or '').strip()
        if Path(name).suffix.lower() not in IMAGE_EXTS:
            continue
        p = fnt_file.parent / name
        if p.is_file():
            rp = p.resolve()
            if rp not in out:
                out.append(rp)
    return out


class AtlasScope:
    """判斷某張圖是否落在 AutoAtlas 的覆蓋範圍（atlas 所在目錄與其所有子目錄）。

    往上找到 assets 根為止，所以即使使用者只指定深層子資料夾，
    上層的 .pac 也一樣算數。
    """

    def __init__(self):
        self._dir_cache = {}
        self._scope_cache = {}

    def _has_pac(self, d: Path) -> bool:
        if d not in self._dir_cache:
            try:
                self._dir_cache[d] = any(d.glob('*.pac'))
            except OSError:
                self._dir_cache[d] = False
        return self._dir_cache[d]

    def covering_atlas_dir(self, img: Path):
        """回傳覆蓋這張圖的 atlas 目錄，沒有則 None。"""
        d = img.parent
        if d in self._scope_cache:
            return self._scope_cache[d]
        chain, found = [], None
        cur = d
        while True:
            chain.append(cur)
            if cur in self._scope_cache and self._scope_cache[cur] is not None:
                found = self._scope_cache[cur]
                break
            if self._has_pac(cur):
                found = cur
                break
            if cur.name == 'assets' or cur.parent == cur:
                break
            cur = cur.parent
        for c in chain:
            self._scope_cache[c] = found
        return found


def scan_dir(base: Path, scope: AtlasScope):
    """掃一個資料夾，回傳 {resolved_path: [kind, note]}。"""
    targets = {}
    claimed = set()

    def claim(p: Path, kind: str):
        p = p.resolve()
        claimed.add(p)
        if p in targets:
            # 一張圖被多個 .atlas/.fnt 共用（多 skel 共用一張 png）—— 只記一次
            return
        atlas_dir = scope.covering_atlas_dir(p)
        note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                if atlas_dir is not None else '')
        targets[p] = [kind, note]

    # 1) AutoAtlas 本身
    for pac in sorted(base.rglob('*.pac')):
        targets.setdefault(pac.resolve(), [KIND_ATLAS, ''])

    # 2) Spine：解析 .atlas / .atlas.txt 取真正引用的圖
    for at in _spine_atlas_files(base):
        for img in parse_spine_atlas(at):
            claim(img, KIND_SPINE)

    # 3) Fnt：解析 page 的 file=
    for fnt in sorted(base.rglob('*.fnt')):
        for img in parse_fnt(fnt):
            claim(img, KIND_FNT)

    # 4) 其餘圖片
    for img in sorted(base.rglob('*')):
        if not img.is_file() or img.suffix.lower() not in IMAGE_EXTS:
            continue
        rp = img.resolve()
        if rp in claimed or rp in targets:
            continue
        atlas_dir = scope.covering_atlas_dir(rp)
        if img.suffix.lower() in JPG_EXTS:
            note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                    if atlas_dir is not None else '')
            targets[rp] = [KIND_JPG, note]
        elif atlas_dir is not None:
            targets[rp] = [KIND_PACKED, f'由 {atlas_dir.name} 合圖']
        else:
            targets[rp] = [KIND_OTHER, '不屬於四種目標，且不在任何 AutoAtlas 範圍內']

    return targets


def scan(paths, scope: AtlasScope):
    """掃描指定路徑（資料夾或單檔），回傳 {resolved_path: [kind, note]}。

    指定單檔時：仍掃它所在資料夾以判斷分類（是否 spine/fnt 用圖、是否被 atlas 合走），
    但結果只保留該檔案本身。
    """
    merged = {}
    for root in paths:
        if root.is_file():
            found = scan_dir(root.parent, scope)
            rp = root.resolve()
            if rp in found:
                merged.setdefault(rp, found[rp])
            elif root.suffix.lower() in IMAGE_EXTS or root.suffix.lower() == '.pac':
                merged.setdefault(rp, [KIND_ATLAS if root.suffix.lower() == '.pac'
                                       else KIND_OTHER, ''])
            else:
                print(f'[略過] 不是圖片或 .pac: {root}', file=sys.stderr)
        else:
            for k, v in scan_dir(root, scope).items():
                merged.setdefault(k, v)
    return merged


# ---------------------------------------------------------------- 處理單一目標

def process(img: Path, kind: str, valid_ids: set, target_id: str,
            fix_type: bool, force_enable: bool, apply: bool):
    """回傳 result dict。"""
    meta_path = Path(str(img) + '.meta')
    res = {
        'path': img, 'kind': kind, 'meta': meta_path,
        'actions': [], 'warns': [], 'type': None, 'preset': None, 'dirty': False,
    }
    if not meta_path.is_file():
        res['actions'].append(ACT_NOMETA)
        return res

    try:
        data, newline, trailing = read_meta(meta_path)
    except (json.JSONDecodeError, OSError) as e:
        res['actions'].append(ACT_NOMETA)
        res['warns'].append(f'meta 讀取失敗: {e}')
        return res

    ud = data.setdefault('userData', {})
    dirty = False

    # --- type 檢查 ---
    # .pac 是 auto-atlas importer 沒有 type 欄位；
    # 未分類的圖不屬於四種目標（可能是 TextMeshPro/shader 用圖，刻意設 texture），一律不碰。
    if kind not in (KIND_ATLAS, KIND_OTHER):
        t = ud.get('type')
        res['type'] = t
        if t != 'sprite-frame':
            res['actions'].append(ACT_TYPE)
            if fix_type:
                ud['type'] = 'sprite-frame'
                dirty = True

    # --- 被 atlas 合走的散圖 / 未分類：不碰壓縮設定 ---
    if kind in (KIND_PACKED, KIND_OTHER):
        if dirty and apply:
            write_meta(meta_path, data, newline, trailing)
        res['dirty'] = dirty
        return res

    # --- 壓縮設定 ---
    cs = ud.get('compressSettings')
    if not isinstance(cs, dict):
        ud['compressSettings'] = {'useCompressTexture': True, 'presetId': target_id}
        res['actions'].append(ACT_ADD)
        res['preset'] = target_id
        dirty = True
    else:
        pid = cs.get('presetId')
        res['preset'] = pid
        if pid not in valid_ids:
            cs['presetId'] = target_id
            res['actions'].append(ACT_FIX)
            res['preset'] = target_id
            dirty = True
        else:
            res['actions'].append(ACT_OK)

        # 沒有 useCompressTexture 這個 key 等同「勾選框沒勾」（Cocos 匯入 AutoAtlas 時
        # 常只寫 presetId），一樣不會生效，所以跟明確的 false 同等處理。
        if cs.get('useCompressTexture') is not True:
            missing = 'useCompressTexture' not in cs
            how = '缺少 useCompressTexture 欄位' if missing else '壓縮勾選是關的'
            if force_enable:
                cs['useCompressTexture'] = True
                dirty = True
                res['warns'].append(f'{how}，已依 --force-enable 補上 true')
            else:
                res['warns'].append(f'{how}，presetId 設了也不會生效'
                                    '（要開就加 --force-enable）')

    if dirty and apply:
        write_meta(meta_path, data, newline, trailing)
    res['dirty'] = dirty
    return res


# ---------------------------------------------------------------- 報告

def rel(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root)).replace('\\', '/')
    except ValueError:
        return str(p)


def report(results, root: Path, presets: dict, target_id: str, apply: bool):
    order = [KIND_ATLAS, KIND_SPINE, KIND_JPG, KIND_FNT, KIND_PACKED, KIND_OTHER]
    by_kind = {k: [] for k in order}
    for r in results:
        by_kind[r['kind']].append(r)

    print('=' * 72)
    print(f'目標 Preset: {presets.get(target_id, "(不在 builder.json)")}  [{target_id}]')
    print(f'模式: {"實際寫入 (--apply)" if apply else "乾跑 dry-run，不寫檔"}')
    print('=' * 72)

    n_add = n_fix = n_ok = n_type = n_nometa = 0

    for kind in order:
        rs = by_kind[kind]
        if not rs:
            continue
        # 「未分類」不處理，只列清單讓使用者知道有這些圖沒被涵蓋
        if kind == KIND_OTHER:
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（不屬於四種目標，也不在任何 AutoAtlas 範圍內；未做任何檢查與修改）')
            for r in sorted(rs, key=lambda x: str(x['path']))[:OTHER_LIST_LIMIT]:
                print(f'  {rel(r["path"], root)}')
            if len(rs) > OTHER_LIST_LIMIT:
                print(f'  ...另外還有 {len(rs) - OTHER_LIST_LIMIT} 個')
            continue

        # 「被Atlas合走」的散圖只需要看有問題的，正常的摺成一行
        if kind == KIND_PACKED:
            bad = [r for r in rs if r['actions']]
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（{len(rs) - len(bad)} 個 type 正常，不個別設壓縮）')
            if not bad:
                continue
            rs = bad
        else:
            print(f'\n【{kind}】{len(rs)} 個')
        for r in sorted(rs, key=lambda x: str(x['path'])):
            acts = r['actions']
            path = rel(r['path'], root)
            tags = []
            if ACT_NOMETA in acts:
                tags.append('沒有 .meta（Cocos 未 import）')
                n_nometa += 1
            if ACT_ADD in acts:
                tags.append('新增壓縮設定')
                n_add += 1
            if ACT_FIX in acts:
                tags.append('presetId 對應不到 → 已改為目標 preset')
                n_fix += 1
            if ACT_OK in acts:
                name = presets.get(r['preset'], '?')
                tags.append(f'壓縮設定正常 ({name})')
                n_ok += 1
            if ACT_TYPE in acts:
                tags.append(f'type 是 "{r["type"]}" 不是 sprite-frame')
                n_type += 1
            note = r.get('note') or ''
            line = f'  {path}'
            if tags:
                line += '\n      - ' + '\n      - '.join(tags)
            for w in r['warns']:
                line += f'\n      ! {w}'
            if note:
                line += f'\n      {note}'
            print(line)

    print('\n' + '=' * 72)
    print(f'新增壓縮設定 : {n_add}')
    print(f'修正 presetId: {n_fix}')
    print(f'原本就正常   : {n_ok}')
    print(f'type 非 sprite-frame: {n_type}')
    print(f'缺少 .meta   : {n_nometa}')
    changed = n_add + n_fix
    if not apply and changed:
        print(f'\n※ 這是乾跑。確認無誤後加 --apply 才會實際寫入 {changed} 個 meta。')
    print('=' * 72)


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description='設定/修正 Cocos 圖片壓縮設定')
    ap.add_argument('--path', nargs='+', help='要處理的路徑（資料夾或單檔），可多個')
    ap.add_argument('--preset-id', help='目標 preset id；不給則自動找 --preset-prefix 開頭的')
    ap.add_argument('--preset-prefix', default='rd4', help='自動挑 preset 的名稱前綴（預設 rd4）')
    ap.add_argument('--project-root', help='專案根目錄；不給則從 --path 往上找')
    ap.add_argument('--list-presets', action='store_true', help='只列出所有 preset 後結束')
    ap.add_argument('--apply', action='store_true', help='實際寫入 meta（預設只乾跑）')
    ap.add_argument('--fix-type', action='store_true', help='把 type 非 sprite-frame 的改掉')
    ap.add_argument('--force-enable', action='store_true',
                    help='把 useCompressTexture=false 強制改成 true')
    args = ap.parse_args()

    if args.project_root:
        root = Path(args.project_root).resolve()
    elif args.path:
        root = find_project_root(Path(args.path[0]).resolve())
    else:
        root = find_project_root(Path.cwd())

    presets = load_presets(root)

    if args.list_presets:
        print(f'專案: {root}')
        print(f'共 {len(presets)} 個 Compress Preset:')
        for pid, name in presets.items():
            print(f'  - {name}\n      id: {pid}')
        return 0

    if not args.path:
        ap.error('需要 --path（或用 --list-presets）')

    # 決定目標 preset
    if args.preset_id:
        target_id = args.preset_id
        if target_id not in presets:
            print(f'[警告] 指定的 preset id 不在 builder.json: {target_id}', file=sys.stderr)
    else:
        picked = pick_default_preset(presets, args.preset_prefix)
        if not picked:
            print(f'[錯誤] 找不到名稱以 "{args.preset_prefix}" 開頭的 preset。'
                  f'請用 --list-presets 查看後以 --preset-id 指定。', file=sys.stderr)
            return 1
        target_id = picked[0]

    paths = []
    for p in args.path:
        pp = Path(p).resolve()
        if not pp.exists():
            print(f'[錯誤] 路徑不存在: {p}', file=sys.stderr)
            return 1
        paths.append(pp)

    scope = AtlasScope()
    targets = scan(paths, scope)
    if not targets:
        print('掃描結果：目標路徑下沒有任何圖片。')
        return 0

    valid_ids = set(presets.keys())
    results = []
    for img, (kind, note) in targets.items():
        r = process(img, kind, valid_ids, target_id,
                    args.fix_type, args.force_enable, args.apply)
        r['note'] = note
        results.append(r)

    report(results, root, presets, target_id, args.apply)
    return 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
設定 / 修正 Cocos 專案圖片的壓縮設定 (compressSettings)。

有效 preset 來源：settings/v2/packages/builder.json 的 textureCompressConfig.userPreset
寫入位置：圖片的 .meta -> userData.compressSettings.{useCompressTexture, presetId}

處理四種目標：AutoAtlas(.pac) / Spine 圖 / jpg / fnt 用圖。
被 AutoAtlas 合走的散圖不個別設壓縮，只檢查 type 是否為 sprite-frame。

預設 dry-run，加 --apply 才寫檔。
"""

import argparse
import json
import re
import sys
from pathlib import Path

# Windows 主控台預設 cp950，中文會亂碼
for _s in (sys.stdout, sys.stderr):
    try:
        if (_s.encoding or '').lower().replace('-', '') != 'utf8':
            _s.reconfigure(encoding='utf-8')
    except (AttributeError, ValueError):
        pass

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.webp'}
JPG_EXTS = {'.jpg', '.jpeg'}

# 分類代號
KIND_ATLAS = 'AutoAtlas'
KIND_SPINE = 'Spine'
KIND_JPG = 'JPG'
KIND_FNT = 'Fnt'
KIND_PACKED = '被Atlas合走'
KIND_OTHER = '未分類'

OTHER_LIST_LIMIT = 10   # 「未分類」清單最多列幾筆

# 處理結果
ACT_ADD = 'ADD'            # 沒有 compressSettings -> 新增
ACT_FIX = 'FIX'            # presetId 對應不到 -> 改成目標 preset
ACT_OK = 'OK'              # presetId 有效 -> 不動
ACT_TYPE = 'TYPE'          # type 不是 sprite-frame
ACT_NOMETA = 'NOMETA'      # 找不到 .meta


# ---------------------------------------------------------------- preset

def find_project_root(start: Path) -> Path:
    """從 start 往上找含 settings/v2/packages/builder.json 的專案根。"""
    for d in [start, *start.parents]:
        if (d / 'settings' / 'v2' / 'packages' / 'builder.json').is_file():
            return d
    raise SystemExit(f'[錯誤] 從 {start} 往上找不到 settings/v2/packages/builder.json，'
                     f'請用 --project-root 指定專案根。')


def load_presets(root: Path) -> dict:
    """回傳 {presetId: name}。"""
    f = root / 'settings' / 'v2' / 'packages' / 'builder.json'
    data = json.loads(f.read_text(encoding='utf-8'))
    user = data.get('textureCompressConfig', {}).get('userPreset', {}) or {}
    return {pid: (info or {}).get('name', '(無名稱)') for pid, info in user.items()}


def pick_default_preset(presets: dict, prefix: str):
    """找 name 以 prefix 開頭的 preset（不分大小寫），回傳 (id, name) 或 None。"""
    low = prefix.lower()
    for pid, name in presets.items():
        if name.lower().startswith(low):
            return pid, name
    return None


# ---------------------------------------------------------------- meta 讀寫

def read_meta(meta_path: Path):
    """回傳 (data, newline, trailing)。保留原換行風格與結尾換行，寫回才不會整檔 diff。"""
    raw = meta_path.read_text(encoding='utf-8', newline='')
    newline = '\r\n' if '\r\n' in raw else '\n'
    trailing = raw.endswith(('\n', '\r'))
    return json.loads(raw), newline, trailing


def write_meta(meta_path: Path, data, newline: str, trailing: bool):
    text = json.dumps(data, indent=2, ensure_ascii=False)
    if trailing:
        text += '\n'
    if newline != '\n':
        text = text.replace('\n', newline)
    meta_path.write_text(text, encoding='utf-8', newline='')


# ---------------------------------------------------------------- 掃描 / 分類

def _spine_atlas_files(base: Path):
    """spine 的 atlas 檔可能是 .atlas，也可能是 .atlas.txt（Cocos 常見）。"""
    found = set(base.rglob('*.atlas'))
    found.update(base.rglob('*.atlas.txt'))
    return sorted(found)


def _atlas_stem(atlas_file: Path) -> str:
    """ExtraBet.atlas.txt -> ExtraBet；Spin.atlas -> Spin"""
    name = atlas_file.name
    for suf in ('.atlas.txt', '.atlas'):
        if name.lower().endswith(suf):
            return name[:-len(suf)]
    return atlas_file.stem


def parse_spine_atlas(atlas_file: Path):
    """從 .atlas 取出它引用的圖檔（可能多張）。解析不到才退回同名比對。"""
    out = []
    try:
        lines = atlas_file.read_text(encoding='utf-8', errors='ignore').splitlines()
    except OSError:
        return out
    for line in lines:
        s = line.strip()
        # 圖名行：不含 ':'（那是屬性行）、不縮排、副檔名是圖片
        if not s or ':' in s or line[:1] in (' ', '\t'):
            continue
        if Path(s).suffix.lower() in IMAGE_EXTS:
            p = atlas_file.parent / s
            if p.is_file():
                out.append(p.resolve())
    if not out:
        # 退回同名：Spin.atlas.txt -> Spin.png / Spin.jpg ...
        stem = _atlas_stem(atlas_file)
        for ext in IMAGE_EXTS:
            p = atlas_file.parent / (stem + ext)
            if p.is_file():
                out.append(p.resolve())
                break
    return out


# 同時涵蓋文字格式 (page id=0 file="x.png") 與 XML 格式 (<page id="0" file="x.png"/>)
FNT_FILE_RE = re.compile(r'file\s*=\s*(?:"([^"]+)"|([^\s/>]+))')


def parse_fnt(fnt_file: Path):
    """從 .fnt 的 page 取出圖檔（檔名常帶 _0 後綴，不能靠同名比對）。"""
    out = []
    try:
        text = fnt_file.read_text(encoding='utf-8', errors='ignore')
    except OSError:
        return out
    for m in FNT_FILE_RE.finditer(text):
        name = (m.group(1) or m.group(2) or '').strip()
        if Path(name).suffix.lower() not in IMAGE_EXTS:
            continue
        p = fnt_file.parent / name
        if p.is_file():
            rp = p.resolve()
            if rp not in out:
                out.append(rp)
    return out


class AtlasScope:
    """判斷某張圖是否落在 AutoAtlas 的覆蓋範圍（atlas 所在目錄與其所有子目錄）。

    往上找到 assets 根為止，所以即使使用者只指定深層子資料夾，
    上層的 .pac 也一樣算數。
    """

    def __init__(self):
        self._dir_cache = {}
        self._scope_cache = {}

    def _has_pac(self, d: Path) -> bool:
        if d not in self._dir_cache:
            try:
                self._dir_cache[d] = any(d.glob('*.pac'))
            except OSError:
                self._dir_cache[d] = False
        return self._dir_cache[d]

    def covering_atlas_dir(self, img: Path):
        """回傳覆蓋這張圖的 atlas 目錄，沒有則 None。"""
        d = img.parent
        if d in self._scope_cache:
            return self._scope_cache[d]
        chain, found = [], None
        cur = d
        while True:
            chain.append(cur)
            if cur in self._scope_cache and self._scope_cache[cur] is not None:
                found = self._scope_cache[cur]
                break
            if self._has_pac(cur):
                found = cur
                break
            if cur.name == 'assets' or cur.parent == cur:
                break
            cur = cur.parent
        for c in chain:
            self._scope_cache[c] = found
        return found


def scan_dir(base: Path, scope: AtlasScope):
    """掃一個資料夾，回傳 {resolved_path: [kind, note]}。"""
    targets = {}
    claimed = set()

    def claim(p: Path, kind: str):
        p = p.resolve()
        claimed.add(p)
        if p in targets:
            # 一張圖被多個 .atlas/.fnt 共用（多 skel 共用一張 png）—— 只記一次
            return
        atlas_dir = scope.covering_atlas_dir(p)
        note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                if atlas_dir is not None else '')
        targets[p] = [kind, note]

    # 1) AutoAtlas 本身
    for pac in sorted(base.rglob('*.pac')):
        targets.setdefault(pac.resolve(), [KIND_ATLAS, ''])

    # 2) Spine：解析 .atlas / .atlas.txt 取真正引用的圖
    for at in _spine_atlas_files(base):
        for img in parse_spine_atlas(at):
            claim(img, KIND_SPINE)

    # 3) Fnt：解析 page 的 file=
    for fnt in sorted(base.rglob('*.fnt')):
        for img in parse_fnt(fnt):
            claim(img, KIND_FNT)

    # 4) 其餘圖片
    for img in sorted(base.rglob('*')):
        if not img.is_file() or img.suffix.lower() not in IMAGE_EXTS:
            continue
        rp = img.resolve()
        if rp in claimed or rp in targets:
            continue
        atlas_dir = scope.covering_atlas_dir(rp)
        if img.suffix.lower() in JPG_EXTS:
            note = (f'⚠ 位於 AutoAtlas 範圍內({atlas_dir.name})，仍個別設定'
                    if atlas_dir is not None else '')
            targets[rp] = [KIND_JPG, note]
        elif atlas_dir is not None:
            targets[rp] = [KIND_PACKED, f'由 {atlas_dir.name} 合圖']
        else:
            targets[rp] = [KIND_OTHER, '不屬於四種目標，且不在任何 AutoAtlas 範圍內']

    return targets


def scan(paths, scope: AtlasScope):
    """掃描指定路徑（資料夾或單檔），回傳 {resolved_path: [kind, note]}。

    指定單檔時：仍掃它所在資料夾以判斷分類（是否 spine/fnt 用圖、是否被 atlas 合走），
    但結果只保留該檔案本身。
    """
    merged = {}
    for root in paths:
        if root.is_file():
            found = scan_dir(root.parent, scope)
            rp = root.resolve()
            if rp in found:
                merged.setdefault(rp, found[rp])
            elif root.suffix.lower() in IMAGE_EXTS or root.suffix.lower() == '.pac':
                merged.setdefault(rp, [KIND_ATLAS if root.suffix.lower() == '.pac'
                                       else KIND_OTHER, ''])
            else:
                print(f'[略過] 不是圖片或 .pac: {root}', file=sys.stderr)
        else:
            for k, v in scan_dir(root, scope).items():
                merged.setdefault(k, v)
    return merged


# ---------------------------------------------------------------- 處理單一目標

def process(img: Path, kind: str, valid_ids: set, target_id: str,
            fix_type: bool, force_enable: bool, apply: bool):
    """回傳 result dict。"""
    meta_path = Path(str(img) + '.meta')
    res = {
        'path': img, 'kind': kind, 'meta': meta_path,
        'actions': [], 'warns': [], 'type': None, 'preset': None, 'dirty': False,
    }
    if not meta_path.is_file():
        res['actions'].append(ACT_NOMETA)
        return res

    try:
        data, newline, trailing = read_meta(meta_path)
    except (json.JSONDecodeError, OSError) as e:
        res['actions'].append(ACT_NOMETA)
        res['warns'].append(f'meta 讀取失敗: {e}')
        return res

    ud = data.setdefault('userData', {})
    dirty = False

    # --- type 檢查 ---
    # .pac 是 auto-atlas importer 沒有 type 欄位；
    # 未分類的圖不屬於四種目標（可能是 TextMeshPro/shader 用圖，刻意設 texture），一律不碰。
    if kind not in (KIND_ATLAS, KIND_OTHER):
        t = ud.get('type')
        res['type'] = t
        if t != 'sprite-frame':
            res['actions'].append(ACT_TYPE)
            if fix_type:
                ud['type'] = 'sprite-frame'
                dirty = True

    # --- 被 atlas 合走的散圖 / 未分類：不碰壓縮設定 ---
    if kind in (KIND_PACKED, KIND_OTHER):
        if dirty and apply:
            write_meta(meta_path, data, newline, trailing)
        res['dirty'] = dirty
        return res

    # --- 壓縮設定 ---
    cs = ud.get('compressSettings')
    if not isinstance(cs, dict):
        ud['compressSettings'] = {'useCompressTexture': True, 'presetId': target_id}
        res['actions'].append(ACT_ADD)
        res['preset'] = target_id
        dirty = True
    else:
        pid = cs.get('presetId')
        res['preset'] = pid
        if pid not in valid_ids:
            cs['presetId'] = target_id
            res['actions'].append(ACT_FIX)
            res['preset'] = target_id
            dirty = True
        else:
            res['actions'].append(ACT_OK)

        # 沒有 useCompressTexture 這個 key 等同「勾選框沒勾」（Cocos 匯入 AutoAtlas 時
        # 常只寫 presetId），一樣不會生效，所以跟明確的 false 同等處理。
        if cs.get('useCompressTexture') is not True:
            missing = 'useCompressTexture' not in cs
            how = '缺少 useCompressTexture 欄位' if missing else '壓縮勾選是關的'
            if force_enable:
                cs['useCompressTexture'] = True
                dirty = True
                res['warns'].append(f'{how}，已依 --force-enable 補上 true')
            else:
                res['warns'].append(f'{how}，presetId 設了也不會生效'
                                    '（要開就加 --force-enable）')

    if dirty and apply:
        write_meta(meta_path, data, newline, trailing)
    res['dirty'] = dirty
    return res


# ---------------------------------------------------------------- 報告

def rel(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root)).replace('\\', '/')
    except ValueError:
        return str(p)


def report(results, root: Path, presets: dict, target_id: str, apply: bool):
    order = [KIND_ATLAS, KIND_SPINE, KIND_JPG, KIND_FNT, KIND_PACKED, KIND_OTHER]
    by_kind = {k: [] for k in order}
    for r in results:
        by_kind[r['kind']].append(r)

    print('=' * 72)
    print(f'目標 Preset: {presets.get(target_id, "(不在 builder.json)")}  [{target_id}]')
    print(f'模式: {"實際寫入 (--apply)" if apply else "乾跑 dry-run，不寫檔"}')
    print('=' * 72)

    n_add = n_fix = n_ok = n_type = n_nometa = 0

    for kind in order:
        rs = by_kind[kind]
        if not rs:
            continue
        # 「未分類」不處理，只列清單讓使用者知道有這些圖沒被涵蓋
        if kind == KIND_OTHER:
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（不屬於四種目標，也不在任何 AutoAtlas 範圍內；未做任何檢查與修改）')
            for r in sorted(rs, key=lambda x: str(x['path']))[:OTHER_LIST_LIMIT]:
                print(f'  {rel(r["path"], root)}')
            if len(rs) > OTHER_LIST_LIMIT:
                print(f'  ...另外還有 {len(rs) - OTHER_LIST_LIMIT} 個')
            continue

        # 「被Atlas合走」的散圖只需要看有問題的，正常的摺成一行
        if kind == KIND_PACKED:
            bad = [r for r in rs if r['actions']]
            print(f'\n【{kind}】{len(rs)} 個'
                  f'（{len(rs) - len(bad)} 個 type 正常，不個別設壓縮）')
            if not bad:
                continue
            rs = bad
        else:
            print(f'\n【{kind}】{len(rs)} 個')
        for r in sorted(rs, key=lambda x: str(x['path'])):
            acts = r['actions']
            path = rel(r['path'], root)
            tags = []
            if ACT_NOMETA in acts:
                tags.append('沒有 .meta（Cocos 未 import）')
                n_nometa += 1
            if ACT_ADD in acts:
                tags.append('新增壓縮設定')
                n_add += 1
            if ACT_FIX in acts:
                tags.append('presetId 對應不到 → 已改為目標 preset')
                n_fix += 1
            if ACT_OK in acts:
                name = presets.get(r['preset'], '?')
                tags.append(f'壓縮設定正常 ({name})')
                n_ok += 1
            if ACT_TYPE in acts:
                tags.append(f'type 是 "{r["type"]}" 不是 sprite-frame')
                n_type += 1
            note = r.get('note') or ''
            line = f'  {path}'
            if tags:
                line += '\n      - ' + '\n      - '.join(tags)
            for w in r['warns']:
                line += f'\n      ! {w}'
            if note:
                line += f'\n      {note}'
            print(line)

    print('\n' + '=' * 72)
    print(f'新增壓縮設定 : {n_add}')
    print(f'修正 presetId: {n_fix}')
    print(f'原本就正常   : {n_ok}')
    print(f'type 非 sprite-frame: {n_type}')
    print(f'缺少 .meta   : {n_nometa}')
    changed = n_add + n_fix
    if not apply and changed:
        print(f'\n※ 這是乾跑。確認無誤後加 --apply 才會實際寫入 {changed} 個 meta。')
    print('=' * 72)


# ---------------------------------------------------------------- main

def main():
    ap = argparse.ArgumentParser(description='設定/修正 Cocos 圖片壓縮設定')
    ap.add_argument('--path', nargs='+', help='要處理的路徑（資料夾或單檔），可多個')
    ap.add_argument('--preset-id', help='目標 preset id；不給則自動找 --preset-prefix 開頭的')
    ap.add_argument('--preset-prefix', default='rd4', help='自動挑 preset 的名稱前綴（預設 rd4）')
    ap.add_argument('--project-root', help='專案根目錄；不給則從 --path 往上找')
    ap.add_argument('--list-presets', action='store_true', help='只列出所有 preset 後結束')
    ap.add_argument('--apply', action='store_true', help='實際寫入 meta（預設只乾跑）')
    ap.add_argument('--fix-type', action='store_true', help='把 type 非 sprite-frame 的改掉')
    ap.add_argument('--force-enable', action='store_true',
                    help='把 useCompressTexture=false 強制改成 true')
    args = ap.parse_args()

    if args.project_root:
        root = Path(args.project_root).resolve()
    elif args.path:
        root = find_project_root(Path(args.path[0]).resolve())
    else:
        root = find_project_root(Path.cwd())

    presets = load_presets(root)

    if args.list_presets:
        print(f'專案: {root}')
        print(f'共 {len(presets)} 個 Compress Preset:')
        for pid, name in presets.items():
            print(f'  - {name}\n      id: {pid}')
        return 0

    if not args.path:
        ap.error('需要 --path（或用 --list-presets）')

    # 決定目標 preset
    if args.preset_id:
        target_id = args.preset_id
        if target_id not in presets:
            print(f'[警告] 指定的 preset id 不在 builder.json: {target_id}', file=sys.stderr)
    else:
        picked = pick_default_preset(presets, args.preset_prefix)
        if not picked:
            print(f'[錯誤] 找不到名稱以 "{args.preset_prefix}" 開頭的 preset。'
                  f'請用 --list-presets 查看後以 --preset-id 指定。', file=sys.stderr)
            return 1
        target_id = picked[0]

    paths = []
    for p in args.path:
        pp = Path(p).resolve()
        if not pp.exists():
            print(f'[錯誤] 路徑不存在: {p}', file=sys.stderr)
            return 1
        paths.append(pp)

    scope = AtlasScope()
    targets = scan(paths, scope)
    if not targets:
        print('掃描結果：目標路徑下沒有任何圖片。')
        return 0

    valid_ids = set(presets.keys())
    results = []
    for img, (kind, note) in targets.items():
        r = process(img, kind, valid_ids, target_id,
                    args.fix_type, args.force_enable, args.apply)
        r['note'] = note
        results.append(r)

    report(results, root, presets, target_id, args.apply)
    return 0


if __name__ == '__main__':
    sys.exit(main())

