let A = args
if (typeof A === 'string') { const t = A.trim(); if (t.startsWith('{')) { try { A = JSON.parse(t) } catch (e) { /* 純股名字串，保持原樣 */ } } }
const stock = (typeof A === 'string') ? A : (A && A.stock)
