const STOCKS = { '力成':'6239','力積電':'6770','士電':'1503','仁寶':'2324','元太':'8069','光寶科':'2301','至上':'8112','鈊象':'3293','台企銀':'2834','台揚':'2314','友達':'2409','群聯':'8299','德律':'3030','漢翔':'2634','時碩工業':'4566','台積電':'2330','亞光':'3019','華新科':'2492','盟立':'2464' }
const TPEX = ['元太','鈊象','群聯']
let code = STOCKS[stock] || (preGround && preGround['代碼']) || '?'
const market = TPEX.includes(stock) ? '上櫃(.TWO)' : '上市(.TW)'

const ROOT = 'D:/AI_Data/股市分析'
const cachePath = `${ROOT}/data/_analysis_cache/${stock}_ground.json`

// ── 階段 0：地面數據（若未預先提供則自動蒐集） ──
// 地面數據是本報告所有數字的唯一權威來源（CLAUDE.md：長線診斷之技術與短期籌碼數字一律引用此快取）。
// 因此「解析失敗／技術面不可用／缺資料基準日」一律視為致命錯誤而 throw：
// 寧可讓父工作流把本檔記為失敗，也絕不容許在無確定性數字下由 LLM 杜撰整份報告，
// 更不容許檔名靜默退化為 _latest 而脫離日期序列。
const stripFence = (s) => String(s == null ? '' : s).trim()
  .replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim()

let ground = preGround
let groundSource = ''
if (ground) {
  groundSource = '呼叫端預先提供(preGround)'
  if (typeof ground === 'string') {
    try { ground = JSON.parse(stripFence(ground)) } catch (e) {
      throw new Error(`個股長線診斷：${stock} 呼叫端傳入的 ground 字串無法解析為 JSON（${e && e.message ? e.message : e}），中止。`)
    }
  }
} else {
  phase('地面數據')
  groundSource = `collect_stock_data.py → ${cachePath}`
  const COLLECT_CMD = `PYTHONIOENCODING=utf-8 python "${ROOT}/skills/collect_stock_data.py" "${stock}" --quiet`
  let lastErr = null
