  for (let attempt = 1; attempt <= 2 && !ground; attempt++) {
    const prompt = attempt === 1
      ? `你只做一件事：用 Bash 執行\n  ${COLLECT_CMD}\n然後用 Read 讀取檔案 ${cachePath}，把其「完整 JSON 內容原樣回傳」——不要加任何說明、不要用程式碼區塊圍欄、不要省略、不得截斷或摘要。你的回覆第一個字元必須是 { ，最後一個字元必須是 } ，中間 = 該檔 JSON 全文。`
      : `【重試】上一次回傳的內容無法被 JSON.parse 解析（錯誤：${String(lastErr)}；長度 ${lastRaw.length}）。請重新用 Read 完整讀取 ${cachePath}（若該檔不存在，先用 Bash 執行 ${COLLECT_CMD} 再讀），把該檔 JSON 全文一字不差原樣輸出：不要說明、不要圍欄、不要省略中間內容、不得截斷。你的回覆第一個字元必須是 { ，最後一個字元必須是 } 。`
    const raw = await agent(prompt, { label: `地面數據:${stock}${attempt > 1 ? '(重試)' : ''}`, phase: '地面數據' })
    lastRaw = stripFence(raw)
    try {
      ground = JSON.parse(lastRaw)
    } catch (e) {
      lastErr = e && e.message ? e.message : e
      ground = null
      log(`地面數據解析失敗(第${attempt}次)：${stock} ← ${cachePath}；錯誤=${String(lastErr)}；回傳長度=${lastRaw.length}`)
    }
  }
  if (!ground) {
    throw new Error(`個股長線診斷：${stock}(${code}) 地面數據 JSON 解析失敗（已重試 2 次）。來源=${cachePath}；解析錯誤=${String(lastErr)}；回傳長度=${lastRaw.length}；開頭120字=${lastRaw.slice(0, 120)}。地面數據為報告唯一權威數字來源，缺此一律中止、不產出報告。`)
  }
}

// ── 地面數據健檢（任一項不成立即中止；不做任何靜默降級） ──
if (typeof ground !== 'object' || ground === null || Array.isArray(ground)) {
  throw new Error(`個股長線診斷：${stock} 地面數據不是 JSON 物件（來源=${groundSource}），中止。`)
}
if (ground['error']) {
  throw new Error(`個股長線診斷：${stock} 地面數據回報錯誤：${String(ground['error'])}（來源=${groundSource}），中止。`)
}
const groundTech = ground['技術面']
if (!groundTech || typeof groundTech !== 'object' || Array.isArray(groundTech)) {
  throw new Error(`個股長線診斷：${stock} 地面數據缺少「技術面」區塊（來源=${groundSource}），無確定性技術數字可用，中止以免杜撰。`)
}
if (groundTech['error']) {
  throw new Error(`個股長線診斷：${stock} 地面數據「技術面」不可用：${String(groundTech['error'])}（來源=${groundSource}；多為 K線 CSV 缺漏或不可讀）。均線位階／乖離／量能皆無從計算，中止以免杜撰。`)
}
const baseDate = String(groundTech['資料基準日'] == null ? '' : groundTech['資料基準日']).trim()
if (!/^\d{4}\/\d{2}\/\d{2}$/.test(baseDate)) {
  throw new Error(`個股長線診斷：${stock} 地面數據「技術面.資料基準日」缺漏或格式非 YYYY/MM/DD（取得值=「${baseDate}」，來源=${groundSource}）。無資料基準日則報告無法日期化（不再退化為 _latest），中止。`)
}

if ((!code || code === '?') && ground['代碼']) code = ground['代碼']  // bootstrap 後回填代碼
const groundStr = JSON.stringify(ground)
const dateStr = baseDate.replace(/\//g, '')
const dateFmt = baseDate

// 產出路徑
