const results = await parallel(names.map((name) => () => {
  const code = STOCKS[name] || '?'
  const market = TPEX.includes(name) ? '上櫃(.TWO)' : '上市(.TW)'
  const cachePath = `${ROOT}/data/_analysis_cache/${name}_ground.json`
  const dateNote = argDate
    ? `檔名日期後綴用 ${argDate}（YYYYMMDD）。`
    : '檔名日期後綴取地面數據「技術面.資料基準日」去除斜線（YYYY/MM/DD→YYYYMMDD）。'
  return agent(
    `你是台股短線擇時分析師。為「${name}(${code})，${market}」產出一份【短線深度報告】(觀點：短線擇時 3~15 個交易日)，比照黃金範本(力成深度報告)的結構與嚴謹度、但**聚焦擇時、精簡**。\n${TONE}\n${RULES}\n\n步驟：\n1. 用 Read 讀地面數據 ${cachePath}（內含最新單棒、型態、量能倍數、MA5~MA240 與乖離、站上均線、週線Weinstein階段、Mansfield RS、技術指標MACD/KD/RSI/布林/DMI-ADX與多空共振、外資/投信25日估計成本線與近5日流向、大盤位階(加權/櫃買週線Stage+52週位階)、籌碼20/60日累積(本地)、市場面官方(PE/PB/殖利率/融資餘額與融資使用率%＋高低/券資比%＋高低/融券使用率/月營收YoY/千張大戶持股比%/三率負債比)、**估值區塊(EPS_TTM/正常化EPS/本益比_現價/正常化本益比/股價淨值比/便宜貴/理由)**；數字全部引用此快取）。若讀取失敗或無此檔，回傳 ok=false 並在 one_liner 說明。\n2. 快速參酌準則：「${ROOT}/steering/技術指標與多空共振.md」(ADX≥25順勢/ADX<20盤整以超買超賣看)、「${ROOT}/steering/量價關係教學.md」(量價十法則、位階決定意義、帶量驗證、天量/地量/背離)、「${ROOT}/steering/偵測法人偷偷放空.md」(融券≠法人放空；法人走借券/期貨；勿以低融券斷定無放空)、「${ROOT}/steering/個股診斷規格.md」、「${ROOT}/steering/防詐騙_避開假止跌型態.md」。\n3. 撰寫繁體中文 Markdown（僅文件本體），結構固定：\n   標題「# ${name}(${code}) 短線深度報告」\n   一行抬頭：資料基準日｜市場${market}｜股性分類(依該股)｜觀點：短線擇時(3~15日)｜基本面錨定另見長線深度診斷報告\n   > 一句話定調(擇時)\n   ## 一、摘要(短線狀態)：資料充足度、收盤與漲跌/52週位階、多空共振方向強度與趨勢環境(ADX)、**訊號可靠度揭露一句(必填)：用 Read 讀 ${ROOT}/data/_analysis_cache/signal_reliability.json，引用其「可靠度」「整體結論」與偏多/偏空兩組的「相對基準邊際%」，明講本報告所用的多空共振方向在目前可測樣本下的實際表現；若判定為反指標，必須寫明「不得單獨作為進出依據」並提醒最可能為區間效應而非永久失效；若該檔不存在則寫「訊號可靠度未評分(needs_manual)」。此為誠實揭露，嚴禁略過或淡化**、**風險等級一句(必填)：依鐵則機械判定並標出對應顏色標記——🔴危險(負債比>60%／法人明確放空三合一「借券占股本高＋外資20/60日雙淨賣＋RS落後大盤」同時成立／週線Stage 4下跌期，任一即危險)、🔵很好(週線Stage 2＋RS領先大盤＋負債比正常，且無任何危險旗標)、🟢安全(無危險旗標但未達很好)、⚪未能判定(關鍵欄位缺漏就標這個，不得硬套等級；**銀行業(如台企銀)一律標⚪並寫明「>60%負債比鐵則不適用、銀行天生高槓桿，應改看資本適足率/逾放比，官方一般業端點不含銀行→償債風險未檢核」，不得因為「沒有>60%」就逕標🟢安全**)。須寫出等級與「依據」。注意：此為財務與籌碼風險標示，不是買賣建議、也不等於短線方向；且與台股紅漲綠跌的價格顏色是兩套獨立配色，勿混用敘述**、短期籌碼一句、**估值一句(EPS(TTM)/本益比(現價PE，循環股另標正常化PE)/PB＋便宜貴，取自地面數據估值區塊；若標未建置則寫「估值待建(needs_manual)」)**、核心操作分類\n   ## 二、K線型態(防假突破/防詐)：最新單棒與組合型態、上下影/實體、抄底三條件是否成立、防詐三合一是否成立、近8日走勢（量價深度判讀見第三節）\n   ## 三、量價關係分析(依 steering/量價關係教學.md)：量能倍數(最新/前5日均量)與量比分級(<0.8縮/0.8~1.5正常/1.5~2.5溫和/2.5~5明顯/>5爆量)、**依量價十法則判定當前量價×位階**(量增價漲健康/量縮價漲背離/高檔天量墓碑出貨/縮量反彈未帶量不承認/無量下跌洗盤或賣壓竭盡/破底縮量地量)、量價背離(頂/底)、帶量驗證(突破須>均量1.5倍且收穩)、爆量兩面性(低檔承接vs高檔長上影出貨)、量價面小結(偏多/偏空/中性、僅擇時)\n   ## 四、均線位階與乖離：MA5~MA240表(數值/乖離%/站上)、多空排列、§6.4乖離管理(高乖離=降低加碼力度非賣訊)、週線Stage與Mansfield RS的擇時提醒(絕對強vs相對強弱)\n   ## 五、短期籌碼三視角：視角A單日/近5日(雜訊層、非訊號)、視角B 25日估計成本線(位階提示非扳機、乖離與貼身防守價)、視角C 20/60日累積(引「籌碼面.20_60日累積」§5.2撤離門檻)＋**融資使用率%＋高低(散戶槓桿溫度)、融券使用率%與券資比%＋高低(空方壓力/軋空)、千張大戶持股比%**(引「市場面(官方)」，須明講融資與融券各已用多少%、屬高或低；**融券主為散戶；法人/外資放空看「借券賣出占股本%＋高低、借券vs融券倍數」(本地已抓、市場面(官方))——勿以低融券斷定無法人放空；借券占股本高＋外資現貨賣超＋RS落後＝法人明確放空/撤離**；**借券方向性已可判讀(本地自建日序列)：須明講「借券20日/60日變化%＋趨勢(攀升法人空單加碼／回補／持平)」與「借券連續增加天數／連續減少天數」——水位高低是靜態、方向與連續天數才是動態，兩者要分開講；例如占股本高但20日回補＝空單正在退場、占股本中等但連續多日攀升＝空方正在建倉。若「借券序列天數」<21 或欄位缺，才寫序列累積中(needs_manual)，不得再籠統宣稱「借券趨勢無法判定」。期貨淨空單仍為 needs_manual**)＋外資/投信持股比率月季/董監質押(仍needs_manual、降權)\n   ## 六、近端支撐壓力+進出時機+止損：壓力/支撐價位(引均線與型態價)、短線劇本(偏多延續/區間震盪/轉弱各觸發)、止損綁均線結構(非單日K、非個人成本、非25日成本線)\n   ## 風險提示(含資料信心)\n   ## 📚 本次引用來源(強制；規範見 steering/資料取得與分析作業規範.md §5.2)：三行——(1)**知識庫(steering/)**：列出你這次真的讀過的準則檔並**具體到章節/法則編號**(例：量價關係教學 法則#3；偵測法人偷偷放空 借券三合一；技術指標與多空共振 ADX門檻)；(2)**技能工具與資料檔**：列出實際引用的腳本與快取檔並**附資料基準日**(例：collect_stock_data.py → <股名>_ground.json(基準日)、法人成本線_YYYYMMDD.csv、market_latest.json、signal_reliability.json)；(3)**未參考**：該查而未查者與理由(例：隔日開盤預測.md——本報告為3~15日擇時，不適用)，此行不得省略。**只列真的讀過的檔案，嚴禁為了看起來嚴謹而虛列**。\n   結尾：警語「投資有風險，分析僅供參考。」與署名「Claude Code (股市分析 Agent)」、標資料基準日。\n4. ${dateNote} 用 Bash 直接產 HTML(不落地.md)：\n   PYTHONIOENCODING=utf-8 python "${ROOT}/skills/report_html.py" --stdin --out "${ROOT}/data/${name}/${name}_${code}_短線深度報告_<YYYYMMDD>.html" <<'MDEOF'\n   (精修後完整 Markdown 全文)\n   MDEOF\n   然後用 ls 確認該 HTML 存在。\n5. 依 schema 回傳：htmlPath(完整路徑)、date(資料基準日)、close、verdict、strength、signal、one_liner(**鐵則§1.1：一句話內不得出現近5日/單日法人張數，也不得以其當多空結論的並列理由；要提籌碼就引20/60日累積趨勢**)、table_row(整合報告用一列；欄位以全形直線｜分隔：股名(代碼)｜收盤與位階｜型態量價｜均線位階｜短期籌碼｜進出時機+止損)、**field_tone(必填：型態量價/均線位階/短期籌碼/進出止損/估值 各給一個 🔵🟢🟡🔴⚪ 標記，供整合報告逐欄上色。須與你在報告內文對該面向的結論一致——內文寫利空就不能在這裡填🟢)**。`,
    { label: `短線深度:${name}`, phase: '短線深度', schema: ROW_SCHEMA },
  )
}))

// 以「索引」對齊 names 判定成敗：agent 回 null、或 ok=false、或無 htmlPath 一律算失敗，且**具名記錄**、不靜默丟棄
const okFlags = results.map((r) => !!(r && r.ok !== false && r.htmlPath))
const okRows = results.filter((r, i) => okFlags[i])
const missing = names.filter((n, i) => !okFlags[i])
const signals = okRows.filter((r) => r.signal)

// ── 鐵則§1.1 確定性守門：一句話禁以近5日法人買賣超作多空結論依據 ──
// 命中條件＝同時出現「近5日」＋「法人主體」＋「買賣超字樣」，且未併列 20/60 日趨勢或雜訊/非訊號免責語。
// 依稽核建議不採 hard fail（會誤殺已併列20/60日的合規句），改為：一句話自動加註免責、卡片欄僅標記，全部具名 log。
const N5_WIN = /近\s*[5５]\s*日|近五日/
const N5_INST = /外資|投信|法人/
const N5_FLOW = /淨買|淨賣|買超|賣超|買賣超|張|回補|撤離|流入|流出|大買|大賣|加碼|減碼/
const N5_OK = /20\s*日|60\s*日|20\/60|雜訊|非訊號|僅作方向記錄/
const n5Bad = (s) => { const t = String(s || ''); return N5_WIN.test(t) && N5_INST.test(t) && N5_FLOW.test(t) && !N5_OK.test(t) }
const N5_NOTE = '（鐵則§1.1註：近5日法人買賣超屬雜訊層、非訊號，方向以20/60日累積趨勢為準）'
const n5FixedOL = []
const n5FlagRow = []
for (const r of okRows) {
  if (n5Bad(r.one_liner)) { r.one_liner = String(r.one_liner || '') + N5_NOTE; n5FixedOL.push(r.stock) }
  if (n5Bad(r.table_row)) n5FlagRow.push(r.stock)
}
if (n5FixedOL.length) log(`⚠ 鐵則§1.1守門：${n5FixedOL.length} 檔一句話引用近5日法人買賣超且未併列20/60日趨勢，已自動加註雜訊層免責：${n5FixedOL.join('、')}`)
if (n5FlagRow.length) log(`⚠ 鐵則§1.1守門：${n5FlagRow.length} 檔卡片籌碼欄同況（僅標記、未改寫，避免破壞全形｜欄位切分）：${n5FlagRow.join('、')}`)

log(`短線深度完成 ${okRows.length}/${names.length} 檔、訊號 ${signals.length} 檔`)
if (missing.length) {
  log(`⚠ 短線深度未產出 ${missing.length}/${names.length} 檔：${missing.join('、')}`)
  for (let i = 0; i < names.length; i++) {
    if (okFlags[i]) continue
    const r = results[i]
    log(`  ↳ ${names[i]}：${r ? `ok=${r.ok} htmlPath=${r.htmlPath || '(無)'} 說明=${String(r.one_liner || '').slice(0, 120)}` : '子代理無回傳(null)'}`)
  }
}
if (!okRows.length) throw new Error(`每日短線深度：${names.length} 檔全數未產出短線深度報告，中止整合階段（缺：${missing.join('、')}）`)

// ── 回收階段：StructuredOutput 失敗但 HTML 其實已產出的個股 ──
// 實測 2026/08/24 群聯、08/25 鈊象皆為此況：子代理完成分析並寫出 40KB 報告，只有最後的結構化回傳
// 重試 5 次失敗，結果被當成缺檔、整合報告靜默少一列。報告內容既然存在，就從 HTML 反萃取整合列，
// 不要浪費一份已完成的分析、也不要讓總覽頁少一檔。
const recoverable = []
for (let i = 0; i < names.length; i++) {
  if (okFlags[i]) continue
  const nm = names[i]
  const cd = STOCKS[nm] || '?'
  const dstr = argDate || ((okRows.find((r) => r.date) || {}).date || '').replace(/\//g, '')
  if (/^\d{8}$/.test(dstr)) recoverable.push({ name: nm, code: cd, path: `${ROOT}/data/${nm}/${nm}_${cd}_短線深度報告_${dstr}.html` })
}
if (recoverable.length) {
  log(`↻ 嘗試從已產出的 HTML 回收 ${recoverable.length} 檔：${recoverable.map((x) => x.name).join('、')}`)
  const RECOVER_SCHEMA = {
    type: 'object', additionalProperties: false,
    properties: {
      stock: { type: 'string' }, code: { type: 'string' },
      found: { type: 'boolean', description: 'HTML 是否存在且內容完整（六節俱全）' },
      date: { type: 'string' }, verdict: { type: 'string' }, signal: { type: 'boolean' },
      one_liner: { type: 'string' }, table_row: { type: 'string' },
      field_tone: {
        type: 'object', additionalProperties: false,
        description: '從報告內文轉錄的逐欄好壞標記（🔵🟢🟡🔴⚪），缺則留空字串',
        properties: {
          型態量價: { type: 'string' }, 均線位階: { type: 'string' },
          短期籌碼: { type: 'string' }, 進出止損: { type: 'string' }, 估值: { type: 'string' },
        },
        required: ['型態量價', '均線位階', '短期籌碼', '進出止損'],
      },
    },
    required: ['stock', 'code', 'found'],
  }
  const rec = await parallel(recoverable.map((x) => () => agent(
    `【回收任務】「${x.name}(${x.code})」的短線深度報告 HTML 已產出，但結構化回傳失敗。請**只做轉錄、不要新增任何分析**：\n1. 用 Bash 確認 ${x.path} 存在；不存在則回傳 found=false。\n2. 讀該 HTML，確認六節俱全（摘要／K線型態／量價關係／均線位階／短期籌碼／支撐壓力進出止損）與結尾警語。缺節則 found=false。\n3. 從報告**自身內容**轉錄出：date(資料基準日)、verdict(短線分類：偏多/區間偏多/中性震盪/偏空/轉弱)、signal(是否有明確短線訊號)、one_liner(取報告的「一句話定調」)、table_row。\n   table_row 為整合報告用一列，欄位以全形直線｜分隔且**恰為 6 欄**：股名(代碼)｜收盤與位階｜型態量價｜均線位階｜短期籌碼｜進出時機+止損。\n   **所有數字一律取自該報告，嚴禁自行計算或臆測**；報告沒寫的就不要寫。\n${RULES}\n回傳 found=true 與上述欄位。`,
    { label: `回收:${x.name}`, phase: '短線深度', schema: RECOVER_SCHEMA },
  )))
  for (const r of rec.filter(Boolean)) {
    if (!r.found || !r.table_row) continue
    const i = names.indexOf(r.stock)
    okRows.push({ stock: r.stock, code: r.code, ok: true, htmlPath: `${ROOT}/data/${r.stock}/${r.stock}_${r.code}_短線深度報告_${r.date ? r.date.replace(/\//g, '') : ''}.html`, date: r.date, verdict: r.verdict, signal: !!r.signal, one_liner: r.one_liner, table_row: r.table_row, field_tone: r.field_tone || {}, _recovered: true })
    if (i >= 0) okFlags[i] = true
    const j = missing.indexOf(r.stock)
    if (j >= 0) missing.splice(j, 1)
    log(`  ✓ 已回收 ${r.stock}（由 HTML 轉錄整合列）`)
  }
  // 回收後依 STOCKS 原順序重排，避免回收列被排到最後
  okRows.sort((a, b) => names.indexOf(a.stock) - names.indexOf(b.stock))
  if (signals.length !== okRows.filter((r) => r.signal).length) {
    signals.length = 0
    signals.push(...okRows.filter((r) => r.signal))
  }
}

const dateStr = argDate || ((okRows.find((r) => r.date) || {}).date || '').replace(/\//g, '')
if (!dateStr) throw new Error('每日短線深度：取不到資料基準日（未傳 dateStr 且無任何子代理回報 date），中止產出，避免整合報告被靜默寫成 短線整合報告_latest.html')
// dateStr 會被插入 Bash 指令與兩個檔案路徑；子代理回報的 date 屬不可信輸入，須嚴格驗格式，
// 否則畸形值可造成指令截斷或寫到非預期路徑。
if (!/^\d{8}$/.test(dateStr)) throw new Error(`每日短線深度：資料基準日格式不合法（取得「${dateStr}」，應為 YYYYMMDD 八位數字），中止產出以免寫入非預期路徑`)
const dateFmt = (okRows.find((r) => r.date) || {}).date || dateStr

// ── 階段 2：整合報告（確定性組 rows JSON → build_integrated_report.py 產卡片式美化 HTML；不走 markdown 表格避免全形｜解析失敗） ──
phase('整合')
const integOut = `${ROOT}/短線整合報告_${dateStr}.html`
const rowsPath = `${ROOT}/data/_analysis_cache/短線整合_rows_${dateStr}.json`

// ── 注入防護：verdict 白名單正規化 ──
// verdict 由子代理自由回傳，會經 tally → baseLine → toneLine → 整合階段 Bash 指令 `--mood "${toneLine}"`。
// 若回傳含雙引號/反引號/$ 之類字元，該指令字串會被截斷或誤執行；故先收斂到固定取值集合。
const VERDICTS = ['偏多', '區間偏多', '中性震盪', '偏空', '轉弱']
// 對映採「主判斷字樣出現位置最前者勝」：中文定調把主結論寫在前，附註（如「中性震盪（結構偏空）」）寫在後，
// 若用固定順序比對會把中性檔誤歸偏空。歷史實例：「中性震盪（結構偏空）」→中性震盪、「區間偏空」→偏空。
const V_PATTERNS = [
  ['區間偏多', /區間.{0,2}偏多/],
  ['中性震盪', /中性|震盪|盤整/],
  ['轉弱', /轉弱/],
  ['偏空', /偏空|偏弱/],
  ['偏多', /偏多|偏強/],
]
const normVerdict = (v) => {
  const t = String(v == null ? '' : v).replace(/\s/g, '')
  if (!t) return '其他'
  if (VERDICTS.includes(t)) return t
  let best = '其他'
  let bestAt = Infinity
  for (const [name, re] of V_PATTERNS) {
    const m = t.match(re)
    if (m && m.index < bestAt) { best = name; bestAt = m.index }
  }
  return best
}
const verdictBad = []
for (const r of okRows) {
  const norm = normVerdict(r.verdict)
  if (String(r.verdict || '').trim() !== norm) verdictBad.push(`${r.stock}:${String(r.verdict || '(空)').slice(0, 20)}→${norm}`)
  r.verdict = norm
}
if (verdictBad.length) log(`⚠ verdict 白名單正規化 ${verdictBad.length} 檔：${verdictBad.join('、')}`)

// ── 注入防護：組進 Bash 指令的字串一律去除 shell 特殊字元 ──
// toneLine 中的股名（n5FixedOL/n5FlagRow 取自子代理回傳的 r.stock）同樣非受信來源，故整條 toneLine 統一消毒。
const shellSafe = (s) => String(s == null ? '' : s)
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/["`$\\]/g, '')        // 雙引號會提前收尾；反引號/$ 在雙引號內仍會被展開；反斜線會吃掉下一字元
  .replace(/[;&|<>()]/g, ' ')     // 指令分隔與重導向（報告正文用全形（）｜，不受影響）
  .replace(/ {2,}/g, ' ')
  .trim()

const tally = {}
for (const r of okRows) { const v = r.verdict || '其他'; tally[v] = (tally[v] || 0) + 1 }
// 少列＝降級：把「實際幾檔／應有幾檔／缺哪幾檔」寫進 mood 橫幅（render 會渲染在儀表板正下方），
// 讓 3/19 檔與 19/19 檔的報告一眼可辨，而不是把殘缺樣本當成全持股市場寬度呈現。
const degradeLine = missing.length
  ? `⚠ 資料降級警告：本報告僅含 ${okRows.length}/${names.length} 檔，缺 ${missing.join('、')}；下方儀表板之收黑/收紅/平盤/平均漲跌/短線訊號股數僅就已抵達的 ${okRows.length} 檔統計，不等於全持股市場寬度，請勿據此判斷大盤寬度。`
  : ''
const ruleLine = (n5FixedOL.length || n5FlagRow.length)
  ? `鐵則§1.1守門紀錄：一句話引用近5日法人買賣超而未併列20/60日趨勢者 ${n5FixedOL.length} 檔（${n5FixedOL.join('、') || '無'}）已自動加註雜訊層免責；卡片籌碼欄同況 ${n5FlagRow.length} 檔（${n5FlagRow.join('、') || '無'}）僅標記未改寫。近5日/單日法人數字一律不得作為多空結論依據，方向請以20/60日累積趨勢為準。`
  : ''
const baseLine = `今日短線分類分佈：${Object.entries(tally).map(([k, v]) => `${k} ${v} 檔`).join('、')}。有明確短線訊號 ${signals.length} 檔（分類由各檔多空共振方向歸納；短線僅擇時、非長線加減碼依據）。`
const toneLine = shellSafe([degradeLine, ruleLine, baseLine].filter(Boolean).join(' '))

const rowsJson = JSON.stringify(okRows.map((r) => ({
  stock: r.stock, code: r.code, table_row: r.table_row || '',
  one_liner: r.one_liner || '', signal: !!r.signal, verdict: r.verdict || '',
  field_tone: r.field_tone || {},
})))

const MIN_HTML_BYTES = 10000  // 正常整合報告約 50KB；低於此視為殘檔/產出失敗
const INTEG_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    ok: { type: 'boolean', description: 'build_integrated_report.py 是否「實測」成功：退出碼 0 且 HTML 確實產出且大小合理。任一未實測或不成立一律 false，嚴禁為交差填 true' },
    htmlPath: { type: 'string' },
    exitCode: { type: 'number', description: 'build_integrated_report.py 的實際退出碼（由 echo EXIT=$? 取得，非臆測）' },
    fileExists: { type: 'boolean', description: 'ls 實測輸出 HTML 是否存在；未實測填 false' },
    fileSize: { type: 'number', description: 'ls -l 實測到的位元組數，須為實際輸出、嚴禁臆測；取不到填 0' },
    note: { type: 'string', description: '失敗原因或 stderr 摘要（成功可留空）' },
  },
  required: ['ok', 'htmlPath', 'fileExists', 'fileSize'],
}
let integPath = null
const integ = await agent(
  `你只做三步、不要加任何分析、不要改動任何內容：\n1. 用 Write 工具把下面這段 JSON「一字不改、原樣」寫入檔案：${rowsPath}\n   JSON 內容：\n${rowsJson}\n\n2. 用 Bash 執行（產出卡片式美化整合報告 HTML），並記下實際退出碼：\n   PYTHONIOENCODING=utf-8 python "${ROOT}/skills/build_integrated_report.py" --rows "${rowsPath}" --date ${dateStr} --out "${integOut}" --mood "${toneLine}"; echo EXIT=$?\n\n3. 用 Bash 執行 ls -l "${integOut}" 取得該檔「實際位元組數」。\n\n依 schema 回傳：htmlPath=${integOut}、exitCode(步驟2實際退出碼)、fileExists(步驟3實測)、fileSize(步驟3實測位元組數，嚴禁臆測)、ok=(退出碼為0 且 檔案存在 且 位元組數>${MIN_HTML_BYTES})。三條件任一不成立即回 ok=false 並在 note 寫明實際錯誤訊息(含 stderr 尾段)。**嚴禁在未實際執行 ls 的情況下回報 fileExists/fileSize 或 ok=true。**`,
  { label: '短線整合報告(美化)', phase: '整合', schema: INTEG_SCHEMA },
)

// 不再只憑 agent 照抄回來的 htmlPath 就宣告成功：ok 欄位必須為真，且檔案存在、大小過門檻
let integStatus = 'OK'
if (!integ) integStatus = '整合代理無回傳(null)'
else if (integ.ok !== true) integStatus = `整合代理回報 ok=false（exitCode=${integ.exitCode === undefined ? '未回報' : integ.exitCode}；note=${integ.note || '無'}）`
else if (integ.fileExists !== true) integStatus = '整合代理回報 ok=true 但 fileExists 非 true（未實測到輸出檔，不予採信）'
else if (!(Number(integ.fileSize) > MIN_HTML_BYTES)) integStatus = `輸出檔僅 ${integ.fileSize} bytes，未達 ${MIN_HTML_BYTES} bytes 門檻，判為殘檔/產出失敗`
if (integStatus === 'OK') {
  const claimed = String(integ.htmlPath || '').replace(/\\/g, '/')
  if (claimed.toLowerCase() !== integOut.toLowerCase()) log(`⚠ 整合代理回報路徑「${claimed}」與工作流指定輸出「${integOut}」不符，以指定輸出為準`)
  integPath = integOut
} else {
  log(`⚠ 整合報告未通過驗證：${integStatus}`)
}

return {
  資料基準日: dateFmt,
  檔數: okRows.length,
  預期檔數: names.length,
  缺漏: missing,
  資料降級: missing.length > 0,
  鐵則守門_一句話已加註近5日免責: n5FixedOL,
  鐵則守門_卡片欄近5日標記: n5FlagRow,
  訊號股: signals.map((r) => r.stock),
  個股報告: okRows.map((r) => r.htmlPath),
  整合報告狀態: integStatus,
  整合報告: integPath || `(整合報告產出失敗：${integStatus}；已完成 ${okRows.length}/${names.length} 檔個股短線深度報告，可用 build_integrated_report.py --rows "${rowsPath}" --date ${dateStr} --out "${integOut}" 事後補產)`,
}

