const done = results.filter((x) => x && x.ok && x.r)
const failed = results.filter((x) => !x || !x.ok)
log(`個股診斷完成 ${done.length}/${STOCKS.length}${failed.length ? '，失敗:' + failed.map((f) => f && f.name).join('/') : ''}`)

// ── 階段 D：彙整配置表 + 交付 HTML ──
phase('彙整交付')
const verdicts = done.map((x) => ({ 股名: x.name, 代碼: x.r.code, 評級: x.r.verdict && x.r.verdict.rating, 一句話: x.r.verdict && x.r.verdict.one_liner, html: x.r.htmlPath }))
const rows = done.map((x) => x.r.verdict && x.r.verdict.table_row).filter(Boolean)
const summaryScratch = `${ROOT}/data/_analysis_cache/長線精選彙整_${dateStr}.md`
