export const meta = {
  name: '基本面研究',
  description: '網路研究19檔的EPS(近4季/TTM/年度)、正常化EPS、每股淨值、PE/PB合理與歷史區間、股性→回傳結構化陣列供建 data/_fundamentals/fundamentals.json。EPS季頻、每季更新一次即可。',
  whenToUse: '建立或每季更新基本面庫(EPS/PE/PB)時。args 可傳 {stocks:[...]}；未傳涵蓋19檔。回傳的 資料 陣列由呼叫端「逐檔 merge」寫入 fundamentals.json——回傳另帶 檔數/應有檔數/完整/失敗/寫入指示，失敗非空時嚴禁整批覆寫，失敗檔須保留舊值並記入 _meta["缺(待補)"]。',
  phases: [{ title: '基本面研究', detail: '19檔平行網路研究 EPS/PE/PB/股性/正常化' }],
}

const STOCKS = { '力成':'6239','力積電':'6770','士電':'1503','仁寶':'2324','元太':'8069','光寶科':'2301','至上':'8112','鈊象':'3293','台企銀':'2834','台揚':'2314','友達':'2409','群聯':'8299','德律':'3030','漢翔':'2634','時碩工業':'4566','台積電':'2330','亞光':'3019','華新科':'2492','盟立':'2464' }
let A = args
if (typeof A === 'string') { const t = A.trim(); if (t.startsWith('{')) { try { A = JSON.parse(t) } catch (e) { A = {} } } else { A = {} } }
A = A || {}
const names = (A.stocks && A.stocks.length) ? A.stocks : Object.keys(STOCKS)

const timeNote = '時空前提：本工作區為模擬2026年時間線；EPS/財報請取真實世界最新可得資料，每筆標 as_of(季別/年度)。查無2026特定季別就用最近可得並註明、勿杜撰精確數字。'

const FUND_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    stock: { type: 'string' }, code: { type: 'string' },
    stock_type: { type: 'string', description: '股性：「景氣循環股」/「成長股」/「穩定收息股」擇一，並附次產業(如 記憶體封測/伺服器ODM/被動元件…)' },
    eps_ttm: { type: ['number', 'null'], description: '近四季合計EPS(TTM)，元；虧損為負；查無填null' },
    eps_recent: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { period: { type: 'string' }, eps: { type: 'number' } }, required: ['period', 'eps'] }, description: '近4~8季EPS' },
    eps_annual: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { year: { type: 'integer' }, eps: { type: 'number' } }, required: ['year', 'eps'] }, description: '近3~5年度EPS' },
    eps_normalized: { type: ['number', 'null'], description: '正常化EPS(整個景氣循環平均獲利，循環股務必估算)' },
    eps_forward: { type: ['number', 'null'], description: '市場預估今年度EPS(可選、標為預估)' },
    book_value: { type: ['number', 'null'], description: '每股淨值(元)' },
    pe_fair_low: { type: ['number', 'null'], description: '該股合理本益比下緣(此值以下偏便宜)' },
    pe_fair_high: { type: ['number', 'null'], description: '該股合理本益比上緣(此值以上偏貴)' },
    pb_cheap: { type: ['number', 'null'], description: '循環股PB便宜界(歷史帶下緣/約-1SD)；非循環股可null' },
    pb_expensive: { type: ['number', 'null'], description: '循環股PB偏貴界(歷史帶上緣/峰頂區)；非循環股可null' },
    pe_hist_range: { type: 'string', description: '歷史PE區間文字(如「20~40x」)或「needs_manual」' },
    pb_hist_range: { type: 'string', description: '歷史PB區間文字或「needs_manual」' },
    valuation_method: { type: 'string', description: '估值主工具：循環股=PB-Band+正常化EPS(低PE≠便宜)/成長股=PE+成長性/穩定股=PE+殖利率' },
    baseline_verdict: { type: 'string', enum: ['便宜', '合理偏低', '合理', '合理偏高', '貴', '難判定'], description: '以研究當下股價之便宜貴初判' },
    baseline_price: { type: ['number', 'null'], description: 'baseline_verdict 所依據的當時股價' },
    as_of: { type: 'string', description: 'EPS/財報資料時點(季別/年度)' },
    confidence: { type: 'string', enum: ['高', '中', '低'] },
    notes: { type: 'string', description: '獲利品質/一次性/循環位階/殖利率 等關鍵一句註記' },
    sources: { type: 'array', items: { type: 'string' } },
  },
  required: ['stock', 'code', 'stock_type', 'eps_ttm', 'eps_normalized', 'book_value', 'valuation_method', 'baseline_verdict', 'as_of', 'confidence'],
}

phase('基本面研究')
const results = await parallel(names.map((name) => () => {
  const code = STOCKS[name] || '?'
  // 逐檔隔離：agent 回 null(schema 重試耗盡) 或拋錯都只讓「該檔」失敗並記名，不得靜默丟棄、也不得拖垮整批
  return Promise.resolve().then(() => agent(
    `你是台股基本面/估值研究員。研究「${name}(${code})」的【獲利與估值基本面】，回傳結構化資料供建立本地基本面庫。\n${timeNote}\n查證重點：\n1. EPS：近4~8季每季EPS、近3~5年度EPS、據以算近四季合計(TTM)EPS。\n2. 正常化EPS：循環股務必估「整個景氣循環的平均獲利能力」(勿用單一谷底或峰頂年)；成長股可用近年趨勢中樞。\n3. 每股淨值(BVPS)。\n4. 股性分類(景氣循環/成長/穩定收息)＋次產業。\n5. 估值區間：該股合理本益比下緣/上緣(便宜界/偏貴界)；循環股另給PB歷史帶下緣(便宜)/上緣(峰頂偏貴)。歷史PE/PB區間查得到就給文字、查不到標needs_manual。\n6. baseline_verdict：以你研究當下的股價，依框架(循環股用PB-Band+正常化EPS、鐵則「低PE≠便宜」；成長股看PE與成長；穩定股看PE與殖利率)初判 便宜/合理偏低/合理/合理偏高/貴，並記 baseline_price。\n嚴禁杜撰精確數字；查無就給區間或標needs_manual、confidence降級。依 schema 回傳。`,
    { label: `基本面:${name}`, phase: '基本面研究', schema: FUND_SCHEMA },
  )).then((r) => {
    if (!r) return { name, code, ok: false, error: 'agent 回傳 null（schema 校驗重試耗盡）' }
    if (!r.stock) return { name, code, ok: false, error: 'agent 回傳缺 stock 欄位（結構不完整）' }
    if (!r.code) r.code = code
    return { name, code, ok: true, row: r }
  }).catch((e) => ({ name, code, ok: false, error: String(e) }))
}))

const done = results.filter((x) => x && x.ok && x.row)
const failed = results.filter((x) => !x || !x.ok || !x.row)
const failList = failed.map((f) => ({ 股名: (f && f.name) || '?', 代碼: (f && f.code) || '?', 原因: (f && f.error) || '未知（parallel 未回傳結果）' }))
const failNames = failList.map((f) => f.股名)
log(`基本面研究完成 ${done.length}/${names.length} 檔${failNames.length ? '，失敗:' + failNames.join('/') : ''}`)

return {
  檔數: done.length,
  應有檔數: names.length,
  完整: failList.length === 0,
  資料: done.map((x) => x.row),
