  () => agent(`你是產業循環研究員，研究「${stock}(${code})」所處產業之【景氣循環位階與競爭定位】。${RULES}\n${timeNote}\n共用研究：${shared}\n地面數據：${groundStr}\n查證重點：所屬次產業循環位階(上行/高峰/下行/落底)、領先指標(Book-to-Bill/稼動率/報價/庫存天數/Capex)、AI暴露度(實質營收占比或沾光)、供給紀律(過剩風險)、與同業對比、近期股價異常波動之可能催化(查無則標未證實)。依 schema 回傳。`,
    { label: `研究:產業循環:${stock}`, phase: '研究', schema: RESEARCH_SCHEMA }),
  () => agent(`你是台股籌碼結構分析師，精通【長線籌碼(非單日訊號)】，研究「${stock}(${code})」。${RULES}\n${timeNote}\n本地系統估算(供解讀，非重算)：${groundStr}\n查證重點(全用趨勢，非單日)：外資/投信持股比率月季趨勢、20/60日累積淨額方向、融資融券餘額/券資比/維持率、千張大戶佔比週趨勢、董監持股與質押設質比、**借券賣出餘額與占股本比、外資期貨/選擇權淨空單(法人放空主管道；依 steering/偵測法人偷偷放空.md——融券≠法人放空、勿以低融券斷定無放空、外資現貨賣超+股價撐住/RS落後+融券低=疑似偷偷布空)**。判斷結構性撤離或短期調節；凡查無長期官方數據誠實標 needs_manual/須人工核實並降權。依 schema 回傳。`,
    { label: `研究:籌碼脈絡:${stock}`, phase: '研究', schema: RESEARCH_SCHEMA }),
])
const research = { 基本面: fund, 產業循環: cycle, 籌碼脈絡: chip }

// ── 階段 2：撰寫初稿 ──
phase('撰寫')
const draft = await agent(
  `你是首席投資策略長。為「${stock}(${code})，${market}」撰寫【長線深度診斷報告】初稿，繁體中文Markdown、僅文件本體(無開場白)。${RULES}\n嚴格套用「個股診斷規格.md 第四節報告骨架(**六段：摘要／技術面／量價關係分析／籌碼面／基本面／結論**，其中「量價關係分析」為獨立一段、依 steering/量價關係教學.md 之量價十法則·量比·主力足跡·背離判讀)」與「第三節四級評級評分卡」。\n地面數據(數字以此為準、勿改)：${groundStr}\n已查證研究(JSON)：${JSON.stringify(research)}\n資料基準日：${dateFmt}。標題用「# ${stock}(${code}) 長線深度診斷報告」。結尾依序附：診斷配置表、**「## 📚 本次引用來源」節**(強制；規範見 steering/資料取得與分析作業規範.md §5.2——(1)知識庫(steering/)具體到章節/法則編號、(2)技能工具與資料檔附資料基準日、(3)「未參考」行列出該查未查者與理由；只列真的讀過與真的引用的，嚴禁虛列)、警語「投資有風險，分析僅供參考。」與署名「Claude Code (股市分析 Agent)」。`,
  { label: `撰寫:${stock}`, phase: '撰寫' },
)

// ── 階段 3：對抗式合規查核 ──
phase('查核')
const VERIFY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    compliant: { type: 'boolean' },
    single_day_signal_violation: { type: 'array', items: { type: 'string' } },
    valuation_check: { type: 'string' },
    debt_warning_check: { type: 'string' },
    data_honesty_check: { type: 'string' },
    three_dimension_alignment: { type: 'string' },
    citation_check: { type: 'string', description: '「📚 本次引用來源」節是否存在且合格：知識庫具體到章節/法則、工具附資料基準日、有「未參考」行、無虛列' },
    factual_concerns: { type: 'array', items: { type: 'string' } },
    required_fixes: { type: 'array', items: { type: 'string' } },
  },
  required: ['compliant', 'single_day_signal_violation', 'valuation_check', 'debt_warning_check', 'data_honesty_check', 'three_dimension_alignment', 'citation_check', 'factual_concerns', 'required_fixes'],
}
const critique = await agent(
  `你是最嚴格的框架合規審稿人。依「${ROOT}/steering/個股診斷規格.md 第五節品質關卡」逐項查核以下 ${stock} 報告：(a)有無把單日/近5日法人當訊號；(b)循環股估值是否誤用低PE=便宜、有無用PB/正常化EPS；(c)負債比>60%是否強制警戒並深剖、未觸線是否誠實(不杜撰假警戒)；(d)技術面短窗與工具限制是否誠實揭露、有無杜撰長均線、是否納入公認指標多空共振(擇時)且與週線Stage/RS一致、技術未凌駕基本面；(e)三面向是否對齊、評級是否成立、主從(基本面為錨、未被誇大湊偏空)是否正確；(f)**是否附「📚 本次引用來源」節**且合格——知識庫是否具體到章節/法則編號、工具是否附資料基準日、是否有「未參考」行、有無列出報告內容顯示並未實際使用的檔案(虛列)。給出定稿前必改清單。\n\n報告全文：\n${draft}`,
  { label: `查核:${stock}`, phase: '查核', schema: VERIFY_SCHEMA },
)

// ── 階段 4：定稿並存檔（作者自寫、無內容轉手遺失） ──
phase('定稿')
const finalMd = await agent(
  `你是首席投資策略長。吸納以下審稿意見的所有 required_fixes 與違規修正，產出 ${stock} 的【最終報告全文】(繁體中文Markdown、僅文件本體)。保持五段式與「📚 本次引用來源」節、地面數字不變、循環股估值、負債比/董監質押警戒、技術面短窗誠實、籌碼以趨勢非單日、四級評級(誠實分級不硬湊)、配置表、警語與署名。\n\n產出後，務必用 Write 工具把「完整最終 Markdown 全文」原樣(一字不差、含標題與警語)寫入檔案：\n  ${scratchMd}\n最後，把同一份 Markdown 全文作為你的回覆內容回傳。\n\n=== 初稿 ===\n${draft}\n\n=== 審稿意見(JSON) ===\n${JSON.stringify(critique)}`,
  { label: `定稿:${stock}`, phase: '定稿' },
)

// ── 階段 5：交付（產 HTML + 萃取評級） ──
phase('交付')
const DELIVER_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    htmlPath: { type: 'string' },
    ok: { type: 'boolean', description: 'HTML 是否成功產出' },
    rating: { type: 'string', enum: ['加碼', '持有', '減碼', '回避'], description: '四級評級' },
    reduce_type: { type: 'string', description: '減碼型別：§9.2惡化型 / §7.4停利型 / NA' },
    one_liner: { type: 'string', description: '一句話定調' },
    fundamental_rating: { type: 'string', description: '基本面評級' },
    chip_rating: { type: 'string', description: '籌碼評級' },
    tech_rating: { type: 'string', description: '技術評級' },
    support: { type: 'string', description: '支撐位' },
    resistance: { type: 'string', description: '壓力位' },
    stop_defense: { type: 'string', description: '防守止損' },
    table_row: { type: 'string', description: '綜合報告用的一列 Markdown 表格列（股名代碼｜收盤與漲跌位階｜技術型態｜籌碼評級｜基本面評級｜核心操作+防守位）' },
  },
  required: ['htmlPath', 'ok', 'rating', 'one_liner', 'table_row'],
}
const delivered = await agent(
  `交付步驟：\n1. 用 Bash 執行(產出 HTML)：\n   PYTHONIOENCODING=utf-8 python "${ROOT}/skills/report_html.py" --stdin --out "${htmlOut}" < "${scratchMd}"\n   確認輸出成功、檔案 ${htmlOut} 存在(可用 ls 檢查)。\n2. 用 Read 讀 ${scratchMd}，萃取該報告的四級評級、減碼型別(若適用)、一句話定調、基本面/籌碼/技術評級、支撐/壓力/防守止損、以及「診斷配置表」中該股的一列(整理成一列 Markdown 表格列，欄位：股名代碼｜收盤與漲跌位階｜技術型態｜籌碼評級｜基本面評級｜核心操作+防守位)。\n3. 依 schema 回傳，htmlPath=${htmlOut}。`,
  { label: `交付:${stock}`, phase: '交付', schema: DELIVER_SCHEMA },
)

return { stock, code, market, 資料基準日: dateFmt, 地面數據來源: groundSource, htmlPath: delivered.htmlPath, verdict: delivered, critique, ground }

export const meta = {
  name: '全持股長線分析',
  description: '19 檔全持股長線分析編排：資料準備→共用研究(總經/產業循環/大盤)跑一次快取→19檔平行呼叫「個股長線診斷」子工作流→綜合投資診斷總報告(HTML)。此即「分析資料」的可重用技能。',
  whenToUse: '使用者說「分析資料」或要一次產出全 19 檔長線診斷＋綜合總報告時。args 可傳 {refresh:true} 先更新K線與法人成本線。',
  phases: [
    { title: '資料準備', detail: 'collect_stock_data.py --all（可選先 task_runner update/chip）' },
    { title: '共用研究', detail: '總經/大盤/半導體各次產業循環一次研究、供19檔共用' },
    { title: '個股診斷', detail: '19 檔平行呼叫子工作流「個股長線診斷」' },
    { title: '綜合總報告', detail: '彙整各檔評級為五段式綜合總報告' },
    { title: '交付', detail: 'report_html.py 產出綜合總報告 HTML' },
  ],
}

const ROOT = 'D:/AI_Data/股市分析'
let A = args
if (typeof A === 'string') { const t = A.trim(); if (t.startsWith('{')) { try { A = JSON.parse(t) } catch (e) {} } }
const REFRESH = !!(A && A.refresh)
const STOCKS = ['台積電', '力積電', '力成', '群聯', '漢翔', '光寶科', '友達', '元太', '華新科', '德律', '鈊象', '士電', '仁寶', '至上', '時碩工業', '台揚', '台企銀', '亞光', '盟立']

// ── 階段 A：資料準備（確定性地面數據） ──
phase('資料準備')
const PREP_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: { done: { type: 'number' }, data_date: { type: 'string', description: 'YYYY/MM/DD，取自任一 _ground.json 的技術面資料基準日' }, note: { type: 'string' } },
  required: ['done', 'data_date'],
}
const prep = await agent(
  `資料準備步驟(用 Bash，路徑用正斜線與 python)：\n${REFRESH ? `1. 先執行 PYTHONIOENCODING=utf-8 python "${ROOT}/skills/task_runner.py" --phase update（更新K線）\n2. 再執行 PYTHONIOENCODING=utf-8 python "${ROOT}/skills/task_runner.py" --phase chip（法人成本線）\n3. ` : '1. '}執行 PYTHONIOENCODING=utf-8 python "${ROOT}/skills/collect_stock_data.py" --all（產生19檔地面數據快取）。\n然後用 Read 讀 ${ROOT}/data/_analysis_cache/台積電_ground.json，取其 技術面.資料基準日。\n依 schema 回傳完成檔數與資料基準日。`,
  { label: '資料準備', phase: '資料準備', schema: PREP_SCHEMA },
)
const dateStr = String(prep.data_date || '').replace(/\//g, '') || 'latest'

// ── 階段 B：共用研究（一次，供 19 檔共用，避免重工） ──
phase('共用研究')
const SHARED_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    market_stage: { type: 'string', description: '大盤位階：加權/櫃買指數位階與Stage、風險情緒' },
    macro: { type: 'string', description: '總經：利率、匯率USD/TWD、全球PMI、AI資本支出' },
    subindustry_cycles: { type: 'array', description: '半導體各次產業循環', items: { type: 'object', additionalProperties: false,
      properties: { subindustry: { type: 'string', description: '次產業' }, stage: { type: 'string', description: '循環位階' }, leading_indicators: { type: 'string', description: '領先指標' }, supply_discipline: { type: 'string', description: '供給紀律/過剩風險' } },
      required: ['subindustry', 'stage', 'leading_indicators', 'supply_discipline'] } },
    ai_structural_trend: { type: 'string', description: 'AI供應鏈結構趨勢與供給檢驗' },
    caveats: { type: 'array', items: { type: 'string' } },
    sources: { type: 'array', items: { type: 'string' } },
  },
  required: ['market_stage', 'macro', 'subindustry_cycles', 'ai_structural_trend', 'caveats', 'sources'],
}
const shared = await agent(
  `你是總經與半導體產業策略研究員。先用 Read 讀「${ROOT}/steering/長線投資分析框架.md」第4章。產出【共用長線研究簡報】供 19 檔個股診斷共用(免各自重查)：\n- 台股大盤/櫃買指數位階與Stage、全球風險情緒；\n- 總經：利率、匯率USD/TWD(對出口股毛利)、全球PMI/ISM、雲端AI資本支出；\n- 半導體各次產業循環位階(記憶體DRAM/NAND/HBM、晶圓代工先進/成熟、封測、面板、PCB/ABF載板、伺服器/AI、被動元件/重電)——各附位階、領先指標(Book-to-Bill/稼動率/報價/庫存/Capex)、供給紀律(過剩風險)；\n- AI供應鏈結構趨勢與「AI拉平週期」的供給檢驗。\n用 WebSearch 查最新真實資料、標來源與時間。依 schema 回傳。`,
  { label: '共用研究', phase: '共用研究', schema: SHARED_SCHEMA },
)
const sharedStr = JSON.stringify(shared)

// ── 階段 C：19 檔平行診斷（呼叫子工作流；一層巢狀，子工作流內不得再 workflow()） ──
phase('個股診斷')
const results = await parallel(STOCKS.map((name) => () =>
  workflow('個股長線診斷', { stock: name, sharedResearch: sharedStr })
    .then((r) => ({ name, ok: true, r }))
    .catch((e) => ({ name, ok: false, error: String(e) })),
))
const done = results.filter((x) => x && x.ok && x.r)
const failed = results.filter((x) => !x || !x.ok)
log(`個股診斷完成 ${done.length}/${STOCKS.length}${failed.length ? '，失敗:' + failed.map((f) => f && f.name).join('/') : ''}`)

// ── 階段 D：綜合總報告 ──
phase('綜合總報告')
const verdicts = done.map((x) => ({ 股名: x.name, 代碼: x.r.code, 評級: x.r.verdict && x.r.verdict.rating, 一句話: x.r.verdict && x.r.verdict.one_liner, html: x.r.htmlPath }))
const rows = done.map((x) => x.r.verdict && x.r.verdict.table_row).filter(Boolean)
const summaryScratch = `${ROOT}/data/_analysis_cache/綜合總報告_${dateStr}.md`
const comboOut = `${ROOT}/綜合投資診斷報告_${dateStr}_Claude.html`

await agent(
  `你是首席投資策略長。產出【綜合投資診斷總報告】(繁體中文Markdown、僅文件本體、五段式)，資料基準日 ${prep.data_date}。\n依 CLAUDE.md 報告規範：\n1. 摘要：資料更新狀態、大盤整體狀態(引共用研究)、核心操作分類(把各檔歸入 加碼/持有/減碼/回避)、有無失敗紀錄(${failed.length ? '失敗:' + failed.map((f) => f && f.name).join('/') : '無'})。\n2. 技術面總覽、3. 籌碼面總覽、4. 基本面與風險總覽(點名負債比>60%或董監質押警戒之個股)、5. 結論與【全持股診斷配置表】。\n配置表直接用以下各檔配置表列組成表格。結尾依序附：**「## 📚 本次引用來源」節**(強制；規範見 steering/資料取得與分析作業規範.md §5.2：(1)知識庫(steering/)具體到章節/法則編號、(2)技能工具與資料檔附資料基準日(collect_stock_data/法人成本線CSV/market_latest/fundamentals 等)、(3)「未參考」行；只列真的引用的，嚴禁虛列)、警語「投資有風險，分析僅供參考。」與署名「Claude Code (股市分析 Agent)」。\n\n共用研究(JSON)：${sharedStr}\n各檔評級(JSON)：${JSON.stringify(verdicts)}\n各檔配置表列(Markdown)：\n${rows.join('\n')}\n\n產出後務必用 Write 把完整 Markdown 全文原樣寫入 ${summaryScratch}，並把全文作為回覆回傳。`,
  { label: '綜合總報告', phase: '綜合總報告' },
)

// ── 階段 E：交付 HTML ──
phase('交付')
const DELIVER_SCHEMA = { type: 'object', additionalProperties: false, properties: { htmlPath: { type: 'string' }, ok: { type: 'boolean' } }, required: ['htmlPath', 'ok'] }
const deliver = await agent(
  `用 Bash 執行：PYTHONIOENCODING=utf-8 python "${ROOT}/skills/report_html.py" --stdin --out "${comboOut}" < "${summaryScratch}"，確認 ${comboOut} 產出(ls 檢查)。依 schema 回傳 htmlPath=${comboOut}。`,
  { label: '交付:綜合總報告', phase: '交付', schema: DELIVER_SCHEMA },
)

return {
  綜合總報告: deliver.htmlPath,
  資料基準日: prep.data_date,
  個股: done.map((x) => ({ 股名: x.name, 評級: x.r.verdict && x.r.verdict.rating, html: x.r.htmlPath })),
  失敗: failed.map((f) => f && f.name),
}

