# -*- coding: utf-8 -*-
"""訊號回溯評分（Backtest）— 量化「多空共振方向」的實際前瞻表現。

用途
----
本系統每交易日產出 data/_analysis_cache/短線訊號_YYYYMMDD.json，內含各檔的
「多空共振方向」(偏多/偏空/中性‧震盪) 與「共振強度」(強/中/弱)。這些都是可
證偽的方向預測，但過去從未被驗證。本腳本以事後 K 線計算前瞻報酬，統計：

  * 命中率：偏多→漲、偏空→跌 視為命中
  * 平均前瞻報酬：依方向分組
  * 對照基準(baseline)：全樣本平均前瞻報酬（＝同期市場漂移）
  * 邊際(edge)：分組平均 − 基準，這才是訊號真正的附加價值
  * 中性/震盪：以絕對變動幅度檢驗是否真的對應「低波動」

用法
----
  PYTHONIOENCODING=utf-8 python skills/backtest_signals.py
  PYTHONIOENCODING=utf-8 python skills/backtest_signals.py --horizons 1,3,5,10
  PYTHONIOENCODING=utf-8 python skills/backtest_signals.py --md

統計誠實聲明
------------
樣本為重疊視窗(同一檔連續多日重複計入)、涵蓋單一市場區間、樣本數有限，
因此結果為**描述性統計**，不等於統計顯著的預測力證據。詳見輸出末段。
"""
import argparse
import glob
import io
import json
import os
import re
from collections import defaultdict

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CACHE = os.path.join(ROOT, "data", "_analysis_cache")
DATA = os.path.join(ROOT, "data")

DIR_LONG = "偏多"
DIR_SHORT = "偏空"


def _norm_dir(d):
    """方向字串正規化：'中性/震盪'、'中性震盪' 等一律歸為 中性。"""
    s = str(d or "").strip()
    if not s:
        return ""
    if s.startswith(DIR_LONG):
        return DIR_LONG
    if s.startswith(DIR_SHORT):
        return DIR_SHORT
    if "中性" in s or "震盪" in s:
        return "中性"
    return s


def load_prices(stock):
    """讀該檔 K 線，回傳 (日期升冪清單, {日期:收盤})。CSV 為日期降冪，需反轉。"""
    hits = glob.glob(os.path.join(DATA, stock, "*近期K線.csv"))
    if not hits:
        return [], {}
    rows = []
    with io.open(hits[0], encoding="utf-8-sig") as fh:
        header = fh.readline().strip().split(",")
        try:
            i_d = header.index("Date")
            i_c = header.index("Close")
        except ValueError:
            return [], {}
        for line in fh:
            parts = line.rstrip("\n").split(",")
            if len(parts) <= max(i_d, i_c):
                continue
            d = parts[i_d].strip()
            c = parts[i_c].strip().replace(",", "")
            if not d or not c:
                continue
            try:
                rows.append((d, float(c)))
            except ValueError:
                continue
    rows.reverse()  # CSV 最新在最上 → 反轉為升冪
    dates = [r[0] for r in rows]
    close = {r[0]: r[1] for r in rows}
    return dates, close


def load_signals():
    """讀所有訊號檔，回傳 record 清單。"""
    recs = []
    for path in sorted(glob.glob(os.path.join(CACHE, "短線訊號_*.json"))):
        try:
            doc = json.load(io.open(path, encoding="utf-8"))
        except Exception:
            continue
        base = str(doc.get("資料基準日") or "").strip()
        if not base:
            m = re.search(r"(\d{8})", os.path.basename(path))
            if not m:
                continue
            g = m.group(1)
            base = "%s/%s/%s" % (g[:4], g[4:6], g[6:])
        for s in doc.get("訊號個股", []):
            recs.append({
                "date": base,
                "stock": str(s.get("股名") or "").strip(),
                "code": str(s.get("代碼") or "").strip(),
                "dir": _norm_dir(s.get("多空共振方向")),
                "strength": str(s.get("共振強度") or "").strip(),
            })
    return recs


def forward_returns(recs, horizons):
    """為每筆 record 補上各 horizon 的前瞻報酬%（交易日為單位）。"""
    cache = {}
    out = []
    for r in recs:
        st = r["stock"]
        if st not in cache:
            cache[st] = load_prices(st)
        dates, close = cache[st]
        if not dates:
            continue
        try:
            i = dates.index(r["date"])
        except ValueError:
            continue  # 訊號日不在 K 線中（停牌/資料缺）
        base = close[dates[i]]
        if not base:
            continue
        rec = dict(r)
        ok = False
        for h in horizons:
            j = i + h
            if j < len(dates):
                rec["fwd%d" % h] = (close[dates[j]] - base) / base * 100.0
                ok = True
            else:
                rec["fwd%d" % h] = None
        if ok:
            out.append(rec)
    return out


def _stats(vals):
    if not vals:
        return None
    n = len(vals)
    mean = sum(vals) / n
    var = sum((v - mean) ** 2 for v in vals) / n if n > 1 else 0.0
    return {"n": n, "mean": mean, "sd": var ** 0.5}


def analyse(recs, horizons):
    """依方向/強度分組，計算命中率、平均前瞻報酬與相對基準的邊際。"""
    res = {}
    for h in horizons:
        key = "fwd%d" % h
        pool = [r for r in recs if r.get(key) is not None]
        if not pool:
            continue
        base_stats = _stats([r[key] for r in pool])
        groups = defaultdict(list)
        for r in pool:
            groups[r["dir"]].append(r)
        by_dir = {}
        for d, items in groups.items():
            vals = [r[key] for r in items]
            st = _stats(vals)
            hit = None
            if d == DIR_LONG:
                hit = sum(1 for v in vals if v > 0) / len(vals) * 100.0
            elif d == DIR_SHORT:
                hit = sum(1 for v in vals if v < 0) / len(vals) * 100.0
            by_dir[d] = {
                "n": st["n"], "mean": st["mean"], "sd": st["sd"],
                "hit": hit,
                "edge": st["mean"] - base_stats["mean"],
                "abs_mean": sum(abs(v) for v in vals) / len(vals),
            }
        by_ds = {}
        for d, items in groups.items():
            for s in ("強", "中", "弱"):
                sub = [r[key] for r in items if r["strength"] == s]
                if not sub:
                    continue
                st = _stats(sub)
                hit = None
                if d == DIR_LONG:
                    hit = sum(1 for v in sub if v > 0) / len(sub) * 100.0
                elif d == DIR_SHORT:
                    hit = sum(1 for v in sub if v < 0) / len(sub) * 100.0
                by_ds[(d, s)] = {"n": st["n"], "mean": st["mean"], "hit": hit,
                                 "edge": st["mean"] - base_stats["mean"]}
        res[h] = {"base": base_stats, "by_dir": by_dir, "by_ds": by_ds}
    return res


def fmt(res, horizons, md=False):
    L = []
    B = "**" if md else ""
    L.append("%s訊號回溯評分（多空共振方向 vs 實際前瞻報酬）%s" % (B, B))
    L.append("")
    for h in horizons:
        if h not in res:
            continue
        r = res[h]
        b = r["base"]
        L.append("%s── 前瞻 %d 個交易日 ──%s" % (B, h, B))
        L.append("基準(全樣本平均) %+.2f%%　樣本 %d 筆" % (b["mean"], b["n"]))
        if md:
            L.append("")
            L.append("| 方向 | 樣本 | 命中率 | 平均報酬 | 相對基準邊際 | 標準差 |")
            L.append("| :-- | --: | --: | --: | --: | --: |")
        for d in (DIR_LONG, DIR_SHORT, "中性"):
            v = r["by_dir"].get(d)
            if not v:
                continue
            hit = "%.1f%%" % v["hit"] if v["hit"] is not None else "—"
            if md:
                L.append("| %s | %d | %s | %+.2f%% | %+.2f%% | %.2f |"
                         % (d, v["n"], hit, v["mean"], v["edge"], v["sd"]))
            else:
                L.append("  %-4s n=%-4d 命中%-7s 平均%+.2f%%  邊際%+.2f%%  sd%.2f"
                         % (d, v["n"], hit, v["mean"], v["edge"], v["sd"]))
        neu = r["by_dir"].get("中性")
        if neu:
            others = [v["abs_mean"] for k, v in r["by_dir"].items() if k != "中性"]
            if others:
                avg_other = sum(others) / len(others)
                L.append("  中性檢定：中性組平均絕對變動 %.2f%% vs 方向組 %.2f%%（前者應較小才合理）"
                         % (neu["abs_mean"], avg_other))
        L.append("")
        L.append("  依共振強度細分：")
        if md:
            L.append("")
            L.append("| 方向 | 強度 | 樣本 | 命中率 | 平均報酬 | 邊際 |")
            L.append("| :-- | :-- | --: | --: | --: | --: |")
        for d in (DIR_LONG, DIR_SHORT, "中性"):
            for s in ("強", "中", "弱"):
                v = r["by_ds"].get((d, s))
                if not v:
                    continue
                hit = "%.1f%%" % v["hit"] if v["hit"] is not None else "—"
                if md:
                    L.append("| %s | %s | %d | %s | %+.2f%% | %+.2f%% |"
                             % (d, s, v["n"], hit, v["mean"], v["edge"]))
                else:
                    L.append("    %-4s/%-2s n=%-4d 命中%-7s 平均%+.2f%%  邊際%+.2f%%"
                             % (d, s, v["n"], hit, v["mean"], v["edge"]))
        L.append("")
    L.append("%s判讀方式%s" % (B, B))
    L.append("- 命中率僅看方向對錯，未計幅度；平均報酬才反映實際損益。")
    L.append("- 「邊際」＝該組平均報酬 − 全樣本基準，扣掉同期市場漂移後的附加價值。")
    L.append("  偏多組的邊際應為正、偏空組應為負，方屬有效訊號；若偏空組邊際為正，代表該訊號實際上是反指標。")
    L.append("- 命中率約 50%、邊際接近 0，代表該訊號與擲硬幣無異。")
    L.append("")
    L.append("%s統計限制（必讀）%s" % (B, B))
    L.append("- 重疊視窗：同一檔連續多日重複計入，樣本非獨立，實際有效樣本數遠小於名目 n。")
    L.append("- 單一區間：僅涵蓋訊號檔存在的期間，未跨多空循環，結論不可外推。")
    L.append("- 未計交易成本、滑價，亦未考慮個股放空限制。")
    L.append("- 本表為描述性統計，非統計顯著性檢定；樣本不足時勿據此調整策略。")
    return "\n".join(L)


RELIABILITY_P = os.path.join(CACHE, "signal_reliability.json")


def emit_reliability(res, horizons, n_pred, n_days):
    """把評分結果寫成機器可讀檔，供報告層引用（訊號可靠度揭露）。

    報告一直以高信心語氣寫「多空共振偏空(強、淨分-5.6)」，卻從未揭露這個訊號
    到底準不準。此檔讓 build_integrated_report.py 與各檔短線深度報告都能引用
    **同一份、當前樣本算出來的**可靠度，而不是寫死一段話——樣本累積後自動更新。
    """
    key_h = max(h for h in horizons) if horizons else 10
    r = res.get(key_h) or {}
    by = r.get("by_dir") or {}
    out = {
        "產生時間": None,          # 由呼叫端不填，避免 Date.now 類不可重現值進版本比對
        "樣本": {"預測筆數": n_pred, "訊號檔天數": n_days,
                 "可評分筆數": (r.get("base") or {}).get("n"),
                 "主要視野(交易日)": key_h},
        "基準報酬%": round((r.get("base") or {}).get("mean", 0.0), 2),
        "各方向": {},
        "整體結論": "",
        "使用限制": ["重疊視窗（同一檔連續多日重複計入），實際有效樣本遠小於名目 n",
                     "僅涵蓋訊號檔存在的單一市場區間，未跨多空循環，不可外推",
                     "未計交易成本與滑價；描述性統計，非統計顯著性檢定"],
    }
    for d, v in by.items():
        out["各方向"][d] = {
            "樣本": v["n"],
            "命中率%": round(v["hit"], 1) if v.get("hit") is not None else None,
            "平均報酬%": round(v["mean"], 2),
            "相對基準邊際%": round(v["edge"], 2),
        }
    lg, sh = by.get(DIR_LONG), by.get(DIR_SHORT)
    verdict = []
    if lg and lg["edge"] < -0.5:
        verdict.append(f"偏多訊號跑輸基準 {abs(lg['edge']):.1f} 個百分點")
    if sh and sh["edge"] > 0.5:
        verdict.append(f"偏空訊號反而優於基準 {sh['edge']:.1f} 個百分點（方向相反）")
    if verdict:
        out["整體結論"] = ("；".join(verdict)
                           + f"——於本區間（前瞻 {key_h} 個交易日）多空共振方向為**反指標**，"
                             "請勿單獨作為進出依據；最可能為區間效應（順勢指標在均值回歸盤失效），"
                             "非證明其永久失效。")
        out["可靠度"] = "反指標(本區間)"
    elif lg and sh and abs(lg["edge"]) < 0.5 and abs(sh["edge"]) < 0.5:
        out["整體結論"] = f"前瞻 {key_h} 個交易日之邊際接近 0，與隨機無異，不具可辨識的預測力。"
        out["可靠度"] = "無邊際"
    else:
        out["整體結論"] = f"前瞻 {key_h} 個交易日之方向與基準同向，具正邊際，惟樣本限制見使用限制。"
        out["可靠度"] = "有正邊際"
    try:
        os.makedirs(CACHE, exist_ok=True)
        io.open(RELIABILITY_P, "w", encoding="utf-8").write(
            json.dumps(out, ensure_ascii=False, indent=1))
        print("[Success] 已寫出訊號可靠度 %s" % RELIABILITY_P)
    except Exception as e:
        print("[Warn] 寫入可靠度檔失敗: %s" % e)
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--horizons", default="1,3,5,10", help="前瞻交易日，逗號分隔")
    ap.add_argument("--md", action="store_true", help="輸出 Markdown 表格")
    ap.add_argument("--out", default="", help="輸出檔路徑（預設印到 stdout）")
    ap.add_argument("--json", action="store_true",
                    help="另寫出 data/_analysis_cache/signal_reliability.json 供報告層引用")
    a = ap.parse_args()
    horizons = [int(x) for x in a.horizons.split(",") if x.strip()]

    recs = load_signals()
    if not recs:
        print("[Warn] 找不到任何 短線訊號_*.json，無法評分。")
        return
    scored = forward_returns(recs, horizons)
    print("[Info] 讀入訊號 %d 筆，成功對上 K 線 %d 筆" % (len(recs), len(scored)))
    dropped = len(recs) - len(scored)
    if dropped:
        print("[Info] %d 筆因訊號日不在 K 線或無足夠後續資料而略過" % dropped)
    res = analyse(scored, horizons)
    if a.json:
        n_days = len(set(r["date"] for r in recs))
        emit_reliability(res, horizons, len(recs), n_days)
    text = fmt(res, horizons, md=a.md)
    if a.out:
        io.open(a.out, "w", encoding="utf-8").write(text)
        print("[Success] 已寫出 %s" % a.out)
    else:
        print()
        print(text)


if __name__ == "__main__":
    main()

"""由已交付的短線報告建立本地分析首頁；只呈現既有結論，不重算訊號。"""

from __future__ import annotations

import html
import json
import re
from pathlib import Path

from daily_stock_run import check_deliverables, stock_map


ROOT = Path(__file__).resolve().parents[1]
CACHE = ROOT / "data" / "_analysis_cache"
HOME = ROOT / "投資分析首頁.html"
SHORT = ROOT / "我的短線分析.html"


def esc(value: object) -> str:
    return html.escape(str(value if value is not None else ""), quote=True)


def read_json(path: Path):
    with path.open(encoding="utf-8") as stream:
        return json.load(stream)


def latest_delivery(stocks: dict[str, str]):
    candidates = sorted(ROOT.glob("短線整合報告_????????.html"), reverse=True)
    for path in candidates:
        day = path.stem[-8:]
        if not re.fullmatch(r"\d{8}", day):
            continue
        rows_path = CACHE / f"codex_rows_{day}.json"
        if not rows_path.is_file():
            continue
        delivery = check_deliverables(day, stocks)
        if not delivery["integrated_ok"] or delivery["delivered"] != len(stocks):
            continue
        rows = read_json(rows_path)
        if not isinstance(rows, list):
            continue
        by_name = {row.get("stock"): row for row in rows if isinstance(row, dict) and row.get("ok")}
        if set(stocks) != set(by_name):
            continue
        if any(str(row.get("date", "")).replace("/", "").replace("-", "") != day for row in by_name.values()):
            continue
        quality_path = CACHE / f"codex_quality_{day}.json"
        quality = read_json(quality_path) if quality_path.is_file() else {}
        if quality.get("結構查核通過") is False:
            continue
        return day, by_name, quality
    raise RuntimeError("找不到整合報告、19 檔個股報告與整合列都齊備的交易日")


