def quality_note(day: str, quality: dict) -> str:
    if quality.get("資料全部完成") is True:
        return "此交易日的品質檢查標記為資料全部完成；細節與限制請查看完整報告。"
    date_check = quality.get("資料日期驗收") or {}
    lag = date_check.get("待補與揭露") or []
    if lag:
        return f"此報告有 {len(lag)} 項資料日期或來源限制；借券、融資融券與外資持股等欄位可能晚於 {day[:4]}/{day[4:6]}/{day[6:]}。以完整報告的逐檔揭露為準。"
    return "品質檢查沒有確認全部資料到齊；請查看完整報告的來源、日期與限制。"


def history_links(day: str, stocks: dict[str, str]) -> str:
    previous = sorted(ROOT.glob("短線整合報告_????????.html"), reverse=True)
    links = []
    for path in previous:
        old = path.stem[-8:]
        if old == day or not re.fullmatch(r"\d{8}", old):
            continue
        delivery = check_deliverables(old, stocks)
        if not delivery["integrated_ok"] or delivery["delivered"] != len(stocks):
            continue
        links.append(f'<a href="{esc(path.name)}">{esc(old[:4] + "/" + old[4:6] + "/" + old[6:])}</a>')
        if len(links) == 5:
            break
    return "".join(links)


