def fetch(kind: str, filename: str, page: str):
    url = BASE + filename
    request = urllib.request.Request(url, headers={"User-Agent": "StockAnalysisResearch/1.0"})
    with urllib.request.urlopen(request, timeout=15) as response:
        raw = response.read(10_000_001)
    if len(raw) > 10_000_000:
        raise ValueError(f"{kind} 回應超過大小上限")
    payload = json.loads(raw.decode("utf-8-sig"))
    if not isinstance(payload, dict) or not isinstance(payload.get("entries"), list):
        raise ValueError(f"{kind} 資料結構異常")
    return kind, page, url, payload


def read_market() -> dict:
    try:
        with MARKET.open(encoding="utf-8") as stream:
            result = json.load(stream)
        return result if isinstance(result, dict) else {}
    except (OSError, ValueError):
        return {}


def western_date(value: object):
    """支援網站的民國日期及 ISO 日期；未知格式不猜。"""
    raw = str(value or "").strip().replace("-", "/")
    parts = raw.split("/")
    if len(parts) != 3 or not all(part.isdigit() for part in parts):
        return None
    year, month, day = (int(part) for part in parts)
    if year < 1912:
        year += 1911
    try:
        return datetime(year, month, day).date()
    except ValueError:
        return None


def month_key(value: object) -> str:
    raw = str(value or "").strip().replace("-", "").replace("/", "")
    if len(raw) == 5 and raw.isdigit():
        return f"{int(raw[:3]) + 1911:04d}{raw[3:]}"
    return raw if len(raw) == 6 and raw.isdigit() else ""


def slim_entry(kind: str, row: dict, today, market: dict) -> dict | None:
    code = str(row.get("code") or "").strip()
    common = {
        "類別": kind,
        "代碼": code,
        "股名": str(row.get("name") or "").strip(),
        "查證狀態": "待官方原始資料核實",
    }
    if kind == "營收":
        period = str(row.get("period") or "").strip()
        if not month_key(period):
            return None
        official_period = month_key((market.get(code) or {}).get("月營收年月"))
        current_period = month_key(period)
        if official_period and current_period > official_period:
            common["比對結果"] = f"網站期別 {period} 新於官方快取 {official_period[:4]}/{official_period[4:]}，待官方更新與核對"
        elif official_period == current_period:
            common["比對結果"] = "網站期別與官方快取相同；數值仍須逐項核對"
        else:
            common["比對結果"] = "網站期別未新於官方快取"
        common.update({
            "期別": period,
            "當月營收_來源數值": row.get("rev"),
            "年增率_來源%": row.get("yoy_pct"),
            "月增率_來源%": row.get("mom_pct"),
            "公司備註": str(row.get("note") or "")[:240],
            "網站首次看見時間": row.get("first_seen"),
            "官方快取期別": f"{official_period[:4]}/{official_period[4:]}" if official_period else None,
        })
        return common
    if kind in ("自結", "季報"):
        announced = western_date(row.get("date"))
        if not announced or announced < today - timedelta(days=21) or announced > today:
            return None
        common.update({
            "公告日期": announced.isoformat(),
            "公告時間": row.get("time"),
            "公告主旨": str(row.get("subject") or "")[:260],
            "公告識別碼": row.get("uid"),
        })
        return common
    if kind == "庫藏股":
        board = western_date(row.get("board_date"))
        end = western_date(row.get("period_end"))
        if not ((board and board >= today - timedelta(days=21)) or
                (end and end >= today and row.get("completed") != "Y")):
            return None
        common.update({
            "董事會日期": board.isoformat() if board else None,
            "預定結束日": end.isoformat() if end else None,
            "買回完成": row.get("completed"),
            "預定買回股數": row.get("planned_shares"),
            "已買回股數": row.get("bought_shares"),
            "來源首次看見時間": row.get("first_seen"),
        })
        return common
    if kind == "公司事件":
        scheduled = western_date(row.get("scheduled_date"))
        if not scheduled or not today <= scheduled <= today + timedelta(days=120):
            return None
        announced = western_date(row.get("date"))
        common.update({
            "預定日期": scheduled.isoformat(),
            "公告日期": announced.isoformat() if announced else None,
            "事件類型_來源": row.get("event_type"),
            "公告主旨": str(row.get("subject") or "")[:260],
            "公告識別碼": row.get("uid"),
        })
        return common
    return None


