        ],
    }
    with ThreadPoolExecutor(max_workers=3) as pool:
        jobs = {kind: pool.submit(fetch, kind, filename, page)
                for kind, (filename, page) in SOURCES.items()}
        for kind, job in jobs.items():
            try:
                _, page, url, payload = job.result()
                output["來源"][kind] = {
                    "頁面": page,
                    "資料位置": url,
                    "網站更新時間": payload.get("fetched_at"),
                    "來源筆數": len(payload["entries"]),
                }
                for row in payload["entries"]:
                    if not isinstance(row, dict):
                        continue
                    code = str(row.get("code") or "").strip()
                    if code not in by_code:
                        continue
                    entry = slim_entry(kind, row, today, market)
                    if entry is not None:
                        entry["頁面"] = page
                        entry["網站更新時間"] = payload.get("fetched_at")
                        output["個股"][code].append(entry)
            except (OSError, ValueError, TimeoutError) as error:
                output["失敗來源"][kind] = str(error)[:250]
    for code, items in output["個股"].items():
        items.sort(key=lambda item: str(item.get("預定日期") or item.get("公告日期")
                                        or item.get("董事會日期") or item.get("期別") or ""),
                   reverse=True)
        output["個股"][code] = items[:12]
    output["有線索檔數"] = sum(bool(items) for items in output["個股"].values())
    output["線索筆數"] = sum(len(items) for items in output["個股"].values())
    directory = OUT / today.strftime("%Y%m%d")
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / "summary.json"
    temporary = directory / "summary.json.tmp"
    temporary.write_text(json.dumps(output, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(temporary, path)
    if not output["來源"]:
        raise RuntimeError("五個外部公告來源皆無法取得；失敗原因已寫入當日 summary.json")
    return path


if __name__ == "__main__":
    try:
        path = collect()
        print(f"外部公告線索已存：{path}")
    except (OSError, RuntimeError, ValueError) as error:
        print(f"[外部公告線索未更新] {error}", file=sys.stderr)
        sys.exit(2)

