                         '(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
           'Accept': 'application/json, text/javascript, */*; q=0.01'}

# ---- 與 update_stocks.py 共用的 CSV 契約（欄名與來源標籤必須逐字一致，勿各自定義）----
# update_stocks.py 以 Source 欄＋SOURCE_RANK 做去重（官方 > 舊列 > Yahoo），本檔讀寫都必須帶上，
# 否則跑完 fetch_history 會把 Source 欄抹除，官方量價在下次 update_stocks 時被 Yahoo 偏低量降級。
SOURCE_RANK = {"TWSE": 3, "TPEX": 3, "_LEGACY": 2, "YAHOO": 1, "UNKNOWN": 0}
CSV_COLS = ["Date", "Open", "High", "Low", "Close", "Volume", "Source"]
LEGACY_SOURCE = "_LEGACY"   # 既有 CSV 無 Source 欄時的沿用值（與 update_stocks.py 相同）

PRICE_LIMIT_PCT = 10.5      # 台股單日漲跌停 ±10%（留 0.5% 緩衝）；超過＝缺交易日或除權息/減資
ZERO_RANGE_LOCK_PCT = 9.0   # 零振幅一字線唯有接近漲跌停才合理，否則視為 OHLC 損毀
SETTLE_HOUR = 14            # 13:30 收盤；14:00 前抓到的當日棒是盤中未收盤的半成品棒
MAX_BACKFILL_MONTHS = 6     # 每檔官方補抓的月份上限（避免對官方站台過量請求）
MAX_INDEX_FILL_MONTHS = 12  # 指數官方補抓的月份上限

WARNINGS = []               # 全域降級記錄；最後統一列印並寫入品質報告


def _warn(msg):
    """任何降級/失敗都要看得見：即時列印並收集到品質報告。"""
    print(f"    [warn] {msg}")
    WARNINGS.append(msg)


def _canon_source(val, default="UNKNOWN"):
    """把來源字串正規化成 update_stocks.py SOURCE_RANK 認得的值（TWSE/TPEX/_LEGACY/YAHOO/UNKNOWN）。"""
    s = "" if val is None else str(val).strip()
    if not s or s.lower() == "nan":
        return default
    if s in SOURCE_RANK:
        return s
    u = s.upper()
    if u in SOURCE_RANK:
        return u
    if "TPEX" in u or "櫃買" in s:
        return "TPEX"
    if "TWSE" in u or "FMTQIK" in u or "證交所" in s:
        return "TWSE"
    if "YAHOO" in u:
        return "YAHOO"
    return default


def _bar_source(bar, default="UNKNOWN"):
    """單列的 Source：優先用明確標好的 Source 欄，否則由內部 _src 標籤推回。"""
    return _canon_source(bar.get("Source") or bar.get("_src"), default)


def _num(x):
    """把官方報表的字串（含千分位、'--'、'X0.00'）轉成 float；不可轉則 None。"""
    if x is None:
        return None
    if isinstance(x, (int, float)):
        return None if x != x else float(x)   # NaN（CSV 空欄）→ None，不可硬轉成數字
    s = str(x).replace(",", "").replace("+", "").strip()
    if s in ("", "--", "---", "N/A", "null"):
        return None
    try:
        return float(s)
    except Exception:
        return None


def _minguo_to_ad(s):
    """'115/08/20' 或 '1150820' → '2026/08/20'；不可解析則 None。"""
    if not s:
        return None
    s = str(s).strip()
    try:
        if "/" in s:
            y, m, d = s.split("/")
        elif len(s) == 7 and s.isdigit():
            y, m, d = s[:3], s[3:5], s[5:7]
        elif len(s) == 8 and s.isdigit():   # 已是西元 YYYYMMDD
            return f"{s[:4]}/{s[4:6]}/{s[6:8]}"
        else:
            return None
        return f"{int(y) + 1911}/{int(m):02d}/{int(d):02d}"
    except Exception:
        return None


def _months_between(d1, d2):
    """d1,d2 為 'YYYY/MM/DD' → ['YYYYMM', ...]（含頭含尾）。"""
    y1, m1 = int(d1[:4]), int(d1[5:7])
    y2, m2 = int(d2[:4]), int(d2[5:7])
    out, y, m = [], y1, m1
    while (y, m) <= (y2, m2):
        out.append(f"{y}{m:02d}")
        m += 1
        if m > 12:
            m, y = 1, y + 1
    return out


# ---------------------------------------------------------------- 逐列驗證（TECH-5 / FETCH-2）

def _is_unsettled(date_str):
    """當日棒且尚未過結算時點（14:00）→ 盤中半成品棒；或未來日期。"""
    now = datetime.now()
    today = now.strftime("%Y/%m/%d")
    if date_str > today:
        return True, "未來日期"
    if date_str == today and now.hour < SETTLE_HOUR:
        return True, f"盤中未收盤棒(現在 {now:%H:%M} < {SETTLE_HOUR}:00)"
    return False, ""


def _bar_issues(bar, prev_close, is_index=False):
    """單列合理性檢查。回傳 (verdict, reasons)：
       'drop'   = 整列不可用，丟棄（價格缺值／盤中棒／OHLC 不一致／零量零振幅幽靈棒）
       'repair' = 價格可用但可疑，保留並標記＋交給官方來源補正
       'ok'     = 通過
    """
    o, h, l, c, v = bar.get("Open"), bar.get("High"), bar.get("Low"), bar.get("Close"), bar.get("Volume")
    d = bar.get("Date")
    reasons = []

    if c is None:
        return "drop", ["來源缺值(無收盤價)"]
    uns, why = _is_unsettled(d)
    if uns:
        return "drop", [why]

    if is_index:
        # 指數的官方補列僅有收盤價；OHLC 不完整可接受，但要標示
        if any(x is None for x in (o, h, l)):
            reasons.append("僅收盤價(來源不含OHLC)")
        else:
            if h < l or h + 1e-9 < max(o, c) or l - 1e-9 > min(o, c):
                return "drop", ["OHLC不一致(high/low 未包住 open/close)"]
            if abs(h - l) < 1e-9 and (v is None or v <= 0):
                return "drop", ["零量零振幅幽靈棒(以前收填補)"]
        if v is None or v <= 0:
            reasons.append("成交量缺值/為0")
        return ("repair" if reasons else "ok"), reasons

    if any(x is None for x in (o, h, l)):
        return "drop", ["來源缺值(OHLC 不完整)"]
    if h < l or h + 1e-9 < max(o, c) or l - 1e-9 > min(o, c):
        return "drop", ["OHLC不一致(high/low 未包住 open/close)"]

    zero_range = abs(h - l) < 1e-9
    no_vol = (v is None) or (v <= 0)
    if zero_range and no_vol:
        # 2026/07/10 那批「O=H=L=C=前收、量=0」的幽靈棒
        return "drop", ["零量零振幅幽靈棒(以前收填補)"]

    chg = None
    if prev_close:
        try:
            chg = (c / prev_close - 1) * 100
        except Exception:
            chg = None

    if zero_range and (chg is None or abs(chg) < ZERO_RANGE_LOCK_PCT):
        # 2024/11/20 那批：O=H=L=C 但量正常、漲跌幅遠離漲跌停 → 只剩收盤價的損毀列
        reasons.append(f"零振幅但有成交量(當日漲跌 {('%+.2f%%' % chg) if chg is not None else '未知'}"
                       f"，非漲跌停鎖死 → 疑似OHLC損毀)")
    if no_vol:
        reasons.append("成交量缺值/為0(有振幅)")
    if chg is not None and abs(chg) > PRICE_LIMIT_PCT:
        reasons.append(f"單日變動 {chg:+.2f}% 超過台股 ±{PRICE_LIMIT_PCT}% 上限"
                       f"(疑似缺交易日；亦可能為除權息/減資，須人工核對)")
    return ("repair" if reasons else "ok"), reasons


def validate_rows(rows, is_index=False, calendar=None, calendar_months=None):
    """逐列驗證（依日期由舊到新，漲跌幅以前一保留列為基準）。
    calendar/calendar_months 有給時，另外剔除「不在官方交易日曆」的列（幽靈交易日）。
    回傳 (clean_rows, issues)。"""
    rows = sorted([r for r in rows if r.get("Date")], key=lambda r: r["Date"])
    clean, issues, prev_close = [], [], None
    for b in rows:
        d = b["Date"]
        if calendar and calendar_months and d[:4] + d[5:7] in calendar_months and d not in calendar:
            issues.append({"日期": d, "處置": "丟棄", "原因": ["非官方交易日(TWSE FMTQIK 日曆無此日)"]})
            continue
        verdict, reasons = _bar_issues(b, prev_close, is_index=is_index)
        if verdict == "drop":
            issues.append({"日期": d, "處置": "丟棄", "原因": reasons})
            continue
        if verdict == "repair":
            issues.append({"日期": d, "處置": "標記(待官方補正)", "原因": reasons,
                           "來源": b.get("_src", "Yahoo")})
        clean.append(b)
        prev_close = b["Close"]
    return clean, issues


# ---------------------------------------------------------------- 來源：Yahoo

def _get_json(url, verify=True, tries=3, timeout=25, quiet=False):
    last = ""
    for _ in range(tries):
        try:
            r = requests.get(url, headers=HEADERS, timeout=timeout, verify=verify)
            if r.status_code == 200:
                return r.json()
            last = f"HTTP {r.status_code}"
        except Exception as e:
            last = str(e)[:90]
        time.sleep(2)
    if not quiet:
        _warn(f"取得失敗 {url[:95]}：{last}")
    return None


def yahoo_rows(symbol, rng="2y"):
    """回傳 (rows, err)。**不再把 None 靜默 continue**：價格 None 的列以 None 保留，
    由 validate_rows 記為『來源缺值』並觸發官方回補（FETCH-2）。"""
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}?range={rng}&interval=1d"
    last = ""
    for attempt in range(3):
        try:
            r = requests.get(url, headers=HEADERS, timeout=20)
            if r.status_code != 200:
                last = f"HTTP {r.status_code}"
            else:
                res = r.json()['chart']['result'][0]
                ts = res.get('timestamp')
                if not ts:
                    return [], f"{symbol} 來源已無資料(回傳無 timestamp，代號可能已停止提供)"
                q = res['indicators']['quote'][0]
                rows = []
                for i in range(len(ts)):
                    def _v(key):
                        arr = q.get(key) or []
                        val = arr[i] if i < len(arr) else None
                        return None if val is None else round(float(val), 2)
                    vol = (q.get('volume') or [None] * len(ts))[i]
                    rows.append({
                        'Date': datetime.fromtimestamp(ts[i]).strftime("%Y/%m/%d"),
                        'Open': _v('open'), 'High': _v('high'), 'Low': _v('low'), 'Close': _v('close'),
                        'Volume': None if vol is None else int(vol),   # 缺量保留 None，不再寫成 0
                        '_src': 'Yahoo', 'Source': 'YAHOO'})
                if rows:
                    return rows, None
                last = "回傳 0 列"
        except Exception as e:
            last = str(e)[:90]
        time.sleep(2)
    return [], f"{symbol} 抓取失敗：{last}"


def yahoo(symbol, rng="2y"):
    """相容舊介面：回傳通過驗證的 DataFrame（失敗回 None）。"""
    rows, err = yahoo_rows(symbol, rng)
    if err:
        _warn(err)
    if not rows:
        return None
    clean, issues = validate_rows(rows, is_index=symbol.startswith("^"))
    for it in issues:
        if it["處置"] == "丟棄":
            _warn(f"{symbol} {it['日期']} 丟棄：{'；'.join(it['原因'])}")
    if not clean:
        return None
    return pd.DataFrame([dict({k: b.get(k) for k in CSV_COLS[:-1]},
                              Source=_bar_source(b, LEGACY_SOURCE)) for b in clean])


# ---------------------------------------------------------------- 來源：官方交易日曆（TWSE FMTQIK）

def _cal_path():
    return os.path.join(INDEX_DIR, "trading_calendar.json")


def _load_cal_cache():
    try:
        with open(_cal_path(), encoding="utf-8") as f:
            return json.load(f).get("months", {})
    except Exception:
        return {}


def _save_cal_cache(months):
    try:
        os.makedirs(INDEX_DIR, exist_ok=True)
        with open(_cal_path(), "w", encoding="utf-8") as f:
            json.dump({"說明": "TWSE FMTQIK 官方交易日曆＋加權指數官方收盤(成交股數單位:股)",
                       "更新時間": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                       "months": months}, f, ensure_ascii=False, indent=1)
    except Exception as e:
        _warn(f"交易日曆快取寫入失敗：{e}")


def _fmtqik_month(ym):
    """TWSE FMTQIK 月報 → {'YYYY/MM/DD': {'close': 加權指數收盤, 'vol': 成交股數}}。"""
    j = _get_json(f"https://www.twse.com.tw/rwd/zh/afterTrading/FMTQIK?date={ym}01&response=json")
    if not j or j.get("stat") != "OK":
        return None
    out = {}
    for row in j.get("data", []):
        d = _minguo_to_ad(row[0])
        if not d:
            continue
        out[d] = {"close": _num(row[4]), "vol": _num(row[1])}
    return out or None


def market_calendar(start_date, end_date):
    """官方交易日曆＋加權指數官方收盤。回傳 (dates:set, twii:dict, ok_months:set, bad_months:list)。"""
    cache = _load_cal_cache()
    cur_ym = datetime.now().strftime("%Y%m")
    dates, twii, ok, bad = set(), {}, set(), []
    for ym in _months_between(start_date, end_date):
        rec = cache.get(ym)
        if not rec or ym >= cur_ym:      # 當月尚未結束 → 一律重抓
            fresh = _fmtqik_month(ym)
            time.sleep(1.0)
            if fresh:
                rec = fresh
                cache[ym] = fresh
        if not rec:
            bad.append(ym)
            continue
        ok.add(ym)
        for d, v in rec.items():
            dates.add(d)
            twii[d] = v
    _save_cal_cache(cache)
    if bad:
        _warn(f"官方交易日曆缺月份 {','.join(bad)}（該區間不做缺日/幽靈日判定）")
    return dates, twii, ok, bad


# ---------------------------------------------------------------- 來源：官方個股月報（補漏/補正）

def _twse_stock_month(code, ym):
    j = _get_json(f"https://www.twse.com.tw/exchangeReport/STOCK_DAY?response=json&date={ym}01&stockNo={code}")
    if not j or j.get("stat") != "OK":
        return {}
    out = {}
    for row in j.get("data", []):
        d = _minguo_to_ad(row[0])
        o, h, l, c, v = _num(row[3]), _num(row[4]), _num(row[5]), _num(row[6]), _num(row[1])
        if not d or None in (o, h, l, c):
            continue
        out[d] = {"Date": d, "Open": round(o, 2), "High": round(h, 2), "Low": round(l, 2),
                  "Close": round(c, 2), "Volume": None if v is None else int(v),
                  "_src": "TWSE官方", "Source": "TWSE"}
    return out


def _tpex_stock_month(code, ym):
    d0 = f"{ym[:4]}/{ym[4:6]}/01"
    j = _get_json(f"https://www.tpex.org.tw/www/zh-tw/afterTrading/tradingStock"
                  f"?code={code}&date={d0}&response=json", verify=False)
    tables = (j or {}).get("tables") or []
    rows = tables[0].get("data", []) if tables else []
    out = {}
    for row in rows:
        d = _minguo_to_ad(row[0])
        o, h, l, c, v = _num(row[3]), _num(row[4]), _num(row[5]), _num(row[6]), _num(row[1])
        if not d or None in (o, h, l, c):
            continue
        out[d] = {"Date": d, "Open": round(o, 2), "High": round(h, 2), "Low": round(l, 2),
                  "Close": round(c, 2),
                  "Volume": None if v is None else int(v * 1000),   # TPEx 為「張」→ 股
                  "_src": "TPEx官方", "Source": "TPEX"}
    return out


def _fit_ratio(month_rows, ref_close, target_date):
    """官方報表是「未還原價」，本地序列是 Yahoo「還原價」（減資/分割會整段位移，如台揚 2025/10 減資）。
    以 target_date 前後最近的重疊交易日估換算比例；比例不一致（>2%）則視為無法安全換算。
    回傳 (ratio, 參考日)；無法估計回 (None, [])。"""
    cands = sorted(set(month_rows) & set(ref_close or {}))
    if not cands:
        return None, []
    use = [d for d in cands if d < target_date][-3:] + [d for d in cands if d > target_date][:3]
    ratios = []
    for d in use:
        oc, rc = month_rows[d].get("Close"), ref_close.get(d)
        if oc and rc:
            ratios.append(rc / oc)
    if not ratios:
        return None, []
    lo, hi = min(ratios), max(ratios)
    if lo <= 0 or (hi - lo) / lo > 0.02:
        return None, use
    return sum(ratios) / len(ratios), use


def _apply_ratio(bar, ratio):
    b = dict(bar)
    for k in ("Open", "High", "Low", "Close"):
        if b.get(k) is not None:
            b[k] = round(b[k] * ratio, 2)
    if b.get("Volume"):
        b["Volume"] = int(b["Volume"] / ratio)   # 減資後股數同比減少，量須反向換算
    return b


def official_stock_rows(name, code, dates, ref_close=None):
    """向官方逐月抓取指定日期的正確 K 棒（補漏 FETCH-2 / 補正 TECH-5 損毀列）。
    官方值一律先與本地序列對基準；對不上就不寫入（回報 rejected），不硬塞。
    回傳 (got, rejected)。"""
    if not dates:
        return {}, []
    months = sorted({d[:4] + d[5:7] for d in dates}, reverse=True)
    if len(months) > MAX_BACKFILL_MONTHS:
        _warn(f"{name} 待官方補正月份 {len(months)} 個，超過上限 {MAX_BACKFILL_MONTHS}，"
              f"本次只處理最近 {MAX_BACKFILL_MONTHS} 個月：{','.join(months[:MAX_BACKFILL_MONTHS])}")
        months = months[:MAX_BACKFILL_MONTHS]
    got, rejected = {}, []
    for ym in months:
        m = _tpex_stock_month(code, ym) if name in TPEX_LIST else _twse_stock_month(code, ym)
        time.sleep(1.2)
        if not m:
            _warn(f"{name} {ym} 官方月報無資料，該月缺口無法補")
            continue
        for d in sorted([x for x in dates if x[:4] + x[5:7] == ym]):
            b = m.get(d)
            if not b:
                continue
            if ref_close:
                ratio, used = _fit_ratio(m, ref_close, d)
                if ratio is None:
                    rejected.append(d)
                    _warn(f"{name} {d} 官方值與本地序列基準對不上（重疊日 {len(used)} 個），"
                          f"未寫入以免混入不同還原基準，該日維持缺漏")
                    continue
                if abs(ratio - 1) > 0.005:
                    b = _apply_ratio(b, ratio)
                    b["_src"] += f"(未還原價，依鄰日比例 {ratio:.4f} 換算為還原基準)"
                    _warn(f"{name} {d} 官方為未還原價（減資/分割），已依鄰日比例 {ratio:.4f} 換算")
            got[d] = b
    return got, rejected


# ---------------------------------------------------------------- 既有 CSV 讀寫

def _read_csv_rows(path):
    """讀本地 CSV → [{'Date','Open',...,'Source'}]，空值為 None。
    Source 為 update_stocks.py 寫入的來源標記；舊檔沒有此欄時沿用 '_LEGACY'（不可清空，
    否則官方量價在下次 update_stocks 去重時會被 Yahoo 偏低量蓋掉）。"""
    if not os.path.exists(path):
        return []
    try:
        df = pd.read_csv(path, encoding="utf-8-sig")
    except Exception as e:
        _warn(f"讀取失敗 {path}：{e}")
        return []
    rows = []
    for _, r in df.iterrows():
        d = str(r.get("Date", "")).strip()
        if not d or d.lower() == "nan":
            continue
        bar = {"Date": d, "_src": "本地既有"}
        for k in ("Open", "High", "Low", "Close"):
            v = _num(r.get(k))
            bar[k] = None if v is None else round(v, 2)
        v = _num(r.get("Volume"))
        bar["Volume"] = None if v is None else int(v)
        bar["Source"] = _canon_source(r.get("Source"), LEGACY_SOURCE)
        rows.append(bar)
    return rows


def existing_last_close(name, code):
    path = os.path.join(BASE_DIR, name, f"{name}_{code}_近期K線.csv")
    rows = _read_csv_rows(path)
    if not rows:
        return None, None
    last = max(rows, key=lambda b: b["Date"])
    return last["Date"], last["Close"]


def _rows_to_df(rows):
    """輸出 DataFrame（最新在最上，欄位＝CSV_COLS 七欄含 Source）。
    Volume 以字串輸出，缺值寫空白、不寫 0；Source 依 update_stocks.py 的標籤集寫回。"""
    df = pd.DataFrame([dict({k: b.get(k) for k in CSV_COLS[:-1]}, Source=_bar_source(b))
                       for b in rows])
    if df.empty:
        return pd.DataFrame(columns=CSV_COLS)
    unknown = int((df["Source"] == "UNKNOWN").sum())
    if unknown:
        _warn(f"有 {unknown} 列無法判定 Source（寫入 UNKNOWN，SOURCE_RANK 最低），請人工核對來源")
    df["Volume"] = ["" if (v is None or pd.isna(v)) else str(int(v)) for v in df["Volume"]]
    df["_dt"] = pd.to_datetime(df["Date"], errors="coerce")
    df = df.dropna(subset=["_dt"]).sort_values("_dt", ascending=False).drop(columns="_dt")
    return df[CSV_COLS]


def save_stock(name, code, rows):
    outdir = os.path.join(BASE_DIR, name)
    os.makedirs(outdir, exist_ok=True)
    path = os.path.join(outdir, f"{name}_{code}_近期K線.csv")
    if os.path.exists(path):     # 備份
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copy2(path, os.path.join(BACKUP_DIR, f"{name}_{code}_近期K線.bak.csv"))
    df = _rows_to_df(rows)
    df.to_csv(path, index=False, encoding="utf-8-sig")
    return len(df)


# ---------------------------------------------------------------- 指數（FETCH-4）

def _existing_index(label):
    return {b["Date"]: b for b in _read_csv_rows(os.path.join(INDEX_DIR, f"{label}.csv"))}


def _tpex_index_month(ym):
    """TPEx 官方『日成交量值指數』月報 → 櫃買指數收盤（無 OHLC）。"""
    d0 = f"{ym[:4]}/{ym[4:6]}/01"
    j = _get_json(f"https://www.tpex.org.tw/www/zh-tw/afterTrading/tradingIndex"
                  f"?date={d0}&response=json", verify=False)
    tables = (j or {}).get("tables") or []
    rows = tables[0].get("data", []) if tables else []
    out = {}
    for row in rows:
        d = _minguo_to_ad(row[0])
        c, v = _num(row[4]), _num(row[1])
        if not d or c is None:
            continue
        out[d] = {"Date": d, "Open": None, "High": None, "Low": None, "Close": round(c, 2),
                  "Volume": None if v is None else int(v),
                  "_src": "TPEx官方(日成交量值指數)", "Source": "TPEX"}
    return out


def _tpex_index_ohlc_recent():
    """TPEx OpenAPI tpex_index：近約 16 個交易日的櫃買指數 OHLC。"""
    j = _get_json("https://www.tpex.org.tw/openapi/v1/tpex_index", verify=False)
    out = {}
    for r in (j or []):
        d = _minguo_to_ad(r.get("Date"))
        o, h, l, c = _num(r.get("Open")), _num(r.get("High")), _num(r.get("Low")), _num(r.get("Close"))
        if not d or c is None:
            continue
        out[d] = {"Date": d, "Open": o, "High": h, "Low": l, "Close": round(c, 2),
                  "Volume": None, "_src": "TPEx OpenAPI tpex_index", "Source": "TPEX"}
    return out


def _merge_index(old, new):
    """欄位級合併：新來源有值才覆蓋（Volume 為 0/None 視為無資訊，不覆蓋既有值）。
    Source 隨「實際被採用的欄位」走：新來源有貢獻才改標新來源，否則沿用既有標記（不清空）。"""
    merged = {d: dict(b) for d, b in old.items()}
    for d, b in new.items():
        cur = merged.get(d, {"Date": d})
        cur["Date"] = d
        took = d not in merged
        for k in ("Open", "High", "Low", "Close"):
            if b.get(k) is not None:
                cur[k] = b[k]
                took = True
            cur.setdefault(k, None)
        v = b.get("Volume")
        if v:
            cur["Volume"] = int(v)
            took = True
        cur.setdefault("Volume", None)
        cur["_src"] = b.get("_src", cur.get("_src", ""))
        cur["Source"] = _bar_source(b, LEGACY_SOURCE) if took \
            else _canon_source(cur.get("Source"), LEGACY_SOURCE)
        merged[d] = cur
    return merged


def update_index(label, calendar, twii_official, cal_months):
    """更新單一指數檔並回傳狀態字典（含資料日、來源、缺漏交易日）。**抓不到不再沉默保留舊檔**。"""
    old = _existing_index(label)
    sources, new = [], {}

    if label == "TWII":
        rows, err = yahoo_rows("^TWII")
        if err:
            _warn(err)
        else:
            sources.append("Yahoo ^TWII")
        clean, _iss = validate_rows(rows, is_index=True)
        new = {b["Date"]: b for b in clean}
        # 官方（FMTQIK）補正/補漏：僅收盤價，成交量單位與 Yahoo 不同故不寫入
        added = 0
        for d, v in (twii_official or {}).items():
            if v.get("close") is None:
                continue
            if d not in new:
                new[d] = {"Date": d, "Open": None, "High": None, "Low": None,
                          "Close": round(v["close"], 2), "Volume": None,
                          "_src": "TWSE FMTQIK官方", "Source": "TWSE"}
                added += 1
        if added:
            sources.append(f"TWSE FMTQIK官方補 {added} 日")
        if not sources:
            _warn("TWII 兩個來源皆失敗")
    else:  # TPEX：^TWOII 已停止提供，改用 TPEx 官方
        have = set(old)
        latest_cal = max(calendar) if calendar else datetime.now().strftime("%Y/%m/%d")
        start = min(have) if have else min(calendar) if calendar else latest_cal
        missing = sorted([d for d in calendar if d not in have and d >= start])
        months = sorted({d[:4] + d[5:7] for d in missing}, reverse=True)
        if not have:
            months = sorted(set(_months_between(start, latest_cal)), reverse=True)
        if len(months) > MAX_INDEX_FILL_MONTHS:
            _warn(f"TPEX 待補月份 {len(months)} 個，本次只處理最近 {MAX_INDEX_FILL_MONTHS} 個")
            months = months[:MAX_INDEX_FILL_MONTHS]
        got = {}
        for ym in months:
            m = _tpex_index_month(ym)
            time.sleep(0.8)
            got.update(m)
        if got:
            sources.append(f"TPEx官方 tradingIndex（{len(months)} 個月／{len(got)} 日）")
        ohlc = _tpex_index_ohlc_recent()
        if ohlc:
            sources.append(f"TPEx OpenAPI tpex_index（近 {len(ohlc)} 日 OHLC）")
            got = _merge_index(got, ohlc)
        new = got
        if not sources:
            _warn("TPEX 官方來源全部失敗（Yahoo ^TWOII 已停止提供，無備援）")

    merged = _merge_index(old, new)
    clean, issues = validate_rows(list(merged.values()), is_index=True,
                                  calendar=calendar, calendar_months=cal_months)
    status = {"來源": sources or ["(全部失敗)"], "更新時間": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}

    if not clean:
        status.update({"狀態": "FAIL", "資料日": None, "筆數": 0,
                       "說明": "本次未取得任何可用列；既有檔案保留未動（若存在）"})
        _mark_stale(label, "本次抓取失敗，指數資料未更新")
        return status

    os.makedirs(INDEX_DIR, exist_ok=True)
    path = os.path.join(INDEX_DIR, f"{label}.csv")
    if os.path.exists(path):
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copy2(path, os.path.join(BACKUP_DIR, f"{label}.bak.csv"))
    _rows_to_df(clean).to_csv(path, index=False, encoding="utf-8-sig")

    last_date = max(b["Date"] for b in clean)
    have = {b["Date"] for b in clean}
    cal_in_range = sorted([d for d in calendar if d >= min(have)])
    gaps = [d for d in cal_in_range if d not in have]
    latest_cal = cal_in_range[-1] if cal_in_range else last_date
    lag = len([d for d in cal_in_range if d > last_date])
    status.update({
        "狀態": "OK" if lag == 0 else "STALE",
        "資料日": last_date, "官方最新交易日": latest_cal, "落後交易日": lag,
        "筆數": len(clean),
        "缺漏交易日": gaps[-15:], "缺漏交易日數": len(gaps),
        "丟棄/標記列": issues[-15:],
    })
    if lag > 0:
        _mark_stale(label, f"資料日 {last_date}，較官方最新交易日 {latest_cal} 落後 {lag} 個交易日")
        _warn(f"【指數過期】{label} 資料日 {last_date}，落後官方 {lag} 個交易日 → "
              f"以此算出的 RS／大盤位階僅供參考，不得作為加碼依據")
    else:
        _clear_stale(label)
    if gaps:
        _warn(f"{label} 指數仍缺 {len(gaps)} 個官方交易日（最近：{'、'.join(gaps[-5:])}）")
    return status


def _mark_stale(label, reason):
    try:
        os.makedirs(INDEX_DIR, exist_ok=True)
        with open(os.path.join(INDEX_DIR, f"{label}.stale"), "w", encoding="utf-8") as f:
            f.write(f"{datetime.now():%Y-%m-%d %H:%M:%S} {label} 指數資料過期/失敗：{reason}\n"
                    f"下游（collect_stock_data 的大盤位階／Mansfield RS）引用時須標示落後天數並降權。\n")
    except Exception as e:
        _warn(f"{label}.stale 標記寫入失敗：{e}")


def _clear_stale(label):
    p = os.path.join(INDEX_DIR, f"{label}.stale")
    if os.path.exists(p):
        try:
            os.remove(p)
        except Exception:
            pass


def _write_index_status(status):
    try:
        os.makedirs(INDEX_DIR, exist_ok=True)
        with open(os.path.join(INDEX_DIR, "index_status.json"), "w", encoding="utf-8") as f:
            json.dump(status, f, ensure_ascii=False, indent=1)
    except Exception as e:
        _warn(f"index_status.json 寫入失敗：{e}")


# ---------------------------------------------------------------- 主流程

def process_stock(name, code, calendar, cal_months):
    """回傳 (rows_written, date_range, record)；失敗時 rows_written 為 'FAIL'。"""
    sym = f"{code}.TWO" if name in TPEX_LIST else f"{code}.TW"
    rec = {"股名": name, "代碼": code, "來源": sym}
    raw, err = yahoo_rows(sym)
    if err:
        _warn(err)
    if not raw:
        old_d, _ = existing_last_close(name, code)
        rec.update({"狀態": "FAIL", "說明": f"抓取失敗，既有 CSV 未更動（既有資料日 {old_d or '無'}）"})
        return "FAIL", None, rec

    clean, issues = validate_rows(raw, calendar=calendar, calendar_months=cal_months)
    if not clean:
        rec.update({"狀態": "FAIL", "說明": "所有列都未通過驗證", "驗證": issues[:20]})
        return "FAIL", None, rec

    yah = {b["Date"]: b for b in clean}
    lo, hi = min(yah), max(yah)

    # 既有本地列（日常流程以 TWSE/TPEx 官方為主來源，成交量為官方值）也走同一套驗證
    old_rows = _read_csv_rows(os.path.join(BASE_DIR, name, f"{name}_{code}_近期K線.csv"))
    old_ok, old_flag, old_bad = {}, {}, {}
    prev_c = None
    for b in sorted(old_rows, key=lambda x: x["Date"]):
        v, rs = _bar_issues(b, prev_c)
        if v == "drop":
            old_bad[b["Date"]] = rs
            continue
        (old_flag if v == "repair" else old_ok)[b["Date"]] = b
        prev_c = b["Close"]
    local_use = dict(old_ok)
    local_use.update(old_flag)

    # 還原基準檢查：Yahoo 遇減資/分割會整段重算還原價，與本地舊基準衝突時必須整段換掉
    overlap = sorted(set(local_use) & set(yah))
    mismatch = [d for d in overlap
                if local_use[d].get("Close") and yah[d].get("Close")
                and abs(yah[d]["Close"] / local_use[d]["Close"] - 1) > 0.02]
    basis_shift = bool(overlap) and len(mismatch) > max(3, 0.05 * len(overlap))
    if basis_shift:
        _warn(f"{name} 本地與 Yahoo 有 {len(mismatch)}/{len(overlap)} 日收盤差異 >2%"
              f"（疑為減資/分割還原基準已變更）→ 本次改以 Yahoo 全段為準")

    # 合併原則（CLAUDE.md 抓取優先序：官方 > Yahoo）：
    #   既有列通過驗證即保留（其量價來自官方），Yahoo 僅用來「補缺日」與「換掉不合格列」。
    by_date = {}
    if not basis_shift:
        by_date.update({d: b for d, b in local_use.items() if d >= lo})
    for d, b in yah.items():
        if basis_shift or d not in by_date:
            by_date[d] = b

    # 需向官方補正/補漏的日期（僅限官方日曆確有交易的日子）
    need = {i["日期"] for i in issues if i["處置"] != "丟棄" or "來源缺值" in "".join(i["原因"])}
    need |= set(old_bad) | set(old_flag)                     # 既有列不合格/可疑 → 官方裁決
    need |= set(mismatch) if not basis_shift else set()      # 兩來源價格歧異 → 官方裁決
    need |= {d for d in calendar if lo <= d <= hi and d not in by_date}
    need = {d for d in need if d in calendar}
    ref_close = {b["Date"]: b["Close"] for b in clean if b.get("Close")}
    patched, rejected = official_stock_rows(name, code, need, ref_close) if need else ({}, [])
    applied, checked_only = [], []
    for d, b in patched.items():
        # 既有本地列已通過驗證者不覆蓋（官方月報的量為「張」精度較粗，且本地量本就取自官方）
        if (not basis_shift) and d in old_ok and d not in mismatch:
            checked_only.append(d)
            continue
        by_date[d] = b
        applied.append(d)

    # Yahoo 2y 視窗之前的既有歷史必須保留（否則每跑一次就截斷一段）
    # 基準重整時，視窗前的舊列仍是舊還原基準，須以重疊日比例換算，否則會出現斷層
    pre_ratio, pre_note = 1.0, ""
    if basis_shift and overlap:
        rr = [yah[d]["Close"] / local_use[d]["Close"] for d in overlap
              if local_use[d].get("Close") and yah[d].get("Close")]
        if rr and min(rr) > 0 and (max(rr) - min(rr)) / min(rr) <= 0.02:
            pre_ratio = sum(rr) / len(rr)
            pre_note = f"視窗前既有歷史已依重疊日比例 {pre_ratio:.4f} 換算為新還原基準"
        else:
            pre_note = "⚠視窗前既有歷史仍為舊還原基準（重疊日比例不一致，無法安全換算），須人工重抓"
        _warn(f"{name} {pre_note}")

    kept_old, fallback_dates = [], []
    for d, b in local_use.items():
        if d < lo:
            kept_old.append(_apply_ratio(b, pre_ratio) if abs(pre_ratio - 1) > 0.005 else b)
        elif (not basis_shift) and d not in by_date and d in calendar:
            kept_old.append(b)          # 新來源與官方補抓都沒有 → 沿用既有列並標記
            fallback_dates.append(d)
    if fallback_dates:
        _warn(f"{name} 有 {len(fallback_dates)} 日沿用既有本地列（新來源缺、官方補抓失敗）："
              f"{'、'.join(fallback_dates[-5:])}")

    final, issues2 = validate_rows(kept_old + list(by_date.values()),
                                   calendar=calendar, calendar_months=cal_months)
    have = {b["Date"] for b in final}
    still_missing = sorted([d for d in calendar if lo <= d <= hi and d not in have])

    # 健檢：與既有 CSV 在最新重疊日的收盤比對（差異 >2% 可能是還原/來源差異）
    health = ""
    old_date, old_close = existing_last_close(name, code)
    if old_date and old_close and old_date in by_date and by_date[old_date].get("Close"):
        ynew = float(by_date[old_date]["Close"])
        diff = abs(ynew / old_close - 1) * 100
        if diff > 2:
            health = f"健檢:{old_date} 既有{old_close} vs 新{ynew}({diff:.1f}%)"
            _warn(f"{name} {health}")

    rows = save_stock(name, code, final)
    rng = f"{min(have)}~{max(have)}"

    src_mix = {}
    for b in final:
        s = _bar_source(b)
        src_mix[s] = src_mix.get(s, 0) + 1

    rec.update({
        "健檢": health,
        "狀態": "OK", "筆數": rows, "區間": rng,
        "來源組成": dict(sorted(src_mix.items(), key=lambda kv: -kv[1])),
        "Yahoo原始列": len(raw), "驗證後": len(clean),
        "官方補正/補漏日": sorted(applied),
        "官方已核對未變更": sorted(checked_only),
        "既有不合格列(丟棄)": {d: rs for d, rs in old_bad.items()},
        "既有可疑列(待官方裁決)": sorted(old_flag.keys()),
        "本地與Yahoo收盤歧異日(>2%)": mismatch,
        "還原基準重整(改以Yahoo全段為準)": basis_shift,
        "還原基準重整說明": pre_note,
        "官方值基準不符未採用": rejected,
        "官方補抓失敗仍缺": still_missing,
        "沿用既有本地列": fallback_dates,
        "來源丟棄列": [i for i in issues if i["處置"] == "丟棄"],
        "來源標記列": [i for i in issues if i["處置"] != "丟棄"],
        "丟棄": [i for i in issues2 if i["處置"] == "丟棄"],
        "標記(可疑)": [i for i in issues2 if i["處置"] != "丟棄"],
    })
    return rows, rng, rec


USAGE = """用法：
  python skills\\fetch_history.py                # 全部 19 檔 + 指數
  python skills\\fetch_history.py 力積電 台積電    # 指定數檔（指數仍會更新）
  python skills\\fetch_history.py --index-only   # 只更新 TWII/TPEX 指數，完全不動個股 K 線（供每日排程呼叫）
"""
INDEX_ONLY_FLAGS = {"--index-only", "--index_only", "--index"}
HELP_FLAGS = {"-h", "--help"}


def main():
    args = sys.argv[1:]
    flags = [a for a in args if a.startswith("-")]
    if set(flags) & HELP_FLAGS:
        print(USAGE)
        return 0
    unknown = sorted(set(flags) - INDEX_ONLY_FLAGS - HELP_FLAGS)
    if unknown:
        # 未知旗標一律拒跑：不可像舊版那樣忽略旗標、無聲改跑全 19 檔並覆寫 CSV
        print(f"[錯誤] 未知旗標 {'、'.join(unknown)}\n{USAGE}")
        return 2

    index_only = bool(set(flags) & INDEX_ONLY_FLAGS)
    named = [a for a in args if not a.startswith("-")]
    if index_only and named:
        print(f"[錯誤] --index-only 不可同時指定個股（收到 {'、'.join(named)}）\n{USAGE}")
        return 2
    targets = [] if index_only else (named or list(STOCKS.keys()))
    if index_only:
        print("=== fetch_history：--index-only（只更新 TWII/TPEX 指數，個股 K 線不動）===")
    else:
        print(f"=== fetch_history：補齊 2 年日K（{len(targets)} 檔）===")

    today = datetime.now().strftime("%Y/%m/%d")
    start = f"{datetime.now().year - 2}/{datetime.now().month:02d}/01"
    print("--- 取官方交易日曆（TWSE FMTQIK，逐月快取）---")
    calendar, twii_official, cal_months, bad_months = market_calendar(start, today)
    print(f"  官方交易日 {len(calendar)} 日，涵蓋月份 {len(cal_months)} 個"
          f"{'，缺月份 ' + ','.join(bad_months) if bad_months else ''}")

    summary, records = [], []
    for name in targets:
        if name not in STOCKS:
            print(f"  [skip] {name} 不在清單")
            continue
        code = STOCKS[name]
        rows, rng, rec = process_stock(name, code, calendar, cal_months)
        records.append(rec)
        if rows == "FAIL":
            print(f"  [FAIL] {name}({code}) 抓取失敗 → 既有 CSV 未更動")
            summary.append((name, code, "FAIL", None, rec.get("說明", "")))
        else:
            tags = []
            if rec["官方補正/補漏日"]:
                tags.append(f"官方補{len(rec['官方補正/補漏日'])}日")
            dropped = {i["日期"] for i in rec["來源丟棄列"]} | {i["日期"] for i in rec["丟棄"]}
            if dropped:
                tags.append(f"丟棄{len(dropped)}列")
            if rec["官方值基準不符未採用"]:
                tags.append(f"⚠官方基準不符{len(rec['官方值基準不符未採用'])}日未採用")
            if rec["標記(可疑)"]:
                tags.append(f"標記{len(rec['標記(可疑)'])}列")
            if rec["官方補抓失敗仍缺"]:
                tags.append(f"⚠仍缺{len(rec['官方補抓失敗仍缺'])}日")
            if rec.get("健檢"):
                tags.append("⚠" + rec["健檢"])
            print(f"  [OK] {name}({code}) {rows}筆 {rng}" + (f"  {'／'.join(tags)}" if tags else ""))
            summary.append((name, code, rows, rng, "／".join(tags)))
        time.sleep(1)

    # 指數
    print("--- 指數 ---")
    index_status = {"更新時間": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "官方最新交易日": max(calendar) if calendar else None,
                    "執行模式": "index-only" if index_only else "full"}
    for label in ("TWII", "TPEX"):
        st = update_index(label, calendar, twii_official, cal_months)
        index_status[label] = st
        print(f"  [指數] {label} 狀態={st.get('狀態')} 資料日={st.get('資料日')} "
              f"筆數={st.get('筆數')} 落後={st.get('落後交易日')}交易日 來源={'＋'.join(st.get('來源', []))}")
    _write_index_status(index_status)

    # 品質報告
    os.makedirs(QUALITY_DIR, exist_ok=True)
    # index-only 走另一個檔名，避免每日排程的指數巡檢覆蓋掉完整跑的個股品質報告
    qpath = os.path.join(QUALITY_DIR, f"fetch_history_品質報告_{datetime.now():%Y%m%d}"
                                      f"{'_indexonly' if index_only else ''}.json")
    try:
        with open(qpath, "w", encoding="utf-8") as f:
            json.dump({"執行時間": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                       "執行模式": "index-only" if index_only else "full",
                       "官方交易日曆缺月份": bad_months,
                       "指數": index_status, "個股": records, "警告": WARNINGS},
                      f, ensure_ascii=False, indent=1)
        print(f"品質報告：{qpath}")
    except Exception as e:
        _warn(f"品質報告寫入失敗：{e}")

    print("\n=== 完成 ===")
    fails = [s for s in summary if s[2] == "FAIL"]
    if fails:
        print("失敗:", ", ".join(f"{s[0]}" for s in fails))
    flagged = [r for r in records if r.get("官方補抓失敗仍缺") or r.get("標記(可疑)")
               or r.get("官方值基準不符未採用")]
    if flagged:
        print("需人工複核（仍缺交易日／可疑列）:")
        for r in flagged:
            if r.get("官方補抓失敗仍缺"):
                print(f"   {r['股名']} 仍缺 {r['官方補抓失敗仍缺']}")
            if r.get("官方值基準不符未採用"):
                print(f"   {r['股名']} 官方值基準不符、未採用 {r['官方值基準不符未採用']}")
            for it in r.get("標記(可疑)", [])[-3:]:
                print(f"   {r['股名']} {it['日期']}：{'；'.join(it['原因'])}")
    for label in ("TWII", "TPEX"):
        st = index_status.get(label, {})
        if st.get("狀態") != "OK":
            print(f"⚠ 指數 {label} 狀態 {st.get('狀態')}：資料日 {st.get('資料日')}／"
                  f"落後 {st.get('落後交易日')} 交易日 → 已寫 {label}.stale，下游引用須標示落後並降權")
    print(f"警告合計 {len(WARNINGS)} 則（明細見品質報告）")
    print("投資有風險，分析僅供參考。")
    # 退出碼固定 0（指數過期不是執行失敗，排程不該因此中斷）；
    # 過期與否請讀 data/_index/index_status.json 與 <label>.stale，這是既有且下游已在用的通道。
    return 0


if __name__ == "__main__":
    sys.exit(main() or 0)

# -*- coding: utf-8 -*-
"""fetch_market_data.py — 官方免費 OpenAPI 抓市場面資料（免 token、無第三方依賴），供 collect_stock_data 併入 ground。
來源：TWSE OpenAPI (openapi.twse.com.tw)、TDCC OpenAPI (openapi.tdcc.com.tw)。
抓（上市為主，上櫃月營收另抓 _O）：
  - PE / PB / 殖利率           (BWIBBU_ALL，日)
  - 融資餘額 / 融券餘額 / 券資比 (TWSE RWD MI_MARGN?date= 上市＋TPEx margin_balance 上櫃，日；
                                 兩者皆帶資料日→寫入「融資融券資料日」並標落後交易日，嚴禁當日值誤述)
  - 月營收 YoY / 累計YoY        (t187ap05_L 上市 + t187ap05_O 上櫃，月)
  - 千張大戶持股比% / 股東人數  (TDCC 集保股權分散 1-5，週)
  - 三率(毛利/營益/稅後淨利率)   (t187ap17_L 上市＋TPEx mopsfin_t187ap06_O_ci 上櫃自算，季)
  - 負債比% / 每股淨值          (t187ap07_L_ci 上市＋mopsfin_t187ap07_O_ci 上櫃，季)
  - 借券賣出餘額/占股本%        (TWT93U 上市＋TPEx sbl 上櫃，日；當日未公布自動退至最近有資料交易日)
  - 處置中/處置期間/措施/注意次數 (TWSE announcement punish+notice、TPEx bulletin disposal+attention；
                                 處置期為分盤撮合＋全額交割→量能不可比，寫入『量能可信度』供報告停用量能判定)
輸出：data/_market_cache/market_latest.json = {代碼: {...}, "_meta": {來源成功/失敗清單}}
      ＋當日備份 data/_market_cache/market_YYYYMMDD.json。
失敗可見性：每個子來源記錄成敗；有來源失敗即印 [Partial] 並回傳非 0（2=部分失敗、3=過半失敗、1=全掛不寫檔）。
未涵蓋(結構性缺口，由各檔「缺漏原因」欄逐項具名說明)：金融業(台企銀2834)三率/負債比——官方僅有當日增量的
t187ap07_L_basi、無累積表，且銀行業本應看資本適足率/逾放比；外資/投信持股比率月季趨勢(投信)、
產業循環領先指標(Book-to-Bill/稼動率/報價)——屬須網路研究項，非官方 OpenAPI 可得。
"""
import os
import re
import sys
import json
import time
import requests
from datetime import datetime, timedelta

requests.packages.urllib3.disable_warnings()
ROOT = r"D:\AI_Data\股市分析"
CACHE = os.path.join(ROOT, "data", "_market_cache")
H = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}
STOCKS = {
    "力成": "6239", "力積電": "6770", "士電": "1503", "仁寶": "2324",
    "元太": "8069", "光寶科": "2301", "至上": "8112", "鈊象": "3293",
    "台企銀": "2834", "台揚": "2314", "友達": "2409", "群聯": "8299",
    "德律": "3030", "漢翔": "2634", "時碩工業": "4566", "台積電": "2330",
    "亞光": "3019", "華新科": "2492", "盟立": "2464",
}
CODES = set(STOCKS.values())


TPEX_CODES = {"8069", "3293", "8299"}  # 元太/鈊象/群聯（上櫃，走 TPEx OpenAPI）
FINANCIAL_CODES = {"2834"}             # 台企銀：銀行業，一般業三率/負債比口徑與官方一般業端點皆不適用

# ── 失敗可見性：逐一記錄每個子來源本次成敗，main() 據此決定 [Partial]/回傳碼 ──────────
STATUS = {}


def _ok(name):
    STATUS[name] = True


def _fail(name, e):
    STATUS[name] = False
    print(f"[warn] {name}: {str(e)[:80]}")


def _note_gap(d, field, reason):
    """把「這欄為何沒有」寫進資料本身，避免下游只憑值是 None 去猜原因（會猜錯）。"""
    d.setdefault("缺漏原因", {})[field] = reason


def _get(url, verify=True):
    last = None
    for k in range(3):  # TPEx 端點偶爾連線不穩，重試
        try:
            return requests.get(url, headers=H, timeout=30, verify=verify).json()
        except Exception as e:
            last = e
            time.sleep(1.5)
    raise last


def _f(x):
    try:
        s = str(x).replace(',', '').strip()
        return float(s) if s not in ('', '-', '--') else None
    except Exception:
        return None


def _roc_slash(s):
    """民國日期(1150824 / 115/08/24) → 西元 'YYYY/MM/DD'；無法解析回 None。"""
    s = str(s or '').strip().replace('-', '/')
    digits = s.replace('/', '')
    if len(digits) == 7 and digits.isdigit():
        return f"{int(digits[:3]) + 1911}/{digits[3:5]}/{digits[5:7]}"
    if len(digits) == 8 and digits.isdigit():
        return f"{digits[:4]}/{digits[4:6]}/{digits[6:8]}"
    return None


def _stamp_lag(d, prefix, asof, note=None):
    """替一組日頻欄位蓋上資料日＋落後交易日數。資料日 ≠ 個股資料基準日(K線最新交易日)時，
    寫出明確時效警告，讓報告不得把 T-1 值當成當日值敘述（長線鐵則：籌碼看趨勢，但日期不得誤植）。"""
    d[f"{prefix}資料日"] = asof
    if asof is None:
        d[f"{prefix}資料日註記"] = note or "來源未提供資料日，時效不可考"
        return
    dates = [ys for _, ys in _recent_trade_dates(8)]
    if not dates or asof not in dates:
        return
    lag = dates.index(asof)
    d[f"{prefix}落後交易日"] = lag
    if lag > 0:
        d[f"{prefix}時效警告"] = f"為 T-{lag} 資料({asof})，非資料基準日({dates[0]})當日值"


def fetch_pepb(out):
    try:
        for row in _get("https://openapi.twse.com.tw/v1/exchangeReport/BWIBBU_ALL"):
            c = str(row.get('Code', '')).strip()
            if c in CODES:
                out.setdefault(c, {}).update({
                    "本益比PE": _f(row.get('PEratio')), "股價淨值比PB": _f(row.get('PBratio')),
                    "殖利率%": _f(row.get('DividendYield')), "PEPB日": row.get('Date')})
        _ok("pepb(twse)")
        # OpenAPI 曾於收盤後仍提供T-1；改查具日期的官方日報，不改標舊值日期。
        expected = _latest_trade_date()[1]
        if any(_roc_slash(out.get(c, {}).get('PEPB日')) != expected for c in CODES - TPEX_CODES):
            url = ('https://www.twse.com.tw/rwd/zh/afterTrading/BWIBBU_d'
                   f'?date={expected.replace("/", "")}&selectType=ALL&response=json')
            report = _get(url)
            if report.get('stat') == 'OK' and _roc_slash(report.get('date')) == expected:
                fields = report.get('fields', [])
                for values in report.get('data', []):
                    row = dict(zip(fields, values))
                    c = str(row.get('證券代號', '')).strip()
                    if c in CODES - TPEX_CODES:
                        out.setdefault(c, {}).update({
                            '本益比PE': _f(row.get('本益比')),
                            '股價淨值比PB': _f(row.get('股價淨值比')),
                            '殖利率%': _f(row.get('殖利率(%)')),
                            'PEPB日': report['date'], 'PEPB來源': url})
                _ok('pepb(twse-dated)')
            else:
                print(f'[warn] 官方PEPB日報尚無{expected}，保留OpenAPI原始日期')
    except Exception as e:
        _fail("pepb(twse)", e)
    try:  # 上櫃：TPEx PE/PB/殖利率
        for row in _get("https://www.tpex.org.tw/openapi/v1/tpex_mainboard_peratio_analysis", verify=False):
            c = str(row.get('SecuritiesCompanyCode', '')).strip()
            if c in CODES:
                out.setdefault(c, {}).update({
                    "本益比PE": _f(row.get('PriceEarningRatio')), "股價淨值比PB": _f(row.get('PriceBookRatio')),
                    "殖利率%": _f(row.get('YieldRatio')), "PEPB日": row.get('Date')})
        _ok("pepb(tpex)")
    except Exception as e:
        _fail("pepb(tpex)", e)


def _tag_fin_use(u):
    """融資使用率(餘額/限額)高低：散戶槓桿溫度計。"""
    if u is None:
        return None
    if u < 10:
        return "偏低(散戶槓桿輕)"
    if u < 20:
        return "中性"
    if u < 30:
        return "偏高(散戶槓桿重、追高過熱警戒)"
    return "高(散戶槓桿過重、籌碼凌亂)"


def _tag_short_ratio(r):
    """券資比(融券/融資)高低：空方壓力/軋空潛力。"""
    if r is None:
        return None
    if r < 5:
        return "低(空方輕、無軋空題材)"
    if r < 15:
        return "中"
    if r < 30:
        return "偏高(空方壓力、留意軋空)"
    return "高(軋空潛力大)"


def _apply_margin(d, rz, rq, fin_use, short_use, asof, note=None):
    ratio = round(rq / rz * 100, 2) if (rz and rz > 0 and rq is not None) else None
    d.update({
        "融資餘額張": rz, "融券餘額張": rq, "券資比%": ratio,
        "融資使用率%": fin_use, "融資使用率高低": _tag_fin_use(fin_use),
        "融券使用率%": short_use, "券資比高低": _tag_short_ratio(ratio)})
    _stamp_lag(d, "融資融券", asof, note)


# openapi.twse.com.tw 的 MI_MARGN 沒有日期欄且實測固定落後一個交易日 → 改走帶 date 參數的 RWD 端點
# （與 fetch_borrow / fetch_foreign_hold 同網域），逐日往回退到最近一個有資料的交易日並記錄資料日。
_MARGN_RWD = "https://www.twse.com.tw/rwd/zh/marginTrading/MI_MARGN?date={ymd}&selectType=STOCK&response=json"
_MARGN_OPENAPI = "https://openapi.twse.com.tw/v1/exchangeReport/MI_MARGN"


def fetch_margin(out):
    hit = None
    for ymd, yslash in _recent_trade_dates(5):  # 上市：RWD 版帶資料日
        try:
            j = _get(_MARGN_RWD.format(ymd=ymd))
            got = 0
            for t in (j.get('tables') or []):
                for r in (t.get('data') or []):
                    # 欄序：0代號 1名稱 2融資買進 3賣出 4現償 5前日餘額 6今日餘額 7融資限額
                    #       8融券買進 9賣出 10現券償還 11前日餘額 12今日餘額 13融券限額
                    c = str(r[0]).strip()
                    if c not in CODES or len(r) < 14:
                        continue
                    rz = _f(r[6]); rq = _f(r[12]); rz_lim = _f(r[7]); rq_lim = _f(r[13])
                    fin_use = round(rz / rz_lim * 100, 2) if (rz_lim and rz_lim > 0 and rz is not None) else None
                    short_use = round(rq / rq_lim * 100, 2) if (rq_lim and rq_lim > 0 and rq is not None) else None
                    _apply_margin(out.setdefault(c, {}), rz, rq, fin_use, short_use, yslash)
                    got += 1
            if got:
                hit = yslash
                break
        except Exception as e:
            print(f"[warn] margin(twse rwd {ymd}): {str(e)[:60]}")
    if hit:
        _ok("margin(twse)")
    else:  # RWD 全數失敗 → 退用無日期的 OpenAPI，但必須明講「日期不可考、實測落後一個交易日」
        try:
            for row in _get(_MARGN_OPENAPI):
                c = str(row.get('股票代號', '')).strip()
                if c not in CODES:
                    continue
                rz = _f(row.get('融資今日餘額')); rq = _f(row.get('融券今日餘額'))
                rz_lim = _f(row.get('融資限額')); rq_lim = _f(row.get('融券限額'))
                fin_use = round(rz / rz_lim * 100, 2) if (rz_lim and rz_lim > 0 and rz is not None) else None
                short_use = round(rq / rq_lim * 100, 2) if (rq_lim and rq_lim > 0 and rq is not None) else None
                _apply_margin(out.setdefault(c, {}), rz, rq, fin_use, short_use, None,
                              "RWD 端點失敗、退用 openapi MI_MARGN；該來源無日期欄且實測固定落後一個交易日，"
                              "不得敘述為當日值")
            _fail("margin(twse)", "RWD 全數失敗，已退用無日期的 openapi(降級)")
        except Exception as e:
            _fail("margin(twse)", e)
    try:  # 上櫃：TPEx（官方直接給使用率，且 Date 欄為民國資料日）
        rows = _get("https://www.tpex.org.tw/openapi/v1/tpex_mainboard_margin_balance", verify=False)
        got = 0
        for row in rows:
            c = str(row.get('SecuritiesCompanyCode', '')).strip()
            if c not in CODES:
                continue
            rz = _f(row.get('MarginPurchaseBalance')); rq = _f(row.get('ShortSaleBalance'))
            _apply_margin(out.setdefault(c, {}), rz, rq,
                          _f(row.get('MarginPurchaseUtilizationRate')), _f(row.get('ShortSaleUtilizationRate')),
                          _roc_slash(row.get('Date')))
            got += 1
        if got:
            _ok("margin(tpex)")
        else:
            _fail("margin(tpex)", "端點有回應但無監控標的資料")
    except Exception as e:
        _fail("margin(tpex)", e)


