HIST_P = os.path.join(CACHE, "foreign_hold_history.json")


def _hold_history(update=None):
    """外資持股比率日序列 {日期: {代碼: %}}，供算月/季趨勢（官方僅給當日快照，趨勢須自行累積）。"""
    h = {}
    try:
        if os.path.exists(HIST_P):
            with open(HIST_P, encoding="utf-8") as f:
                h = json.load(f)
    except Exception:
        h = {}
    if update:
        h.update(update)
        for k in sorted(h)[:-320]:      # 只留約1.3年
            h.pop(k, None)
        try:
            os.makedirs(CACHE, exist_ok=True)
            with open(HIST_P, "w", encoding="utf-8") as f:
                json.dump(h, f, ensure_ascii=False)
        except Exception as e:
            print("[warn] hold-hist:", str(e)[:60])
    return h


def fetch_foreign_hold(out):
    """全體外資及陸資持股比率（TWSE MI_QFIIS，日）＋自建日序列→20/60日趨勢（長線籌碼用趨勢、非單日）。
    上櫃(元太/鈊象/群聯)無對應官方 OpenAPI，仍列 needs_manual。"""
    snap = None
    for ymd, yslash in _recent_trade_dates(4):
        try:
            j = _get(f"https://www.twse.com.tw/rwd/zh/fund/MI_QFIIS?date={ymd}&selectType=ALLBUT0999&response=json")
            cur = {}
            for r in j.get('data', []):
                c = str(r[0]).strip()
                if c in CODES and len(r) > 7:
                    pct = _f(r[7])          # 全體外資及陸資持股比率
                    if pct is not None:
                        cur[c] = pct
            if cur:
                snap = (yslash, cur)
                break
        except Exception as e:
            print("[warn] qfii:", str(e)[:70])
    if not snap:
        _fail("qfii(外資持股比率)", "近4個交易日皆無資料")
        return
    _ok("qfii(外資持股比率)")
    yslash, cur = snap
    hist = _hold_history({yslash: cur})
    dates = sorted(hist)
    for c, pct in cur.items():
        d = out.setdefault(c, {})
        d["外資持股比率%"] = pct
        d["外資持股資料日"] = yslash
        for lb, back in (("20日", 20), ("60日", 60)):
            prev = None
            for dt in reversed(dates[:-1]):
                if len(dates) - 1 - dates.index(dt) >= back:
                    prev = hist[dt].get(c)
                    break
            if prev is not None:
                dlt = round(pct - prev, 2)
                d[f"外資持股比率{lb}變化(百分點)"] = dlt
                d[f"外資持股{lb}趨勢"] = ("增持" if dlt >= 0.5 else "減持" if dlt <= -0.5 else "持平")
        if "外資持股20日趨勢" not in d:
            d["外資持股趨勢"] = f"序列累積中({len(dates)}日)，滿20日後可判月趨勢"


def fetch_insider(out):
    """董監事暨內部人持股與設質(t187ap11_L 上市 + mopsfin_t187ap11_O 上櫃，月頻)＋申讓(t187ap12_L)。
    設質比高＝大股東資金壓力/信心疑慮，為長線籌碼負面訊號。"""
    # 同一人/法人會因兼任多個職稱重複列出（例：士電「仰德投資」出現4列、法人董事各代表人各一列），
    # 直接加總會灌水（士電曾算出150%）→ 以「姓名」去重、同名取最大值。
    agg = {}
    for url, vfy, tag in [("https://openapi.twse.com.tw/v1/opendata/t187ap11_L", True, "insider(twse)"),
                          ("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap11_O", False, "insider(tpex)")]:
        try:
            for row in _get(url, verify=vfy):
                c = str(row.get('公司代號', '')).strip()
                if c in CODES:
                    a = agg.setdefault(c, {"ppl": {}, "ym": row.get('資料年月')})
                    nm = str(row.get('姓名', '')).strip()
                    h = _f(row.get('目前持股')) or 0.0
                    p = _f(row.get('設質股數')) or 0.0
                    prev = a["ppl"].get(nm, (0.0, 0.0))
                    a["ppl"][nm] = (max(prev[0], h), max(prev[1], p))
            _ok(tag)
        except Exception as e:
            _fail(tag, e)
    for c, a in agg.items():
        a["hold"] = sum(v[0] for v in a["ppl"].values())
        a["pledge"] = sum(v[1] for v in a["ppl"].values())
        d = out.setdefault(c, {})
        d["董監內部人持股張"] = round(a["hold"] / 1000, 1)
        d["董監資料年月"] = a["ym"]
        tot = d.get("集保總股數")
        if tot and tot > 0:
            d["董監內部人持股比%"] = round(a["hold"] / tot * 100, 2)
        if a["hold"] > 0:
            p = round(a["pledge"] / a["hold"] * 100, 2)
            d["董監設質比%"] = p
            d["董監設質比高低"] = ("高(>50%，大股東資金壓力，長線負面)" if p > 50 else
                                   "偏高(>30%，留意)" if p > 30 else "低(<30%)")
    try:  # 董監申讓（預定轉讓）：有申報＝內部人賣出意圖，為紅旗
        for row in _get("https://openapi.twse.com.tw/v1/opendata/t187ap12_L"):
            c = str(row.get('公司代號', '')).strip()
            if c in CODES:
                out.setdefault(c, {})["董監申讓申報"] = (
                    f"{row.get('姓名', '')}({row.get('申報人身分', '')}) 預定轉讓{row.get('預定轉讓方式及股數-轉讓股數', '')}股")
        _ok("insider-transfer(twse)")
    except Exception as e:
        _fail("insider-transfer(twse)", e)


_SEASON_SEEN = set()      # 本次各端點看到的所有季別（全市場，非僅監控標的）→ 判斷沿用值是否過期


def _season_key(s):
    """'115Q2' → 可比較的整數(年*4+季)；無法解析回 None。"""
    try:
        y, q = str(s).upper().split("Q")
        return int(y) * 4 + int(q)
    except Exception:
        return None


def _latest_season():
    ks = [(_season_key(s), s) for s in _SEASON_SEEN]
    ks = [x for x in ks if x[0] is not None]
    return max(ks)[1] if ks else None


