def fetch_eps(out):
    """官方季 EPS（基本每股盈餘，累計數）：上市 t187ap06_L_ci ＋ 上櫃 mopsfin_t187ap06_O_ci。

    2026/09/06 新增。此前 EPS 只靠每季一次的『基本面研究』網路研究，漏更新時整個估值
    分母停在舊季（當日發現 18/19 檔停在 2026Q1、半年報已於 8 月公布），而 valuation
    會據此標『資料過期』並降級全部估值判定。金融業(台企銀)不在此端點涵蓋範圍。
    """
    upd = {}
    for url, vfy, idk, ykey, skey, tag in [
            ("https://openapi.twse.com.tw/v1/opendata/t187ap06_L_ci", True, '公司代號', '年度', '季別', "eps(上市)"),
            ("https://openapi.twse.com.tw/v1/opendata/t187ap06_L_basi", True, '公司代號', '年度', '季別', "eps(上市金融)"),
            ("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap06_O_ci", False, 'SecuritiesCompanyCode', 'Year', 'Season', "eps(上櫃)")]:
        try:
            for row in _get(url, verify=vfy):
                c = str(row.get(idk, '')).strip()
                if c not in CODES:
                    continue
                eps = _f(row.get('基本每股盈餘（元）'))
                yr, sn = row.get(ykey), row.get(skey)
                if eps is None or not yr or not sn:
                    continue
                season = f"{int(yr) + 1911}Q{int(sn)}"
                upd.setdefault(season, {})[c] = eps
                d = out.setdefault(c, {})
                d["官方EPS季別"] = season
                d["官方EPS累計元"] = eps
                d["官方EPS說明"] = f"{season[:4]}年至Q{sn}累計基本每股盈餘(官方綜合損益表)"
            _ok(tag)
        except Exception as e:
            _fail(tag, e)
    if upd:
        _eps_history(upd)


def fetch_financials(out):
    try:  # 三率(上市)：t187ap17_L 只涵蓋上市一般業，不含上櫃、不含金融業
        for row in _get("https://openapi.twse.com.tw/v1/opendata/t187ap17_L"):
            season = f"{row.get('年度')}Q{row.get('季別')}"
            _SEASON_SEEN.add(season)
            c = str(row.get('公司代號', '')).strip()
            if c in CODES:
                out.setdefault(c, {}).update({
                    "三率季別": season,
                    "毛利率%": _f(row.get('毛利率(%)(營業毛利)/(營業收入)')),
                    "營益率%": _f(row.get('營業利益率(%)(營業利益)/(營業收入)')),
                    "稅後淨利率%": _f(row.get('稅後純益率(%)(稅後純益)/(營業收入)'))})
        _ok("fin17(上市三率)")
    except Exception as e:
        _fail("fin17(上市三率)", e)
    try:  # 三率(上櫃)：官方無現成三率表 → 由 TPEx 綜合損益表自算（元太/鈊象/群聯，原為永久缺漏）
        for row in _get("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap06_O_ci", verify=False):
            season = f"{row.get('Year')}Q{row.get('Season')}"
            _SEASON_SEEN.add(season)
            c = str(row.get('SecuritiesCompanyCode', '')).strip()
            if c not in CODES:
                continue
            rev = _f(row.get('營業收入'))
            if not rev or rev <= 0:
                continue
            gp = _f(row.get('營業毛利（毛損）'))
            if gp is None:
                gp = _f(row.get('營業毛利（毛損）淨額'))
            op = _f(row.get('營業利益（損失）')); ni = _f(row.get('本期淨利（淨損）'))
            d = out.setdefault(c, {})
            d["三率季別"] = season
            d["三率來源"] = "TPEx mopsfin_t187ap06_O_ci 綜合損益表自算(累計數)"
            if gp is not None:
                d["毛利率%"] = round(gp / rev * 100, 2)
            if op is not None:
                d["營益率%"] = round(op / rev * 100, 2)
            if ni is not None:
                d["稅後淨利率%"] = round(ni / rev * 100, 2)
        _ok("fin06(上櫃三率)")
    except Exception as e:
        _fail("fin06(上櫃三率)", e)
    # 資產負債表：上市 t187ap07_L_ci(鍵=公司代號) ＋ 上櫃 mopsfin_t187ap07_O_ci(鍵=SecuritiesCompanyCode)
    for url, vfy, idkey, tag in [("https://openapi.twse.com.tw/v1/opendata/t187ap07_L_ci", True, '公司代號', "fin07(上市資負)"),
                                 ("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap07_O_ci", False, 'SecuritiesCompanyCode', "fin07(上櫃資負)")]:
      try:  # 負債比 + 每股淨值
        for row in _get(url, verify=vfy):
            yr = row.get('年度') or row.get('Year'); sn = row.get('季別') or row.get('Season')
            if yr and sn:
                _SEASON_SEEN.add(f"{yr}Q{sn}")
            c = str(row.get(idkey, '')).strip()
            if c in CODES:
                d = out.setdefault(c, {})
                if yr and sn:
                    # 季別獨立記錄：三率與資產負債表可能來自不同季，共用一個「財報季別」會造成混季誤讀
                    d["資產負債表季別"] = f"{yr}Q{sn}"
                # 註：本表欄名為「資產總計/負債總計」（非總額）；舊版寫成總額→負債比恆為空，已修正並保留兩種鍵名相容。
                asset = _f(row.get('資產總計')) or _f(row.get('資產總額'))
                liab = _f(row.get('負債總計')) or _f(row.get('負債總額'))
                eq = _f(row.get('歸屬於母公司業主之權益合計')); cap = _f(row.get('股本'))
                if asset and liab:
                    d["負債比%"] = round(liab / asset * 100, 2)
                    d["負債比警戒"] = "高風險警戒(>60%)" if liab / asset * 100 > 60 else "正常"
                bv = _f(row.get('每股參考淨值'))
                if bv:
                    d["每股淨值元"] = bv
                elif eq and cap and cap > 0:
                    d["每股淨值元"] = round(eq / (cap / 10.0), 2)  # 股本千元/面額10=千股；權益千元/千股=元
        _ok(tag)
      except Exception as e:
        _fail(tag, e)
    # 金融(銀行)業資產負債表：上市 t187ap07_L_basi（涵蓋 2834 台企銀）
    try:
        for row in _get("https://openapi.twse.com.tw/v1/opendata/t187ap07_L_basi"):
            c = str(row.get('公司代號', '')).strip()
            if c in CODES and c in FINANCIAL_CODES:
                yr = row.get('年度'); sn = row.get('季別')
                if yr and sn:
                    _SEASON_SEEN.add(f"{yr}Q{sn}")
                d = out.setdefault(c, {})
                if yr and sn:
                    d["資產負債表季別"] = f"{yr}Q{sn}"
                    d["財報季別"] = f"{yr}Q{sn}"
                asset = _f(row.get('資產總額')) or _f(row.get('資產總計'))
                liab = _f(row.get('負債總額')) or _f(row.get('負債總計'))
                if asset and liab:
                    d["負債比%"] = round(liab / asset * 100, 2)
                    d["負債比警戒"] = "銀行業（吸收存款高槓桿，不適用一般業>60%鐵則；看資本適足率與逾放比）"
                    # 資負表端點沒有銀行資本適足率/逾放比；不得填入無來源常數。
                    d["金融業財務體質"] = "銀行資本適足率與逾放比未取得，償債風險未能判定"
                    d.setdefault("缺漏原因", {})["資本適足率%"] = "此官方資負表端點未提供，須另查銀行揭露"
                    d.setdefault("缺漏原因", {})["逾放比%"] = "此官方資負表端點未提供，須另查銀行揭露"
                bv = _f(row.get('每股參考淨值'))
                if bv:
                    d["每股淨值元"] = bv
        _ok("fin07(金融資負)")
    except Exception as e:
        _fail("fin07(金融資負)", e)
    for c in CODES:  # 相容舊欄位：財報季別＝三率季別，無則取資產負債表季別（不再由兩來源交叉 setdefault）
        d = out.get(c)
        if isinstance(d, dict):
            s = d.get("三率季別") or d.get("資產負債表季別")
            if s:
                d["財報季別"] = s


def _recent_trade_dates(n=4):
    """由台積電 K線取最近 n 個交易日 → [(YYYYMMDD, YYYY/MM/DD), ...] 由新到舊。
    借券報表(TWT93U)公布時間晚於 18:00 排程，當日常抓不到 → 需逐日往回退。"""
    p = os.path.join(ROOT, "data", "台積電", "台積電_2330_近期K線.csv")
    out = []
    try:
        with open(p, encoding="utf-8-sig") as f:
            f.readline()
            for _ in range(n):
                row = f.readline()
                if not row:
                    break
                d = row.split(",")[0].strip()
                if d:
                    out.append((d.replace("/", ""), d))
    except Exception:
        pass
    return out


def _latest_trade_date():
    r = _recent_trade_dates(1)
    return r[0] if r else (None, None)


def fetch_borrow(out):
    """借券賣出餘額（法人放空主管道，≠融券）。TWSE TWT93U(上市)＋TPEx margin/sbl(上櫃)。
    欄位結構同：[0]代號[1]名稱[2-7]融券[8-13]借券賣出，借券『當日餘額』=索引12(股→張)。"""
    dates = _recent_trade_dates(4)
    if not dates:
        _fail("borrow(twse)", "無法取得交易日清單(台積電K線讀取失敗)")
        _fail("borrow(tpex)", "無法取得交易日清單(台積電K線讀取失敗)")
        return
    hit_twse = hit_tpex = None
    for ymd, yslash in dates:   # 當日報表未公布(18:00 排程常見)→往前退到最近一個有資料的交易日
        if hit_twse is None:
            try:  # 上市
                j = _get(f"https://www.twse.com.tw/rwd/zh/marginTrading/TWT93U?date={ymd}&response=json")
                got = 0
                for r in j.get('data', []):
                    c = str(r[0]).strip()
                    if c in CODES and len(r) > 12:
                        sbl = _f(r[12])
                        if sbl is not None:
                            out.setdefault(c, {})["借券賣出餘額張"] = round(sbl / 1000, 1)
                            got += 1
                if got:
                    hit_twse = yslash
            except Exception as e:
                print("[warn] borrow(twse):", str(e)[:70])
        if hit_tpex is None:
            try:  # 上櫃
                j = _get(f"https://www.tpex.org.tw/www/zh-tw/margin/sbl?date={yslash}&response=json", verify=False)
                got = 0
                for r in (j.get('tables') or [{}])[0].get('data', []):
                    c = str(r[0]).strip()
                    if c in CODES and len(r) > 12:
                        sbl = _f(r[12])
                        if sbl is not None:
                            out.setdefault(c, {})["借券賣出餘額張"] = round(sbl / 1000, 1)
                            got += 1
                if got:
                    hit_tpex = yslash
            except Exception as e:
                print("[warn] borrow(tpex):", str(e)[:70])
        if hit_twse and hit_tpex:
            break
    if hit_twse:
        _ok("borrow(twse)")
    else:
        _fail("borrow(twse)", "近4個交易日皆無 TWT93U 資料")
    if hit_tpex:
        _ok("borrow(tpex)")
    else:
        _fail("borrow(tpex)", "近4個交易日皆無 TPEx sbl 資料")
    for c, d in out.items():
        if d.get("借券賣出餘額張") is not None:
            _stamp_lag(d, "借券", hit_tpex if c in TPEX_CODES else hit_twse)
    print(f"  [借券] 上市資料日={hit_twse or '無'}／上櫃資料日={hit_tpex or '無'}")
    # 借券 vs 融券 對比（法人 vs 散戶空單）＋借券占股本（真正空單比重）
    for c, d in out.items():
        b = d.get("借券賣出餘額張"); rq = d.get("融券餘額張"); tot = d.get("集保總股數")
        if b is not None and rq and rq > 0:
            d["借券vs融券倍數"] = round(b / rq, 1)
            bd, md = d.get("借券資料日"), d.get("融資融券資料日")
            if bd and md and bd != md:   # 跨來源比值：兩邊資料日不同要講清楚，別當同日對比
                d["借券vs融券日期不一致"] = f"借券={bd}／融券={md}"
        if b is not None and tot and tot > 0:
            pct = round(b * 1000 / tot * 100, 2)
            d["借券占股本%"] = pct
            d["借券占股本高低"] = ("高(法人空單壓力大)" if pct >= 8 else "偏高(留意法人放空)" if pct >= 5
                                   else "中" if pct >= 2 else "低")
    _sbl_trend(out)


