# 2026/09/06 新增。動機（3450 聯鈞實例）：該檔 9/3 起進入第二次處置（人工管制撮合約每 2 分鐘一次
# ＋全額交割），成交量由 1,100 萬股驟降至 165 萬股、量能倍數 0.12 —— 若不知處置，量價分析會把
# 這種「制度性萎縮」誤讀成《量價關係教學》#4 的洗盤縮量或 #9 的地量，進而推出完全相反的結論。
# 處置與注意同時也是「投機過熱」的官方客觀證據（注意公告內含週轉率、當沖比、單一分點占比）。
DISP_LOOKBACK_DAYS = 100        # 處置公告回溯天數（處置期最長約 10 個營業日，抓 100 天足以涵蓋近期多次）
NOTICE_LOOKBACK_DAYS = 35       # 注意公告回溯天數（近一個月頻率即足以判斷過熱）


def _disp_range(s):
    """處置起迄字串（115/09/03～115/09/11、115/09/04~115/09/10）→ (西元起, 西元迄)；失敗回 (None, None)。"""
    parts = re.split(r"[~～至\-]+", str(s or ""))
    if len(parts) < 2:
        return None, None
    return _roc_slash(parts[0]), _roc_slash(parts[1])


def _disp_measure(text):
    """由處置內容擷取撮合頻率與是否全額交割（量能失真程度取決於撮合頻率）。"""
    t = str(text or "")
    m = re.search(r"約每([一-鿿A-Za-z0-9]{1,6})分鐘撮合", t)
    freq = f"人工管制撮合約每{m.group(1)}分鐘一次" if m else ("人工管制撮合" if "人工管制" in t else None)
    full = "全額交割(預收全部價金／證券)" if ("收取全部之買進價金" in t or "全額" in t) else None
    return "＋".join(x for x in (freq, full) if x) or None


def fetch_disposition(out):
    """處置股／注意股：寫入 `處置中`／`處置期間`／`處置措施`／`處置次數(近100日)`／`注意次數(近35日)`。

    **量能可信度守門**：處置期間為人工管制分盤撮合＋全額交割，成交量與非處置期**不可比**；
    本函式在處置中時寫入 `量能可信度` 警語，供報告端停用量能倍數／爆量縮量判定
    （見 steering/量價關係教學.md §十 適用限制）。
    """
    today = datetime.now()
    d0 = (today - timedelta(days=DISP_LOOKBACK_DAYS)).strftime("%Y%m%d")
    d1 = today.strftime("%Y%m%d")
    n0 = (today - timedelta(days=NOTICE_LOOKBACK_DAYS)).strftime("%Y%m%d")
    asof = _latest_trade_date()[1]      # 以最近交易日判斷「現在是否在處置期間內」
    disp = {}       # code -> [(起, 迄, 措施, 公布日)]
    notice = {}     # code -> [(日期, 內容)]

    try:    # 上市：處置
        j = _get(f"https://www.twse.com.tw/rwd/zh/announcement/punish?startDate={d0}&endDate={d1}&response=json")
        for r in (j.get('data') or []):
            c = str(r[2]).strip() if len(r) > 2 else ''
