            if c in CODES:
                notice.setdefault(c, []).append((_roc_slash(r[5]) if len(r) > 5 else None,
                                                 str(r[4])[:200] if len(r) > 4 else ''))
        _ok("notice(上市注意)")
    except Exception as e:
        _fail("notice(上市注意)", e)

    try:    # 上櫃：注意
        j = _get("https://www.tpex.org.tw/www/zh-tw/bulletin/attention"
                 f"?startDate={n0[:4]}/{n0[4:6]}/{n0[6:]}&endDate={d1[:4]}/{d1[4:6]}/{d1[6:]}&response=json",
                 verify=False)
        for t in (j.get('tables') or []):
            for r in (t.get('data') or []):
                c = str(r[1]).strip() if len(r) > 1 else ''
                if c in CODES:
                    notice.setdefault(c, []).append((_roc_slash(r[5]) if len(r) > 5 else None,
                                                     str(r[4])[:200] if len(r) > 4 else ''))
        _ok("attention(上櫃注意)")
