SBL_HIST_P = os.path.join(CACHE, "sbl_history.json")


def _sbl_history(update=None):
    """借券賣出餘額日序列 {日期: {代碼: 餘額張}}。

    官方 TWT93U／TPEx sbl 只給「當日餘額」，沒有歷史。趨勢與「連續幾天增加」必須自行累積，
    做法比照 _hold_history()（外資持股比率）。稽核前的狀態是：只有當日水位、
    報告只能寫「借券趨勢為 needs_manual、無法判定攀升或回補」，
    等於看得到法人空單有多少、卻看不出是正在加碼還是回補——方向性資訊完全缺席。
    """
    h = {}
    try:
        if os.path.exists(SBL_HIST_P):
            with open(SBL_HIST_P, encoding="utf-8") as f:
                h = json.load(f)
    except Exception:
        h = {}
    if update:
        for dt, rec in update.items():
            h.setdefault(dt, {}).update(rec)
        for k in sorted(h)[:-320]:      # 只留約1.3年
            h.pop(k, None)
        try:
            os.makedirs(CACHE, exist_ok=True)
            with open(SBL_HIST_P, "w", encoding="utf-8") as f:
                json.dump(h, f, ensure_ascii=False)
        except Exception as e:
            print("[warn] sbl-hist:", str(e)[:60])
    return h


def _sbl_trend(out):
    """自建借券日序列 → 20/60 日變化、連續增減天數、趨勢研判。

    鐵則對齊：借券是**法人**空單主管道（融券主要是散戶），故此處判的是法人空方力道的方向。
    與外資現貨 20/60 日淨賣、RS 落後併看，才構成《偵測法人偷偷放空》的「法人明確放空」三合一。
    單日水位高低不等於方向——本函式補的正是方向。
    """
    upd = {}
    for c, d in out.items():
        bal, dt = d.get("借券賣出餘額張"), d.get("借券資料日")
        if bal is not None and dt:
            upd.setdefault(dt, {})[c] = bal
    if not upd:
        return
    hist = _sbl_history(upd)
    dates = sorted(hist)

    for c, d in out.items():
        bal, dt = d.get("借券賣出餘額張"), d.get("借券資料日")
        if bal is None or not dt or dt not in hist:
            continue
        # 只取「有該檔資料」的日期序列，避免某天抓取失敗造成天數誤算
        seq = [(x, hist[x][c]) for x in dates if c in hist[x]]
        idx = next((i for i, (x, _) in enumerate(seq) if x == dt), None)
        if idx is None:
            continue
        d["借券序列天數"] = len(seq)

        for lb, back in (("20日", 20), ("60日", 60)):
            j = idx - back
            if j >= 0:
                prev = seq[j][1]
                dlt = round(bal - prev, 1)
                d[f"借券{lb}變化張"] = dlt
                if prev > 0:
                    d[f"借券{lb}變化%"] = round(dlt / prev * 100, 1)
                # 門檻用相對值：餘額規模各檔差異大，絕對張數不可比
                r = (dlt / prev * 100) if prev > 0 else 0
                d[f"借券{lb}趨勢"] = ("攀升(法人空單加碼)" if r >= 10 else
                                      "回補(法人空單減少)" if r <= -10 else "持平")

        # 連續增加/減少天數（使用者最關心的「連續 N 天借券賣」）
        up = dn = 0
        for i in range(idx, 0, -1):
            if seq[i][1] > seq[i - 1][1]:
                if dn:
                    break
                up += 1
            elif seq[i][1] < seq[i - 1][1]:
                if up:
                    break
                dn += 1
            else:
                break
        if up:
            d["借券連續增加天數"] = up
        if dn:
            d["借券連續減少天數"] = dn

        if len(seq) < 21:
            d["借券趨勢說明"] = (f"借券日序列累積中（目前 {len(seq)} 日，滿 21 日後可判月趨勢）；"
                                 f"連續增加 {up} 日／連續減少 {dn} 日僅供參考(needs_manual)")
        else:
            t20 = d.get("借券20日趨勢", "持平")
            d["借券趨勢說明"] = (f"20日{t20}"
                                 + (f"、已連續 {up} 個交易日增加" if up else "")
                                 + (f"、已連續 {dn} 個交易日減少" if dn else "")
                                 + "；借券為法人空單主管道，須與外資現貨20/60日流向、RS 併看")


def _sbl_one_day(ymd, yslash):
    """取單一交易日的借券賣出餘額（上市＋上櫃），回傳 {代碼: 張}。供回補用。"""
    rec = {}
    try:
        j = _get(f"https://www.twse.com.tw/rwd/zh/marginTrading/TWT93U?date={ymd}&response=json")
        for r in j.get('data', []):
            c = str(r[0]).strip()
            if c in CODES and len(r) > 12:
                v = _f(r[12])
                if v is not None:
                    rec[c] = round(v / 1000, 1)
    except Exception as e:
        print(f"  [warn] {yslash} 上市: {str(e)[:50]}")
    try:
        j = _get(f"https://www.tpex.org.tw/www/zh-tw/margin/sbl?date={yslash}&response=json", verify=False)
        for r in (j.get('tables') or [{}])[0].get('data', []):
            c = str(r[0]).strip()
            if c in CODES and len(r) > 12:
                v = _f(r[12])
                if v is not None:
                    rec[c] = round(v / 1000, 1)
    except Exception as e:
        print(f"  [warn] {yslash} 上櫃: {str(e)[:50]}")
    return rec


def backfill_sbl(days=65):
    """回補借券日序列（TWT93U／TPEx sbl 皆吃 date 參數，故歷史可補）。

    不回補的話，新建的序列要等 21 個交易日才判得出月趨勢、才答得出「連續幾天借券賣」。
    已完整的日期會跳過，可重複執行。
    """
    dates = _recent_trade_dates(days)
    if not dates:
        print("[Fail] 無法取得交易日清單（台積電 K 線讀取失敗）")
        return 1
    hist = _sbl_history()
    need = len(CODES)
    added = skipped = 0
    print(f"=== 回補借券日序列：目標 {len(dates)} 個交易日（{dates[-1][1]} ~ {dates[0][1]}）===")
    for ymd, yslash in reversed(dates):          # 由舊到新
        # 以「清單內每一檔是否都有」判定，不能只比筆數：換標的時（移除微星、加入漢翔）
        # 舊日期仍是 19 筆但少了新標的，比筆數會全部跳過、新標的序列永遠補不起來。
        if CODES.issubset((hist.get(yslash) or {}).keys()):
            skipped += 1
            continue
        rec = _sbl_one_day(ymd, yslash)
        if rec:
            hist = _sbl_history({yslash: rec})
            added += 1
            print(f"  {yslash}: {len(rec)}/{need} 檔")
        else:
            print(f"  {yslash}: 無資料（非交易日或報表未留存）")
        time.sleep(0.4)                          # 對官方端點放慢，避免被擋
    dts = sorted(hist)
    print(f"=== 完成：新增 {added} 日、已存在跳過 {skipped} 日；序列現有 {len(dts)} 日"
          f"（{dts[0] if dts else '-'} ~ {dts[-1] if dts else '-'}）-> {SBL_HIST_P}")
    return 0


# 季報欄位沿用：分成「三率」與「資產負債表」兩組，各自帶自己的季別，避免混季
# （舊版兩組共用一個「財報季別」＋一個不指名欄位的布林旗標→季別顯示新一季、數值其實是上一季）。
QUARTERLY_GROUPS = [
    ("三率", ["毛利率%", "營益率%", "稅後淨利率%"], "三率季別"),
    ("資產負債表", ["負債比%", "負債比警戒", "每股淨值元"], "資產負債表季別"),
]
MAX_CARRY_QUARTERS = 2      # 沿用年限：距最新已申報季別超過 2 季即不再沿用（改列缺漏，不無限沿用）


def _carry_over(out):
    """自前次快取沿用季報欄位，但逐欄位具名記錄「沿用自哪一季」，並設沿用年限。"""
    prev_p = os.path.join(CACHE, "market_latest.json")
    if not os.path.exists(prev_p):
        return
    with open(prev_p, encoding="utf-8") as f:
        prev = json.load(f)
    latest = _latest_season()
    lk = _season_key(latest)
    for c, pd_ in prev.items():
        # 已移除的標的不得靠沿用復活：舊版用 setdefault 會把前次快取裡的每個代碼都
        # 補回 out（微星2377 下市於本清單後仍每天被寫回，成為幽靈檔）。
        if c.startswith("_") or not isinstance(pd_, dict) or c not in CODES:
            continue
        d = out.setdefault(c, {})
        for gname, fields, skey in QUARTERLY_GROUPS:
            miss = [k for k in fields if d.get(k) is None and pd_.get(k) is not None]
            if not miss:
                continue
            psn = pd_.get(skey) or pd_.get("財報季別")
            pk = _season_key(psn)
            if lk is not None and pk is not None and lk - pk > MAX_CARRY_QUARTERS:
                for k in miss:   # 過期：寧可留 None 讓下游標 needs_manual，也不沿用陳舊值
                    _note_gap(d, k, f"前期值({psn})距最新季別({latest})逾{MAX_CARRY_QUARTERS}季，已停止沿用")
                continue
            for k in miss:
                d[k] = pd_[k]
            d[skey] = f"{psn}(前期沿用)" if psn else "前期沿用(季別不明)"
            d.setdefault("財報沿用欄位", []).extend(miss)
            d["財報為前期沿用"] = True
        s = d.get("三率季別") or d.get("資產負債表季別")
        if s:
            d["財報季別"] = s


def _annotate_gaps(out):
    """具名說明每個缺漏欄位的真正原因（結構性缺口 vs 本次未取得 vs 尚未申報），
    避免下游只憑『值是 None』推測成『當季財報未申報』這種與事實相反的敘述。"""
    bank_rate = ("金融(銀行)業：TWSE t187ap17_L 與 TPEx 綜合損益表皆不含金融業，"
                 "官方僅有當日增量的 t187ap07_L_basi、無累積表可抓(結構性缺口)")
    bank_debt = ("金融(銀行)業：官方一般業資產負債表(t187ap07_L_ci)不含銀行；且銀行業應看資本適足率/逾放比，"
                 "非一般業負債比口徑(結構性缺口，非未申報)")
    for c in CODES:
        d = out.get(c)
        if not isinstance(d, dict):
            continue
        already = d.get("缺漏原因", {})
        rate_src = "fin06(上櫃三率)" if c in TPEX_CODES else "fin17(上市三率)"
        bs_src = "fin07(上櫃資負)" if c in TPEX_CODES else "fin07(上市資負)"
        for k in ("毛利率%", "營益率%", "稅後淨利率%"):
            if d.get(k) is None and k not in already:
                if c in FINANCIAL_CODES:
                    _note_gap(d, k, bank_rate)
                elif STATUS.get(rate_src) is False:   # 來源掛了 ≠ 公司沒申報，不可混為一談
                    _note_gap(d, k, f"{rate_src} 本次取數失敗(來源異常，非未申報)，且無前期可沿用")
                else:
                    _note_gap(d, k, f"{rate_src} 無此檔資料：該季未申報且無前期可沿用")
        if d.get("負債比%") is None and "負債比%" not in already:
            if c in FINANCIAL_CODES:
                _note_gap(d, "負債比%", bank_debt)
            elif STATUS.get(bs_src) is False:
                _note_gap(d, "負債比%", f"{bs_src} 本次取數失敗(來源異常，非未申報)，且無前期可沿用；>60% 鐵則無法自動核驗")
            else:
                _note_gap(d, "負債比%", f"{bs_src} 無此檔資料：該季未申報且無前期可沿用；>60% 鐵則無法自動核驗")
        if d.get("外資持股比率%") is None and c in TPEX_CODES:
            _note_gap(d, "外資持股比率%", "MI_QFIIS 僅涵蓋上市，上櫃無對應官方端點(結構性缺口)")


def backfill_hold(days=65):
    """回補外資持股比率日序列（TWSE MI_QFIIS 吃 date 參數，故歷史可補）。

    與 backfill_sbl 同理：漏跑的交易日若不回補，20/60 日趨勢會拿「跳日」的舊值當基準，
    月趨勢判斷失真（2026/09/06 發現 08/31~09/04 五個交易日整週缺漏）。
    已完整的日期會跳過，可重複執行。僅上市有此端點（上櫃為結構性缺口）。
    """
    dates = _recent_trade_dates(days)
    if not dates:
        print("[Fail] 無法取得交易日清單（台積電 K 線讀取失敗）")
        return 1
    hist = _hold_history()
    listed = {c for c in CODES if c not in TPEX_CODES}
    added = skipped = 0
    print(f"=== 回補外資持股比率日序列：目標 {len(dates)} 個交易日（{dates[-1][1]} ~ {dates[0][1]}）===")
    for ymd, yslash in reversed(dates):
        if listed.issubset((hist.get(yslash) or {}).keys()):
            skipped += 1
            continue
        cur = {}
        try:
            j = _get(f"https://www.twse.com.tw/rwd/zh/fund/MI_QFIIS?date={ymd}&selectType=ALLBUT0999&response=json")
            for r in j.get('data', []):
                c = str(r[0]).strip()
                if c in CODES and len(r) > 7:
                    pct = _f(r[7])
                    if pct is not None:
                        cur[c] = pct
        except Exception as e:
            print(f"  [warn] {yslash}: {str(e)[:60]}")
        if cur:
            hist = _hold_history({yslash: cur})
            added += 1
            print(f"  {yslash}: {len(cur)}/{len(listed)} 檔")
        else:
            print(f"  {yslash}: 無資料（非交易日或報表未留存）")
        time.sleep(0.4)
    dts = sorted(hist)
    print(f"=== 完成：新增 {added} 日、已存在跳過 {skipped} 日；序列現有 {len(dts)} 日"
          f"（{dts[0] if dts else '-'} ~ {dts[-1] if dts else '-'}）-> {HIST_P}")
    return 0


def main():
    os.makedirs(CACHE, exist_ok=True)
    argv = sys.argv[1:]
    if "--backfill-hold" in argv:
        i = argv.index("--backfill-hold")
        n = 65
        if i + 1 < len(argv) and argv[i + 1].isdigit():
            n = int(argv[i + 1])
        return backfill_hold(n)
    if "--backfill-sbl" in argv:
        i = argv.index("--backfill-sbl")
        n = 65
        if i + 1 < len(argv) and argv[i + 1].isdigit():
            n = int(argv[i + 1])
        return backfill_sbl(n)
    for a in argv:
        if a.startswith("-") and a not in ("--backfill-sbl", "--backfill-hold") and not a.isdigit():
            print(f"[錯誤] 未知旗標 {a}\n用法：fetch_market_data.py [--backfill-sbl [天數]] [--backfill-hold [天數]]")
            return 2
    out = {}
    fetch_pepb(out)
    fetch_margin(out)
    fetch_revenue(out)
    fetch_tdcc(out)          # 需先於 insider：董監持股比%以集保總股數為分母
    fetch_insider(out)
    fetch_foreign_hold(out)
    fetch_eps(out)
    fetch_financials(out)
    fetch_borrow(out)
    fetch_disposition(out)   # 處置/注意：量能可信度守門，須在寫檔前
    fails = sorted(k for k, v in STATUS.items() if not v)
    n_src, n_ok = len(STATUS), sum(1 for v in STATUS.values() if v)
    if not out or n_ok == 0:
        print(f"[Error] 全部來源失敗、無資料（{n_src} 個來源全掛）— 保留前次 market_latest.json 不覆寫")
        return 1
    try:
        _carry_over(out)
    except Exception as e:
        print("[warn] carry-over:", str(e)[:70])
    _annotate_gaps(out)
    n_stock = len([k for k in out if not k.startswith("_")])
    out["_meta"] = {
        "執行時間": datetime.now().strftime("%Y/%m/%d %H:%M:%S"),
        "資料基準交易日": _latest_trade_date()[1],
        "來源總數": n_src, "來源成功": n_ok, "失敗來源": fails,
        "資料完整": not fails,
        "警告": None if not fails else f"本次 {len(fails)}/{n_src} 個官方來源取數失敗，相關欄位缺漏或為降級值，勿當完整資料使用",
    }
    with open(os.path.join(CACHE, "market_latest.json"), "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    try:  # docstring 承諾的當日備份（供事後回溯「那天到底抓到什麼」）
        with open(os.path.join(CACHE, f"market_{datetime.now().strftime('%Y%m%d')}.json"), "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print("[warn] backup:", str(e)[:70])
    if fails:
        print(f"[Partial] 市場面 {n_stock}/{len(CODES)} 檔；來源 {n_ok}/{n_src} 成功，失敗: {'、'.join(fails)}"
              f" -> data/_market_cache/market_latest.json")
    else:
        print(f"[Success] 市場面 {n_stock}/{len(CODES)} 檔（來源 {n_ok}/{n_src} 全數成功）"
              f" -> data/_market_cache/market_latest.json")
    inv = {v: k for k, v in STOCKS.items()}
    for c in STOCKS.values():
        if c in out:
            print(f"  {inv[c]}({c}):", json.dumps(out[c], ensure_ascii=False)[:150])
    if not fails:
        return 0
    return 3 if n_ok * 2 < n_src else 2      # 過半來源失敗=3、部分失敗=2（排程日誌看得到 exit≠0）


if __name__ == "__main__":
    sys.exit(main())

