def _inline(text):
    text = _html.escape(text, quote=False)
    text = re.sub(r'`([^`]+)`', lambda m: f'<code>{m.group(1)}</code>', text)
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
    text = re.sub(r'(?<!\*)\*(?!\s)(.+?)(?<!\s)\*(?!\*)', r'<em>\1</em>', text)
    text = re.sub(r'\[([^\]]+)\]\(([^)\s]+)\)', r'<a href="\2">\1</a>', text)
    return text


def _split_row(line):
    s = line.strip()
    if s.startswith('|'):
        s = s[1:]
    if s.endswith('|'):
        s = s[:-1]
    return [c.strip() for c in s.split('|')]


def _aligns(cells):
    out = []
    for c in cells:
        c = c.strip()
        l, r = c.startswith(':'), c.endswith(':')
        out.append('center' if (l and r) else 'right' if r else 'left' if l else '')
    return out


def _render_list(items, tag):
    if not items:
        return ''
    base = min(ind for ind, _ in items)
    parts = [f'<{tag}>']
    k = 0
    while k < len(items):
        ind, txt = items[k]
        if ind <= base:
            sub, j = [], k + 1
            while j < len(items) and items[j][0] > base:
                sub.append(items[j])
                j += 1
            if sub:
                parts.append(f'<li>{txt}{_render_list(sub, "ul")}</li>')
                k = j
            else:
                parts.append(f'<li>{txt}</li>')
                k += 1
        else:
            k += 1
    parts.append(f'</{tag}>')
    return '\n'.join(parts)


def md_to_html(md):
    lines = md.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    if lines and lines[0].startswith('﻿'):
        lines[0] = lines[0].lstrip('﻿')
    out, i, n = [], 0, len(lines)
    while i < n:
        line = lines[i]
        s = line.strip()
        if not s:
            i += 1
            continue
        if re.fullmatch(r'(-{3,}|\*{3,}|_{3,})', s):
            out.append('<hr/>')
            i += 1
            continue
        m = re.match(r'(#{1,6})\s+(.*)', s)
        if m:
            lv = len(m.group(1))
            out.append(f'<h{lv}>{_inline(m.group(2).strip())}</h{lv}>')
            i += 1
            continue
        # 表格
        if s.startswith('|') and i + 1 < n and re.search(r'\|?\s*:?-{2,}:?\s*\|', lines[i + 1]):
            header = _split_row(s)
            aligns = _aligns(_split_row(lines[i + 1]))
            rows, j = [], i + 2
            while j < n and lines[j].strip().startswith('|'):
                rows.append(_split_row(lines[j].strip()))
                j += 1

            def cell(tag, val, idx):
                a = aligns[idx] if idx < len(aligns) else ''
                st = f' style="text-align:{a}"' if a else ''
                return f'<{tag}{st}>{_inline(val)}</{tag}>'

            t = ['<table>', '<thead><tr>'] + [cell('th', h, k) for k, h in enumerate(header)]
            t.append('</tr></thead><tbody>')
            for r in rows:
                t.append('<tr>' + ''.join(cell('td', v, k) for k, v in enumerate(r)) + '</tr>')
            t.append('</tbody></table>')
            out.append('\n'.join(t))
            i = j
            continue
        # 引用
        if s.startswith('>'):
            buf = []
            while i < n and lines[i].strip().startswith('>'):
                buf.append(_inline(re.sub(r'^\s*>\s?', '', lines[i])))
                i += 1
            out.append('<blockquote>' + '<br/>'.join(buf) + '</blockquote>')
            continue
        # 清單
        if re.match(r'\s*([-*]|\d+\.)\s+', line):
            tag = 'ol' if re.match(r'\s*\d+\.\s+', line) else 'ul'
            items = []
            while i < n and re.match(r'\s*([-*]|\d+\.)\s+', lines[i]):
                mm = re.match(r'(\s*)([-*]|\d+\.)\s+(.*)', lines[i])
                items.append((len(mm.group(1)), _inline(mm.group(3))))
                i += 1
            out.append(_render_list(items, tag))
            continue
        # 段落
        out.append(f'<p>{_inline(s)}</p>')
        i += 1
    return '\n'.join(out)


def _wrap_tables(h):
    """把 <table> 包進可橫向捲動容器，避免寬表撐破版面。冪等（先還原既有包裹再統一包一層）。"""
    h = h.replace('<div class="tbl"><table>', '<table>').replace('</table></div>', '</table>')
    return h.replace('<table>', '<div class="tbl"><table>').replace('</table>', '</table></div>')


def _split_sections(body_html):
    """依 <h2> 把內文切成 (h1, lead, [(標題, HTML), ...])。h1=標題列、lead=首個h2前的引言。"""
    h1m = re.search(r'<h1>.*?</h1>', body_html, re.S)
    h1 = h1m.group(0) if h1m else ''
    rest = body_html[h1m.end():] if h1m else body_html
    parts = re.split(r'(?=<h2>)', rest)
    lead = parts[0].strip() if parts else ''
    sections = []
    for p in parts[1:]:
        p = p.strip()
        if not p:
            continue
        tm = re.match(r'<h2>(.*?)</h2>', p, re.S)
        label = re.sub(r'<[^>]+>', '', tm.group(1)).strip() if tm else '章節'
        sections.append((label, p))
    return h1, lead, sections


def _tab_label(lbl):
    lbl = lbl.strip()
    lbl = re.split(r'[（(]', lbl)[0].strip()   # 分頁籤只留主標、去掉括號描述
    lbl = re.sub(r'\s+', '', lbl)
    return (lbl[:12] + '…') if len(lbl) > 13 else lbl


def wrap(title, body_html):
    body_html = _wrap_tables(body_html)
    h1, lead, sections = _split_sections(body_html)
    if not h1:
        h1 = f'<h1>{_html.escape(title)}</h1>'
    foot = ('<div class="foot"><div class="warn">投資有風險，分析僅供參考。</div>'
            f'由 {_html.escape(report_author())}（股市分析 Agent）產生 · 分頁式 HTML 報告</div>')
    if len(sections) >= 2:
        tabs = ''.join(f'<button class="tab" type="button">{_html.escape(_tab_label(l))}</button>'
                       for l, _ in sections)
        panels = ''.join(f'<section class="panel">{h}</section>' for _, h in sections)
        lead_html = f'<div class="lead">{lead}</div>' if lead else ''
        inner = (f'<div class="hd">{h1}</div>{lead_html}'
                 f'<nav class="tabs" role="tablist">{tabs}</nav>'
                 f'<div class="panels">{panels}</div>{foot}')
        js = f'<script>{TABS_JS}</script>'
    else:
        content = body_html.replace(h1, '', 1) if h1 in body_html else body_html
        inner = f'<div class="hd">{h1}</div><div class="panels">{content}</div>{foot}'
        js = ''
    return (f'<!DOCTYPE html>\n<html lang="zh-Hant">\n<head>\n<meta charset="utf-8"/>\n'
            f'<meta name="viewport" content="width=device-width,initial-scale=1"/>\n'
            f'<title>{_html.escape(title)}</title>\n<style>{CSS}</style>\n</head>\n<body>\n'
            f'<div class="wrap paged">\n{inner}\n</div>\n{js}\n</body>\n</html>\n')


def _title_from_md(md, fallback):
    m = re.search(r'^\s*#\s+(.*)', md, re.M)
    return re.sub(r'[*`]', '', m.group(1)).strip() if m else fallback


def render_string(md, html_path, title=None):
    """將 Markdown 字串直接渲染成 HTML 檔（不需 .md 檔落地）。"""
    if title is None:
        title = _title_from_md(md, os.path.splitext(os.path.basename(html_path))[0])
    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(wrap(title, md_to_html(md)))
    return html_path


def render_file(md_path, html_path=None, title=None):
    with open(md_path, 'r', encoding='utf-8-sig') as f:
        md = f.read()
    if title is None:
        title = _title_from_md(md, os.path.splitext(os.path.basename(md_path))[0])
    if html_path is None:
        html_path = os.path.splitext(md_path)[0] + '.html'
    return render_string(md, html_path, title)


def _usage():
    print("用法:\n"
          "  python report_html.py <報告.md> [更多.md ...]\n"
          "  python report_html.py <報告.md> --out <輸出.html>\n"
          "  python report_html.py --stdin --out <輸出.html> [--title <標題>]")


if __name__ == '__main__':
    argv = sys.argv[1:]
    if not argv:
        _usage()
        sys.exit(1)
    out_path = None
    title = None
    use_stdin = False
    files = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--out':
            i += 1
            out_path = argv[i] if i < len(argv) else None
        elif a == '--title':
            i += 1
            title = argv[i] if i < len(argv) else None
        elif a == '--stdin':
            use_stdin = True
        else:
            files.append(a)
        i += 1

    if use_stdin:
        if not out_path:
            print("[Error] --stdin 需搭配 --out <輸出.html>")
            sys.exit(1)
        md = sys.stdin.buffer.read().decode('utf-8-sig')
        try:
            print(f"[Success] (stdin) -> {render_string(md, out_path, title)}")
        except Exception as e:
            print(f"[Error] stdin: {e}")
            sys.exit(1)
    elif out_path:
        if len(files) != 1:
            print("[Error] --out 僅能搭配單一輸入 .md")
            sys.exit(1)
        try:
            print(f"[Success] {files[0]} -> {render_file(files[0], out_path, title)}")
        except Exception as e:
            print(f"[Error] {files[0]}: {e}")
            sys.exit(1)
    else:
        for p in files:
            try:
                print(f"[Success] {p} -> {render_file(p)}")
            except Exception as e:
                print(f"[Error] {p}: {e}")

