def parse_args(argv):
    """嚴格參數驗證。

    舊版直接掃 sys.argv、未知旗標被靜默忽略 → 例如打 `--help` 會照跑「非 --all 的 15 檔路徑」
    並覆寫當日正式的 短線分析報告/短線訊號。此處改為白名單解析，未知參數印用法後 sys.exit(2)。
    """
    quiet = False
    all_stocks = False
    want_html = False
    lt_override = None
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--quiet":
            quiet = True
        elif a == "--all":
            all_stocks = True
        elif a == "--html":
            want_html = True
        elif a in ("-h", "--help"):
            print(USAGE)
            sys.exit(0)
        elif a == "--longterm":
            if i + 1 >= len(argv) or argv[i + 1].startswith("-"):
                print(USAGE)
                print("\n[Error] --longterm 需接以逗號分隔的股名清單。")
                sys.exit(2)
            lt_override = [s.strip() for s in argv[i + 1].split(",") if s.strip()]
            i += 1
        elif a.startswith("--longterm="):
            lt_override = [s.strip() for s in a.split("=", 1)[1].split(",") if s.strip()]
        else:
            print(USAGE)
            print(f"\n[Error] 未知參數：{a}——為免誤覆寫正式報告，已中止執行。")
            sys.exit(2)
        i += 1
    if lt_override is not None:
        unknown = [s for s in lt_override if s not in STOCKS]
        if unknown:
            print(USAGE)
            print(f"\n[Error] --longterm 含不在監控清單中的股名：{'、'.join(unknown)}。")
            sys.exit(2)
    return quiet, all_stocks, lt_override, want_html


