def ma_stage_label(su):
    up5, up20, up60 = su.get("站上MA5"), su.get("站上MA20"), su.get("站上MA60")
    if up5 and up20 and up60:
        return "MA5/20/60之上(多頭)"
    if not up5 and not up20 and not up60:
        return "均線之下(空頭)"
