def support_resistance(close, ma):
    if close is None:
        return "—", "—"
    levels = [(k, float(v)) for k in ("MA5", "MA10", "MA20", "MA60", "MA120", "MA240")
              if isinstance(ma.get(k), (int, float)) for v in [ma[k]]]
    below = [(k, v) for k, v in levels if v <= close]
    above = [(k, v) for k, v in levels if v > close]
    sup = max(below, key=lambda x: x[1]) if below else None
    res = min(above, key=lambda x: x[1]) if above else None
    return (f"{sup[0]}≈{sup[1]:.1f}" if sup else "無(創低)"), (f"{res[0]}≈{res[1]:.1f}" if res else "無(創高)")


def _lots(x):
    """張數格式化（千分位＋正負號）。"""
    if not isinstance(x, (int, float)):
        return "—"
