def _norm_date(s):
    """'2026/08/24' / '20260824' → 'YYYYMMDD'；無法解析回傳 ''。"""
    d = re.sub(r"\D", "", str(s or ""))
    return d if len(d) == 8 else ""


def _date_lag(d_tech, d_chip):
    """籌碼基準日落後 K 線基準日的日曆天數；同日或無法計算回傳 None。"""
    a, b = _norm_date(d_tech), _norm_date(d_chip)
    if not a or not b or a == b:
        return None
    try:
        da = datetime.date(int(a[:4]), int(a[4:6]), int(a[6:]))
        db = datetime.date(int(b[:4]), int(b[4:6]), int(b[6:]))
    except ValueError:
        return None
    return (da - db).days


def csv_latest_date(name, code):
    """該檔 K 線 CSV 首列（最新在最上·降冪）日期，正規化為 'YYYYMMDD'；讀不到回 None。"""
    p = os.path.join(ROOT, "data", name, f"{name}_{code}_近期K線.csv")
    try:
        with open(p, encoding="utf-8-sig") as f:
            f.readline()                                   # 表頭
            for line in f:
                d = _norm_date(line.split(",")[0])
                if d:
                    return d
    except Exception:
        return None
    return None


def _fmt_d(d8):
    return f"{d8[:4]}/{d8[4:6]}/{d8[6:]}" if d8 and len(d8) == 8 else "—"


def stale_note(g, name, code):
    """偵測「陳舊快取」，回傳說明字串（None＝不陳舊）。

    兩個來源都要看，否則會用今日抬頭印昨日數字：
    1) collect_stock_data 收集殘缺時，會保留舊 ground.json 並蓋上『快取未更新警示』戳記；
    2) 快取的技術面基準日 ≠ 該檔 K 線 CSV 首列日期（K 線已更新但快取沒跟上）。
    """
    notes = []
    w = ((g or {}).get("快取未更新警示") or {})
    if w:
        notes.append("collect_stock_data 蓋有『快取未更新警示』（內容基準日 {}；本次嘗試 {}；失敗原因：{}）".format(
            w.get("快取內容基準日") or "—", w.get("本次嘗試時間") or "—",
            w.get("本次收集失敗原因") or "—"))
    tech_raw = ((g or {}).get("技術面") or {}).get("資料基準日")
    tech_d, csv_d = _norm_date(tech_raw), csv_latest_date(name, code)
    if tech_d and csv_d and tech_d != csv_d:
        notes.append(f"快取基準日 {_fmt_d(tech_d)} ≠ K線CSV最新日 {_fmt_d(csv_d)}（快取未跟上 K 線）")
    return "；".join(notes) or None


def fetch_status_line(report_date):
    """讀 data/fetch_status_latest.json，產出摘要用的「抓取失敗紀錄」揭露句。

    CLAUDE.md §報告輸出規範第 1 節要求每份報告揭露「有無抓取失敗紀錄」。
    判讀契約由 update_stocks.py 定義（schema fetch_status/1.1）：
    一律以 [本次有失敗]/[本次失敗清單] 為準，不可自行解讀 fetch_failures.csv 的歷史累積列。
    狀態檔缺席或非本輪產物時，必須明說「無法確認」，**不得**逕自宣告「無抓取失敗」——
    那正是本次稽核 RPT-1 的原始缺陷（報告恆宣告無失敗）。
    """
    p = os.path.join(ROOT, "data", "fetch_status_latest.json")
    if not os.path.exists(p):
        return ("K線抓取狀態：⚠️ 查無狀態檔 data/fetch_status_latest.json，"
                "**無法確認本輪有無抓取失敗**（needs_manual；請確認 update_stocks.py 已執行）。")
    try:
        st = json.load(io_open_utf8(p))
    except Exception as e:
        return f"K線抓取狀態：⚠️ 狀態檔無法解析（{e}），**無法確認本輪有無抓取失敗**（needs_manual）。"

    ts = str(st.get("執行時間ISO") or "")
    stamp = ts[:10].replace("-", "/") if len(ts) >= 10 else ""
    fresh = (not stamp) or (not report_date) or (stamp == report_date)
    fails = st.get("本次失敗清單") or []
    oks = st.get("本次成功清單") or []
    stale_note = "" if fresh else (f"；⚠️ 狀態檔執行日 {stamp} 與報告基準日 {report_date} 不符，"
                                   "本輪 update 可能未執行，下述結果僅供參考")

    if st.get("本次有失敗"):
        names = "、".join(str(x.get("股名") or x) if isinstance(x, dict) else str(x) for x in fails)
        return (f"K線抓取狀態：⚠️ **本輪有 {len(fails)} 檔抓取失敗**（{names}）"
                f"——該檔技術面沿用舊資料，判讀須降權{stale_note}。")
    return (f"K線抓取狀態：本輪無抓取失敗紀錄（成功 {len(oks)} 檔，"
            f"依 {st.get('schema', 'fetch_status')} 狀態檔 {stamp or '無時戳'}）{stale_note}。")


def io_open_utf8(p):
    return open(p, encoding="utf-8")


def rs_short(r):
    """總表／摘要用的精簡 RS 標示。"""
    if isinstance(r.get("rs"), (int, float)):
        return f"RS{fnum(r['rs'], 0, plus=True)}%"
    lag = r.get("rs_lag")
    if isinstance(lag, (int, float)):
        return f"RS不可用(指數過期{int(lag)}交易日)"
    return "RS不可用(無資料)"


def rs_text(r):
    """簡評／訊號 JSON 用的 RS 標示。

    TECH-3 讓指數過期時 RS%=None 並在 ground.json 寫明原因；交付層若只印 'RS—%'，
    讀者看不到 needs_manual 與過期天數，等同沒修。故 RS 不可用時一律帶出過期說明。
    """
    if isinstance(r.get("rs"), (int, float)):
        return f"RS{fnum(r['rs'], 0, plus=True)}%"
    lag = r.get("rs_lag")
    if isinstance(lag, (int, float)):
        return (f"⚠RS 不可用(指數過期{int(lag)}個交易日；RS基準日{r.get('rs_base') or '—'} vs "
                f"個股基準日{r.get('rs_stock_base') or '—'}·needs_manual，不得作相對強弱多空依據)")
    v = str(r.get("rs_view") or "").strip()
    if v:
        return f"⚠RS 不可用（{v}）"
    return "⚠RS 不可用(無 Mansfield RS 資料·needs_manual)"


def flow_material(net, vol):
    """框架 §5.4 量能校正：法人淨額須達「近5日總成交量」10% 以上才脫離雜訊層。

    回傳 True(達門檻) / False(雜訊層) / None(無淨額或無量能基準、無法校正)。
    近5日均量單位為股、法人淨額單位為張，故基準換算 股→張。
    """
    if not isinstance(net, (int, float)):
        return None
    av5 = (vol or {}).get("近5日均量")
    if not isinstance(av5, (int, float)) or av5 <= 0:
        return None
    return abs(net) >= 0.10 * (av5 * 5.0 / 1000.0)


def trend_flow(chip):
    """取框架 §5.2 趨勢層（20/60 日累積）並帶出涵蓋天數，缺漏一律可稽核。"""
    a = ((chip or {}).get("20_60日累積(本地)") or {})
    m = re.search(r"20日(\d+)\D+60日(\d+)", str(a.get("涵蓋交易日") or ""))
    d20 = int(m.group(1)) if m else None
    d60 = int(m.group(2)) if m else None
    has = bool(a) and (a.get("外資20日累計張") is not None or a.get("外資60日累計張") is not None)
    return {
        "has": has, "d20": d20, "d60": d60,
        "fx20": a.get("外資20日累計張"), "fx60": a.get("外資60日累計張"),
        "inv20": a.get("投信20日累計張"), "inv60": a.get("投信60日累計張"),
        "view": a.get("外資研判(20vs60)"), "inv_view": a.get("投信研判(20vs60)"),
        "short": (not has) or d20 is None or d60 is None or d20 < 20 or d60 < 60,
    }


def foreign_hold(mk):
    """官方外資持股比率%（僅上市有值；上櫃回 None）。"""
    v = (mk or {}).get("外資持股比率%")
    return v if isinstance(v, (int, float)) else None


def tech_signals(t, pat, su, vol, chip, hold=None):
    tags = [pat.get("紅綠", "")]
    reasons, flags = [], []
    red = str(pat.get("紅綠", "")).startswith("紅")
    shrink = bool(pat.get("今棒縮量(vs前棒)"))
    pos52 = t.get("現價52週位階%")
    deep = (isinstance(pos52, (int, float)) and pos52 <= 30) or \
           (isinstance(t.get("自52週高%"), (int, float)) and t["自52週高%"] <= -25)
    vr = vol.get("最新量/前5日均量(倍)")
    fx_leg = chip.get("外資") or {}
    fx5 = fx_leg.get("近5日張")
    # 「淨流出/無成本線」只有在確實取得外資資料時才成立；籌碼整段缺漏不得冒充淨流出
    fx_out = bool(fx_leg) and fx_leg.get("估計成本線") is None

    if pat.get("母子懷抱線"):
        tags.append("母子懷抱線")
        if shrink and deep:
            reasons.append("母子懷抱線(縮量+低檔)")
            flags.append("✅合格抄底候選(縮量+位階跌深)")
        else:
            reasons.append("母子懷抱線(位階未跌深/未縮量)")
            flags.append("⚠高檔母子→變盤/非抄底")
    if pat.get("十字線"):
        tags.append("十字線")
        reasons.append("十字線")
        flags.append("⚠十字線變盤警訊")
    if pat.get("錘子型"):
        tags.append("錘子型")
        reasons.append("錘子型")
        flags.append("錘子(低檔止跌試探)" if deep else "錘子(非低檔、意義弱)")
    if pat.get("墓碑型"):
        tags.append("墓碑型")
        reasons.append("墓碑型")
        flags.append("⚠墓碑/長上影→賣壓")
    if shrink and "縮量" not in tags:
        tags.append("縮量")

    if isinstance(vr, (int, float)) and vr >= 2.0:
        reasons.append(f"爆量{vr:.1f}x")
        chg = (t.get("近10日單日漲跌幅%") or [None])[-1]
        if not red or (isinstance(chg, (int, float)) and chg <= 0):
            flags.append("⚠爆量滯漲/收黑→出貨疑慮")
    elif isinstance(vr, (int, float)) and vr <= 0.4:
        reasons.append(f"極縮量{vr:.2f}x")

    fx_div = (chip.get("外資") or {}).get("乖離%")
    inv_div = (chip.get("投信") or {}).get("乖離%")
    if isinstance(fx_div, (int, float)) and abs(fx_div) >= 8:
        reasons.append(f"外資乖離{fx_div:+.1f}%")
    if isinstance(inv_div, (int, float)) and abs(inv_div) >= 8:
        reasons.append(f"投信乖離{inv_div:+.1f}%")

    # —— 籌碼旗標：方向一律取框架 §5.2 趨勢層(20/60日累積)，近5日僅作 §8.2 抄底第三條件之「驗證」，
    #    且所有法人淨額先過 §5.4 量能校正；§5.3 法人本就低持股者其流向不作背離依據 ——
    tr = trend_flow(chip)
    fx20, fx60 = tr["fx20"], tr["fx60"]
    m5, m20 = flow_material(fx5, vol), flow_material(fx20, vol)
    low_hold = isinstance(hold, (int, float)) and hold < 5.0

    # 籌碼背離：紅K上漲，但外資 20/60 日累積同向淨賣（趨勢層撤離）且淨額達量能門檻
    if red and not low_hold and m20 is True and isinstance(fx20, (int, float)) and fx20 < 0 \
            and isinstance(fx60, (int, float)) and fx60 < 0:
        flags.append(f"⚠籌碼背離(紅K漲但外資20/60日同向淨賣：20日{_lots(fx20)}張)")
        reasons.append("籌碼背離(外資20日累計淨賣)")

    # 防假止跌(§8.2)：低檔轉強K棒須有法人同步驗證；缺驗證即標記，且明列判定依據
    fx_sync = (m20 is True and isinstance(fx20, (int, float)) and fx20 > 0) or \
              (m5 is True and isinstance(fx5, (int, float)) and fx5 > 0)
    if (pat.get("錘子型") or red) and deep and not low_hold and not fx_sync:
        if m20 is True and isinstance(fx20, (int, float)) and fx20 < 0:
            basis = f"外資20日累計{_lots(fx20)}張"
        elif fx_out:
            basis = "外資視窗內淨流出·無成本線"
        elif m5 is True and isinstance(fx5, (int, float)) and fx5 < 0:
            basis = f"外資近5日{_lots(fx5)}張(達量能門檻)"
        elif not tr["has"]:
            basis = "⚠外資20/60日趨勢層資料缺漏·無法驗證(needs_manual)"
        elif m20 is None and m5 is None:
            basis = "⚠法人流向資料缺漏·無法驗證"
        else:
            basis = "法人流向皆在雜訊層·無法驗證同步"
        flags.append(f"⚠防假止跌(低檔轉強未獲法人趨勢驗證：{basis})")
        reasons.append("防假止跌")
    if su.get("站上MA5") != su.get("站上MA20"):
        reasons.append("MA5/20位階分歧")

    return "、".join([x for x in tags if x]) or "—", reasons, flags


def chip_cell(leg):
    if not leg:
        return "—"
    cost = leg.get("估計成本線")
    if cost is None:
        return "淨流出"
    d5 = leg.get("近5日張")
    d5s = f"{d5/1000:+.1f}k張" if isinstance(d5, (int, float)) else "—"
    return f"{cost:.1f}｜{fnum(leg.get('乖離%'),1,plus=True)}%｜5日{d5s}(雜訊層)"


def chip_full(tag, leg):
    if not leg:
        return f"{tag}：—"
    cost = leg.get("估計成本線")
    if cost is None:
        return f"{tag}：淨流出/無成本線（近5日{fnum(leg.get('近5日張'),0,plus=True)}張·雜訊層非訊號）"
    return (f"{tag}成本線 {cost:.1f}（乖離{fnum(leg.get('乖離%'),1,plus=True)}%、起算{leg.get('起算日','—')}、"
            f"累計{fnum(leg.get('累計張'),0)}張、近5日{fnum(leg.get('近5日張'),0,plus=True)}張·雜訊層非訊號）")


def trend_cell(tr, vol, hold):
    """總表「外資20/60日(趨勢層)」欄：合法窗口＋量能校正＋涵蓋天數，全部可稽核。"""
    if not tr["has"]:
        return "⚠20/60日資料缺漏"
    s = [f"20日{_lots(tr['fx20'])}／60日{_lots(tr['fx60'])}張"]
    if tr.get("view"):
        s.append(str(tr["view"]))
    if flow_material(tr["fx20"], vol) is False:
        s.append("(20日<近5日量10%·雜訊層)")
    elif flow_material(tr["fx20"], vol) is None:
        s.append("(無量能基準·未校正)")
    if isinstance(hold, (int, float)) and hold < 5.0:
        s.append(f"(外資持股{hold:.1f}%·參考性低)")
    if tr["short"]:
        s.append(f"⚠涵蓋{tr['d20']}/{tr['d60']}日(不足20/60)")
    return "｜".join(s)


def trend_full(tr, vol, hold):
    """簡評用的趨勢層敘述。"""
    if not tr["has"]:
        return "外資20/60日趨勢層：⚠資料缺漏、無法判斷（needs_manual）"
    txt = (f"外資20日累計{_lots(tr['fx20'])}張／60日累計{_lots(tr['fx60'])}張"
           f"（{tr.get('view') or '—'}；涵蓋{tr['d20']}/{tr['d60']}交易日"
           f"{'⚠不足' if tr['short'] else ''}）")
    mat = flow_material(tr["fx20"], vol)
    if mat is False:
        txt += "；20日淨額未達近5日總量10%，依§5.4屬雜訊層、不作方向依據"
    elif mat is None:
        txt += "；⚠無量能基準可作§5.4校正"
    if isinstance(hold, (int, float)) and hold < 5.0:
        txt += f"；外資持股比率僅{hold:.1f}%（§5.3 法人本就低持股，流向不作背離依據）"
    return txt


def _adx_env(a):
    v = a.get("ADX")
    if not isinstance(v, (int, float)):
        return "—"
    return "趨勢" if v >= 25 else ("盤整" if v < 20 else "醞釀")


def compact_ind(ind):
    """表格用精簡指標串。"""
    if not ind or "error" in ind:
        return "指標資料不足"
    m, k, r = ind.get("MACD", {}), ind.get("KD", {}), ind.get("RSI", {})
    b, a = ind.get("布林通道", {}), ind.get("DMI_ADX", {})
    mac = f"MACD柱{m.get('OSC(柱)')}({m.get('方向')}{'·'+m['交叉'] if m.get('交叉') else ''})"
    kd = f"KD{k.get('K')}/{k.get('D')}{'·'+k['交叉'] if k.get('交叉') else ''}"
    if k.get("區間") not in (None, "中性"):
        kd += f"·{k['區間']}"
    rsi = f"RSI{r.get('值')}"
    if r.get("區間") not in (None, "中性"):
        rsi += f"·{r['區間']}"
    boll = f"布林{(b.get('位置') or '').split('(')[0]}"
    adx = f"ADX{a.get('ADX')}({_adx_env(a)})"
    return "；".join([mac, kd, rsi, boll, adx])


def ind_full(ind):
    """簡評用完整指標串。"""
    if not ind or "error" in ind:
        return "公認指標：資料不足"
    m, k, r = ind.get("MACD", {}), ind.get("KD", {}), ind.get("RSI", {})
    b, a = ind.get("布林通道", {}), ind.get("DMI_ADX", {})
    res = ind.get("多空共振", {})
    parts = [
        f"MACD DIF{m.get('DIF')}/DEA{m.get('DEA')}、柱{m.get('OSC(柱)')}（{m.get('零軸')}、方向{m.get('方向')}{'、'+m['交叉'] if m.get('交叉') else ''}）",
        f"KD {k.get('K')}/{k.get('D')}（{k.get('區間')}{'、'+k['交叉'] if k.get('交叉') else ''}）",
        f"RSI {r.get('值')}（{r.get('區間')}）",
        f"布林 {b.get('位置')}（%B{b.get('%B')}、帶寬{b.get('帶寬%')}%）",
        f"DMI +DI{a.get('+DI')}/-DI{a.get('-DI')}、ADX{a.get('ADX')}（{a.get('趨勢環境')}）",
    ]
    head = f"多空共振：{res.get('方向')}（強度{res.get('強度')}、淨分{res.get('淨分')}、{res.get('多方指標')}多:{res.get('空方指標')}空）"
    return head + "；" + "；".join(parts)


def analyze(name):
    g = load_ground(name)
    code = STOCKS.get(name, "?")
    t = (g or {}).get("技術面") or {}
    tech_date = t.get("資料基準日")
    stale = stale_note(g, name, code)
    # OPS-3：殘缺判定須做「實質檢查」。舊版只看鍵是否存在，技術面＝{"error":...} 時仍算有資料，
    # 於是在 close=None、均線全空的情況下照樣輸出 ma_stage='均線之下(空頭)'／verdict='偏空'——
    # 完全沒有數字卻斷定方向。改為要求「最新單棒有收盤價」才視為可用，否則一律標資料缺漏(needs_manual)。
    bar0 = t.get("最新單棒") or {}
    if (not g) or (not t) or ("error" in t) or (bar0.get("Close") is None):
        if not g:
            why = "找不到地面數據快取"
        elif not t:
            why = "快取內無技術面"
        elif "error" in t:
            why = f"技術面錯誤：{t.get('error')}"
        elif not bar0:
            why = "技術面無最新單棒"
        else:
            why = "最新單棒無收盤價"
        return {"name": name, "code": code, "missing": True, "missing_reason": why,
                "tech_date": tech_date, "stale": stale}
    chip = g.get("籌碼面", {}) or {}
    bar = t.get("最新單棒", {}) or {}
    pat = t.get("最新單棒型態", {}) or {}
    su = t.get("站上均線", {}) or {}
    vol = t.get("量能", {}) or {}
    ma = t.get("均線", {}) or {}
    week = (t.get("週線Weinstein") or {})
    rs = (t.get("MansfieldRS") or {})
    ind = t.get("技術指標") if isinstance(t.get("技術指標"), dict) else {}

    close = bar.get("Close")
    chgs = t.get("近10日單日漲跌幅%") or []
    chg = chgs[-1] if chgs else None

    mk = g.get("市場面(官方)") or {}
    hold = foreign_hold(mk)
    tr = trend_flow(chip)
    chip_date = chip.get("資料基準日")
    chip_lag = _date_lag(t.get("資料基準日"), chip_date)

    tag_str, reasons, flags = tech_signals(t, pat, su, vol, chip, hold)
    sup, res = support_resistance(close, ma)

    reso = ind.get("多空共振") if ind and "error" not in ind else None
    if reso:
        verdict = reso["方向"]
        strength = reso.get("強度", "")
        env = reso.get("趨勢環境", "")
        for key, fld in (("MACD", "交叉"), ("KD", "交叉"), ("均線交叉", "近日交叉")):
            cx = (ind.get(key) or {}).get(fld)
            if cx:
                reasons.append(f"{key.replace('交叉','')}{cx}")
    else:
        verdict = judge_fallback(su, stage_num(week.get("階段")), flags)
        strength, env = "", ""

    vr = vol.get("最新量/前5日均量(倍)")
    return {
        "name": name, "code": code, "missing": False,
        "close": close, "chg": chg, "pos52": t.get("現價52週位階%"),
        "ma_stage": ma_stage_label(su), "tag": tag_str, "flags": flags,
        "vol": (f"{vr:.2f}x " + ("放量" if vr >= 1.5 else ("縮量" if vr <= 0.7 else "持平"))) if isinstance(vr, (int, float)) else "—",
        "fx": chip_cell(chip.get("外資")), "inv": chip_cell(chip.get("投信")),
        "fx_full": chip_full("外資", chip.get("外資")), "inv_full": chip_full("投信", chip.get("投信")),
        "chip_view": chip.get("研判(系統)", "—"),
        "trend": trend_cell(tr, vol, hold), "trend_full": trend_full(tr, vol, hold),
        "trend_short": bool(tr["short"]), "fx_hold": hold,
        "chip_date": chip_date, "chip_lag": chip_lag,
        "tech_date": tech_date, "stale": stale,
        "week_full": week.get("階段", "—"), "rs": rs.get("RS%"), "rs_view": rs.get("研判", ""),
        "rs_lag": rs.get("落後交易日數"), "rs_base": rs.get("RS基準日"),
        "rs_stock_base": rs.get("個股基準日"),
        "sup": sup, "res": res,
        "ind_compact": compact_ind(ind), "ind_full": ind_full(ind), "ind_env": env,
        "verdict": verdict, "strength": strength,
        "signal": bool(reasons) or bool(flags), "reasons": reasons,
    }


def judge_fallback(su, snum, flags):
    up5, up20, up60 = su.get("站上MA5"), su.get("站上MA20"), su.get("站上MA60")
    ups = sum(1 for x in (up5, up20, up60) if x)
    v = "偏多" if (ups == 3 or (up5 and up20)) else ("偏空" if (ups == 0 or (not up5 and not up20)) else "中性/震盪")
    if snum == 4:
        v = "偏空"
    return v


def vd_mark(v):
    return f"**{v}**" if v in ("偏多", "偏空") else v


def build_md(rows, datefmt, scope_label, excluded=None, date_note=None):
    ok = [r for r in rows if not r["missing"]]
    n_bull = sum(1 for r in ok if r["verdict"] == "偏多")
    n_bear = sum(1 for r in ok if r["verdict"] == "偏空")
    n_neu = len(ok) - n_bull - n_bear
    sig = [r for r in ok if r["signal"]]
    missing = [r["name"] for r in rows if r["missing"]]
    excluded = excluded or []
    lagged = [r for r in ok if r.get("chip_lag")]
    short_cov = [r for r in ok if r.get("trend_short")]
    stale_rows = [r for r in rows if r.get("stale")]
    rs_bad = [r for r in ok if not isinstance(r.get("rs"), (int, float))]

    md = []
    md.append(f"# 短線分析報告（{scope_label}）\n")
    md.append(f"**資料基準日：{datefmt}** ｜ 涵蓋：{scope_label}"
              f"{'（監控 %d 檔扣除長線 %d 檔：%s）' % (len(STOCKS), len(excluded), '、'.join(excluded)) if excluded else '（監控清單全覆蓋）'} ｜ "
              "公認技術指標(MACD/KD/RSI/布林/DMI-ADX)＋法人成本線皆內嵌本報告。\n")
    md.append("> 方法：以台股六大指標＋**多指標共振**定短線方向（趨勢MACD/均線/DMI＋動能KD/RSI＋波動布林），"
              "並用 **ADX 判趨勢盤(順勢)/盤整盤(超買超賣做均值回歸)**；輔以 K線型態(母子懷抱線須縮量＋跌深才算抄底、"
              "十字線變盤、墓碑賣壓)、防詐騙假止跌與**籌碼背離(以外資20/60日累積趨勢層判定)**、法人成本線位階。"
              "**籌碼分層鐵則：單日／近5日買賣超屬雜訊層，僅供記錄與抄底條件驗證，嚴禁當買賣訊號**；"
              "法人淨額一律先過 §5.4 量能校正（未達近5日總成交量 10% 視為雜訊）。詳 steering/技術指標與多空共振.md。\n")

    md.append("## 一、摘要\n")
    md.append(f"- 涵蓋範圍：本報告共 **{len(rows)} 檔**（{scope_label}）；資料可用 {len(ok)} 檔。")
