def main():
    # 參數採白名單嚴格驗證（未知參數 → 印用法、exit 2），不得靜默退回會覆寫正式報告的預設路徑
    quiet, all_stocks, lt_override, want_html = parse_args(sys.argv[1:])
    excluded = list(lt_override) if lt_override is not None else list(LONGTERM)
    short_list = [s for s in STOCKS if s not in lt_override] if lt_override is not None else SHORT
    if all_stocks:                     # 涵蓋全部監控標的（長線軌移除後，每日保底全覆蓋）
        short_list = list(STOCKS)
        excluded = []
    excluded = [s for s in excluded if s in STOCKS and s not in short_list]
    # 涵蓋範圍字串一律由實際 short_list 動態產生，供 h1／副標／HTML <title> 共用（不得寫死檔數）
    scope_label = (f"全持股 {len(short_list)} 檔" if len(short_list) == len(STOCKS)
                   else f"其他 {len(short_list)} 檔")

    rows = [analyze(n) for n in short_list]

    # 報告日期：舊版只取「第一檔有資料基準日的股票」，其餘檔即使停在舊日也被冠上同一個抬頭。
    # 改為逐檔比對：抬頭取最新的基準日，任一檔不同即列入警示（陳舊快取另由 stale_note 標示）。
    dated = [(r["name"], r.get("tech_date")) for r in rows if r.get("tech_date")]
    if not dated:
        print("[Error] 找不到任何地面數據快取，請先跑 collect_stock_data.py --all。")
        return 1
    datefmt = max(d for _, d in dated)
    off_date = [(n, d) for n, d in dated if d != datefmt]
    date_note = None
    if off_date:
        date_note = ("- ⚠️ **各檔快取基準日不一致**（本報告抬頭取最新者 %s）：%s"
                     "——標示檔之數字為該檔自身基準日的資料，不得以抬頭日名義判讀。"
                     % (datefmt, "、".join(f"{n}({d})" for n, d in off_date)))
        print(f"[Warn] 快取基準日不一致：{'、'.join(f'{n}({d})' for n, d in off_date)}（抬頭 {datefmt}）")
    datestr = datefmt.replace("/", "")

    md, sig = build_md(rows, datefmt, scope_label, excluded, date_note)

    # 自檢：總表資料列數須等於涵蓋檔數，不符即為涵蓋範圍與內容不一致（不得靜默交付）
    n_table = sum(1 for ln in md.splitlines()
                  if ln.startswith("| ") and "(" in ln.split("|")[1] and "股名" not in ln.split("|")[1])
    scope_ok = (n_table == len(short_list))
    if not scope_ok:
        warn = (f"- ⚠️ 自檢未通過：總表資料列 {n_table} 列 ≠ 涵蓋檔數 {len(short_list)} 檔，"
                "請勿依本報告的涵蓋範圍敘述作判讀。")
        md = md.replace("## 二、全覆蓋總表", warn + "\n\n## 二、全覆蓋總表", 1)
        print(f"[Error] 涵蓋範圍自檢未通過：表格 {n_table} 列 vs 應為 {len(short_list)} 檔")

    with open(os.path.join(CACHE, f"短線報告_{datestr}.md"), "w", encoding="utf-8") as f:
        f.write(md)

    with open(os.path.join(CACHE, f"短線訊號_{datestr}.json"), "w", encoding="utf-8") as f:
        json.dump({"資料基準日": datefmt, "涵蓋範圍": scope_label, "涵蓋檔數": len(short_list),
                   "未涵蓋(長線)": excluded, "涵蓋自檢": scope_ok,
                   "各檔基準日不一致": [{"股名": n, "資料基準日": d} for n, d in off_date],
                   "陳舊快取": [{"股名": r["name"], "說明": r["stale"], "資料基準日": r.get("tech_date")}
                             for r in rows if r.get("stale")],
                   "資料缺漏": [{"股名": r["name"], "原因": r.get("missing_reason")}
                             for r in rows if r["missing"]],
                   "訊號個股": [
            {"股名": r["name"], "代碼": r["code"], "收盤": r["close"], "漲跌%": r["chg"],
             "52週位階%": r["pos52"], "均線位階": r["ma_stage"], "型態": r["tag"], "旗標": r["flags"],
             "近端支撐": r["sup"], "近端壓力": r["res"], "量能": r["vol"],
             "公認指標": r["ind_full"], "多空共振方向": r["verdict"], "共振強度": r["strength"],
             "外資20_60日(趨勢層)": r["trend_full"], "20_60日涵蓋不足": r["trend_short"],
             "外資成本線": r["fx_full"], "投信成本線": r["inv_full"], "系統研判": r["chip_view"],
             "籌碼資料基準日": r["chip_date"], "籌碼落後日曆日": r["chip_lag"],
             "週線階段": r["week_full"], "RS%": r["rs"],
             # RS% 為 null 時必須同時帶出不可用原因（指數過期天數／needs_manual），不可只有 null
             "RS%說明": rs_text(r), "RS研判": r["rs_view"] or None,
             "RS指數落後交易日數": r.get("rs_lag"), "RS基準日": r.get("rs_base"),
             "陳舊快取": r.get("stale"), "個股資料基準日": r.get("tech_date"),
             "訊號": r["reasons"]}
            for r in sig]}, f, ensure_ascii=False, indent=2)

    # 「短線分析報告」HTML 自 2026/09/09 起停產（使用者指示：不需要這份保底報告）。
    # 每日交付＝19 檔短線深度報告＋短線整合報告；本腳本仍須續跑，因為
    # 短線訊號 JSON 是 backtest_signals.py 的輸入、也是報告「訊號可靠度揭露」的來源。
    html_path = None
    if want_html:
        html_path = os.path.join(ROOT, f"短線分析報告_{datestr}_Claude.html")
        with open(html_path, "w", encoding="utf-8") as f:
            f.write(report_html.wrap(f"短線分析報告（{scope_label}·保底） {datefmt}", report_html.md_to_html(md)))

    if not quiet:
        n_ok = sum(1 for r in rows if not r["missing"])
        print(f"[Success] 短線報告 {datefmt}（{scope_label}）：{n_ok}/{len(short_list)} 檔、訊號 {len(sig)} 檔")
        print(f"  HTML: {html_path}" if html_path else "  HTML: 已停產（--html 才產）；訊號 JSON 照常寫出")
        for r in [x for x in rows if not x["missing"]]:
            print(f"  {r['name']}({r['code']}) {r['verdict']}{('/'+r['strength']) if r['strength'] else ''}｜{r['ind_compact'][:60]}")
    # 報告仍寫出（保底交付不可缺），但涵蓋範圍自檢未過時以非 0 退出碼讓失敗可見
    return 0 if scope_ok else 1


if __name__ == "__main__":
    sys.exit(main())

# -*- coding: utf-8 -*-
"""
估值模組：給「現價 + 基本面庫(fundamentals.json)的一檔資料」→ 算 EPS/PE/PB 並依
長線框架判「便宜/合理偏低/合理/合理偏高/貴」。

框架鐵則：
- 循環股用 PB-Band ＋ 正常化EPS 為主，鐵則「低PE≠便宜」(谷底EPS會使trailing PE虛高)。
- 成長股用 PE 區間(對照成長性)。
- 穩定收息股用 PE 區間＋殖利率。

EPS 屬季頻(慢)，PE 用「現價 ÷ EPS」每日重算；本模組不落地、由呼叫端寫入 ground 或報告。

【新鮮度與口徑揭露】(修 VAL-1 / RPT-3：禁止靜默降級)
- EPS/每股淨值皆為季頻。assess() 會判定基本面庫的 EPS 季別是否落後：
  優先與呼叫端傳入之官方「財報季別」(民國 115Q2＝2026Q2) 比對；官方缺該欄(如金融業台企銀)
  時退為「台股財報申報期限」推算(Q1 5/15、Q2 8/14、Q3 11/14、Q4併年報 3/31)。
  落後 ≥1 季即標 `資料過期=True`＋`過期說明`，並把 `信心` 降級；one_line() 前綴 ⚠。
- 官方市場面(market_latest.json 該檔)可由呼叫端傳入；未傳則本模組自行依 fund['code'] 讀取快取
  (避免「沒人接線＝檢核永不啟動」)。據此併算「官方口徑」PE/PB 作交叉檢核，差異過大填 `口徑衝突`，
  供呼叫端推進 needs_manual、供報告揭露(不再只印單一過期數字而無對照)。
- PB-Band 的判定分母仍採基本面庫 book_value：pb_cheap/pb_expensive 是研究員對著同一條
  BVPS 序列校準出來的界線，單換分母等於整條帶位平移；且官方 BVPS 為除息後帳面值，
  每年除息當季機械性跳水，逕行替換會讓高配息股在除息季被系統性判「貴」(製造新假訊號)。
  故官方值作為對照與揭露；若 PB-Band 條件在官方口徑下不成立，會直接寫進「理由」。
"""
import datetime as _dt
import json
import os
import re

FUND_REL = os.path.join("data", "_fundamentals", "fundamentals.json")

# 5 級 → 3 級徽章
TAG3 = {"便宜": "便宜", "合理偏低": "便宜", "合理": "合理", "合理偏高": "貴", "貴": "貴", "難判定": "—"}

# 台股財報申報期限（Q4 併年報，翌年 3/31）
_FILING_DEADLINE = {1: (5, 15), 2: (8, 14), 3: (11, 14)}
# 口徑差異告警門檻（PE 因官方 PE 之股價基準日與本地收盤可能差數日，門檻放寬）
_PB_CONFLICT_TH = 0.10
_PE_CONFLICT_TH = 0.15


def load_fundamentals(root):
    p = os.path.join(root, FUND_REL)
    try:
        with open(p, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _num(x):
    try:
        if x is None:
            return None
        return float(x)
    except Exception:
        return None


def _head(stype):
    """取主分類(括號前)，避免括號內描述如「兼具循環特性」誤判股性。"""
    s = str(stype or "")
    for sep in ("（", "(", "／", "/", "，", "、"):
        s = s.split(sep)[0]
    return s.strip()


def _is_cyclical(stype):
    return "循環" in _head(stype)


def _is_income(stype):
    h = _head(stype)
    return any(w in h for w in ("穩定", "收息", "金融", "銀行"))


# ---------------- 季別 / 新鮮度 ----------------

def _parse_period(s):
    """'2026Q1'/'115Q2'(民國)/'2026 Q1' → (2026, 1)；無法解析回 None(不示警、不誤判為無限落後)。"""
    m = re.search(r"(\d{3,4})\s*[QqＱq季]\s*([1-4])", str(s or ""))
    if not m:
        return None
    y, q = int(m.group(1)), int(m.group(2))
    if y < 1911:            # 民國年（115Q2 → 2026Q2）
        y += 1911
    if not (1990 <= y <= 2100):
        return None
    return (y, q)


def _period_str(p):
    return f"{p[0]}Q{p[1]}" if p else None


def _q_diff(a, b):
    """b 比 a 新幾季。"""
    return (b[0] - a[0]) * 4 + (b[1] - a[1])


def _as_date(x):
    if isinstance(x, _dt.datetime):
        return x.date()
    if isinstance(x, _dt.date):
        return x
    s = str(x or "").strip().replace("-", "/")
    m = re.search(r"(\d{4})/(\d{1,2})/(\d{1,2})", s)
    if not m:
        m2 = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", s)
        if not m2:
            return None
        m = m2
    try:
        return _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None


def _expected_period(today):
    """依台股申報期限推算「此刻應已公布的最新季別」(官方季別缺漏時的備援基準)。"""
    cands = []
    for y in (today.year - 1, today.year):
        for q in (1, 2, 3, 4):
            dl = _dt.date(y + 1, 3, 31) if q == 4 else _dt.date(y, *_FILING_DEADLINE[q])
            if dl <= today:
                cands.append((y, q))
    return max(cands) if cands else None


def _fund_period(fund):
    """基本面庫該檔的 EPS 季別：取 eps_recent 內最大 period（該陣列排序不一致，不可取末筆），
    無 eps_recent 時退而解析 as_of 自由文字內的季別。"""
    best = None
    for e in (fund.get("eps_recent") or []):
        p = _parse_period((e or {}).get("period") if isinstance(e, dict) else e)
        if p and (best is None or p > best):
            best = p
    if best is None:
        best = _parse_period(fund.get("as_of"))
    return best


_MK_REL = os.path.join("data", "_market_cache", "market_latest.json")
_MK_CACHE = {"mtime": None, "data": {}, "date": ""}


def _load_market_latest():
    """自行讀官方市場面快取(依 mtime 快取)。呼叫端未傳 official 時的備援，
    避免『沒人接線＝交叉檢核永遠不啟動』的靜默降級。"""
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    p = os.path.join(root, _MK_REL)
    try:
        mt = os.path.getmtime(p)
    except Exception:
        return {}, ""
    if _MK_CACHE["mtime"] != mt:
        try:
            with open(p, encoding="utf-8") as f:
                _MK_CACHE["data"] = json.load(f)
        except Exception:
            _MK_CACHE["data"] = {}
        _MK_CACHE["mtime"] = mt
        _MK_CACHE["date"] = _dt.datetime.fromtimestamp(mt).strftime("%Y/%m/%d")
    return _MK_CACHE["data"], _MK_CACHE["date"]


def _official_view(official, fund=None):
    """呼叫端可傳：該檔「市場面(官方)」dict、單一官方每股淨值數值、或 None(→自動由快取取該檔)。
    回傳 (dict, 來源說明)。"""
    if isinstance(official, dict):
        return official, "呼叫端傳入"
    if official is not None:
        v = _num(official)
        return ({"每股淨值元": v} if v is not None else {}), "呼叫端傳入(僅每股淨值)"
    code = (fund or {}).get("code") or (fund or {}).get("代碼")
    if not code:
        return {}, "無(未傳入且基本面庫無代碼)"
    data, mdate = _load_market_latest()
    d = data.get(str(code))
    if isinstance(d, dict):
        return d, f"自動讀取 market_latest.json（快取更新日 {mdate}）"
    return {}, "無(官方市場面快取無此檔或尚未抓取)"


def _r1(x):
    return round(x, 1) if x is not None else None


def _r2(x):
    return round(x, 2) if x is not None else None


def assess(close, fund, official=None, today=None):
    """回傳估值 dict。
    close    = 現價(float)
    fund     = fundamentals.json 內該股的 entry
    official = 該檔「市場面(官方)」dict(market_latest.json 該檔) 或單一官方每股淨值；
               未傳則自動以 fund['code'] 由 market_latest.json 取該檔(取不到才退為申報期限推算)。
    today    = 新鮮度檢核基準日(date 或 'YYYY/MM/DD'/'YYYYMMDD')，預設今日。
    """
    today = _as_date(today) or _dt.date.today()

    if not fund:
        return {"可用": False, "說明": "基本面資料未建置(needs_manual)",
                "資料過期": None, "過期說明": "", "口徑衝突": None}
    off, off_src = _official_view(official, fund)
    close = _num(close)
    stype = fund.get("stock_type", fund.get("股性", ""))
    eps_ttm = _num(fund.get("eps_ttm"))
    eps_norm = _num(fund.get("eps_normalized"))
    eps_fwd = _num(fund.get("eps_forward"))
    bvps_res = _num(fund.get("book_value"))
    pe_lo = _num(fund.get("pe_fair_low"))
    pe_hi = _num(fund.get("pe_fair_high"))
    pb_cheap = _num(fund.get("pb_cheap"))
    pb_exp = _num(fund.get("pb_expensive"))

    # --- 官方口徑（僅作對照/揭露，不替換 PB-Band 分母，理由見模組 docstring） ---
    off_period = _parse_period(off.get("財報季別"))
    off_period_s = _period_str(off_period)
    bvps_off = _num(off.get("每股淨值元"))
    pe_off = _num(off.get("本益比PE"))
    pb_off_pub = _num(off.get("股價淨值比PB"))
    off_carry = bool(off.get("財報為前期沿用"))

    # --- 新鮮度閘門（VAL-1）：官方季別優先，缺則用申報期限推算 ---
    fp = _fund_period(fund)
    base_p, base_src = (off_period, "官方財報季別") if off_period else (_expected_period(today), "申報期限推算")
    lag = _q_diff(fp, base_p) if (fp and base_p) else None
    stale = bool(lag and lag >= 1)
    if fp is None:
        stale, lag = True, None
        stale_msg = "基本面庫無可解析的 EPS 季別(eps_recent/as_of 缺 period)，無從查核新鮮度，PE/PB 請勿當校準基準"
    elif stale:
        stale_msg = (f"EPS/每股淨值僅至 {_period_str(fp)}，{base_src}已到 {_period_str(base_p)}"
                     f"(落後 {lag} 季)；PE/PB 與便宜貴判定失真，請跑「基本面研究」季更")
        if off_carry:
            stale_msg += "；註：官方季報欄位標示為前期沿用"
    else:
        stale_msg = ""

    pe_ttm = (close / eps_ttm) if (close and eps_ttm and eps_ttm > 0) else None
    pe_norm = (close / eps_norm) if (close and eps_norm and eps_norm > 0) else None
    pe_fwd = (close / eps_fwd) if (close and eps_fwd and eps_fwd > 0) else None

    # PB 分母：以基本面庫 book_value 為準(PB帶即以此校準)；缺值才退用官方季報值並標明來源
    if bvps_res and bvps_res > 0:
        bvps, bvps_src = bvps_res, f"基本面庫 book_value（研究值，同庫 EPS 季別 {_period_str(fp) or '未標'}；PB帶以此基準校準）"
    elif bvps_off and bvps_off > 0:
        bvps, bvps_src = bvps_off, f"官方季報 每股淨值元（{off_period_s or '季別未標'}；基本面庫缺 book_value，PB帶未依此基準重校）"
    else:
        bvps, bvps_src = None, "無（基本面庫與官方季報皆無每股淨值）"
    pb = (close / bvps) if (close and bvps and bvps > 0) else None

    # 官方口徑 PB：優先用官方每股淨值×現價重算(與本地同價基準)；官方無淨值(金融業)才用 BWIBBU 公布值
    if close and bvps_off and bvps_off > 0:
        pb_official = close / bvps_off
        pb_off_basis = f"官方每股淨值 {bvps_off}（{off_period_s or '季別未標'}）× 現價"
    elif pb_off_pub and pb_off_pub > 0:
        pb_official = pb_off_pub
        pb_off_basis = f"官方 BWIBBU 股價淨值比（資料日 {off.get('PEPB日') or '未標'}，非以現價重算）"
    else:
        pb_official, pb_off_basis = None, ""

    verdict = "難判定"
    reason = ""
    basis = ""      # 判定依據分支（供口徑衝突時精準揭露）

    if _is_cyclical(stype):
        # 循環股：PB-Band 為主 + 正常化PE 佐證；低trailing PE 不視為便宜
        if pb is not None and pb_cheap is not None and pb <= pb_cheap:
            verdict, reason, basis = "便宜", f"PB {pb:.2f}≤便宜界{pb_cheap:.2f}(循環谷底低PB)", "PB-Band便宜"
        elif pb is not None and pb_exp is not None and pb >= pb_exp:
            verdict, reason, basis = "貴", f"PB {pb:.2f}≥偏貴界{pb_exp:.2f}(循環峰頂區)", "PB-Band偏貴"
        elif pe_norm is not None and pe_lo is not None and pe_hi is not None:
            basis = "正常化PE"
            if pe_norm <= pe_lo:
                verdict, reason = "合理偏低", f"正常化PE {pe_norm:.1f}≤{pe_lo:.0f}"
            elif pe_norm >= pe_hi:
                verdict, reason = "貴", f"正常化PE {pe_norm:.1f}≥{pe_hi:.0f}"
            else:
                verdict, reason = "合理", f"正常化PE {pe_norm:.1f}(區間{pe_lo:.0f}~{pe_hi:.0f})"
        elif pb is not None and pb_cheap is not None and pb_exp is not None:
            mid = (pb_cheap + pb_exp) / 2
            verdict, reason = ("合理偏低" if pb < mid else "合理偏高"), f"PB {pb:.2f}(帶{pb_cheap:.2f}~{pb_exp:.2f})"
            basis = "PB-Band中位"
        if reason:
            reason += "；循環股低PE≠便宜"
    else:
        # 成長/穩定股：以 PE 區間為主(優先 forward，其次 TTM)
        pe_use = pe_fwd if pe_fwd is not None else pe_ttm
        peb = "預估PE" if pe_fwd is not None else "本益比"
        if pe_use is not None and pe_lo is not None and pe_hi is not None:
            basis = "預估PE區間" if pe_fwd is not None else "TTM PE區間"
            if pe_use <= pe_lo:
                verdict, reason = "便宜", f"{peb} {pe_use:.1f}≤合理下緣{pe_lo:.0f}"
            elif pe_use >= pe_hi:
                verdict, reason = "貴", f"{peb} {pe_use:.1f}≥合理上緣{pe_hi:.0f}"
            else:
                mid = (pe_lo + pe_hi) / 2
                verdict, reason = ("合理偏低" if pe_use < mid else "合理偏高"), f"{peb} {pe_use:.1f}(合理{pe_lo:.0f}~{pe_hi:.0f})"
        elif pe_use is None and eps_ttm is not None and eps_ttm <= 0:
            verdict, reason, basis = "難判定", "近四季虧損、本益比失真", "TTM虧損"

    # --- 口徑交叉檢核（RPT-3 / 供 VAL-2 呼叫端取用） ---
    conflicts = {}
    if pb is not None and pb_official is not None and pb_official > 0 and bvps_res and bvps_res > 0:
        d = pb / pb_official - 1
        if abs(d) > _PB_CONFLICT_TH:
            conflicts["PB"] = {"估值庫": _r2(pb), "官方": _r2(pb_official), "差異%": round(d * 100, 1),
                               "官方基準": pb_off_basis}
    if pe_ttm is not None and pe_off is not None and pe_off > 0:
        d = pe_ttm / pe_off - 1
        if abs(d) > _PE_CONFLICT_TH:
            conflicts["PE"] = {"估值庫(TTM)": _r1(pe_ttm), "官方": _r1(pe_off), "差異%": round(d * 100, 1),
                               "官方基準": f"官方PE 資料日 {off.get('PEPB日') or '未標'}（EPS 季別 {off_period_s or '未標'}）"}

    # PB-Band 判定若在官方口徑下不成立，必須寫進「理由」(避免判定理由建立在過期分母上)
    if basis in ("PB-Band便宜", "PB-Band偏貴") and pb_official is not None:
        still = (pb_official <= pb_cheap) if basis == "PB-Band便宜" else (pb_official >= pb_exp)
        if not still:
            reason += (f"；⚠官方口徑 PB {pb_official:.2f}（{pb_off_basis}）未觸發同一界線，"
                       f"本判定之 PB 帶與官方淨值基準不一致，待季更重校")
    if stale:
        short = (f"⚠EPS季別 {_period_str(fp)} 已落後 {lag} 季（應至 {_period_str(base_p)}），本判定失真、詳見「過期說明」"
                 if (fp and base_p and lag) else "⚠EPS季別不明、無從查核新鮮度，詳見「過期說明」")
        reason = (reason + "；" + short) if reason else short

    conf = fund.get("confidence", "")
    if stale:
        conf = f"低（{'EPS季別落後%d季' % lag if lag else 'EPS季別不明'}，原評「{conf or '未標'}」）"

    return {
        "可用": True,
        "股性": stype,
        "EPS_TTM": eps_ttm, "正常化EPS": eps_norm, "預估EPS": eps_fwd, "每股淨值": bvps,
        "本益比_現價": _r1(pe_ttm), "正常化本益比": _r1(pe_norm), "預估本益比": _r1(pe_fwd), "股價淨值比": _r2(pb),
        "合理PE區間": ([pe_lo, pe_hi] if (pe_lo is not None and pe_hi is not None) else None),
        "PB便宜貴界": ([pb_cheap, pb_exp] if (pb_cheap is not None and pb_exp is not None) else None),
        "估值方法": fund.get("valuation_method", ""),
        "便宜貴": verdict, "便宜貴3級": TAG3.get(verdict, "—"),
        "判定依據": basis,
        "理由": reason,
        # 新鮮度（可稽核欄位；下游 needs_manual 與報告據此揭露）
        "EPS季別": _period_str(fp),
        "官方財報季別": off_period_s,
        "新鮮度基準季別": _period_str(base_p),
        "新鮮度基準來源": base_src if base_p else "無法判定",
        "季別落後(季)": lag,
        "資料過期": stale,
        "過期說明": stale_msg,
        # 口徑（每股淨值來源＋官方對照）
        "每股淨值來源": bvps_src,
        "每股淨值_官方": bvps_off,
        "股價淨值比_官方": _r2(pb_official),
        "官方PB基準": pb_off_basis,
        "本益比_官方": _r1(pe_off),
        "官方市場面來源": off_src,
        "口徑衝突": (conflicts or None),
        "資料時點": fund.get("as_of", ""), "信心": conf,
        "註記": fund.get("notes", ""),
    }


def one_line(v):
    """把 assess() 結果縮成一行(報告用)。過期/口徑衝突一律顯性揭露，不得只印單一數字。"""
    if not v or not v.get("可用"):
        return "估值：基本面資料未建置(needs_manual)"
    parts = []
    if v.get("EPS_TTM") is not None:
        parts.append(f"EPS(TTM) {v['EPS_TTM']:g}")
    if v.get("本益比_現價") is not None:
        parts.append(f"PE {v['本益比_現價']:g}x")
    elif v.get("正常化本益比") is not None:
        parts.append(f"正常化PE {v['正常化本益比']:g}x")
    if v.get("股價淨值比") is not None:
        parts.append(f"PB {v['股價淨值比']:g}")
    head = "、".join(parts)
    # ⚠ 前綴：季別落後時先講失真，避免只印過期數字
    warn = ""
    if v.get("資料過期"):
        eps_q = v.get("EPS季別") or "季別不明"
        b_q, b_src = v.get("新鮮度基準季別"), v.get("新鮮度基準來源") or ""
        warn = (f"⚠EPS基準 {eps_q} 已落後（應至 {b_q}，{b_src}），PE/PB 失真待季更；"
                if b_q else f"⚠EPS基準 {eps_q}、新鮮度無從查核，PE/PB 僅供參考；")
    # 理由內已有同義的季別落後短句，前綴既已揭露就不重複(ground.json 的「理由」仍保留完整文字)
    rsn = v.get("理由") or ""
    if warn and "⚠EPS季別" in rsn:
        rsn = rsn.split("⚠EPS季別")[0].rstrip("；")
    tail = f"→ {v['便宜貴']}" + (f"（{rsn}）" if rsn else "")
    # 官方對照：兩套口徑差異過大時同行並列，避免報告只出現過期的那一個數字
    ck = v.get("口徑衝突") or {}
    cmp_parts = []
    if ck.get("PE"):
        cmp_parts.append(f"PE {ck['PE'].get('官方')}x")
    if ck.get("PB"):
        cmp_parts.append(f"PB {ck['PB'].get('官方')}")
    cmp_txt = f"；官方口徑對照 {'／'.join(cmp_parts)}（{v.get('官方財報季別') or '官方季別未標'}）" if cmp_parts else ""
    return f"估值：{warn}{head} {tail}{cmp_txt}".strip()


# ---------------- 目前價值（把倍數帶還原成價格區間） ----------------

def _band(m_lo, m_hi, base):
    """倍數帶 × 每股基準 → 價格區間。任一缺值/非正數回 None（不猜、不外插）。"""
    m_lo, m_hi, base = _num(m_lo), _num(m_hi), _num(base)
    if None in (m_lo, m_hi, base) or base <= 0 or m_lo <= 0 or m_hi <= 0:
        return None
    lo, hi = sorted((m_lo * base, m_hi * base))
    return (lo, hi)


def _pe_base(v):
    """PE 錨的每股盈餘基準。循環股一律用正常化EPS（鐵則：峰頂/谷底單期EPS不可直接乘），
    其餘採 預估EPS → TTM EPS。回 (eps, 說明) 或 (None, 原因)。"""
    if _is_cyclical(v.get("股性")):
        e = _num(v.get("正常化EPS"))
        if e and e > 0:
            return e, f"正常化EPS {e:g}（循環股鐵則：不用單期EPS）"
        return None, "循環股缺正常化EPS，不以單期EPS推價（低PE≠便宜陷阱）"
    e = _num(v.get("預估EPS"))
    if e and e > 0:
        return e, f"預估EPS {e:g}"
    e = _num(v.get("EPS_TTM"))
    if e and e > 0:
        return e, f"EPS(TTM) {e:g}"
    return None, "EPS 缺值或為負（虧損股本益比失真）"


def fair_value(v, close=None):
    """由 assess() 結果推「目前價值」：把估值倍數帶還原成**價格區間（元）**，
    再與現價比出折溢價——讓「便宜/貴」有可對照的數字，而不是只剩形容詞。

    主錨與 assess() 的判定分支一致（循環股 PB-Band 優先、其餘 PE 區間）；另一套
    倍數若可算則並列為「交叉錨」，兩錨不一致時明講（不擇一隱藏、不取平均混為一談）。
    價格區間 ＝ 倍數帶 × 每股基準（BVPS 或 EPS）。BVPS 沿用 assess() 選定的分母
    （PB 帶即以該序列校準，換分母等於整條帶位平移，理由見模組 docstring）。
    EPS 季別落後時照算但標 ⚠：過期的便宜**不得**當買進理由（紅燈可信、綠燈不可信）。
    回傳 dict；無法成帶時 可用=False 並寫明原因（不硬給價位）。
    """
    if not v or not v.get("可用"):
        return {"可用": False, "說明": "估值未建置（needs_manual），無法推算合理價區間"}
    close = _num(close)
    cyc = _is_cyclical(v.get("股性"))
    bvps = _num(v.get("每股淨值"))
    pbb = v.get("PB便宜貴界") or [None, None]
    peb = v.get("合理PE區間") or [None, None]
    eps, eps_note = _pe_base(v)

    pb_band = _band(pbb[0], pbb[1], bvps)
    pe_band = _band(peb[0], peb[1], eps)

    anchors = []
    if pb_band:
        anchors.append(("PB-Band", pb_band,
                        f"PB {pbb[0]:g}~{pbb[1]:g}× 每股淨值 {bvps:g}"))
    if pe_band:
        anchors.append(("PE區間", pe_band,
                        f"PE {peb[0]:g}~{peb[1]:g}× {eps_note}"))
    if not anchors:
        why = []
        if not pb_band:
            why.append("PB帶或每股淨值缺值" if not (bvps and pbb[0]) else "PB帶不可用")
        if not pe_band:
            why.append(eps_note if eps is None else "合理PE區間缺值")
        return {"可用": False, "說明": "無法還原合理價區間：" + "；".join(why)}

    # 主錨必須是 assess() 實際下判定的那一套倍數（`判定依據`），否則會出現
    # 「帶內 22%」配「判定：貴」這種自相矛盾的卡片——循環股在 PB 未觸兩端時，
    # assess() 是改用正常化PE 定案的，價格帶就必須跟著用 PE 錨還原。
    basis_key = str(v.get("判定依據") or "")
    if basis_key.startswith("PB-Band"):
        order = ["PB-Band", "PE區間"]
    elif "PE" in basis_key:
        order = ["PE區間", "PB-Band"]
    else:   # 判定依據缺漏（難判定等）→ 退回股性預設：循環股 PB 優先
        order = ["PB-Band", "PE區間"] if cyc else ["PE區間", "PB-Band"]
    anchors.sort(key=lambda a: order.index(a[0]))
    name, (lo, hi), basis = anchors[0]
    cross = None
    if len(anchors) > 1:
        cname, (clo, chi), cbasis = anchors[1]
        cross = {"名稱": cname, "區間": [_r1(clo), _r1(chi)], "基準": cbasis,
                 "與主錨重疊": not (chi < lo or clo > hi)}

    mid = (lo + hi) / 2
    out = {
        "可用": True,
        "主錨": name, "主錨基準": basis,
        "合理價低": _r1(lo), "合理價高": _r1(hi), "合理價中值": _r1(mid),
        "交叉錨": cross,
        "便宜貴": v.get("便宜貴"), "便宜貴3級": v.get("便宜貴3級"),
        "資料過期": bool(v.get("資料過期")),
        "警語": [],
    }
    if v.get("資料過期"):
        out["警語"].append("⚠" + (v.get("過期說明") or "EPS 季別落後，價值區間同步失真"))
    if cross and not cross["與主錨重疊"]:
        out["警語"].append(
            f"兩套口徑不重疊：{name} {_r1(lo)}~{_r1(hi)} vs {cross['名稱']} "
            f"{cross['區間'][0]}~{cross['區間'][1]} 元，價值區間本身不確定，勿只引用其中一套")
    if close is None or close <= 0:
        out["說明"] = "無現價可比對（僅列合理價區間）"
        return out

    # 現價要顯示成交價本身（低價股報價到 0.01，_r1 會把 16.45 變 16.4＝顯示錯價）；
    # 合理價區間才保留 1 位（那是研究值推算、非成交價）。
    out["現價"] = round(close, 2)
    out["相對中值%"] = round((close / mid - 1) * 100, 1)
    out["回到中值空間%"] = round((mid / close - 1) * 100, 1)
    if close < lo:
        out["位置"] = "低於合理下緣"
        out["折溢價%"] = round((close / lo - 1) * 100, 1)   # 負值＝折價
        out["帶內位置%"] = 0.0
    elif close > hi:
        out["位置"] = "高於合理上緣"
        out["折溢價%"] = round((close / hi - 1) * 100, 1)   # 正值＝溢價
        out["帶內位置%"] = 100.0
    else:
        pctn = (close - lo) / (hi - lo) * 100 if hi > lo else 50.0
        out["位置"] = "位於合理帶內"
        out["折溢價%"] = 0.0
        out["帶內位置%"] = round(pctn, 1)
    # 與 assess() 五級判定的一致性守門：兩者本應同一分支，不一致代表主錨選擇有落差，
    # 不靜默擇一顯示（那會讓報告出現「便宜」徽章配「高於合理上緣」的自相矛盾）。
    v5, pos = out.get("便宜貴") or "", out["位置"]
    if (v5 in ("便宜", "合理偏低") and pos == "高於合理上緣") or (v5 == "貴" and pos == "低於合理下緣"):
        out["警語"].append(f"與五級判定不一致（判定「{v5}」但現價{pos}）：主錨與 assess() 判定分支不同，"
                           "請以各檔深度報告的估值章節為準")
    return out


def value_line(fv):
    """「目前價值」一行（報告用）。無法推算就明講無法推算，不編價位。"""
    if not fv or not fv.get("可用"):
        return "目前價值：" + (fv or {}).get("說明", "無法推算（needs_manual）")
    lo, hi, mid = fv["合理價低"], fv["合理價高"], fv["合理價中值"]
    s = f"合理價 {lo:g}~{hi:g} 元（中值 {mid:g}；{fv['主錨']}：{fv['主錨基準']}）"
    if fv.get("現價") is not None:
        pos, d = fv["位置"], fv.get("折溢價%", 0.0)
        if pos == "低於合理下緣":
            s += f"；現價 {fv['現價']:g} 元 → 折價 {d:.1f}%（低於下緣），回中值 {fv['回到中值空間%']:+.1f}%"
        elif pos == "高於合理上緣":
            s += f"；現價 {fv['現價']:g} 元 → 溢價 +{d:.1f}%（高於上緣），回中值 {fv['回到中值空間%']:+.1f}%"
        else:
            s += (f"；現價 {fv['現價']:g} 元 → 在帶內 {fv['帶內位置%']:.0f}% 位置，"
                  f"距中值 {fv['相對中值%']:+.1f}%")
    if fv.get("交叉錨"):
        c = fv["交叉錨"]
        s += f"；交叉錨 {c['名稱']} {c['區間'][0]:g}~{c['區間'][1]:g} 元（{c['基準']}）"
    if fv.get("警語"):
        s += "；" + "；".join(fv["警語"])
    return "目前價值：" + s


